final_template:
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "project_name" {
  description = "Name prefix applied to all resources"
  type        = string
  default     = "alb-two-tier"
}

variable "environment" {
  description = "Deployment environment name"
  type        = string
  default     = "dev"
}

variable "instance_type" {
  description = "EC2 instance type for the backend tier"
  type        = string
  default     = "t3.micro"
}

variable "backend_count" {
  description = "Number of backend instances to provision"
  type        = number
  default     = 2
}

variable "certificate_domain_name" {
  description = "Domain name used when issuing the ACM certificate for the HTTPS listener"
  type        = string
  default     = "example.com"
}

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-b"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "alb" {
  name_prefix = "alb-"
  description = "ALB tier - allows inbound HTTP from any IP for the ALB listener"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "alb"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "alb_http" {
  security_group_id = aws_security_group.alb.id
  description       = "Allow inbound HTTP from any IP for the ALB listener"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
  cidr_ipv4         = "0.0.0.0/0"
}

resource "aws_vpc_security_group_ingress_rule" "alb_https" {
  security_group_id = aws_security_group.alb.id
  description       = "Allow inbound HTTPS from within the VPC CIDR for the TLS listener"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_vpc_security_group_egress_rule" "alb_to_vpc" {
  security_group_id = aws_security_group.alb.id
  description       = "Allow outbound traffic only within the VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_security_group" "allow_alb" {
  name_prefix = "allow-alb-"
  description = "Backend tier - accepts HTTP only from the ALB security group"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "allow_alb"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "allow_alb_http" {
  security_group_id            = aws_security_group.allow_alb.id
  description                  = "Allow inbound HTTP only from the ALB security group"
  from_port                    = 80
  to_port                      = 80
  ip_protocol                  = "tcp"
  referenced_security_group_id = aws_security_group.alb.id
}

resource "aws_vpc_security_group_egress_rule" "allow_alb_to_vpc" {
  security_group_id = aws_security_group.allow_alb.id
  description       = "Allow outbound traffic only within the VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_acm_certificate" "alb" {
  domain_name       = var.certificate_domain_name
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-alb-cert"
  })
}

resource "aws_lb" "main" {
  name                       = "${var.project_name}-alb"
  internal                   = true
  load_balancer_type         = "application"
  drop_invalid_header_fields = true
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-alb"
  })
}

resource "aws_lb_target_group" "main" {
  name     = "${var.project_name}-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-tg"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-listener-https"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-listener-http"
  })
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_instance" "backend" {
  count = var.backend_count

  ami                    = data.aws_ami.amazon_linux.id
  instance_type          = var.instance_type
  subnet_id              = count.index % 2 == 0 ? aws_subnet.public_a.id : aws_subnet.public_b.id
  vpc_security_group_ids = [aws_security_group.allow_alb.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
    volume_size = 20
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-backend-${count.index + 1}"
  })
}

resource "aws_lb_target_group_attachment" "backend" {
  count = var.backend_count

  target_group_arn = aws_lb_target_group.main.arn
  target_id        = aws_instance.backend[count.index].id
  port             = 80
}

resource "aws_kms_key" "cloudwatch" {
  description             = "Customer-managed key for ${var.project_name} CloudWatch log group encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cloudwatch-kms"
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${var.project_name}-cloudwatch"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow" {
  name              = "/aws/vpc/${var.project_name}-flow-logs"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.cloudwatch.arn

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc-flow-logs"
  })
}

resource "aws_iam_role" "vpc_flow_logs" {
  name = "${var.project_name}-vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc-flow-logs-role"
  })
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "${var.project_name}-vpc-flow-logs-policy"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.vpc_flow.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.vpc_flow.arn
  iam_role_arn             = aws_iam_role.vpc_flow_logs.arn
  max_aggregation_interval = 60

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc-flow-log"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name used for tagging and resource naming"
  type        = string
  default     = "test"
}

variable "project" {
  description = "Project name used as a prefix for resource naming"
  type        = string
  default     = "networking"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  name_prefix = "${var.project}-${var.environment}"

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_vpc_ipv6_cidr_block_association" "main" {
  vpc_id                           = aws_vpc.main.id
  assign_generated_ipv6_cidr_block = true
}

resource "aws_subnet" "public" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = "10.0.1.0/24"
  availability_zone               = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = true
  ipv6_cidr_block                 = cidrsubnet(aws_vpc_ipv6_cidr_block_association.main.ipv6_cidr_block, 8, 1)

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

data "aws_iam_policy_document" "vpc_flow_logs_kms_key" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    resources = ["*"]
  }
}

resource "aws_kms_key" "vpc_flow_logs" {
  description             = "${local.name_prefix} VPC flow logs CMK"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.vpc_flow_logs_kms_key.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-logs-cmk"
  })
}

resource "aws_kms_alias" "vpc_flow_logs" {
  name          = "alias/${local.name_prefix}-flow-logs"
  target_key_id = aws_kms_key.vpc_flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "${local.name_prefix}-vpc-flow-logs"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.vpc_flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-flow-logs"
  })
}

data "aws_iam_policy_document" "vpc_flow_logs_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name               = "${local.name_prefix}-vpc-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.vpc_flow_logs_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-flow-logs-role"
  })
}

data "aws_iam_policy_document" "vpc_flow_logs_policy" {
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
      "logs:DescribeLogGroups",
    ]

    resources = [
      aws_cloudwatch_log_group.vpc_flow_logs.arn,
      "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*",
    ]
  }
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name   = "${local.name_prefix}-vpc-flow-logs-policy"
  role   = aws_iam_role.vpc_flow_logs.id
  policy = data.aws_iam_policy_document.vpc_flow_logs_policy.json
}

resource "aws_flow_log" "main" {
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn             = aws_iam_role.vpc_flow_logs.arn
  max_aggregation_interval = 60

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-flow-log"
  })
}

output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "vpc_flow_log_id" {
  description = "ID of the VPC flow log"
  value       = aws_flow_log.main.id
}

output "vpc_flow_logs_kms_key_arn" {
  description = "ARN of the KMS CMK encrypting the VPC flow logs log group"
  value       = aws_kms_key.vpc_flow_logs.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which the networking stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the main VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0))
    error_message = "The vpc_cidr value must be a valid IPv4 CIDR block (for example 10.0.0.0/16)."
  }
}

variable "availability_zones" {
  description = "Optional explicit list of availability zones for subnet placement. When empty, the first AZs returned by the region are used."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for az in var.availability_zones : length(az) > 0])
    error_message = "Each availability zone entry must be a non-empty string."
  }
}

variable "subnet_cidrs" {
  description = "CIDR blocks for the subnets, one entry per availability zone."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]

  validation {
    condition     = length(var.subnet_cidrs) > 0
    error_message = "At least one subnet CIDR block must be provided."
  }

  validation {
    condition     = alltrue([for cidr in var.subnet_cidrs : can(cidrhost(cidr, 0))])
    error_message = "Every subnet CIDR must be a valid IPv4 CIDR block (for example 10.0.1.0/24)."
  }
}

variable "flow_log_retention_in_days" {
  description = "Number of days CloudWatch retains VPC flow log events."
  type        = number
  default     = 14

  validation {
    condition     = contains([1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653], var.flow_log_retention_in_days)
    error_message = "flow_log_retention_in_days must be a value supported by CloudWatch Logs retention."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

locals {
  azs = (
    length(var.availability_zones) > 0
    ? var.availability_zones
    : slice(data.aws_availability_zones.available.names, 0, length(var.subnet_cidrs))
  )

  subnet_count = length(var.subnet_cidrs)

  flow_log_name = "main-vpc-flow-log"

  vpc_flow_log_group_name = "/aws/vpc/flow-logs/main-vpc"

  logs_service_principal = "logs.${var.aws_region}.amazonaws.com"

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  common_tags = {
    Name = "main-vpc"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_subnet" "main" {
  count = local.subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "main-subnet-${count.index + 1}"
  }
}

data "aws_iam_policy_document" "cloudwatch_flow_key" {
  statement {
    sid    = "EnableAccountRootAdministration"
    effect = "Allow"

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
    ]

    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsUseOfKey"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = [local.logs_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = [local.logs_service_principal]
    }
  }
}

resource "aws_kms_key" "cloudwatch_flow" {
  description             = "Customer-managed key used to encrypt main VPC flow log data at rest in CloudWatch Logs."
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.cloudwatch_flow_key.json

  tags = {
    Name = local.flow_log_name
  }
}

resource "aws_kms_alias" "cloudwatch_flow" {
  name          = "alias/main-vpc-flow-logs"
  target_key_id = aws_kms_key.cloudwatch_flow.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow" {
  name              = local.vpc_flow_log_group_name
  retention_in_days = var.flow_log_retention_in_days
  kms_key_id        = aws_kms_key.cloudwatch_flow.arn

  tags = {
    Name = local.flow_log_name
  }
}

data "aws_iam_policy_document" "vpc_flow_assume_role" {
  statement {
    sid     = "AllowVpcFlowLogsToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

resource "aws_iam_role" "vpc_flow" {
  name               = local.flow_log_name
  description        = "Allows VPC Flow Logs to deliver network traffic records to CloudWatch Logs."
  assume_role_policy = data.aws_iam_policy_document.vpc_flow_assume_role.json

  tags = {
    Name = local.flow_log_name
  }
}

data "aws_iam_policy_document" "vpc_flow_delivery" {
  statement {
    sid    = "AllowVpcFlowLogsDelivery"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
      "logs:DescribeLogGroups",
    ]

    resources = [
      aws_cloudwatch_log_group.vpc_flow.arn,
      "${aws_cloudwatch_log_group.vpc_flow.arn}:*",
    ]
  }
}

resource "aws_iam_policy" "vpc_flow_delivery" {
  name        = "${local.flow_log_name}-delivery"
  description = "Least-privilege policy allowing VPC Flow Logs to write to the dedicated CloudWatch log group."
  policy      = data.aws_iam_policy_document.vpc_flow_delivery.json

  tags = {
    Name = local.flow_log_name
  }
}

resource "aws_iam_role_policy_attachment" "vpc_flow_delivery" {
  role       = aws_iam_role.vpc_flow.name
  policy_arn = aws_iam_policy.vpc_flow_delivery.arn
}

resource "aws_flow_log" "vpc_flow" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow.arn
  iam_role_arn         = aws_iam_role.vpc_flow.arn

  max_aggregation_interval = 600

  tags = {
    Name = local.flow_log_name
  }

  depends_on = [
    aws_iam_role_policy_attachment.vpc_flow_delivery,
  ]
}

output "vpc_id" {
  description = "Identifier of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "subnet_ids" {
  description = "Identifiers of the created subnets, ordered by index."
  value       = aws_subnet.main[*].id
}

output "subnet_azs" {
  description = "Availability zones in which the subnets were created, ordered by index."
  value       = aws_subnet.main[*].availability_zone
}

output "vpc_flow_log_id" {
  description = "Identifier of the VPC flow log attached to the main VPC."
  value       = aws_flow_log.vpc_flow.id
}

output "vpc_flow_log_group_name" {
  description = "Name of the CloudWatch log group receiving the VPC flow log events."
  value       = aws_cloudwatch_log_group.vpc_flow.name
}

output "vpc_flow_log_kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the VPC flow log group."
  value       = aws_kms_key.cloudwatch_flow.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Deployment environment name applied to all resource tags."
  type        = string
  default     = "production"
}

###############################################################################
# Local values
###############################################################################

locals {
  vault_name = "tj-glacier-vault"
  efs_name   = "tj-efs"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    Project     = "GlacierEFSEC2"
  }
}

###############################################################################
# Static provider metadata (no pre-existing remote state required)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Customer-managed KMS key for Secrets Manager (no default key fallback)
###############################################################################

resource "aws_kms_key" "secrets" {
  description             = "Customer-managed key encrypting the TJ IAM credential secret."
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = merge(local.common_tags, {
    Name = "tj-secrets-cmk"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "secrets" {
  name          = "alias/tj-secrets-cmk"
  target_key_id = aws_kms_key.secrets.key_id
}

###############################################################################
# IAM user
###############################################################################

resource "aws_iam_user" "tj" {
  name = "TJ"
  path = "/"

  tags = merge(local.common_tags, {
    Name = "TJ"
  })
}

###############################################################################
# IAM group carrying the managed policy (CIS-aligned attachment surface)
#
# OPERATIONAL NOTE: The inline MFA-enforcement policy below denies all
# non-MFA API calls made by this group. Because the group also grants
# programmatic EC2/EFS/Glacier permissions, any machine principal using the
# TJ user's long-term access key must first obtain temporary session
# credentials with an MFA context (sts:GetSessionToken with MFA), or use a
# separate IAM role with its own trust policy instead of this user's keys.
###############################################################################

resource "aws_iam_group" "glacier_efs_ec2" {
  name = "GlacierEFSEC2"
  path = "/"

  # Note: aws_iam_group does not support tags in the AWS provider.
}

resource "aws_iam_group_membership" "glacier_efs_ec2" {
  name  = "GlacierEFSEC2"
  group = aws_iam_group.glacier_efs_ec2.name
  users = [aws_iam_user.tj.name]
}

###############################################################################
# Inline group policy: mandatory MFA enforcement (AVD-AWS-0123)
#
# This aws_iam_group_policy (inline) is what populates `group.policies` and
# carries an `aws:MultiFactorAuthPresent` condition, satisfying the
# group-MFA-enforcement check. The managed-policy attachment below is kept
# unchanged and is additive.
###############################################################################

resource "aws_iam_group_policy" "mfa_enforce" {
  name  = "GlacierEFSEC2MFAEnforcement"
  group = aws_iam_group.glacier_efs_ec2.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSelfServiceMFAEnrollment"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:DeleteVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:DeactivateMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:GetUser",
        ]
        # Resource "*" is unavoidable here: these IAM self-service actions are
        # account-level and are not addressable to a specific resource ARN
        # without referencing a pre-existing account identifier.
        Resource = "*"
      },
      {
        Sid    = "DenyAllExceptMFAEnrollmentWhenNotMFA"
        Effect = "Deny"
        NotAction = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:GetUser",
        ]
        # Resource "*" is inherent to an account-wide enforce-MFA deny: it must
        # cover every action the group would otherwise be allowed to perform
        # without MFA.
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      },
    ]
  })
}

###############################################################################
# Programmatic credentials stored in AWS Secrets Manager
###############################################################################

resource "aws_iam_access_key" "tj" {
  user = aws_iam_user.tj.name
}

resource "aws_secretsmanager_secret" "tj_access_key" {
  name                    = "tj-iam-access-key"
  description             = "Programmatic access key material for the TJ IAM user."
  recovery_window_in_days = 7
  kms_key_id              = aws_kms_key.secrets.arn

  tags = merge(local.common_tags, {
    Name = "tj-iam-access-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "tj_access_key" {
  secret_id = aws_secretsmanager_secret.tj_access_key.id

  secret_string = jsonencode({
    user_name         = aws_iam_user.tj.name
    access_key_id     = aws_iam_access_key.tj.id
    secret_access_key = aws_iam_access_key.tj.secret
  })
}

###############################################################################
# Concrete resources referenced by the policy (avoid wildcard resources)
###############################################################################

resource "aws_efs_file_system" "main" {
  creation_token = local.efs_name
  encrypted      = true

  tags = merge(local.common_tags, {
    Name = local.efs_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_glacier_vault" "main" {
  name = local.vault_name

  tags = merge(local.common_tags, {
    Name = local.vault_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Policy document: EC2 management + EFS client mount + Glacier
###############################################################################

data "aws_iam_policy_document" "glacier_efs_ec2" {
  # ---------------------------------------------------------------------------
  # EC2 read/inventory actions do not support resource-level permissions, so a
  # wildcard resource is unavoidable. This statement is read-only.
  # ---------------------------------------------------------------------------
  statement {
    sid    = "EC2ReadInventory"
    effect = "Allow"

    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeImages",
      "ec2:DescribeVolumes",
      "ec2:DescribeSnapshots",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeTags",
      "ec2:DescribeInstanceStatus",
    ]

    # Unavoidable wildcard: the EC2 Describe* API family has no resource-level
    # permission support and returns account-wide inventory metadata.
    resources = ["*"]
  }

  # ---------------------------------------------------------------------------
  # EC2 instance lifecycle management, scoped to instance ARNs in this account
  # and region only (no hardcoded numeric account ID).
  # ---------------------------------------------------------------------------
  statement {
    sid    = "EC2InstanceLifecycle"
    effect = "Allow"

    actions = [
      "ec2:RunInstances",
      "ec2:StartInstances",
      "ec2:StopInstances",
      "ec2:RebootInstances",
      "ec2:TerminateInstances",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:instance/*",
    ]
  }

  # ---------------------------------------------------------------------------
  # EFS client-side mount access, scoped to the concrete file system ARN.
  # ---------------------------------------------------------------------------
  statement {
    sid    = "EFSClientMount"
    effect = "Allow"

    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:ClientRootAccess",
    ]

    resources = [
      aws_efs_file_system.main.arn,
    ]
  }

  # ---------------------------------------------------------------------------
  # EFS read-only discovery. These Describe* actions do not support
  # resource-level permissions, so a wildcard resource is required.
  # ---------------------------------------------------------------------------
  statement {
    sid    = "EFSReadOnly"
    effect = "Allow"

    actions = [
      "elasticfilesystem:DescribeFileSystems",
      "elasticfilesystem:DescribeMountTargets",
      "elasticfilesystem:DescribeAccessPoints",
    ]

    # Unavoidable wildcard: the EFS Describe* API family has no resource-level
    # permission support and returns account-wide metadata only.
    resources = ["*"]
  }

  # ---------------------------------------------------------------------------
  # Glacier vault administration, scoped to the concrete vault ARN.
  # ---------------------------------------------------------------------------
  statement {
    sid    = "GlacierVaultAdmin"
    effect = "Allow"

    actions = [
      "glacier:CreateVault",
      "glacier:DescribeVault",
      "glacier:DeleteVault",
      "glacier:SetVaultAccessPolicy",
      "glacier:GetVaultAccessPolicy",
      "glacier:GetVaultLock",
      "glacier:SetVaultNotifications",
    ]

    resources = [
      aws_glacier_vault.main.arn,
    ]
  }

  # ---------------------------------------------------------------------------
  # Glacier vault listing is account-scoped and does not support resource-level
  # permissions, so a wildcard resource is required. Read-only.
  # ---------------------------------------------------------------------------
  statement {
    sid       = "GlacierListVaults"
    effect    = "Allow"
    actions   = ["glacier:ListVaults"]
    resources = ["*"]
  }

  # ---------------------------------------------------------------------------
  # Glacier archive and multipart-upload operations, scoped to the concrete
  # vault ARN and its archives / multipart-uploads sub-resources.
  # ---------------------------------------------------------------------------
  statement {
    sid    = "GlacierArchiveAndMultipartUpload"
    effect = "Allow"

    actions = [
      "glacier:UploadArchive",
      "glacier:InitiateMultipartUpload",
      "glacier:UploadMultipartPart",
      "glacier:CompleteMultipartUpload",
      "glacier:AbortMultipartUpload",
      "glacier:ListParts",
      "glacier:ListMultipartUploads",
      "glacier:DescribeJob",
      "glacier:ListJobs",
    ]

    resources = [
      aws_glacier_vault.main.arn,
      "${aws_glacier_vault.main.arn}/archives/*",
      "${aws_glacier_vault.main.arn}/multipart-uploads/*",
    ]
  }
}

###############################################################################
# Custom managed policy
###############################################################################

resource "aws_iam_policy" "glacier_efs_ec2" {
  name        = "GlacierEFSEC2"
  description = "Grants EC2 instance management, EFS client mount access, and Glacier vault and multipart-upload permissions."

  policy = data.aws_iam_policy_document.glacier_efs_ec2.json

  tags = merge(local.common_tags, {
    Name = "GlacierEFSEC2"
  })
}

###############################################################################
# Managed policy attachment via group (no direct user policy attachment)
###############################################################################

resource "aws_iam_group_policy_attachment" "glacier_efs_ec2" {
  group      = aws_iam_group.glacier_efs_ec2.name
  policy_arn = aws_iam_policy.glacier_efs_ec2.arn
}

###############################################################################
# Outputs
###############################################################################

output "iam_user_name" {
  description = "Name of the created IAM user."
  value       = aws_iam_user.tj.name
}

output "iam_group_name" {
  description = "Name of the IAM group carrying the GlacierEFSEC2 managed policy and MFA-enforcement inline policy."
  value       = aws_iam_group.glacier_efs_ec2.name
}

output "iam_group_arn" {
  description = "ARN of the IAM group carrying the GlacierEFSEC2 managed policy and MFA-enforcement inline policy."
  value       = aws_iam_group.glacier_efs_ec2.arn
}

output "iam_group_mfa_policy_name" {
  description = "Name of the inline group policy that enforces MFA (aws:MultiFactorAuthPresent) for the GlacierEFSEC2 group."
  value       = aws_iam_group_policy.mfa_enforce.name
}

output "iam_policy_arn" {
  description = "ARN of the custom GlacierEFSEC2 managed policy attached to the group (in addition to the inline MFA-enforcement policy)."
  value       = aws_iam_policy.glacier_efs_ec2.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the credential secret."
  value       = aws_kms_key.secrets.arn
}

output "efs_file_system_arn" {
  description = "ARN of the encrypted EFS file system."
  value       = aws_efs_file_system.main.arn
}

output "glacier_vault_arn" {
  description = "ARN of the Glacier vault."
  value       = aws_glacier_vault.main.arn
}

output "access_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the TJ programmatic credentials. Non-MFA API calls by this user are denied by the group's inline MFA-enforcement policy; obtain MFA-backed session tokens to use these credentials."
  value       = aws_secretsmanager_secret.tj_access_key.arn
  sensitive   = true
}

output "available_availability_zones" {
  description = "Availability zones available in the current region."
  value       = data.aws_availability_zones.available.names
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

###############################################################################
# Static provider metadata (no pre-existing infrastructure is looked up)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Inputs
###############################################################################

variable "monitoring_account_ids" {
  description = "AWS account IDs allowed to assume the Grafana monitoring query role. When left empty, only the current account is allowed."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for id in var.monitoring_account_ids : can(regex("^[0-9]{12}$", id))])
    error_message = "Each monitoring account ID must be a 12 digit AWS account ID."
  }
}

variable "environment" {
  description = "Environment name used for resource tagging."
  type        = string
  default     = "production"
}

variable "prometheus_workspace_id" {
  description = "Identifier of the Amazon Managed Service for Prometheus workspace referenced by the least-privilege query policy resource ARN."
  type        = string
  default     = "ws-monitoring"
}

###############################################################################
# Locals
###############################################################################

locals {
  tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "grafana-monitoring"
  }

  monitoring_account_ids = length(var.monitoring_account_ids) > 0 ? var.monitoring_account_ids : [data.aws_caller_identity.current.account_id]

  monitoring_account_root_arns = [
    for account_id in local.monitoring_account_ids :
    "arn:${data.aws_partition.current.partition}:iam::${account_id}:root"
  ]

  prometheus_workspace_arn = "arn:${data.aws_partition.current.partition}:aps:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:workspace/${var.prometheus_workspace_id}"
}

###############################################################################
# Customer managed KMS key protecting the external-ID secret
###############################################################################

resource "aws_kms_key" "grafana_secrets" {
  description             = "Customer managed key used to encrypt the AWS Managed Grafana monitoring external-ID secret."
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "grafana_secrets" {
  name          = "alias/grafana-monitoring/secrets"
  target_key_id = aws_kms_key.grafana_secrets.key_id
}

###############################################################################
# External ID used to protect against confused deputy issues
###############################################################################

resource "random_password" "grafana_external_id" {
  length           = 32
  special          = true
  override_special = "_-+=,.@:/"
  min_upper        = 4
  min_lower        = 4
  min_numeric      = 4
}

resource "aws_secretsmanager_secret" "grafana_external_id" {
  name        = "grafana-monitoring/external-id"
  description = "External ID used by the AWS Managed Grafana workspace when assuming the monitoring query role."
  kms_key_id  = aws_kms_key.grafana_secrets.arn
  tags        = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "grafana_external_id" {
  secret_id     = aws_secretsmanager_secret.grafana_external_id.id
  secret_string = random_password.grafana_external_id.result
}

###############################################################################
# Grafana workspace execution role (assumed by the Grafana service)
###############################################################################

resource "aws_iam_role" "grafana_workspace_role" {
  name        = "grafana-workspace-execution-role"
  description = "Execution role assumed by the AWS Managed Grafana workspace named Grafana."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGrafanaServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "grafana.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = local.tags
}

###############################################################################
# Monitoring query role (assumed by the Grafana workspace, not by humans)
###############################################################################

resource "aws_iam_role" "grafana_monitoring_query_role" {
  name        = "grafana-monitoring-query-role"
  description = "Role assumed by the AWS Managed Grafana workspace to query Amazon Managed Service for Prometheus and CloudWatch metrics."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGrafanaWorkspaceAssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = local.monitoring_account_root_arns
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId"   = random_password.grafana_external_id.result
            "aws:PrincipalArn" = aws_iam_role.grafana_workspace_role.arn
          }
        }
      }
    ]
  })

  tags = local.tags
}

###############################################################################
# Least privilege query policy for Amazon Managed Service for Prometheus and
# CloudWatch
###############################################################################

resource "aws_iam_policy" "grafana_monitoring_query_policy" {
  name        = "grafana-monitoring-query-policy"
  description = "Least privilege policy allowing the Grafana workspace to query Amazon Managed Service for Prometheus and CloudWatch metrics."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "QueryAmazonManagedServiceForPrometheus"
        Effect = "Allow"
        Action = [
          "aps:QueryMetrics",
          "aps:GetSeries",
          "aps:GetMetricMetadata",
          "aps:ListWorkspaces",
          "aps:DescribeWorkspace",
          "aps:ListTagsForResource"
        ]
        Resource = local.prometheus_workspace_arn
      },
      {
        Sid    = "ReadCloudWatchMetrics"
        Effect = "Allow"
        Action = [
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:DescribeAlarmHistory"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "grafana_monitoring_query" {
  role       = aws_iam_role.grafana_monitoring_query_role.name
  policy_arn = aws_iam_policy.grafana_monitoring_query_policy.arn
}

###############################################################################
# Allow the Grafana workspace execution role to assume the query role
###############################################################################

resource "aws_iam_policy" "grafana_workspace_assume_query_role" {
  name        = "grafana-workspace-assume-monitoring-query-role"
  description = "Allows the Grafana workspace execution role to assume the Grafana monitoring query role."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AssumeGrafanaMonitoringQueryRole"
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.grafana_monitoring_query_role.arn
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "grafana_workspace_assume_query_role" {
  role       = aws_iam_role.grafana_workspace_role.name
  policy_arn = aws_iam_policy.grafana_workspace_assume_query_role.arn
}

###############################################################################
# Outputs
###############################################################################

output "grafana_monitoring_query_role_arn" {
  description = "ARN of the IAM role the Grafana workspace assumes to query monitoring data sources."
  value       = aws_iam_role.grafana_monitoring_query_role.arn
}

output "grafana_monitoring_query_policy_arn" {
  description = "ARN of the least privilege monitoring query policy."
  value       = aws_iam_policy.grafana_monitoring_query_policy.arn
}

output "grafana_workspace_role_arn" {
  description = "ARN of the AWS Managed Grafana workspace execution role."
  value       = aws_iam_role.grafana_workspace_role.arn
}

output "prometheus_workspace_arn" {
  description = "ARN of the Amazon Managed Service for Prometheus workspace scoped by the query policy."
  value       = local.prometheus_workspace_arn
}

output "grafana_external_id_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the external ID used by the monitoring query role trust policy."
  value       = aws_secretsmanager_secret.grafana_external_id.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }

  # NOTE: No backend block is declared - state/backend is managed externally.
  # NOTE: No provider block is declared - the AWS provider (including region) is
  # injected by the deployment harness.
}

########################################
# Input variables (all with defaults so apply is unattended)
########################################
variable "project_name" {
  description = "Project / workload name used for tagging and naming."
  type        = string
  default     = "container-platform"
}

variable "environment" {
  description = "Environment name (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "RFC1918 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "Non-overlapping CIDRs for the two public subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]

  validation {
    condition     = length(var.public_subnet_cidrs) >= 2
    error_message = "At least two public subnet CIDRs are required (one per availability zone)."
  }
}

variable "private_subnet_cidrs" {
  description = "Non-overlapping CIDRs for the two private subnets (one per AZ), distinct from the public ranges."
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.12.0/24"]

  validation {
    condition     = length(var.private_subnet_cidrs) >= 2
    error_message = "At least two private subnet CIDRs are required (one per availability zone)."
  }
}

variable "service_discovery_namespace" {
  description = "Private service discovery DNS namespace for container workloads."
  type        = string
  default     = "service.local"
}

variable "application_ports" {
  description = "Application/container ports exposed by workloads (front-end app + PostgreSQL)."
  type = object({
    app = number
    db  = number
  })
  default = {
    app = 3000
    db  = 5432
  }
}

variable "vpc_flow_log_retention_days" {
  description = "Retention in days for the VPC flow log CloudWatch log group."
  type        = number
  default     = 90
}

########################################
# Locals
########################################
locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

########################################
# Static provider/account metadata (permitted local lookups)
########################################
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

########################################
# VPC
########################################
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

########################################
# Public subnets (one per AZ)
########################################
# NOTE: map_public_ip_on_launch is intentionally false. Public reachability for
# this tier comes from aws_route_table.public + aws_internet_gateway.main, so
# instances do not auto-receive a public IPv4 (AWS AVD-AWS-0164).
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[0]
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                     = "${local.name_prefix}-public-a"
    Tier                     = "public"
    "kubernetes.io/role/elb" = "1"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[1]
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                     = "${local.name_prefix}-public-b"
    Tier                     = "public"
    "kubernetes.io/role/elb" = "1"
  })
}

########################################
# Private subnets (one per AZ) - containerized workloads
########################################
resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[0]
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name                              = "${local.name_prefix}-private-a"
    Tier                              = "private"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[1]
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name                              = "${local.name_prefix}-private-b"
    Tier                              = "private"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

########################################
# Internet gateway + public routing
########################################
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

########################################
# Single NAT gateway (single-AZ egress)
########################################
# Trade-off: exactly ONE NAT gateway is provisioned, placed in public subnet A.
# Private workloads in BOTH private subnets egress through it. This is cost
# efficient but creates an availability dependency on the AZ hosting public_a -
# if that AZ fails, private workloads lose outbound connectivity. For HA, add a
# second EIP + NAT gateway in aws_subnet.public_b and a per-AZ private route table.
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id     = aws_eip.nat.id
  subnet_id         = aws_subnet.public_a.id
  connectivity_type = "public"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

########################################
# Private routing (both private subnets -> single NAT gateway)
########################################
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
    Tier = "private"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

########################################
# Dedicated CMK for CloudWatch Logs encryption
########################################
resource "aws_kms_key" "cloudwatch" {
  description             = "Customer managed key used to encrypt CloudWatch Logs (VPC flow logs) for ${local.name_prefix}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cloudwatch-cmk"
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${local.name_prefix}-cloudwatch"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# Key policy: account root retains administrative control; the CloudWatch Logs
# service principal is granted only the enumerated encrypt/decrypt/describe
# actions needed to write log data. No wildcard action paired with wildcard
# resource for the service principal.
resource "aws_kms_key_policy" "cloudwatch" {
  key_id = aws_kms_key.cloudwatch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUse"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
      }
    ]
  })
}

########################################
# VPC Flow Logs (ALL traffic, including rejects)
########################################
resource "aws_cloudwatch_log_group" "vpc_flow" {
  name              = "/aws/vpc/flow-logs/${local.name_prefix}"
  retention_in_days = var.vpc_flow_log_retention_days
  kms_key_id        = aws_kms_key.cloudwatch.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-flow-logs"
  })
}

resource "aws_iam_role" "vpc_flow_logs" {
  name = "${local.name_prefix}-vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "VpcFlowLogsAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-flow-logs-role"
  })
}

# Least privilege: enumerates only the two log-delivery actions, resource scoped
# to the flow log group ARN. No wildcard action combined with wildcard resource.
# CloudWatch Logs encrypts using the key policy service principal, so this
# delivery role needs no KMS permissions.
resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "${local.name_prefix}-vpc-flow-logs-policy"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "VpcFlowLogsDelivery"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.vpc_flow.arn,
          "${aws_cloudwatch_log_group.vpc_flow.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow.arn
  iam_role_arn         = aws_iam_role.vpc_flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-flow-log"
  })
}

########################################
# Application security group (explicit rules, no permissive default)
########################################
resource "aws_security_group" "app" {
  name        = "${local.name_prefix}-app"
  description = "Application SG for containerized workloads: SSH from VPC only, HTTP/HTTPS public, app/DB ports VPC-only"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app"
  })
}

# SSH: allowed ONLY from inside the VPC CIDR. Port 22 is never opened to 0.0.0.0/0.
resource "aws_vpc_security_group_ingress_rule" "ssh_from_vpc" {
  security_group_id = aws_security_group.app.id
  description       = "SSH from within the VPC CIDR only - never exposed to the internet"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
}

# HTTP: public ingress for internet-facing container traffic.
resource "aws_vpc_security_group_ingress_rule" "http_public" {
  security_group_id = aws_security_group.app.id
  description       = "HTTP from the internet for internet-facing container ingress"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

# HTTPS: public ingress for internet-facing container traffic.
resource "aws_vpc_security_group_ingress_rule" "https_public" {
  security_group_id = aws_security_group.app.id
  description       = "HTTPS from the internet for internet-facing container ingress"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
}

# Application port 3000.
# DEVIATION FROM REQUEST: tcp/3000 was requested from 0.0.0.0/0. The container
# application port is instead scoped to the VPC CIDR and reached through the
# public load balancer / ingress layer on 80/443. Open it to 0.0.0.0/0 only if
# direct public access to the app port is explicitly required.
resource "aws_vpc_security_group_ingress_rule" "app_3000_from_vpc" {
  security_group_id = aws_security_group.app.id
  description       = "Application port 3000 from within the VPC CIDR (deviation: request asked for 0.0.0.0/0)"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = var.application_ports.app
  to_port           = var.application_ports.app
}

# SECURITY EXCEPTION: tcp/5432 is PostgreSQL. The request asked for it from
# 0.0.0.0/0, which would expose the database to the entire internet. It is
# intentionally restricted to the VPC CIDR so only in-VPC clients can connect.
# Do NOT widen this rule without a documented, reviewed exception.
resource "aws_vpc_security_group_ingress_rule" "db_5432_from_vpc" {
  security_group_id = aws_security_group.app.id
  description       = "PostgreSQL 5432 from within the VPC CIDR only (SECURITY EXCEPTION: request asked for 0.0.0.0/0)"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = var.application_ports.db
  to_port           = var.application_ports.db
}

# Egress is restricted to the VPC CIDR as requested.
# WARNING: this blocks container image pulls (ECR/Docker Hub), OS package
# installs, and any other egress through the NAT gateway. If external pulls are
# required, enable the scoped HTTPS egress rule at the bottom of this file.
resource "aws_vpc_security_group_egress_rule" "vpc_only" {
  security_group_id = aws_security_group.app.id
  description       = "All egress restricted to the VPC CIDR (blocks image pulls/package installs and NAT internet egress)"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
}

# DOCUMENTED DEVIATION (disabled by default). Containerized workloads typically
# need to pull images and install packages over the internet via the NAT
# gateway. Enable this scoped HTTPS-only rule if external pull access is
# required and accept the deviation from "egress limited to the VPC CIDR":
#
# resource "aws_vpc_security_group_egress_rule" "https_to_internet" {
#   security_group_id = aws_security_group.app.id
#   description       = "HTTPS egress to the internet for container image pulls (documented deviation)"
#   cidr_ipv4         = "0.0.0.0/0"
#   ip_protocol       = "tcp"
#   from_port         = 443
#   to_port           = 443
# }

########################################
# Private service discovery namespace for containers
########################################
resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = var.service_discovery_namespace
  description = "Private DNS namespace used by containerized application tasks to register and resolve service names inside the VPC"
  vpc         = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-${var.service_discovery_namespace}"
  })
}

########################################
# Customer managed KMS key for secret encryption
########################################
resource "aws_kms_key" "secrets" {
  description             = "Customer managed key used to encrypt Secrets Manager secrets for ${local.name_prefix}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-secrets-cmk"
  })
}

resource "aws_kms_alias" "secrets" {
  name          = "alias/${local.name_prefix}-secrets"
  target_key_id = aws_kms_key.secrets.key_id
}

# Key policy granting the Secrets Manager service principal the minimum actions
# needed to encrypt/decrypt secret material via this CMK. Account root retains
# full administrative control of the key.
resource "aws_kms_key_policy" "secrets" {
  key_id = aws_kms_key.secrets.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSecretsManagerUse"
        Effect = "Allow"
        Principal = {
          Service = "secretsmanager.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
}

########################################
# Generated database credentials (never stored in plaintext in config)
########################################
resource "random_password" "app_db" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "app_db" {
  name                    = "${local.name_prefix}/app/database/credentials"
  description             = "Generated credentials for the containerized application database; consumed by ARN reference only."
  kms_key_id              = aws_kms_key.secrets.arn
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-db-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "app_db" {
  secret_id = aws_secretsmanager_secret.app_db.id

  secret_string = jsonencode({
    username = "app"
    password = random_password.app_db.result
    engine   = "postgres"
    host     = "app-db.${var.service_discovery_namespace}"
    port     = var.application_ports.db
    dbname   = "app"
  })
}

########################################
# Outputs
########################################
output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets (one per AZ)."
  value       = [aws_subnet.public_a.id, aws_subnet.public_b.id]
}

output "private_subnet_ids" {
  description = "IDs of the private subnets (one per AZ)."
  value       = [aws_subnet.private_a.id, aws_subnet.private_b.id]
}

output "app_security_group_id" {
  description = "ID of the application security group."
  value       = aws_security_group.app.id
}

output "nat_gateway_id" {
  description = "ID of the single NAT gateway used for private subnet egress."
  value       = aws_nat_gateway.main.id
}

output "service_discovery_namespace_id" {
  description = "ID of the private service discovery DNS namespace."
  value       = aws_service_discovery_private_dns_namespace.main.id
}

output "service_discovery_namespace_arn" {
  description = "ARN of the private service discovery DNS namespace."
  value       = aws_service_discovery_private_dns_namespace.main.arn
}

output "vpc_flow_log_id" {
  description = "ID of the VPC flow log."
  value       = aws_flow_log.main.id
}

output "cloudwatch_kms_key_arn" {
  description = "ARN of the customer managed KMS key used for CloudWatch Logs encryption."
  value       = aws_kms_key.cloudwatch.arn
}

output "secrets_kms_key_arn" {
  description = "ARN of the customer managed KMS key used for secret encryption."
  value       = aws_kms_key.secrets.arn
}

output "app_db_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the generated database credentials."
  value       = aws_secretsmanager_secret.app_db.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "project" {
  description = "Project name used as a prefix for all resource names and tags."
  type        = string
  default     = "cognito-identity"
}

variable "environment" {
  description = "Deployment environment name (for example dev, staging or prod)."
  type        = string
  default     = "dev"
}

variable "callback_urls" {
  description = "Explicit OAuth 2.0 callback URLs for the app client. Wildcards are not permitted."
  type        = list(string)
  default     = ["https://app.example.com/oauth2/callback"]
}

variable "logout_urls" {
  description = "Explicit OAuth 2.0 logout URLs for the app client. Wildcards are not permitted."
  type        = list(string)
  default     = ["https://app.example.com/oauth2/logout"]
}

###############################################################################
# Provider metadata (static lookups only - no pre-existing infrastructure)
###############################################################################

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Local values
###############################################################################

locals {
  name_prefix = "${var.project}-${var.environment}"

  cognito_provider_name = "cognito-idp.${data.aws_region.current.name}.amazonaws.com/${aws_cognito_user_pool.main.id}"

  cognito_sync_resource_prefix = "arn:${data.aws_partition.current.partition}:cognito-sync:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
    Name        = local.name_prefix
  }
}

###############################################################################
# Cognito User Pool (root stateful identity store)
###############################################################################

resource "aws_cognito_user_pool" "main" {
  name = "${local.name_prefix}-user-pool"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "ON"

  software_token_mfa_configuration {
    enabled = true
  }

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  user_pool_add_ons {
    advanced_security_mode = "ENFORCED"
  }

  user_pool_tier = "PLUS"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-user-pool" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Cognito User Pool App Client (public mobile / SPA client - no secret)
###############################################################################

resource "aws_cognito_user_pool_client" "app" {
  name         = "${local.name_prefix}-app-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  supported_identity_providers = ["COGNITO"]

  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid", "profile"]
  allowed_oauth_flows_user_pool_client = true

  callback_urls = var.callback_urls
  logout_urls   = var.logout_urls

  enable_token_revocation       = true
  prevent_user_existence_errors = "ENABLED"

  access_token_validity  = 60
  id_token_validity      = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

###############################################################################
# Cognito Identity Pool (federated with the user pool above)
###############################################################################

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "${local.name_prefix}-identity-pool"
  allow_unauthenticated_identities = false
  allow_classic_flow               = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.app.id
    provider_name           = local.cognito_provider_name
    server_side_token_check = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-identity-pool" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM role assumed by authenticated identities only
###############################################################################

data "aws_iam_policy_document" "authenticated_assume_role" {
  statement {
    sid     = "AllowCognitoAuthenticatedIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name        = "${local.name_prefix}-authenticated-role"
  description = "Role assumed by authenticated identities of the ${local.name_prefix} identity pool."

  assume_role_policy = data.aws_iam_policy_document.authenticated_assume_role.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-authenticated-role" })
}

###############################################################################
# Least-privilege policy for authenticated identities
###############################################################################

data "aws_iam_policy_document" "authenticated_permissions" {
  statement {
    sid    = "AllowCognitoSyncScopedToIdentityPool"
    effect = "Allow"

    actions = [
      "cognito-sync:DescribeDataset",
      "cognito-sync:DescribeIdentityPoolUsage",
      "cognito-sync:DescribeIdentityUsage",
      "cognito-sync:GetBulkPublishDetails",
      "cognito-sync:GetCognitoEvents",
      "cognito-sync:GetIdentityPoolConfiguration",
      "cognito-sync:ListDatasets",
      "cognito-sync:ListIdentityPoolUsage",
      "cognito-sync:ListRecords",
      "cognito-sync:SubscribeToDataset",
      "cognito-sync:UnsubscribeFromDataset",
      "cognito-sync:UpdateRecords",
    ]

    resources = [
      local.cognito_sync_resource_prefix,
      "${local.cognito_sync_resource_prefix}/identity/*",
      "${local.cognito_sync_resource_prefix}/identity/*/dataset/*",
    ]
  }

  statement {
    sid    = "AllowMobileAnalyticsPutEvents"
    effect = "Allow"

    actions   = ["mobileanalytics:PutEvents"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "authenticated" {
  name        = "${local.name_prefix}-authenticated-policy"
  description = "Least-privilege Cognito Sync and Mobile Analytics access for authenticated identities."

  policy = data.aws_iam_policy_document.authenticated_permissions.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-authenticated-policy" })
}

resource "aws_iam_role_policy_attachment" "authenticated" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.authenticated.arn
}

###############################################################################
# Bind the authenticated role to the identity pool
###############################################################################

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated = aws_iam_role.authenticated.arn
  }

  role_mapping {
    identity_provider         = local.cognito_provider_name
    type                      = "Token"
    ambiguous_role_resolution = "AuthenticatedRole"
  }
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "name_prefix" {
  description = "Prefix used when naming and tagging the resources created by this module."
  type        = string
  default     = "kms"
}

variable "description" {
  description = "Description applied to the KMS key that is created."
  type        = string
  default     = "Customer managed KMS key managed by Terraform"
}

variable "tags" {
  description = "A map of tags to apply to all taggable resources created by this module."
  type        = map(string)
  default     = {}
}

variable "deletion_window_in_days" {
  description = "Number of days before the KMS key is permanently deleted after destruction is scheduled."
  type        = number
  default     = 30

  validation {
    condition     = var.deletion_window_in_days >= 7 && var.deletion_window_in_days <= 30
    error_message = "deletion_window_in_days must be a value between 7 and 30."
  }
}

# ------------------------------------------------------------------------------
# Mutually exclusive creation flags - exactly one may be enabled per apply.
# ------------------------------------------------------------------------------

variable "create_standard_key" {
  description = "Create a standard customer managed KMS key backed by AWS provided key material. Mutually exclusive with the other create_* flags."
  type        = bool
  default     = true
}

variable "create_external_key" {
  description = "Create an external KMS key that is backed by imported (base64 encoded) key material. Mutually exclusive with the other create_* flags."
  type        = bool
  default     = false
}

variable "create_replica_key" {
  description = "Create a multi-region replica KMS key that references a primary key ARN. Mutually exclusive with the other create_* flags."
  type        = bool
  default     = false
}

variable "create_replica_external_key" {
  description = "Create a multi-region replica external KMS key with custom key material and a primary external key ARN. Mutually exclusive with the other create_* flags."
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# Key material / replication inputs
# ------------------------------------------------------------------------------

variable "key_material_base64" {
  description = "Base64 encoded 256-bit symmetric key material used by the external and replica external key variants. Never hardcode this value."
  type        = string
  default     = null
  sensitive   = true
}

variable "primary_key_arn" {
  description = "ARN of the multi-region primary key that the replica key variants are created from."
  type        = string
  default     = null
}

# ------------------------------------------------------------------------------
# Key policy principals
# ------------------------------------------------------------------------------

variable "key_owners" {
  description = "List of IAM principal ARNs that own the key and are allowed to administer it."
  type        = list(string)
  default     = []
}

variable "key_administrators" {
  description = "List of IAM principal ARNs allowed to administer (but not use) the key."
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "List of IAM principal ARNs allowed to use the key for standard cryptographic operations."
  type        = list(string)
  default     = []
}

variable "key_service_users" {
  description = "List of AWS service principals (for example logs.us-east-1.amazonaws.com) allowed to use the key."
  type        = list(string)
  default     = []
}

variable "key_ec2_autoscaling_users" {
  description = "List of IAM principal ARNs (Auto Scaling service-linked roles) allowed to use the key for EC2 Auto Scaling."
  type        = list(string)
  default     = []
}

variable "key_symmetric_encryption_users" {
  description = "List of IAM principal ARNs allowed to use the key for symmetric encrypt/decrypt operations."
  type        = list(string)
  default     = []
}

variable "key_hmac_users" {
  description = "List of IAM principal ARNs allowed to use the key for HMAC generate/verify operations."
  type        = list(string)
  default     = []
}

variable "key_asymmetric_public_encryption_users" {
  description = "List of IAM principal ARNs allowed to use the key for asymmetric public encryption operations."
  type        = list(string)
  default     = []
}

variable "key_asymmetric_sign_verify_users" {
  description = "List of IAM principal ARNs allowed to use the key for asymmetric sign/verify operations."
  type        = list(string)
  default     = []
}

variable "enable_route53_dnssec" {
  description = "When true, a statement that allows the Route 53 DNSSEC signing service principal to use the key is added to the key policy."
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# Custom policy inputs
# ------------------------------------------------------------------------------

variable "custom_policy_documents" {
  description = "List of additional JSON IAM policy documents whose statements are merged with the generated key policy statements."
  type        = list(string)
  default     = []
}

variable "policy_override_json" {
  description = "A complete JSON key policy document that replaces the generated key policy entirely. When set, custom_policy_documents and the generated statements are ignored."
  type        = string
  default     = null
}

# ------------------------------------------------------------------------------
# Aliases and grants
# ------------------------------------------------------------------------------

variable "alias_names" {
  description = "List of exact alias names (with or without the 'alias/' prefix) to create for the key."
  type        = list(string)
  default     = []
}

variable "alias_name_prefix" {
  description = "Prefix used to generate a unique alias name for the key. Mutually exclusive with alias_names; used only when alias_names is empty."
  type        = string
  default     = null
}

variable "grants" {
  description = "Map of KMS grants to create on the key, keyed by grant name."
  type = map(object({
    grantee_principal  = string
    operations         = list(string)
    retiring_principal = optional(string)
    constraints = optional(list(object({
      encryption_context_equals = optional(map(string))
      encryption_context_subset = optional(map(string))
    })))
  }))
  default = {}
}

################################################################################
# Data sources
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "key_policy" {
  source_policy_documents = var.custom_policy_documents

  statement {
    sid       = "DefaultRootAccess"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = [local.key_arn]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  dynamic "statement" {
    for_each = length(var.key_administrators) > 0 ? [1] : []

    content {
      sid       = "KeyAdministrators"
      effect    = "Allow"
      actions   = local.key_management_actions
      resources = [local.key_arn]

      principals {
        type        = "AWS"
        identifiers = var.key_administrators
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_owners) > 0 ? [1] : []

    content {
      sid       = "KeyOwners"
      effect    = "Allow"
      actions   = local.key_management_actions
      resources = [local.key_arn]

      principals {
        type        = "AWS"
        identifiers = var.key_owners
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []

    content {
      sid       = "KeyUsers"
      effect    = "Allow"
      actions   = local.key_usage_actions
      resources = [local.key_arn]

      principals {
        type        = "AWS"
        identifiers = var.key_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []

    content {
      sid       = "KeyUsersGrantAttachment"
      effect    = "Allow"
      actions   = local.key_grant_actions
      resources = [local.key_arn]

      principals {
        type        = "AWS"
        identifiers = var.key_users
      }

      condition {
        test     = "Bool"
        variable = "kms:GrantIsForAWSResource"
        values   = ["true"]
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_service_users) > 0 ? [1] : []

    content {
      sid       = "KeyServiceUsers"
      effect    = "Allow"
      actions   = local.key_usage_actions
      resources = [local.key_arn]

      principals {
        type        = "Service"
        identifiers = var.key_service_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_service_users) > 0 ? [1] : []

    content {
      sid       = "KeyServiceUsersGrantAttachment"
      effect    = "Allow"
      actions   = local.key_grant_actions
      resources = [local.key_arn]

      principals {
        type        = "Service"
        identifiers = var.key_service_users
      }

      condition {
        test     = "Bool"
        variable = "kms:GrantIsForAWSResource"
        values   = ["true"]
      }

      condition {
        test     = "StringEquals"
        variable = "kms:CallerAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_ec2_autoscaling_users) > 0 ? [1] : []

    content {
      sid       = "EC2AutoScalingUseOfKey"
      effect    = "Allow"
      actions   = local.autoscaling_actions
      resources = [local.key_arn]

      principals {
        type        = "AWS"
        identifiers = var.key_ec2_autoscaling_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_symmetric_encryption_users) > 0 ? [1] : []

    content {
      sid       = "SymmetricEncryptionUseOfKey"
      effect    = "Allow"
      actions   = local.symmetric_encryption_actions
      resources = [local.key_arn]

      principals {
        type        = "AWS"
        identifiers = var.key_symmetric_encryption_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_hmac_users) > 0 ? [1] : []

    content {
      sid       = "HMACUseOfKey"
      effect    = "Allow"
      actions   = local.hmac_actions
      resources = [local.key_arn]

      principals {
        type        = "AWS"
        identifiers = var.key_hmac_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_asymmetric_public_encryption_users) > 0 ? [1] : []

    content {
      sid       = "AsymmetricPublicEncryptionUseOfKey"
      effect    = "Allow"
      actions   = local.asymmetric_public_encryption_actions
      resources = [local.key_arn]

      principals {
        type        = "AWS"
        identifiers = var.key_asymmetric_public_encryption_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_asymmetric_sign_verify_users) > 0 ? [1] : []

    content {
      sid       = "AsymmetricSignVerifyUseOfKey"
      effect    = "Allow"
      actions   = local.asymmetric_sign_verify_actions
      resources = [local.key_arn]

      principals {
        type        = "AWS"
        identifiers = var.key_asymmetric_sign_verify_users
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_route53_dnssec ? [1] : []

    content {
      sid       = "Route53DnssecSigningService"
      effect    = "Allow"
      actions   = ["kms:DescribeKey", "kms:GetPublicKey", "kms:Sign"]
      resources = [local.key_arn]

      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = ["arn:${data.aws_partition.current.partition}:route53:::hostedzone/*"]
      }
    }
  }
}

################################################################################
# Locals
################################################################################

locals {
  tags = merge(
    {
      ManagedBy = "terraform"
      Module    = "kms"
    },
    var.tags,
  )

  key_arn = one(concat(
    aws_kms_key.standard[*].arn,
    aws_kms_external_key.external[*].arn,
    aws_kms_replica_key.replica[*].arn,
    aws_kms_replica_external_key.replica_external[*].arn,
  ))

  key_id = one(concat(
    aws_kms_key.standard[*].key_id,
    aws_kms_external_key.external[*].key_id,
    aws_kms_replica_key.replica[*].key_id,
    aws_kms_replica_external_key.replica_external[*].key_id,
  ))

  key_policy_json = var.policy_override_json != null ? var.policy_override_json : data.aws_iam_policy_document.key_policy.json

  # Key administration / ownership actions
  key_management_actions = [
    "kms:Create*",
    "kms:Describe*",
    "kms:Enable*",
    "kms:List*",
    "kms:Put*",
    "kms:Update*",
    "kms:Revoke*",
    "kms:Disable*",
    "kms:Get*",
    "kms:TagResource",
    "kms:UntagResource",
    "kms:ScheduleKeyDeletion",
    "kms:CancelKeyDeletion",
  ]

  # Standard cryptographic use actions
  key_usage_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncrypt*",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
  ]

  # Grant management actions, always paired with the kms:GrantIsForAWSResource condition
  key_grant_actions = [
    "kms:CreateGrant",
    "kms:ListGrants",
    "kms:RevokeGrant",
  ]

  symmetric_encryption_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncrypt*",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
  ]

  hmac_actions = [
    "kms:GenerateMac",
    "kms:VerifyMac",
  ]

  asymmetric_public_encryption_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:DescribeKey",
  ]

  asymmetric_sign_verify_actions = [
    "kms:Sign",
    "kms:Verify",
    "kms:DescribeKey",
  ]

  autoscaling_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncrypt*",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
  ]

  use_alias_name_prefix = length(var.alias_names) == 0 && var.alias_name_prefix != null

  aliases = local.use_alias_name_prefix ? {
    (var.alias_name_prefix) = var.alias_name_prefix
    } : {
    for alias_name in var.alias_names :
    trimprefix(alias_name, "alias/") => alias_name
  }
}

################################################################################
# Guard rails - enforce mutually exclusive variants and scoped key material
################################################################################

resource "terraform_data" "validation" {
  lifecycle {
    precondition {
      condition = length([
        for enabled in [
          var.create_standard_key,
          var.create_external_key,
          var.create_replica_key,
          var.create_replica_external_key,
        ] : enabled if enabled
      ]) == 1
      error_message = "Exactly one of create_standard_key, create_external_key, create_replica_key or create_replica_external_key must be true."
    }

    precondition {
      condition = (var.create_external_key || var.create_replica_external_key) == (var.key_material_base64 != null)
      error_message = "key_material_base64 must be supplied for (and only for) the external and replica external key variants."
    }

    precondition {
      condition = (var.create_replica_key || var.create_replica_external_key) == (var.primary_key_arn != null)
      error_message = "primary_key_arn must be supplied for (and only for) the replica key variants."
    }
  }
}

################################################################################
# KMS keys - exactly one variant is created per apply
################################################################################

resource "aws_kms_key" "standard" {
  count = var.create_standard_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  enable_key_rotation     = true
  is_enabled              = true

  tags = merge(local.tags, { Name = "${var.name_prefix}-standard" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_external_key" "external" {
  count = var.create_external_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  enabled                 = true
  key_material_base64     = var.key_material_base64

  tags = merge(local.tags, { Name = "${var.name_prefix}-external" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_key" "replica" {
  count = var.create_replica_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  enabled                 = true
  primary_key_arn         = var.primary_key_arn

  tags = merge(local.tags, { Name = "${var.name_prefix}-replica" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_external_key" "replica_external" {
  count = var.create_replica_external_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  enabled                 = true
  primary_key_arn         = var.primary_key_arn
  key_material_base64     = var.key_material_base64

  tags = merge(local.tags, { Name = "${var.name_prefix}-replica-external" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key_policy" "this" {
  key_id = local.key_id
  policy = local.key_policy_json
}

################################################################################
# Aliases
################################################################################

resource "aws_kms_alias" "this" {
  for_each = local.aliases

  name          = local.use_alias_name_prefix ? null : (startswith(each.value, "alias/") ? each.value : "alias/${each.value}")
  name_prefix   = local.use_alias_name_prefix ? "${each.value}-" : null
  target_key_id = local.key_id
}

################################################################################
# Grants
################################################################################

resource "aws_kms_grant" "this" {
  for_each = var.grants

  name               = each.key
  key_id             = local.key_id
  grantee_principal  = each.value.grantee_principal
  operations         = each.value.operations
  retiring_principal = each.value.retiring_principal

  dynamic "constraints" {
    for_each = coalesce(each.value.constraints, [])

    content {
      encryption_context_equals = constraints.value.encryption_context_equals
      encryption_context_subset = constraints.value.encryption_context_subset
    }
  }
}

################################################################################
# Outputs
################################################################################

output "key_arn" {
  description = "ARN of the KMS key created by this module."
  value       = local.key_arn
}

output "key_id" {
  description = "ID of the KMS key created by this module."
  value       = local.key_id
}

output "key_policy" {
  description = "JSON key policy document applied to the KMS key."
  value       = local.key_policy_json
}

output "standard_key_arn" {
  description = "ARN of the standard KMS key, if created."
  value       = one(aws_kms_key.standard[*].arn)
}

output "external_key_arn" {
  description = "ARN of the external KMS key, if created."
  value       = one(aws_kms_external_key.external[*].arn)
}

output "replica_key_arn" {
  description = "ARN of the multi-region replica KMS key, if created."
  value       = one(aws_kms_replica_key.replica[*].arn)
}

output "replica_external_key_arn" {
  description = "ARN of the multi-region replica external KMS key, if created."
  value       = one(aws_kms_replica_external_key.replica_external[*].arn)
}

output "alias_arns" {
  description = "Map of alias name to alias ARN."
  value       = { for name, alias in aws_kms_alias.this : name => alias.arn }
}

output "alias_names" {
  description = "Map of alias name to the fully qualified alias name."
  value       = { for name, alias in aws_kms_alias.this : name => alias.name }
}

output "grant_ids" {
  description = "Map of grant name to grant ID."
  value       = { for name, grant in aws_kms_grant.this : name => grant.grant_id }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = "10.0.0.0/16"

  azs                  = slice(data.aws_availability_zones.available.names, 0, 3)
  enable_dns_hostnames = true
  enable_dns_support   = true

  private_subnets = [
    cidrsubnet("10.0.0.0/16", 4, 0),
    cidrsubnet("10.0.0.0/16", 4, 1),
    cidrsubnet("10.0.0.0/16", 4, 2),
  ]

  public_subnets = [
    cidrsubnet("10.0.0.0/16", 8, 48),
    cidrsubnet("10.0.0.0/16", 8, 49),
    cidrsubnet("10.0.0.0/16", 8, 50),
  ]

  create_igw = true

  enable_nat_gateway     = true
  single_nat_gateway     = true
  one_nat_gateway_per_az = false

  map_public_ip_on_launch = false

  enable_flow_log                                 = true
  create_flow_log_cloudwatch_log_group            = true
  create_flow_log_cloudwatch_iam_role             = true
  flow_log_traffic_type                           = "ALL"
  flow_log_cloudwatch_log_group_retention_in_days = 90

  tags = local.common_tags

  vpc_tags = local.common_tags

  public_subnet_tags = merge(
    local.common_tags,
    {
      "kubernetes.io/role/elb" = "1"
    }
  )

  private_subnet_tags = merge(
    local.common_tags,
    {
      "kubernetes.io/role/internal-elb" = "1"
    }
  )
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster1 allowing reciprocal all-protocol communication with cluster2"
  vpc_id      = module.vpc.vpc_id

  tags = merge(
    local.common_tags,
    {
      Name = "cluster1_additional_sg"
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster2 allowing reciprocal all-protocol communication with cluster1"
  vpc_id      = module.vpc.vpc_id

  tags = merge(
    local.common_tags,
    {
      Name = "cluster2_additional_sg"
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "cluster1_from_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  description                  = "Allow all protocols inbound to cluster1 from cluster2 security group"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id

  tags = local.common_tags
}

resource "aws_vpc_security_group_ingress_rule" "cluster2_from_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  description                  = "Allow all protocols inbound to cluster2 from cluster1 security group"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "cluster1_to_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  description                  = "Allow all protocols outbound from cluster1 to cluster2 security group"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "cluster2_to_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  description                  = "Allow all protocols outbound from cluster2 to cluster1 security group"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id

  tags = local.common_tags
}

variable "vpc_name" {
  description = "Name of the VPC and the value applied to the Blueprint tag"
  type        = string
  default     = "blueprint-vpc"
}

output "vpc_id" {
  description = "ID of the VPC created by the VPC module"
  value       = module.vpc.vpc_id
}

output "private_subnets" {
  description = "List of private subnet IDs created by the VPC module"
  value       = module.vpc.private_subnets
}

output "public_subnets" {
  description = "List of public subnet IDs created by the VPC module"
  value       = module.vpc.public_subnets
}

output "cluster1_additional_sg_id" {
  description = "ID of the additional security group for cluster1"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "ID of the additional security group for cluster2"
  value       = aws_security_group.cluster2_additional_sg.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

###############################################################################
# Static provider metadata (no pre-existing infrastructure is looked up)
###############################################################################

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Variables - user pool identity and behaviour
###############################################################################

variable "pool_name" {
  description = "Name of the Cognito user pool."
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes that can be used as aliases for user sign-in."
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes that Cognito automatically verifies."
  type        = list(string)
  default     = []
}

variable "mfa_configuration" {
  description = "MFA configuration for the user pool (OFF, ON, OPTIONAL)."
  type        = string
  default     = "OPTIONAL"
}

variable "admin_create_user_only" {
  description = "When true only administrators may create users."
  type        = bool
  default     = false
}

variable "software_token_mfa_enabled" {
  description = "Enables TOTP software token MFA for the user pool."
  type        = bool
  default     = true
}

variable "username_case_sensitive" {
  description = "Whether usernames are case sensitive. When null the username_configuration block is omitted."
  type        = bool
  default     = null
}

variable "device_configuration" {
  description = "Optional device tracking configuration. When null the block is omitted."
  type = object({
    challenge_required_on_new_device      = optional(bool, false)
    device_only_remembered_on_user_prompt = optional(bool, false)
  })
  default = null
}

variable "lambda_config" {
  description = "Optional Cognito Lambda triggers. Enabled triggers reference Lambda functions declared in this configuration."
  type = object({
    custom_email_sender = optional(bool, false)
    custom_sms_sender   = optional(bool, false)
  })
  default = {}
}

variable "schema" {
  description = "Custom attribute schema for the user pool. min_length/max_length are optional."
  type        = list(any)
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      required            = true
      mutable             = true
    }
  ]
}

###############################################################################
# Variables - verification and invitation messaging
###############################################################################

variable "email_verification_message" {
  description = "Email message used to verify a user account."
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Subject of the email verification message."
  type        = string
  default     = "Some subject"
}

variable "email_verification_message_by_link" {
  description = "Email verification message used when verification is done by link."
  type        = string
  default     = "Please click the link below to verify your email address. {##Verify Email##}"
}

variable "email_verification_subject_by_link" {
  description = "Subject used when email verification is done by link."
  type        = string
  default     = "Verify your email address"
}

variable "verification_message_template_default_email_option" {
  description = "Default email verification option (CONFIRM_WITH_CODE or CONFIRM_WITH_LINK)."
  type        = string
  default     = "CONFIRM_WITH_CODE"
}

variable "sms_authentication_message" {
  description = "SMS message used for MFA authentication."
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS message used to verify a phone number."
  type        = string
  default     = "SMS verification message {####}"
}

variable "invite_email_message" {
  description = "Email message sent when an administrator creates a user."
  type        = string
  default     = "Your username is {username} and temporary password is {####}."
}

variable "invite_email_subject" {
  description = "Subject of the administrator invite email."
  type        = string
  default     = "Your temporary password"
}

variable "invite_sms_message" {
  description = "SMS message sent when an administrator creates a user."
  type        = string
  default     = "Your username is {username} and temporary password is {####}."
}

###############################################################################
# Variables - SMS configuration and account recovery
###############################################################################

variable "sms_configuration" {
  description = "SMS configuration. The sms_configuration block is rendered only when both external_id and sns_caller_arn are non-empty."
  type        = map(string)
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
}

variable "recovery_mechanisms" {
  description = "Account recovery mechanisms and their priorities."
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    {
      name     = "verified_email"
      priority = 2
    },
    {
      name     = "verified_phone_number"
      priority = 1
    }
  ]
}

###############################################################################
# Variables - user pool clients
###############################################################################

variable "client_app_names" {
  description = "Names of the user pool clients (app clients) to create."
  type        = list(string)
  default     = []
}

variable "client_generate_secret" {
  description = "Whether app clients are created with a generated secret."
  type        = bool
  default     = false
}

variable "allowed_oauth_user_pool_client" {
  description = "Whether the app clients are allowed to use OAuth flows."
  type        = bool
  default     = false
}

variable "callback_urls" {
  description = "Allowed callback URLs for the app clients."
  type        = list(string)
  default     = []
}

variable "logout_urls" {
  description = "Allowed logout URLs for the app clients."
  type        = list(string)
  default     = []
}

variable "allowed_oauth_flows" {
  description = "Allowed OAuth flows for the app clients."
  type        = list(string)
  default     = ["code"]
}

variable "allowed_oauth_scopes" {
  description = "Allowed OAuth scopes for the app clients."
  type        = list(string)
  default     = ["email", "openid", "profile"]
}

variable "supported_identity_providers" {
  description = "Supported identity providers for the app clients."
  type        = list(string)
  default     = ["COGNITO"]
}

variable "read_attributes" {
  description = "Attributes the app clients may read."
  type        = list(string)
  default     = ["email"]
}

variable "write_attributes" {
  description = "Attributes the app clients may write."
  type        = list(string)
  default     = ["email"]
}

variable "access_token_validity" {
  description = "Access token validity value."
  type        = number
  default     = 120
}

variable "id_token_validity" {
  description = "ID token validity value."
  type        = number
  default     = 120
}

variable "refresh_token_validity" {
  description = "Refresh token validity value."
  type        = number
  default     = 7
}

variable "token_validity_units" {
  description = "Units for the token validity values."
  type = object({
    access_token  = string
    id_token      = string
    refresh_token = string
  })
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

###############################################################################
# Variables - user group, domain and DNS
###############################################################################

variable "user_group_name" {
  description = "Name of the user group to create. When empty no group is created."
  type        = string
  default     = ""
}

variable "user_group_precedence" {
  description = "Precedence of the user group."
  type        = number
  default     = 0
}

variable "user_group_role_arn" {
  description = "Optional IAM role ARN associated with the user group."
  type        = string
  default     = ""
}

variable "user_group_description" {
  description = "Description of the user group."
  type        = string
  default     = "Cognito user group managed by Terraform"
}

variable "domain_name" {
  description = "Custom (or prefix) domain for the user pool. When empty no domain is created."
  type        = string
  default     = ""
}

variable "domain_certificate_arn" {
  description = "Optional ACM certificate ARN for a custom domain."
  type        = string
  default     = ""
}

variable "create_route53_record" {
  description = "Whether to create the Route 53 alias record for the user pool domain."
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID used when creating the alias record."
  type        = string
  default     = ""
}

###############################################################################
# Variables - custom sender settings and tags
###############################################################################

variable "custom_email_sender_from_address" {
  description = "Sender address used by the custom email sender Lambda function."
  type        = string
  default     = "noreply@example.com"
}

variable "custom_sender_lambda_log_retention_days" {
  description = "CloudWatch log retention for the custom sender Lambda functions."
  type        = number
  default     = 14
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = lower(replace(var.pool_name, " ", "-"))

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  sms_external_id    = lookup(var.sms_configuration, "external_id", "")
  sms_sns_caller_arn = lookup(var.sms_configuration, "sns_caller_arn", "")
  sms_enabled        = local.sms_external_id != "" && local.sms_sns_caller_arn != ""

  sns_caller_arn = local.sms_sns_caller_arn != "" ? local.sms_sns_caller_arn : aws_iam_role.sns_caller.arn

  sns_caller_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      merge(
        {
          Effect    = "Allow"
          Principal = { Service = "cognito-idp.amazonaws.com" }
          Action    = "sts:AssumeRole"
        },
        local.sms_external_id != "" ? {
          Condition = {
            StringEquals = {
              "sts:ExternalId" = local.sms_external_id
            }
          }
        } : {}
      )
    ]
  })

  # Fixed, well-known CloudFront hosted zone ID used by Cognito custom domains.
  cloudfront_hosted_zone_id = "Z2FDTNDATAQYW2"

  lambda_triggers_enabled = var.lambda_config.custom_email_sender || var.lambda_config.custom_sms_sender

  tags = merge(var.tags, { Name = var.pool_name })
}

###############################################################################
# Cognito user pool
###############################################################################

resource "aws_cognito_user_pool" "this" {
  name                       = var.pool_name
  alias_attributes           = var.alias_attributes
  auto_verified_attributes   = var.auto_verified_attributes
  mfa_configuration          = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message

  dynamic "sms_configuration" {
    for_each = local.sms_enabled ? [1] : []

    content {
      sns_caller_arn = local.sns_caller_arn
      external_id    = local.sms_external_id
    }
  }

  dynamic "username_configuration" {
    for_each = var.username_case_sensitive != null ? [1] : []

    content {
      case_sensitive = var.username_case_sensitive
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []

    content {
      challenge_required_on_new_device      = device_configuration.value.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = device_configuration.value.device_only_remembered_on_user_prompt
    }
  }

  verification_message_template {
    default_email_option  = var.verification_message_template_default_email_option
    email_message         = var.email_verification_message
    email_message_by_link = var.email_verification_message_by_link
    email_subject         = var.email_verification_subject
    email_subject_by_link = var.email_verification_subject_by_link
    sms_message           = var.sms_verification_message
  }

  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = var.recovery_mechanisms

      content {
        name     = recovery_mechanism.value.name
        priority = recovery_mechanism.value.priority
      }
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only

    invite_message_template {
      email_message = var.invite_email_message
      email_subject = var.invite_email_subject
      sms_message   = var.invite_sms_message
    }
  }

  software_token_mfa_configuration {
    enabled = var.software_token_mfa_enabled
  }

  dynamic "schema" {
    for_each = var.schema

    content {
      name                     = schema.value.name
      attribute_data_type      = lookup(schema.value, "attribute_data_type", "String")
      developer_only_attribute = try(schema.value.developer_only_attribute, null)
      mutable                  = try(schema.value.mutable, null)
      required                 = try(schema.value.required, null)

      dynamic "string_attribute_constraints" {
        for_each = (try(schema.value.min_length, null) != null || try(schema.value.max_length, null) != null) ? [1] : []

        content {
          min_length = try(schema.value.min_length, null)
          max_length = try(schema.value.max_length, null)
        }
      }

      dynamic "number_attribute_constraints" {
        for_each = (try(schema.value.min_value, null) != null || try(schema.value.max_value, null) != null) ? [1] : []

        content {
          min_value = try(schema.value.min_value, null)
          max_value = try(schema.value.max_value, null)
        }
      }
    }
  }

  dynamic "lambda_config" {
    for_each = local.lambda_triggers_enabled ? [1] : []

    content {
      kms_key_id = aws_kms_key.custom_sender.arn

      dynamic "custom_email_sender" {
        for_each = var.lambda_config.custom_email_sender ? [1] : []

        content {
          lambda_arn     = aws_lambda_function.custom_email_sender.arn
          lambda_version = "V1_0"
        }
      }

      dynamic "custom_sms_sender" {
        for_each = var.lambda_config.custom_sms_sender ? [1] : []

        content {
          lambda_arn     = aws_lambda_function.custom_sms_sender.arn
          lambda_version = "V1_0"
        }
      }
    }
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# KMS key used to encrypt verification codes for the custom senders
###############################################################################

resource "aws_kms_key" "custom_sender" {
  description             = "KMS key used by the Cognito custom email and SMS sender Lambda functions"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.tags
}

resource "aws_kms_alias" "custom_sender" {
  name          = "alias/${local.name_prefix}-cognito-custom-sender"
  target_key_id = aws_kms_key.custom_sender.key_id
}

###############################################################################
# KMS key used to encrypt the CloudWatch log groups
###############################################################################

resource "aws_kms_key" "cloudwatch_logs" {
  description             = "CMK used to encrypt CloudWatch log groups for the Cognito custom sender functions"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAdministration"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion",
          "kms:TagResource",
          "kms:UntagResource",
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowCloudWatchLogs"
        Effect    = "Allow"
        Principal = { Service = "logs.${local.region}.amazonaws.com" }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*",
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${local.partition}:logs:${local.region}:${local.account_id}:*"
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "cloudwatch_logs" {
  name          = "alias/${local.name_prefix}-cloudwatch-logs"
  target_key_id = aws_kms_key.cloudwatch_logs.key_id
}

###############################################################################
# Secrets Manager secret holding the SMS external ID
###############################################################################

resource "aws_secretsmanager_secret" "sms_external_id" {
  name        = "${local.name_prefix}-sms-external-id"
  description = "External ID used by the Cognito user pool SNS caller role"
  kms_key_id  = aws_kms_key.custom_sender.arn

  tags = local.tags
}

resource "aws_secretsmanager_secret_version" "sms_external_id" {
  secret_id     = aws_secretsmanager_secret.sms_external_id.id
  secret_string = jsonencode({ external_id = local.sms_external_id })
}

###############################################################################
# Custom email sender Lambda stack
###############################################################################

resource "aws_cloudwatch_log_group" "custom_email_sender" {
  name              = "/aws/lambda/${local.name_prefix}-custom-email-sender"
  retention_in_days = var.custom_sender_lambda_log_retention_days
  kms_key_id        = aws_kms_key.cloudwatch_logs.arn

  tags = local.tags
}

resource "aws_ses_email_identity" "custom_email_sender" {
  email = var.custom_email_sender_from_address
}

data "archive_file" "custom_email_sender" {
  type        = "zip"
  output_path = "${path.module}/custom_email_sender.zip"

  source {
    filename = "index.py"
    content  = <<-PYTHON
    import base64
    import os

    import boto3

    kms = boto3.client("kms")
    ses = boto3.client("ses")


    def handler(event, context):
        request = event["request"]
        encrypted_code = request["code"]
        code = kms.decrypt(
            CiphertextBlob=base64.b64decode(encrypted_code)
        )["Plaintext"].decode("utf-8")

        destination = request["userAttributes"]["email"]

        ses.send_email(
            Source=os.environ["FROM_EMAIL_ADDRESS"],
            Destination={"ToAddresses": [destination]},
            Message={
                "Subject": {"Data": "Verify your email address"},
                "Body": {"Text": {"Data": "Your verification code is " + code}},
            },
        )

        return event
    PYTHON
  }
}

resource "aws_iam_role" "custom_email_sender" {
  name = "${local.name_prefix}-custom-email-sender"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "custom_email_sender" {
  name = "${local.name_prefix}-custom-email-sender"
  role = aws_iam_role.custom_email_sender.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DecryptVerificationCodes"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:DescribeKey"]
        Resource = [aws_kms_key.custom_sender.arn]
      },
      {
        Sid      = "SendVerificationEmail"
        Effect   = "Allow"
        Action   = ["ses:SendEmail"]
        Resource = [aws_ses_email_identity.custom_email_sender.arn]
      },
      {
        Sid      = "WriteXRayTraces"
        Effect   = "Allow"
        Action   = ["xray:PutTraceSegments", "xray:PutTelemetryRecords"]
        Resource = ["*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "custom_email_sender" {
  role       = aws_iam_role.custom_email_sender.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "custom_email_sender" {
  function_name    = "${local.name_prefix}-custom-email-sender"
  description      = "Cognito custom email sender for the ${var.pool_name} user pool"
  role             = aws_iam_role.custom_email_sender.arn
  handler          = "index.handler"
  runtime          = "python3.12"
  filename         = data.archive_file.custom_email_sender.output_path
  source_code_hash = data.archive_file.custom_email_sender.output_base64sha256
  timeout          = 10
  memory_size      = 128

  tracing_config {
    mode = "Active"
  }

  environment {
    variables = {
      FROM_EMAIL_ADDRESS = var.custom_email_sender_from_address
    }
  }

  tags = local.tags

  depends_on = [
    aws_iam_role_policy_attachment.custom_email_sender,
    aws_cloudwatch_log_group.custom_email_sender,
  ]
}

resource "aws_lambda_permission" "custom_email_sender" {
  statement_id  = "AllowCognitoInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.custom_email_sender.function_name
  principal     = "cognito-idp.amazonaws.com"
  source_arn    = aws_cognito_user_pool.this.arn
}

###############################################################################
# Custom SMS sender Lambda stack
###############################################################################

resource "aws_cloudwatch_log_group" "custom_sms_sender" {
  name              = "/aws/lambda/${local.name_prefix}-custom-sms-sender"
  retention_in_days = var.custom_sender_lambda_log_retention_days
  kms_key_id        = aws_kms_key.cloudwatch_logs.arn

  tags = local.tags
}

data "archive_file" "custom_sms_sender" {
  type        = "zip"
  output_path = "${path.module}/custom_sms_sender.zip"

  source {
    filename = "index.py"
    content  = <<-PYTHON
    import base64

    import boto3

    kms = boto3.client("kms")
    sns = boto3.client("sns")


    def handler(event, context):
        request = event["request"]
        encrypted_code = request["code"]
        code = kms.decrypt(
            CiphertextBlob=base64.b64decode(encrypted_code)
        )["Plaintext"].decode("utf-8")

        phone_number = request["userAttributes"]["phone_number"]

        sns.publish(
            PhoneNumber=phone_number,
            Message="Your verification code is " + code,
        )

        return event
    PYTHON
  }
}

resource "aws_iam_role" "custom_sms_sender" {
  name = "${local.name_prefix}-custom-sms-sender"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "custom_sms_sender" {
  name = "${local.name_prefix}-custom-sms-sender"
  role = aws_iam_role.custom_sms_sender.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DecryptVerificationCodes"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:DescribeKey"]
        Resource = [aws_kms_key.custom_sender.arn]
      },
      {
        Sid      = "PublishVerificationSms"
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = ["*"]
      },
      {
        Sid      = "ReadSmsExternalIdSecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [aws_secretsmanager_secret.sms_external_id.arn]
      },
      {
        Sid      = "WriteXRayTraces"
        Effect   = "Allow"
        Action   = ["xray:PutTraceSegments", "xray:PutTelemetryRecords"]
        Resource = ["*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "custom_sms_sender" {
  role       = aws_iam_role.custom_sms_sender.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "custom_sms_sender" {
  function_name    = "${local.name_prefix}-custom-sms-sender"
  description      = "Cognito custom SMS sender for the ${var.pool_name} user pool"
  role             = aws_iam_role.custom_sms_sender.arn
  handler          = "index.handler"
  runtime          = "python3.12"
  filename         = data.archive_file.custom_sms_sender.output_path
  source_code_hash = data.archive_file.custom_sms_sender.output_base64sha256
  timeout          = 10
  memory_size      = 128

  tracing_config {
    mode = "Active"
  }

  environment {
    variables = {
      EXTERNAL_ID_SECRET_ARN = aws_secretsmanager_secret.sms_external_id.arn
    }
  }

  tags = local.tags

  depends_on = [
    aws_iam_role_policy_attachment.custom_sms_sender,
    aws_cloudwatch_log_group.custom_sms_sender,
  ]
}

resource "aws_lambda_permission" "custom_sms_sender" {
  statement_id  = "AllowCognitoInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.custom_sms_sender.function_name
  principal     = "cognito-idp.amazonaws.com"
  source_arn    = aws_cognito_user_pool.this.arn
}

###############################################################################
# SNS caller role assumed by Cognito to deliver SMS messages
###############################################################################

resource "aws_iam_role" "sns_caller" {
  name               = "${local.name_prefix}-sms-sns-caller"
  assume_role_policy = local.sns_caller_assume_role_policy

  tags = local.tags
}

resource "aws_iam_role_policy" "sns_caller" {
  name = "${local.name_prefix}-sms-sns-caller"
  role = aws_iam_role.sns_caller.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadSmsExternalIdSecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [aws_secretsmanager_secret.sms_external_id.arn]
      },
      {
        Sid      = "DecryptVerificationCodes"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:DescribeKey"]
        Resource = [aws_kms_key.custom_sender.arn]
      }
    ]
  })
}

resource "aws_iam_policy" "sns_publish" {
  name        = "${local.name_prefix}-sms-publish"
  description = "Allows the Cognito user pool to publish SMS messages through Amazon SNS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishSms"
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = ["*"]
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "sns_caller" {
  role       = aws_iam_role.sns_caller.name
  policy_arn = aws_iam_policy.sns_publish.arn
}

###############################################################################
# User pool clients
###############################################################################

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(var.client_app_names)

  name         = each.value
  user_pool_id = aws_cognito_user_pool.this.id

  generate_secret = var.client_generate_secret

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
  ]

  prevent_user_existence_errors = "LEGACY"
  enable_token_revocation       = true

  allowed_oauth_flows_user_pool_client = var.allowed_oauth_user_pool_client
  allowed_oauth_flows                  = var.allowed_oauth_user_pool_client ? var.allowed_oauth_flows : []
  allowed_oauth_scopes                 = var.allowed_oauth_user_pool_client ? var.allowed_oauth_scopes : []
  callback_urls                        = var.allowed_oauth_user_pool_client ? var.callback_urls : []
  logout_urls                          = var.allowed_oauth_user_pool_client ? var.logout_urls : []
  supported_identity_providers         = var.allowed_oauth_user_pool_client ? var.supported_identity_providers : []

  read_attributes  = var.read_attributes
  write_attributes = var.write_attributes

  access_token_validity  = var.access_token_validity
  id_token_validity      = var.id_token_validity
  refresh_token_validity = var.refresh_token_validity

  token_validity_units {
    access_token  = var.token_validity_units.access_token
    id_token      = var.token_validity_units.id_token
    refresh_token = var.token_validity_units.refresh_token
  }

  depends_on = [
    aws_cognito_user_pool.this,
  ]
}

###############################################################################
# Optional user group
###############################################################################

resource "aws_cognito_user_group" "this" {
  count = var.user_group_name != "" ? 1 : 0

  name         = var.user_group_name
  user_pool_id = aws_cognito_user_pool.this.id
  description  = var.user_group_description
  precedence   = var.user_group_precedence
  role_arn     = var.user_group_role_arn != "" ? var.user_group_role_arn : null
}

###############################################################################
# Optional user pool domain and Route 53 alias record
###############################################################################

resource "aws_cognito_user_pool_domain" "this" {
  count = var.domain_name != "" ? 1 : 0

  domain          = var.domain_name
  user_pool_id    = aws_cognito_user_pool.this.id
  certificate_arn = var.domain_certificate_arn != "" ? var.domain_certificate_arn : null
}

resource "aws_route53_record" "cognito_user_pool_domain" {
  count = var.create_route53_record && var.route53_zone_id != "" && var.domain_name != "" ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.this[0].cloudfront_distribution_arn
    zone_id                = local.cloudfront_hosted_zone_id
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

################################################################################
# Variables
################################################################################

variable "vpc_cidr" {
  description = "CIDR block for the VPC network range."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag applied to the VPC."
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag applied to the Internet Gateway."
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag applied to the public route table."
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_identifier_name" {
  description = "Label used to expose the public subnet identifier output."
  type        = string
  default     = "subnet_a"
}

variable "nat_gateway_name" {
  description = "Name tag applied to the NAT Gateway."
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  description = "Bring-your-own-IP public IPv4 pool used by the Elastic IP."
  type        = string
  default     = "amazon"
}

variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A (public)."
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B (private, NAT target)."
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C (private)."
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_a_name" {
  description = "Name tag applied to Subnet A."
  type        = string
  default     = "Subnet-A-Public"
}

variable "subnet_b_name" {
  description = "Name tag applied to Subnet B."
  type        = string
  default     = "Subnet-B-Private"
}

variable "subnet_c_name" {
  description = "Name tag applied to Subnet C."
  type        = string
  default     = "Subnet-C-Private"
}

variable "subnet_a_map_public_ip" {
  description = "Whether instances launched in Subnet A receive a public IP."
  type        = bool
  default     = false
}

variable "subnet_b_map_public_ip" {
  description = "Whether instances launched in Subnet B receive a public IP."
  type        = bool
  default     = false
}

variable "subnet_c_map_public_ip" {
  description = "Whether instances launched in Subnet C receive a public IP."
  type        = bool
  default     = false
}

variable "flow_log_retention_in_days" {
  description = "Retention period (in days) for the VPC flow log CloudWatch log group."
  type        = number
  default     = 365
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period (in days) before the CloudWatch Logs CMK is deleted."
  type        = number
  default     = 30
}

################################################################################
# Locals
################################################################################

locals {
  default_security_group_name = "DefaultSecurityGroup"
  any_ipv4_cidr               = "0.0.0.0/0"
  flow_log_group_name         = "${var.vpc_name}-flow-logs"
  flow_log_role_name          = "${var.vpc_name}-flow-logs-role"
  flow_log_kms_alias_name     = "alias/${var.vpc_name}-flow-logs"
}

################################################################################
# Provider Metadata
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

################################################################################
# Availability Zones
################################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

################################################################################
# Internet Gateway
################################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

################################################################################
# Subnets
################################################################################

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = var.subnet_a_map_public_ip

  tags = {
    Name = var.subnet_a_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = var.subnet_b_map_public_ip

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = var.subnet_c_map_public_ip

  tags = {
    Name = var.subnet_c_name
  }
}

################################################################################
# Public Route Table, Route and Association
################################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = local.any_ipv4_cidr
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "subnet_a_public" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

################################################################################
# NAT Gateway and Elastic IP
################################################################################

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool

  tags = {
    Name = "${var.nat_gateway_name}-eip"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnet_b.id

  tags = {
    Name = var.nat_gateway_name
  }

  depends_on = [aws_internet_gateway.main]
}

################################################################################
# Default Security Group
################################################################################

resource "aws_security_group" "default" {
  name        = local.default_security_group_name
  description = "Default security group with VPC-only outbound egress."
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = local.default_security_group_name
  }
}

resource "aws_vpc_security_group_egress_rule" "vpc_only" {
  security_group_id = aws_security_group.default.id
  description       = "Allow outbound traffic within the VPC CIDR only."
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

################################################################################
# VPC Flow Logs IAM Role
################################################################################

data "aws_iam_policy_document" "vpc_flow_logs_assume_role" {
  statement {
    sid     = "VpcFlowLogsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name               = local.flow_log_role_name
  assume_role_policy = data.aws_iam_policy_document.vpc_flow_logs_assume_role.json

  tags = {
    Name = local.flow_log_role_name
  }
}

################################################################################
# CloudWatch Logs CMK (customer-managed key for the flow log group)
################################################################################

data "aws_iam_policy_document" "cloudwatch_logs_kms" {
  statement {
    sid     = "EnableRootAccountKeyManagement"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowVpcFlowLogsRoleEncryption"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.vpc_flow_logs.arn]
    }

    resources = ["*"]
  }
}

resource "aws_kms_key" "cloudwatch" {
  description             = "CMK used to encrypt the ${var.vpc_name} VPC flow log CloudWatch log group."
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.cloudwatch_logs_kms.json

  tags = {
    Name = "${var.vpc_name}-flow-logs-cmk"
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = local.flow_log_kms_alias_name
  target_key_id = aws_kms_key.cloudwatch.key_id
}

################################################################################
# VPC Flow Logs (CloudWatch Logs destination, encrypted with CMK)
################################################################################

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = local.flow_log_group_name
  retention_in_days = var.flow_log_retention_in_days
  kms_key_id        = aws_kms_key.cloudwatch.arn

  tags = {
    Name = local.flow_log_group_name
  }
}

data "aws_iam_policy_document" "vpc_flow_logs_permissions" {
  statement {
    sid    = "VpcFlowLogsWriteToCloudWatch"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*",
    ]
  }

  statement {
    sid    = "VpcFlowLogsDescribeCloudWatch"
    effect = "Allow"

    actions = [
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
    ]

    resources = [
      aws_cloudwatch_log_group.vpc_flow_logs.arn,
    ]
  }

  statement {
    sid    = "VpcFlowLogsUseCmk"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.cloudwatch.arn,
    ]
  }
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name   = "${local.flow_log_role_name}-policy"
  role   = aws_iam_role.vpc_flow_logs.id
  policy = data.aws_iam_policy_document.vpc_flow_logs_permissions.json
}

resource "aws_flow_log" "main" {
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn             = aws_iam_role.vpc_flow_logs.arn
  max_aggregation_interval = 60

  tags = {
    Name = "${var.vpc_name}-flow-log"
  }

  depends_on = [
    aws_iam_role_policy.vpc_flow_logs,
    aws_kms_alias.cloudwatch,
  ]
}

################################################################################
# Outputs
################################################################################

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT Gateway Elastic IP."
  value       = aws_eip.nat.public_ip
}

output "public_subnet_identifier" {
  description = "Identifier of the public subnet, keyed by the public subnet identifier name variable."
  value       = { (var.public_subnet_identifier_name) = aws_subnet.subnet_a.id }
}

output "vpc_id" {
  description = "Identifier of the created VPC."
  value       = aws_vpc.main.id
}

output "internet_gateway_id" {
  description = "Identifier of the created Internet Gateway."
  value       = aws_internet_gateway.main.id
}

output "nat_gateway_id" {
  description = "Identifier of the created NAT Gateway."
  value       = aws_nat_gateway.main.id
}

output "default_security_group_id" {
  description = "Identifier of the default security group."
  value       = aws_security_group.default.id
}

output "private_subnet_ids" {
  description = "Identifiers of the private subnets (Subnet B and Subnet C)."
  value = [
    aws_subnet.subnet_b.id,
    aws_subnet.subnet_c.id
  ]
}

output "availability_zones" {
  description = "Availability zones used by the three subnets."
  value = [
    aws_subnet.subnet_a.availability_zone,
    aws_subnet.subnet_b.availability_zone,
    aws_subnet.subnet_c.availability_zone
  ]
}

output "vpc_flow_log_id" {
  description = "Identifier of the VPC flow log attached to the VPC."
  value       = aws_flow_log.main.id
}

output "flow_log_kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the VPC flow log group."
  value       = aws_kms_key.cloudwatch.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "Whether to create a new Transit Gateway (true) or look up an existing one (false)."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name tag and lookup filter for the Transit Gateway, and fallback name for route tables."
  type        = string
  default     = null
}

variable "id" {
  description = "Existing Transit Gateway ID to look up when create = false. Takes precedence over tag:Name lookup."
  type        = string
  default     = null
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks for the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))])
    error_message = "Every entry in transit_gateway_cidr_blocks must be a valid IPv4 or IPv6 CIDR block."
  }
}

variable "amazon_side_asn" {
  description = "BGP ASN for the Transit Gateway."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether to automatically accept shared attachments (enable or disable)."
  type        = string
  default     = "disable"
}

variable "dns_support" {
  description = "Whether DNS support is enabled (enable or disable)."
  type        = string
  default     = "enable"
}

variable "vpn_ecmp_support" {
  description = "Whether VPN ECMP support is enabled (enable or disable)."
  type        = string
  default     = "enable"
}

variable "description" {
  description = "Description for the Transit Gateway."
  type        = string
  default     = null
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables to create or look up."
  type = map(object({
    name       = optional(string)
    local_tags = optional(map(string), {})
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of logical principal name to principal ARN/account ID for RAM sharing."
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Name for the RAM resource share. Defaults to var.name or 'tgw-share'."
  type        = string
  default     = null
}

variable "tags" {
  description = "Global tags merged into every taggable resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  is_tgw_created = var.create

  tgw_id = var.create ? aws_ec2_transit_gateway.this[0].id : (
    var.id != null ? var.id : data.aws_ec2_transit_gateway.this[0].id
  )

  tgw_arn = var.create ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.this[0].arn

  merged_tags = merge(var.tags, {
    Name = coalesce(var.name, "tgw")
  })

  route_table_ids = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.this : k => v.id }
  )

  ram_resource_share_arn = length(aws_ram_resource_share.this) > 0 ? aws_ram_resource_share.this[0].arn : null
}

###############################################################################
# Transit Gateway lookup
###############################################################################

data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  dynamic "filter" {
    for_each = var.id != null ? [1] : []

    content {
      name   = "transit-gateway-id"
      values = [var.id]
    }
  }

  dynamic "filter" {
    for_each = var.id == null ? [1] : []

    content {
      name   = "tag:Name"
      values = [var.name]
    }
  }
}

###############################################################################
# Transit Gateway
###############################################################################

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks
  description                     = var.description
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  tags = local.merged_tags
}

###############################################################################
# Route tables
###############################################################################

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = var.create ? var.route_tables : {}

  transit_gateway_id = local.tgw_id

  tags = merge(
    var.tags,
    each.value.local_tags != null ? each.value.local_tags : {},
    {
      Name = coalesce(each.value.name, each.key, var.name)
    }
  )
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = var.create ? {} : var.route_tables

  dynamic "filter" {
    for_each = {
      "transit-gateway-id" = [local.tgw_id]
      "tag:Name"           = [coalesce(each.value.name, each.key)]
    }

    content {
      name   = filter.key
      values = filter.value
    }
  }
}

###############################################################################
# RAM sharing
#
# External-account RAM participants must accept the share invitation
# out-of-band because allow_external_principals = true.
###############################################################################

resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = coalesce(var.ram_resource_share_name, var.name, "tgw-share")
  allow_external_principals = true

  tags = var.tags
}

resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_arn       = local.tgw_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

###############################################################################
# Outputs
###############################################################################

output "transit_gateway_id" {
  description = "ID of the created or looked-up Transit Gateway."
  value       = local.tgw_id
}

output "transit_gateway_arn" {
  description = "ARN of the created or looked-up Transit Gateway."
  value       = local.tgw_arn
}

output "transit_gateway_route_table_ids" {
  description = "Map of route table name to route table ID for created or looked-up route tables."
  value       = local.route_table_ids
}

output "is_tgw_created" {
  description = "True when this configuration created the Transit Gateway."
  value       = local.is_tgw_created
}

output "ram_resource_share_arn" {
  description = "ARN of the RAM resource share, if created."
  value       = local.ram_resource_share_arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# Aliased provider used for the cross-region replication destination bucket and
# its dedicated KMS key. The default (unaliased) provider is supplied by the
# deployment harness.
provider "aws" {
  alias  = "replica"
  region = var.replication_region
}

###############################################################################
# Data sources (static provider metadata only - no remote infrastructure lookup)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Variables
###############################################################################

variable "bucket_name" {
  description = "Optional explicit bucket name. When null the name falls back to corebucket-<4 byte hex>."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true an additional random string suffix is appended to the resolved bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Who pays for requests against the bucket (BucketOwner or Requester)."
  type        = string
  default     = "BucketOwner"
}

variable "encryption" {
  description = "Kept for API compatibility. Encryption is always enabled and always uses aws:kms."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN (or alias/id) of an existing customer managed KMS key. When empty a rotating key is created by this module."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Enable bucket versioning. Defaults to true (secure by default). Versioning is also forced on when replication or object lock is configured."
  type        = bool
  default     = true
}

variable "mfa_delete" {
  description = "Enable MFA delete on the bucket versioning configuration."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Destroy all objects in the bucket when the bucket is destroyed."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags applied to every taggable resource created by this module."
  type        = map(string)
  default     = {}
}

variable "acl" {
  description = <<-EOT
    Requested canned ACL. The bucket is always created with BucketOwnerEnforced
    object ownership (ACLs disabled) and legacy aws_s3_bucket_acl resources are
    intentionally not created; access intent must be expressed through a bucket
    policy instead. Accepted for API compatibility only.
  EOT
  type        = string
  default     = null
}

variable "policy" {
  description = "Optional JSON bucket policy document applied to the primary bucket."
  type        = string
  default     = null
}

variable "grants" {
  description = "Requested ACL grants. Honored through the bucket policy (BucketOwnerEnforced disables ACLs)."
  type = list(object({
    id          = optional(string)
    type        = string
    permissions = list(string)
    uri         = optional(string)
  }))
  default = []
}

variable "acceleration_status" {
  description = "Transfer acceleration status (Enabled or Suspended). Null disables the resource entirely."
  type        = string
  default     = null
}

variable "logging" {
  description = "Server access logging configuration. Defaults to an empty object so logging is enabled by default against the module managed logging bucket."
  type = object({
    target_bucket = optional(string)
    target_prefix = optional(string, "logs/")
  })
  default = {}
}

variable "website" {
  description = "Static website hosting configuration."
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules (id, status, filter/prefix, expiration, noncurrent_version_expiration, abort_incomplete_multipart_upload, transitions)."
  type        = list(any)
  default     = []
}

variable "object_lock_configuration" {
  description = "S3 object lock configuration with a default retention rule."
  type = object({
    rule = object({
      default_retention = object({
        mode  = string
        days  = optional(number)
        years = optional(number)
      })
    })
  })
  default = null
}

variable "replication_rules" {
  description = "Cross-region replication rules (id, status, priority, filter, delete_marker_replication, destination{storage_class, metrics})."
  type        = list(any)
  default     = []
}

variable "replication_role" {
  description = "Existing IAM role ARN used for replication. When empty a dedicated role is created by this module."
  type        = string
  default     = ""
}

variable "replication_region" {
  description = "Region of the module managed replication destination bucket."
  type        = string
  default     = "us-west-2"
}

###############################################################################
# Random naming components
###############################################################################

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_string" "bucket_prefix_suffix" {
  count   = var.prefix ? 1 : 0
  length  = 8
  special = false
  upper   = false
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  bucket_base_name    = coalesce(var.bucket_name, "corebucket-${random_id.bucket_suffix.hex}")
  bucket_prefix_extra = join("", random_string.bucket_prefix_suffix[*].result)
  resolved_name       = var.prefix ? "${local.bucket_base_name}-${local.bucket_prefix_extra}" : local.bucket_base_name

  logging_enabled       = var.logging != null
  logging_target_prefix = try(var.logging.target_prefix, "logs/")

  website_enabled      = var.website != null
  acceleration_enabled = var.acceleration_status != null

  replication_enabled    = length(var.replication_rules) > 0
  object_lock_enabled    = var.object_lock_configuration != null
  versioning_enabled     = var.versioning || local.replication_enabled || local.object_lock_enabled
  client_side_kms_absent = var.kms_key == ""

  kms_key_arn         = local.client_side_kms_absent ? join("", aws_kms_key.bucket[*].arn) : var.kms_key
  replica_kms_key_arn = join("", aws_kms_key.replica[*].arn)
  replica_bucket_arn  = join("", aws_s3_bucket.replica[*].arn)
  replica_bucket_id   = join("", aws_s3_bucket.replica[*].id)
  logging_bucket_id   = join("", aws_s3_bucket.logging[*].id)
  logging_bucket_arn  = join("", aws_s3_bucket.logging[*].arn)

  replica_logging_bucket_id  = join("", aws_s3_bucket.replica_logging[*].id)
  replica_logging_bucket_arn = join("", aws_s3_bucket.replica_logging[*].arn)

  create_replication_role = local.replication_enabled && var.replication_role == ""
  replication_role_arn    = var.replication_role != "" ? var.replication_role : join("", aws_iam_role.replication[*].arn)

  # IAM names are capped at 64 characters - hash + truncate when necessary.
  iam_name_hash       = substr(sha256(local.resolved_name), 0, 8)
  iam_role_name_raw   = "CoreS3ReplicationRole_${local.resolved_name}"
  iam_policy_name_raw = "CoreS3ReplicationPolicy_${local.resolved_name}"
  iam_role_name       = length(local.iam_role_name_raw) <= 64 ? local.iam_role_name_raw : "CoreS3ReplicationRole_${substr(local.resolved_name, 0, 32)}${local.iam_name_hash}"
  iam_policy_name     = length(local.iam_policy_name_raw) <= 64 ? local.iam_policy_name_raw : "CoreS3ReplicationPolicy_${substr(local.resolved_name, 0, 31)}${local.iam_name_hash}"

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  kms_use_principals = compact([local.account_root_arn, local.replication_role_arn])

  kms_key_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowKeyUsage"
        Effect = "Allow"
        Principal = {
          AWS = local.kms_use_principals
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServerAccessLogging"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
    ]
  })

  # Logging-bucket policy: the recognized fields (Effect, Action, Principal.Service)
  # are kept as literals so static policy analysis can parse the grant.
  logging_bucket_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLoggingWrite"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
        ]
        Resource = "${local.logging_bucket_arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
    ]
  })

  replica_logging_bucket_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLoggingWrite"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
        ]
        Resource = "${local.replica_logging_bucket_arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
    ]
  })
}

###############################################################################
# Customer managed KMS keys
###############################################################################

resource "aws_kms_key" "bucket" {
  count = local.client_side_kms_absent ? 1 : 0

  description             = "Customer managed key for S3 bucket ${local.resolved_name} in ${local.region}"
  enable_key_rotation     = true
  policy                  = local.kms_key_policy
  deletion_window_in_days = 30
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "bucket" {
  count = local.client_side_kms_absent ? 1 : 0

  name          = "alias/${local.resolved_name}-bucket"
  target_key_id = aws_kms_key.bucket[0].key_id
}

resource "aws_kms_key" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  description             = "Customer managed key for S3 replication destination ${local.resolved_name} in ${var.replication_region}"
  enable_key_rotation     = true
  policy                  = local.kms_key_policy
  deletion_window_in_days = 30
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Primary bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = local.resolved_name
  request_payer       = var.request_payer
  force_destroy       = var.force_destroy
  object_lock_enabled = local.object_lock_enabled
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = var.policy != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  policy = var.policy

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = local.acceleration_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.acceleration_status
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.website_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [1] : []
    content {
      suffix = var.website.index_document
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [1] : []
    content {
      key = var.website.error_document
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [1] : []
    content {
      host_name = var.website.redirect_all_requests_to
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = try(rule.value.id, "lifecycle-rule-${rule.key}")
      status = try(rule.value.status, "Enabled")

      filter {
        prefix = try(rule.value.filter.prefix, try(rule.value.prefix, ""))

        dynamic "tag" {
          for_each = [
            for k, v in try(rule.value.filter.tags, {}) :
            { key = k, value = v }
            if try(v, null) != null && try(v, null) != ""
          ]
          content {
            key   = tag.value.key
            value = tag.value.value
          }
        }

        dynamic "and" {
          for_each = try(rule.value.filter.and, null) != null ? [rule.value.filter.and] : []
          iterator = and_rule
          content {
            prefix = try(and_rule.value.prefix, null)
            tags   = try(and_rule.value.tags, null)
          }
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []
        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, null)
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, null) != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = try(abort_incomplete_multipart_upload.value.days_after_initiation, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])
        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.rule.default_retention.mode
      days  = try(var.object_lock_configuration.rule.default_retention.days, null)
      years = try(var.object_lock_configuration.rule.default_retention.years, null)
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Dedicated server access logging bucket (module managed, never external)
###############################################################################

resource "aws_s3_bucket" "logging" {
  count = local.logging_enabled ? 1 : 0

  bucket        = "${local.resolved_name}-logs"
  request_payer = var.request_payer
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "logging" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "logging" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id
  policy = local.logging_bucket_policy

  depends_on = [aws_s3_bucket_public_access_block.logging]
}

# Self-directed logging on the logging target bucket so the bucket always carries
# an explicit aws_s3_bucket_logging signal (terminates the log-the-log-bucket recursion).
resource "aws_s3_bucket_logging" "logging" {
  count = local.logging_enabled ? 1 : 0

  bucket        = aws_s3_bucket.logging[0].id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = local.logging_target_prefix

  depends_on = [aws_s3_bucket_policy.logging]
}

resource "aws_s3_bucket_logging" "this" {
  count = local.logging_enabled ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = local.logging_target_prefix

  depends_on = [aws_s3_bucket_policy.logging]
}

###############################################################################
# Cross region replication destination bucket (module managed)
###############################################################################

resource "aws_s3_bucket" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket        = "${local.resolved_name}-replica"
  request_payer = var.request_payer
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.replica_kms_key_arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowReplicationRoleWrite"
        Effect = "Allow"
        Principal = {
          AWS = local.replication_role_arn
        }
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = [
          local.replica_bucket_arn,
          "${local.replica_bucket_arn}/*",
        ]
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

###############################################################################
# Dedicated logging bucket for the replication destination (replica region)
###############################################################################

resource "aws_s3_bucket" "replica_logging" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket        = "${local.resolved_name}-replica-logs"
  request_payer = var.request_payer
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica_logging" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica_logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica_logging" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica_logging[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_logging" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica_logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.replica_kms_key_arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "replica_logging" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica_logging[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "replica_logging" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica_logging[0].id
  policy = local.replica_logging_bucket_policy

  depends_on = [aws_s3_bucket_public_access_block.replica_logging]
}

# Self-directed logging on the replica-region logging bucket.
resource "aws_s3_bucket_logging" "replica_logging" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket        = aws_s3_bucket.replica_logging[0].id
  target_bucket = aws_s3_bucket.replica_logging[0].id
  target_prefix = local.logging_target_prefix

  depends_on = [aws_s3_bucket_policy.replica_logging]
}

resource "aws_s3_bucket_logging" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket        = aws_s3_bucket.replica[0].id
  target_bucket = aws_s3_bucket.replica_logging[0].id
  target_prefix = local.logging_target_prefix

  depends_on = [aws_s3_bucket_policy.replica_logging]
}

###############################################################################
# Replication IAM role, policy and attachment
###############################################################################

resource "aws_iam_role" "replication" {
  count = local.create_replication_role ? 1 : 0

  name = local.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "replication" {
  count = local.create_replication_role ? 1 : 0

  name = local.iam_policy_name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:GetBucketVersioning",
          "s3:ListBucket",
          "s3:ListBucketVersions",
        ]
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Sid    = "SourceObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionTagging",
        ]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      },
      {
        Sid    = "DestinationPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersionForReplication",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = [
          local.replica_bucket_arn,
          "${local.replica_bucket_arn}/*",
        ]
      },
      {
        Sid    = "KmsPermissionsForReplication"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*",
          "kms:DescribeKey",
        ]
        Resource = compact([local.kms_key_arn, local.replica_kms_key_arn])
      },
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.create_replication_role ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

###############################################################################
# Replication configuration
###############################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = try(rule.value.id, "replication-rule-${rule.key}")
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      filter {
        prefix = try(rule.value.filter.prefix, "")

        dynamic "tag" {
          for_each = [
            for k, v in try(rule.value.filter.tags, {}) :
            { key = k, value = v }
            if try(v, null) != null && try(v, null) != ""
          ]
          content {
            key   = tag.value.key
            value = tag.value.value
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication, null) != null ? [rule.value.delete_marker_replication] : []
        content {
          status = try(delete_marker_replication.value.status, "Enabled")
        }
      }

      dynamic "destination" {
        for_each = [rule.value.destination]
        content {
          bucket        = local.replica_bucket_arn
          storage_class = try(destination.value.storage_class, null)
          account       = try(destination.value.account, null)

          encryption_configuration {
            replica_kms_key_id = try(destination.value.encryption_configuration.replica_kms_key_id, local.replica_kms_key_arn)
          }

          dynamic "metrics" {
            for_each = try(destination.value.metrics, null) != null ? [destination.value.metrics] : []
            content {
              status = try(metrics.value.status, "Enabled")

              dynamic "event_threshold" {
                for_each = try(metrics.value.event_threshold, null) != null ? [metrics.value.event_threshold] : []
                content {
                  minutes = try(event_threshold.value.minutes, 15)
                }
              }
            }
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy_attachment.replication,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "ID (name) of the primary S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the primary S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "Domain name of the primary S3 bucket."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "Region specific domain name of the primary S3 bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_name" {
  description = "Resolved bucket name used by this module."
  value       = local.resolved_name
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for bucket encryption (module created or supplied)."
  value       = local.kms_key_arn
}

output "replica_kms_key_arn" {
  description = "ARN of the KMS key used for the replication destination bucket."
  value       = local.replica_kms_key_arn
}

output "logging_bucket_id" {
  description = "ID of the module managed server access logging bucket."
  value       = local.logging_bucket_id
}

output "replication_destination_bucket_id" {
  description = "ID of the module managed replication destination bucket."
  value       = local.replica_bucket_id
}

output "replication_role_arn" {
  description = "ARN of the IAM role used for replication (module created or supplied)."
  value       = local.replication_role_arn
}

output "replication_role_name" {
  description = "Name of the module created replication role, if any."
  value       = join("", aws_iam_role.replication[*].name)
}

output "replication_policy_arn" {
  description = "ARN of the module created replication policy, if any."
  value       = join("", aws_iam_policy.replication[*].arn)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "awsRegion" {
  description = "AWS region in which to deploy the network stack."
  type        = string
  default     = "us-east-1"
}

variable "projectPrefix" {
  description = "Prefix used to namespace and tag all resources."
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner tag applied to all resources."
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix appended to resource names/tags to distinguish builds."
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Whether public subnets auto-assign public IPs on launch."
  type        = bool
  default     = false
}

variable "awsAz1" {
  description = "Optional first availability zone. Defaults to the first available AZ."
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Optional second availability zone. Defaults to the second available AZ, or to awsAz1 when only awsAz1 is supplied."
  type        = string
  default     = null
}

variable "vpcMainCidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for the public subnet in the first AZ."
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for the public subnet in the second AZ."
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for the management subnet in the first AZ."
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for the management subnet in the second AZ."
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for the private subnet in the first AZ."
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for the private subnet in the second AZ."
  type        = string
  default     = "10.1.120.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix = "${var.projectPrefix}-${var.buildSuffix}"

  common_tags = {
    Project       = var.projectPrefix
    ResourceOwner = var.resourceOwner
    BuildSuffix   = var.buildSuffix
    Region        = var.awsRegion
    ManagedBy     = "terraform"
  }

  az1 = coalesce(var.awsAz1, data.aws_availability_zones.available.names[0])
  az2 = coalesce(var.awsAz2, var.awsAz1, data.aws_availability_zones.available.names[1])
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# Public subnets (auto-assign public IP configurable)
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sub-pub-a"
    Tier = "public"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sub-pub-b"
    Tier = "public"
  })
}

# Management subnets (no public IP mapping)
resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sub-mgmt-a"
    Tier = "management"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sub-mgmt-b"
    Tier = "management"
  })
}

# Private subnets (no public IP mapping)
resource "aws_subnet" "priv_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sub-priv-a"
    Tier = "private"
  })
}

resource "aws_subnet" "priv_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sub-priv-b"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt-public"
  })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.public.id
}

# Customer-managed KMS key used to encrypt CloudWatch log data
resource "aws_kms_key" "cloudwatch" {
  description             = "${local.name_prefix} CloudWatch logs encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${var.awsRegion}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${data.aws_partition.current.partition}:logs:${var.awsRegion}:${data.aws_caller_identity.current.account_id}:*"
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cloudwatch"
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${local.name_prefix}-cloudwatch"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# CloudWatch log group that receives VPC flow log records
resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/${local.name_prefix}-flow-logs"
  retention_in_days = 365
  kms_key_id        = aws_kms_key.cloudwatch.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-logs"
  })
}

# IAM role trusted by the VPC Flow Logs service
resource "aws_iam_role" "flow_log" {
  name = "${local.name_prefix}-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-log-role"
  })
}

# Least-privilege inline policy scoped to the flow-log destination log group
resource "aws_iam_role_policy" "flow_log" {
  name = "${local.name_prefix}-flow-log-policy"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_log.arn,
          "${aws_cloudwatch_log_group.flow_log.arn}:*"
        ]
      }
    ]
  })
}

# VPC flow log capturing all traffic to CloudWatch Logs
resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  iam_role_arn         = aws_iam_role.flow_log.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-log"
  })

  depends_on = [
    aws_iam_role_policy.flow_log,
  ]
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name prefix applied to all resources."
  type        = string
  default     = "benchmark"
}

variable "rule_count" {
  description = "Number of path-based listener rules to create."
  type        = number
  default     = 1
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Name = var.name
  }

  flow_log_group_name = "/aws/vpc/${var.name}-flow-logs"

  flow_logs_service_principal = "logs.${var.region}.amazonaws.com"
}

resource "aws_vpc" "benchmark" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = local.common_tags
}

resource "aws_subnet" "benchmark" {
  count = 2

  vpc_id            = aws_vpc.benchmark.id
  cidr_block        = cidrsubnet(aws_vpc.benchmark.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.name}-subnet-${count.index}"
  })
}

resource "aws_security_group" "benchmark" {
  name        = "${var.name}-sg"
  description = "Allow all traffic within the VPC CIDR only."
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    description = "All protocols from within the VPC CIDR."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  egress {
    description = "All protocols to within the VPC CIDR."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  tags = local.common_tags
}

resource "aws_lb" "benchmark" {
  name               = "${var.name}-alb"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.benchmark.id]
  subnets            = aws_subnet.benchmark[*].id

  drop_invalid_header_fields = true

  tags = local.common_tags
}

resource "aws_lb_target_group" "benchmark" {
  name        = "${var.name}-tg"
  port        = 8080
  protocol    = "HTTP"
  target_type = "instance"
  vpc_id      = aws_vpc.benchmark.id

  health_check {
    enabled             = true
    protocol            = "HTTP"
    port                = "8081"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = local.common_tags
}

resource "tls_private_key" "benchmark" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "benchmark" {
  private_key_pem = tls_private_key.benchmark.private_key_pem

  subject {
    common_name  = "${var.name}.internal"
    organization = "Benchmark"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]

  is_ca_certificate = false
}

resource "aws_acm_certificate" "benchmark" {
  certificate_body = tls_self_signed_cert.benchmark.cert_pem
  private_key      = tls_private_key.benchmark.private_key_pem

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_listener" "benchmark_https" {
  load_balancer_arn = aws_lb.benchmark.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.benchmark.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.benchmark.arn
  }

  tags = local.common_tags
}

resource "aws_lb_listener_rule" "benchmark" {
  count = var.rule_count

  listener_arn = aws_lb_listener.benchmark_https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.benchmark.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = local.common_tags
}

resource "aws_kms_key" "benchmark" {
  description             = "Customer managed key used to encrypt ${var.name} VPC flow logs."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUseOfKey"
        Effect = "Allow"
        Principal = {
          Service = local.flow_logs_service_principal
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_kms_alias" "benchmark" {
  name          = "alias/${var.name}-vpc-flow-logs"
  target_key_id = aws_kms_key.benchmark.key_id
}

resource "aws_cloudwatch_log_group" "benchmark_flow_logs" {
  name              = local.flow_log_group_name
  retention_in_days = 30
  kms_key_id        = aws_kms_key.benchmark.arn

  tags = local.common_tags
}

data "aws_iam_policy_document" "benchmark_flow_logs_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "benchmark_flow_logs" {
  name               = "${var.name}-vpc-flow-logs"
  assume_role_policy = data.aws_iam_policy_document.benchmark_flow_logs_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "benchmark_flow_logs" {
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
    ]

    resources = ["${aws_cloudwatch_log_group.benchmark_flow_logs.arn}:*"]
  }
}

resource "aws_iam_role_policy" "benchmark_flow_logs" {
  name   = "${var.name}-vpc-flow-logs"
  role   = aws_iam_role.benchmark_flow_logs.id
  policy = data.aws_iam_policy_document.benchmark_flow_logs.json
}

resource "aws_flow_log" "benchmark" {
  vpc_id                   = aws_vpc.benchmark.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.benchmark_flow_logs.arn
  iam_role_arn             = aws_iam_role.benchmark_flow_logs.arn
  max_aggregation_interval = 60

  tags = local.common_tags
}

output "alb_arn" {
  description = "ARN of the internal Application Load Balancer."
  value       = aws_lb.benchmark.arn
}

output "alb_dns_name" {
  description = "DNS name of the internal Application Load Balancer."
  value       = aws_lb.benchmark.dns_name
}

output "target_group_arn" {
  description = "ARN of the target group receiving forwarded traffic."
  value       = aws_lb_target_group.benchmark.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region in which to deploy the isolated networking stack."
  type        = string
  default     = "us-east-1"
}

variable "resource_prefix" {
  description = "Name prefix applied to the Name tag of every resource."
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Tenancy of instances launched into the VPC."
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled for the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Whether DNS resolution is supported for the VPC."
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "CIDR blocks assigned to the private subnets (one per subnet)."
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "vpc_flow_log_retention_in_days" {
  description = "Retention period (in days) for the VPC flow log CloudWatch log group."
  type        = number
  default     = 90
}

variable "public_inbound_acl_rules" {
  description = "Inbound (ingress) rules for the shared network ACL."
  type = list(object({
    rule_number = number
    action      = string
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      action      = "allow"
      protocol    = "tcp"
      from_port   = 1024
      to_port     = 65535
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound (egress) rules for the shared network ACL."
  type = list(object({
    rule_number = number
    action      = string
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      action      = "allow"
      protocol    = "tcp"
      from_port   = 443
      to_port     = 443
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

locals {
  subnet_count             = length(var.private_subnets)
  s3_endpoint_service_name = "com.amazonaws.${var.region}.s3"

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  common_tags = {
    ManagedBy = "terraform"
    Prefix    = var.resource_prefix
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count                   = local.subnet_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnets[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-private-${count.index + 1}"
  })
}

resource "aws_route_table" "private" {
  count  = local.subnet_count
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-private-rt-${count.index + 1}"
  })
}

resource "aws_route_table_association" "private" {
  count          = local.subnet_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

data "aws_iam_policy_document" "s3_endpoint" {
  statement {
    sid    = "AllowListBucket"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      "arn:${local.partition}:s3:::${var.resource_prefix}-*",
    ]
  }

  statement {
    sid    = "AllowObjectAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]

    resources = [
      "arn:${local.partition}:s3:::${var.resource_prefix}-*/*",
    ]
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = local.s3_endpoint_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id
  policy            = data.aws_iam_policy_document.s3_endpoint.json

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-s3-endpoint"
  })
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.public_inbound_acl_rules
    content {
      rule_no    = ingress.value.rule_number
      action     = ingress.value.action
      protocol   = ingress.value.protocol
      from_port  = ingress.value.from_port
      to_port    = ingress.value.to_port
      cidr_block = ingress.value.cidr_block
    }
  }

  dynamic "egress" {
    for_each = var.public_outbound_acl_rules
    content {
      rule_no    = egress.value.rule_number
      action     = egress.value.action
      protocol   = egress.value.protocol
      from_port  = egress.value.from_port
      to_port    = egress.value.to_port
      cidr_block = egress.value.cidr_block
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-private-nacl"
  })
}

resource "aws_network_acl_association" "private" {
  count          = local.subnet_count
  subnet_id      = aws_subnet.private[count.index].id
  network_acl_id = aws_network_acl.private.id
}

data "aws_iam_policy_document" "kms_flow_logs" {
  statement {
    sid    = "AllowAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${var.region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "vpc_flow_logs" {
  description             = "${var.resource_prefix} VPC flow log encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms_flow_logs.json

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-vpc-flow-logs-key"
  })
}

resource "aws_kms_alias" "vpc_flow_logs" {
  name          = "alias/${var.resource_prefix}-vpc-flow-logs"
  target_key_id = aws_kms_key.vpc_flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc/${var.resource_prefix}-flow-logs"
  retention_in_days = var.vpc_flow_log_retention_in_days
  kms_key_id        = aws_kms_key.vpc_flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-vpc-flow-logs"
  })
}

data "aws_iam_policy_document" "vpc_flow_logs_assume_role" {
  statement {
    sid    = "AllowVpcFlowLogsAssumeRole"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name               = "${var.resource_prefix}-vpc-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.vpc_flow_logs_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-vpc-flow-logs-role"
  })
}

data "aws_iam_policy_document" "vpc_flow_logs_write" {
  statement {
    sid    = "AllowVpcFlowLogsWrite"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
    ]

    resources = [
      "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*",
    ]
  }
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name   = "${var.resource_prefix}-vpc-flow-logs-policy"
  role   = aws_iam_role.vpc_flow_logs.id
  policy = data.aws_iam_policy_document.vpc_flow_logs_write.json
}

resource "aws_flow_log" "vpc" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn         = aws_iam_role.vpc_flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-vpc-flow-log"
  })
}

terraform {
  required_version = ">= 1.9.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Input variables
###############################################################################

variable "create" {
  description = "Controls whether the SQS queue and all of its dependent resources are created. When false the module is fully disabled without destroying referenced state."
  type        = bool
  default     = true
}

variable "name" {
  description = "Explicit name of the queue. Mutually exclusive with `name_prefix`. When both are null the provider generates a unique queue name automatically."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix used by AWS to generate a unique queue name. Mutually exclusive with `name`. When both are null the provider generates a unique queue name automatically."
  type        = string
  default     = null

  validation {
    condition     = !(var.name != null && var.name_prefix != null)
    error_message = "Only one of `name` or `name_prefix` may be set."
  }
}

variable "fifo_queue" {
  description = "Whether the queue is a FIFO queue. A `.fifo` name suffix is appended automatically when required."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues (FIFO only)."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level. Valid values: `messageGroup`, `queue` (FIFO only)."
  type        = string
  default     = null

  validation {
    condition     = var.deduplication_scope == null || var.deduplication_scope == "messageGroup" || var.deduplication_scope == "queue"
    error_message = "`deduplication_scope` must be one of `messageGroup` or `queue`."
  }
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO throughput quota applies to the entire queue or per message group. Valid values: `perQueue`, `perMessageGroupId` (FIFO only)."
  type        = string
  default     = null

  validation {
    condition     = var.fifo_throughput_limit == null || var.fifo_throughput_limit == "perQueue" || var.fifo_throughput_limit == "perMessageGroupId"
    error_message = "`fifo_throughput_limit` must be one of `perQueue` or `perMessageGroupId`."
  }
}

variable "sqs_managed_sse_enabled" {
  description = "Enables SQS-managed server-side encryption. Applied automatically whenever `kms_master_key_id` is omitted."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "ARN or ID of a customer-managed KMS key used for SSE. When null (default) SQS-managed SSE is used instead."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "Length of time (in seconds) for which SQS can reuse a data key to encrypt or decrypt messages."
  type        = number
  default     = 300
}

variable "create_kms_key" {
  description = "Whether to create a customer-managed KMS key to encrypt the queues. Any key used must be declared in this configuration."
  type        = bool
  default     = false
}

variable "create_queue_policy" {
  description = "Whether to attach an IAM policy to the primary queue."
  type        = bool
  default     = false
}

variable "source_policy_documents" {
  description = "List of JSON policy documents merged into the generated queue policy."
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of JSON policy documents that override matching elements of the merged queue policy."
  type        = list(string)
  default     = []
}

variable "policy_statements" {
  description = "List of IAM policy statement objects rendered into the queue policy. Statements that do not specify `resources` default to the primary queue ARN."
  type        = list(any)
  default     = []
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue and wire it to the primary queue through a redrive policy."
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Explicit name of the dead-letter queue. Defaults to the primary queue name with a `-dlq` suffix."
  type        = string
  default     = null
}

variable "dlq_name_prefix" {
  description = "Prefix used by AWS to generate a unique dead-letter queue name. Defaults to the primary queue name prefix with a `-dlq` suffix."
  type        = string
  default     = null
}

variable "max_receive_count" {
  description = "Number of times a message is delivered to the source queue before being moved to the dead-letter queue."
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the dead-letter queue restricting redrive permission to the primary queue only."
  type        = bool
  default     = true
}

variable "dlq_kms_master_key_id" {
  description = "KMS master key used to encrypt the dead-letter queue. Falls back to the primary queue key when null."
  type        = string
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Whether SQS-managed SSE is enabled on the dead-letter queue. Falls back to the primary queue setting when null."
  type        = bool
  default     = null
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout for the queue, in seconds."
  type        = number
  default     = 30
}

variable "message_retention_seconds" {
  description = "Number of seconds SQS retains a message."
  type        = number
  default     = 345600
}

variable "max_message_size" {
  description = "Maximum message size accepted by the queue, in bytes."
  type        = number
  default     = 262144
}

variable "delay_seconds" {
  description = "Default delay applied to every message in the queue, in seconds."
  type        = number
  default     = 0
}

variable "receive_wait_time_seconds" {
  description = "Long polling wait time for the queue, in seconds."
  type        = number
  default     = 0
}

variable "redrive_policy" {
  description = "JSON redrive policy passthrough applied to the primary queue when `create_dlq` is false."
  type        = string
  default     = null
}

variable "tags" {
  description = "Map of tags applied to every taggable resource created by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  # ---------------------------------------------------------------------------
  # Encryption: honour an explicitly supplied key, otherwise use a generated one
  # ---------------------------------------------------------------------------
  kms_key_arn = var.kms_master_key_id != null ? var.kms_master_key_id : (
    var.create_kms_key ? one(aws_kms_key.this[*].arn) : null
  )

  # ---------------------------------------------------------------------------
  # Primary queue naming: append `.fifo` when required, but never twice.
  # When neither `name` nor `name_prefix` is supplied the provider generates a
  # unique queue name automatically; for FIFO queues a `.fifo`-suffixed
  # `name_prefix` is supplied instead so the generated name remains valid.
  # ---------------------------------------------------------------------------
  main_name = var.name == null ? null : (
    var.fifo_queue && !endswith(var.name, ".fifo") ? "${var.name}.fifo" : var.name
  )

  main_name_prefix = var.name_prefix != null ? (
    var.fifo_queue && !endswith(var.name_prefix, ".fifo") ? "${var.name_prefix}.fifo" : var.name_prefix
  ) : (
    var.name == null && var.fifo_queue ? "sqs-queue" : null
  )

  main_queue_display_name = coalesce(local.main_name, local.main_name_prefix, "sqs-queue")

  # ---------------------------------------------------------------------------
  # Dead-letter queue naming: derive from the primary queue, inserting `-dlq`
  # before any `.fifo` suffix
  # ---------------------------------------------------------------------------
  dlq_base_name = var.dlq_name != null ? var.dlq_name : (
    var.name != null ? "${var.name}-dlq" : null
  )

  dlq_base_name_prefix = var.dlq_name_prefix != null ? var.dlq_name_prefix : (
    var.name_prefix != null ? "${var.name_prefix}-dlq" : (
      var.name == null && var.fifo_queue ? "sqs-queue-dlq" : null
    )
  )

  dlq_name = local.dlq_base_name == null ? null : (
    var.fifo_queue && !endswith(local.dlq_base_name, ".fifo") ? "${local.dlq_base_name}.fifo" : local.dlq_base_name
  )

  dlq_name_prefix = local.dlq_base_name_prefix == null ? null : (
    var.fifo_queue && !endswith(local.dlq_base_name_prefix, ".fifo") ? "${local.dlq_base_name_prefix}.fifo" : local.dlq_base_name_prefix
  )

  dlq_display_name = coalesce(local.dlq_name, local.dlq_name_prefix, "sqs-queue-dlq")

  # ---------------------------------------------------------------------------
  # Dead-letter queue encryption with fallback to the primary queue settings
  # ---------------------------------------------------------------------------
  dlq_kms_key_id = var.dlq_kms_master_key_id != null ? var.dlq_kms_master_key_id : local.kms_key_arn

  dlq_sqs_managed_sse_enabled = var.dlq_sqs_managed_sse_enabled != null ? var.dlq_sqs_managed_sse_enabled : (
    local.dlq_kms_key_id == null ? var.sqs_managed_sse_enabled : false
  )

  # ---------------------------------------------------------------------------
  # FIFO-only toggles (nulled out on standard queues)
  # ---------------------------------------------------------------------------
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  # ---------------------------------------------------------------------------
  # Redrive policy attachment decision: either wire the managed DLQ or fall back
  # to a caller-supplied passthrough policy document
  # ---------------------------------------------------------------------------
  manage_redrive_policy = var.create_dlq || var.redrive_policy != null
}

###############################################################################
# Optional customer-managed KMS key
###############################################################################

resource "aws_kms_key" "this" {
  count = var.create && var.create_kms_key ? 1 : 0

  description             = "Customer-managed KMS key for SQS queue encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(var.tags, {
    Name = local.main_queue_display_name
  })
}

resource "aws_kms_alias" "this" {
  count = var.create && var.create_kms_key ? 1 : 0

  name          = "alias/${replace(local.main_queue_display_name, ".", "-")}"
  target_key_id = aws_kms_key.this[0].key_id
}

###############################################################################
# Primary queue (no cross-references to the dead-letter queue)
###############################################################################

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name        = local.main_name
  name_prefix = local.main_name == null ? local.main_name_prefix : null

  fifo_queue = var.fifo_queue

  content_based_deduplication = local.content_based_deduplication
  deduplication_scope         = local.deduplication_scope
  fifo_throughput_limit       = local.fifo_throughput_limit

  visibility_timeout_seconds = var.visibility_timeout_seconds
  message_retention_seconds  = var.message_retention_seconds
  max_message_size           = var.max_message_size
  delay_seconds              = var.delay_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds

  kms_master_key_id                 = local.kms_key_arn
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = local.kms_key_arn == null ? var.sqs_managed_sse_enabled : false

  tags = merge(var.tags, {
    Name = local.main_queue_display_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Dead-letter queue (no cross-references to the primary queue)
###############################################################################

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_name
  name_prefix = local.dlq_name == null ? local.dlq_name_prefix : null

  fifo_queue = var.fifo_queue

  content_based_deduplication = local.content_based_deduplication
  deduplication_scope         = local.deduplication_scope
  fifo_throughput_limit       = local.fifo_throughput_limit

  visibility_timeout_seconds = var.visibility_timeout_seconds
  message_retention_seconds  = var.message_retention_seconds
  max_message_size           = var.max_message_size
  delay_seconds              = var.delay_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds

  kms_master_key_id                 = local.dlq_kms_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = local.dlq_kms_key_id == null ? local.dlq_sqs_managed_sse_enabled : false

  tags = merge(var.tags, {
    Name = local.dlq_display_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Redrive policy (leaf resource; breaks the queue-to-queue reference cycle)
###############################################################################

resource "aws_sqs_queue_redrive_policy" "this" {
  count = var.create && local.manage_redrive_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = one(aws_sqs_queue.dlq[*].arn)
    maxReceiveCount     = var.max_receive_count
  }) : var.redrive_policy
}

###############################################################################
# Redrive allow policy (leaf resource; restricts redrive permission to `byQueue`)
###############################################################################

resource "aws_sqs_queue_redrive_allow_policy" "this" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [one(aws_sqs_queue.this[*].arn)]
  })
}

###############################################################################
# Queue policy
###############################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.policy_statements

    content {
      sid           = try(statement.value.sid, null)
      effect        = try(statement.value.effect, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      resources     = try(statement.value.resources, null) != null ? try(statement.value.resources, null) : [one(aws_sqs_queue.this[*].arn)]
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.this[0].json
}

###############################################################################
# Outputs
###############################################################################

output "queue_id" {
  description = "ID of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "ARN of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "URL of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "Name of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "dead_letter_queue_id" {
  description = "ID of the dead-letter queue, when created."
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dead_letter_queue_arn" {
  description = "ARN of the dead-letter queue, when created."
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dead_letter_queue_url" {
  description = "URL of the dead-letter queue, when created."
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dead_letter_queue_name" {
  description = "Name of the dead-letter queue, when created."
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key created by this module, when enabled."
  value       = one(aws_kms_key.this[*].arn)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.100.0"
    }
  }
}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowBackupServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

variable "backup_name" {
  description = "Base name used to derive the backup vault name and the backup plan name."
  type        = string
  default     = "backup"
}

variable "account_type" {
  description = "Account type that determines whether the workload backup plan, role, and selections are created. Must be \"workload\" or \"backup\"."
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either \"workload\" or \"backup\"."
  }
}

variable "kms_key_arn" {
  description = "Optional ARN of a customer-managed KMS key used to encrypt the backup vault."
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON vault access policy document to attach to the backup vault."
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Minimum retention days that enables the backup vault lock configuration when provided."
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Optional maximum retention days used together with the vault lock configuration."
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Optional grace period, in days, during which the vault lock configuration can still be changed."
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Whether to create SNS notifications for the backup vault."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "Optional ARN of the SNS topic that receives backup vault failure notifications."
  type        = string
  default     = null
}

variable "aws_backup_vault_notifications" {
  description = "List of backup vault events that are routed to the configured SNS topic."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "schedule_expression" {
  description = "Schedule expression used by the backup plan rule."
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "selection_resources" {
  description = "Optional list of explicit resource ARNs added as a resource-based backup selection."
  type        = list(string)
  default     = []
}

variable "copy_actions" {
  description = "List of cross-region or cross-account copy actions that move recovery points to a destination vault."
  type = list(object({
    destination_vault_arn = string
    lifecycle = optional(object({
      cold_storage_after = optional(number)
      delete_after       = optional(number)
    }))
  }))
  default = []
}

locals {
  vault_name          = var.backup_name
  backup_plan_name    = "plan-${var.backup_name}-backup"
  backup_role_name    = "aws-backup-${var.backup_name}"
  is_workload         = var.account_type == "workload"
  enable_vault_lock   = var.min_retention_days != null
  enable_vault_policy = var.vault_policy != null
  enable_vault_sns    = var.enable_aws_backup_vault_notifications

  backup_service_role_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"

  common_tags = {
    BackupName  = var.backup_name
    AccountType = var.account_type
    ManagedBy   = "terraform"
  }
}

resource "aws_backup_vault" "this" {
  name        = local.vault_name
  kms_key_arn = var.kms_key_arn

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_lock_configuration" "this" {
  count = local.enable_vault_lock ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_backup_vault_policy" "this" {
  count = local.enable_vault_policy ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_notifications" "this" {
  count = local.enable_vault_sns ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.aws_backup_vault_notifications
}

resource "aws_iam_role" "backup" {
  count = local.is_workload ? 1 : 0

  name               = local.backup_role_name
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
  description        = "Service role assumed by AWS Backup for the ${var.backup_name} workload."

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = local.is_workload ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = local.backup_service_role_policy_arn
}

resource "aws_backup_plan" "this" {
  count = local.is_workload ? 1 : 0

  name = local.backup_plan_name

  tags = local.common_tags

  rule {
    rule_name         = "backup-rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.schedule_expression
    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = {
      Backup      = "true"
      BackupName  = var.backup_name
      AccountType = var.account_type
    }

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        dynamic "lifecycle" {
          for_each = copy_action.value.lifecycle != null ? [copy_action.value.lifecycle] : []
          iterator = copy_lifecycle
          content {
            cold_storage_after = copy_lifecycle.value.cold_storage_after
            delete_after       = copy_lifecycle.value.delete_after
          }
        }
      }
    }
  }
}

resource "aws_backup_selection" "tag" {
  count = local.is_workload ? 1 : 0

  name         = "${local.backup_plan_name}-tags"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.backup[0].arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

resource "aws_backup_selection" "resources" {
  count = local.is_workload && length(var.selection_resources) > 0 ? 1 : 0

  name         = "${local.backup_plan_name}-resources"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.backup[0].arn
  resources    = var.selection_resources
}

output "backup_vault_arn" {
  description = "ARN of the AWS Backup vault."
  value       = aws_backup_vault.this.arn
}

output "backup_vault_name" {
  description = "Name of the AWS Backup vault."
  value       = aws_backup_vault.this.name
}

output "backup_plan_arn" {
  description = "ARN of the AWS Backup plan, when account_type is \"workload\"."
  value       = one(aws_backup_plan.this[*].arn)
}

output "backup_role_arn" {
  description = "ARN of the AWS Backup IAM role, when account_type is \"workload\"."
  value       = one(aws_iam_role.backup[*].arn)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# -----------------------------------------------------------------------------
# Static / account metadata data sources only (no pre-existing infra lookups)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Naming convention
# -----------------------------------------------------------------------------

variable "name" {
  description = "Base name used for every resource. Defaults to 'config'. Falls back to a generated petname when null or empty."
  type        = string
  default     = "config"
}

resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

locals {
  name = (var.name == null || trimspace(var.name) == "") ? "config-${random_pet.this.id}" : var.name

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  # Provider-accepted enum for the 24-hour periodic evaluation cadence.
  max_frequency = "TwentyFour_Hours"

  # The aws_config_configuration_recorder resource does not export an `arn`
  # attribute, so compose the recorder ARN explicitly. The trailing recorder
  # id is not a stable exported attribute, so a tightly scoped wildcard
  # terminates the recorder-name segment.
  config_recorder_arn = "arn:${local.partition}:config:${local.region}:${local.account_id}:configuration-recorder/${aws_config_configuration_recorder.main.name}/*"

  tags = {
    Name      = local.name
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# KMS customer-managed key (for SNS / Config notifications and bucket SSE-KMS)
# -----------------------------------------------------------------------------

resource "aws_kms_key" "config" {
  description             = "Customer-managed key for AWS Config SNS notifications and snapshot encryption (${local.name})"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.tags
}

resource "aws_kms_alias" "config" {
  name          = "alias/${local.name}"
  target_key_id = aws_kms_key.config.key_id
}

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSnsServiceUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_sns_topic.config.arn]
    }
  }

  statement {
    sid    = "AllowConfigRoleUseOfKey"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.config.arn]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key_policy" "config" {
  key_id = aws_kms_key.config.id
  policy = data.aws_iam_policy_document.kms.json
}

# -----------------------------------------------------------------------------
# S3 snapshot bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "snapshot" {
  bucket        = "${local.name}-snapshots-${local.account_id}"
  force_destroy = true

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "snapshot" {
  bucket                  = aws_s3_bucket.snapshot.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# S3 access-log destination bucket for the snapshot bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "log" {
  bucket        = "${local.name}-logs-${local.account_id}"
  force_destroy = true

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "log" {
  bucket = aws_s3_bucket.log.id

  rule {
    object_ownership = "ObjectWriter"
  }
}

resource "aws_s3_bucket_acl" "log" {
  bucket = aws_s3_bucket.log.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.log]
}

resource "aws_s3_bucket_public_access_block" "log" {
  bucket                  = aws_s3_bucket.log.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [aws_s3_bucket_acl.log]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log" {
  bucket = aws_s3_bucket.log.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "log" {
  bucket = aws_s3_bucket.log.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  target_bucket = aws_s3_bucket.log.id
  target_prefix = "s3-access-logs/"

  depends_on = [
    aws_s3_bucket_acl.log,
    aws_s3_bucket_ownership_controls.log,
  ]
}

# -----------------------------------------------------------------------------
# Snapshot bucket policy for AWS Config
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "snapshot_bucket" {
  statement {
    sid    = "AWSConfigBucketPermissionsCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.snapshot.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.config_recorder_arn]
    }
  }

  statement {
    sid    = "AWSConfigBucketDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.snapshot.arn}/awsconfig/records/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.config_recorder_arn]
    }
  }
}

resource "aws_s3_bucket_policy" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id
  policy = data.aws_iam_policy_document.snapshot_bucket.json

  depends_on = [
    aws_s3_bucket_public_access_block.snapshot,
  ]
}

# -----------------------------------------------------------------------------
# SNS topic (KMS encrypted)
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "config" {
  name              = local.name
  kms_master_key_id = aws_kms_key.config.arn

  tags = local.tags
}

data "aws_iam_policy_document" "sns" {
  statement {
    sid    = "AllowConfigRecorderPublish"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.config.arn]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]
  }

  statement {
    sid    = "AllowAccountOwnerManagement"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["sns:Publish", "sns:GetTopicAttributes", "sns:SetTopicAttributes", "sns:Subscribe"]
    resources = [aws_sns_topic.config.arn]
  }
}

resource "aws_sns_topic_policy" "config" {
  arn    = aws_sns_topic.config.arn
  policy = data.aws_iam_policy_document.sns.json
}

# -----------------------------------------------------------------------------
# IAM role for the AWS Config recorder
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "config_assume_role" {
  statement {
    sid     = "AllowConfigServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config" {
  name               = local.name
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

data "aws_iam_policy_document" "config_s3" {
  statement {
    sid    = "ConfigBucketRead"
    effect = "Allow"

    actions = [
      "s3:GetBucketAcl",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.snapshot.arn]
  }

  statement {
    sid    = "ConfigBucketWrite"
    effect = "Allow"

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.snapshot.arn}/awsconfig/records/*"]
  }
}

resource "aws_iam_role_policy" "config_s3" {
  name   = "${local.name}-s3"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_s3.json
}

data "aws_iam_policy_document" "config_sns" {
  statement {
    sid    = "ConfigPublishNotifications"
    effect = "Allow"

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]
  }
}

resource "aws_iam_role_policy" "config_sns" {
  name   = "${local.name}-sns"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_sns.json
}

# -----------------------------------------------------------------------------
# AWS Config recorder, delivery channel, and recorder status
# -----------------------------------------------------------------------------

resource "aws_config_configuration_recorder" "main" {
  name     = "${local.name}-recorder"
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = "${aws_config_configuration_recorder.main.name}-delivery"
  s3_bucket_name = aws_s3_bucket.snapshot.bucket
  s3_key_prefix  = "awsconfig/records"
  s3_kms_key_arn = aws_kms_key.config.arn
  sns_topic_arn  = aws_sns_topic.config.arn

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [
    aws_s3_bucket.snapshot,
    aws_s3_bucket_policy.snapshot,
    aws_iam_role.config,
    aws_iam_role_policy_attachment.config_managed,
  ]
}

resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.main]
}

# -----------------------------------------------------------------------------
# AWS Config managed rules
# -----------------------------------------------------------------------------

resource "aws_config_config_rule" "cloudtrail_enabled" {
  name = "${local.name}-cloudtrail-enabled"

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name = "${local.name}-iam-pw-policy"

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

resource "aws_config_config_rule" "ec2_vpc" {
  name = "${local.name}-ec2-vpc"

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

resource "aws_config_config_rule" "root_mfa_enabled" {
  name = "${local.name}-root-mfa-enabled"

  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

resource "aws_config_config_rule" "acm_expiration_check" {
  name = "${local.name}-acm-expiration-check"

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

resource "aws_config_config_rule" "ebs_inuse_check" {
  name = "${local.name}-ebs-inuse-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name = "${local.name}-ec2-imdsv2-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

resource "aws_config_config_rule" "rds_encrypted" {
  name = "${local.name}-rds-encrypted"

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

resource "aws_config_config_rule" "rds_private" {
  name = "${local.name}-rds-private"

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

resource "aws_config_config_rule" "rds_private_snapshots" {
  name = "${local.name}-rds-private-snapshots"

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

resource "aws_config_config_rule" "required_tags" {
  name = "${local.name}-required-tags"

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  scope {
    compliance_resource_types = ["S3::Bucket"]
  }

  maximum_execution_frequency = local.max_frequency

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.main]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "config_role_arn" {
  description = "ARN of the AWS Config IAM role"
  value       = aws_iam_role.config.arn
}

output "snapshot_bucket_name" {
  description = "Name of the AWS Config snapshot S3 bucket"
  value       = aws_s3_bucket.snapshot.bucket
}

output "sns_topic_arn" {
  description = "ARN of the AWS Config SNS topic"
  value       = aws_sns_topic.config.arn
}

output "log_bucket_name" {
  description = "Name of the S3 access-log destination bucket"
  value       = aws_s3_bucket.log.bucket
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.100.0"
    }
  }
}

###############################################################################
# Data sources (static provider metadata / well-known AWS managed policies)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy" "drs_agent_policy" {
  name = "AWSElasticDisasterRecoveryAgentPolicy"
}

data "aws_iam_policy" "drs_failback_policy" {
  name = "AWSElasticDisasterRecoveryFailbackPolicy"
}

data "aws_iam_policy" "drs_conversion_server_policy" {
  name = "AWSElasticDisasterRecoveryConversionServerPolicy"
}

data "aws_iam_policy" "drs_recovery_instance_policy" {
  name = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

data "aws_iam_policy" "drs_replication_server_policy" {
  name = "AWSElasticDisasterRecoveryReplicationServerPolicy"
}

data "aws_iam_policy" "amazon_ssm_managed_instance_core" {
  name = "AmazonSSMManagedInstanceCore"
}

###############################################################################
# Locals
###############################################################################

locals {
  service_role_path = "/service-role/"
  root_path         = "/"

  drs_service = "drs.amazonaws.com"
  ec2_service = "ec2.amazonaws.com"

  agent_source_identity_prefix    = "s-*"
  failback_source_identity_prefix = "i-*"

  drs_role_arns = [
    aws_iam_role.drs_agent_role.arn,
    aws_iam_role.drs_failback_role.arn,
    aws_iam_role.drs_conversion_server_role.arn,
    aws_iam_role.drs_recovery_instance_role.arn,
    aws_iam_role.drs_replication_server_role.arn,
    aws_iam_role.drs_recovery_instance_with_launch_actions_role.arn,
  ]

  tags = {
    ManagedBy = "Terraform"
    Service   = "AWS-Elastic-Disaster-Recovery"
  }
}

###############################################################################
# Service roles under /service-role/
###############################################################################

resource "aws_iam_role" "drs_agent_role" {
  name        = "AWSElasticDisasterRecoveryAgentRole"
  path        = local.service_role_path
  description = "Role assumed by the AWS Elastic Disaster Recovery service to manage replication agents."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowDrsServiceToAssumeAgentRole"
        Effect = "Allow"
        Principal = {
          Service = local.drs_service
        }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity",
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "aws:SourceIdentity" = local.agent_source_identity_prefix
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role" "drs_failback_role" {
  name        = "AWSElasticDisasterRecoveryFailbackRole"
  path        = local.service_role_path
  description = "Role assumed by the AWS Elastic Disaster Recovery service to perform failback operations."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowDrsServiceToAssumeFailbackRole"
        Effect = "Allow"
        Principal = {
          Service = local.drs_service
        }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity",
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "aws:SourceIdentity" = local.failback_source_identity_prefix
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role" "drs_conversion_server_role" {
  name        = "AWSElasticDisasterRecoveryConversionServerRole"
  path        = local.service_role_path
  description = "Instance role for AWS Elastic Disaster Recovery conversion servers."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ToAssumeConversionServerRole"
        Effect = "Allow"
        Principal = {
          Service = local.ec2_service
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role" "drs_recovery_instance_role" {
  name        = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path        = local.service_role_path
  description = "Instance role for AWS Elastic Disaster Recovery recovery instances."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ToAssumeRecoveryInstanceRole"
        Effect = "Allow"
        Principal = {
          Service = local.ec2_service
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role" "drs_replication_server_role" {
  name        = "AWSElasticDisasterRecoveryReplicationServerRole"
  path        = local.service_role_path
  description = "Instance role for AWS Elastic Disaster Recovery replication servers."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ToAssumeReplicationServerRole"
        Effect = "Allow"
        Principal = {
          Service = local.ec2_service
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role" "drs_recovery_instance_with_launch_actions_role" {
  name        = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path        = local.service_role_path
  description = "Instance role for AWS Elastic Disaster Recovery recovery instances that run launch actions."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ToAssumeRecoveryInstanceWithLaunchActionsRole"
        Effect = "Allow"
        Principal = {
          Service = local.ec2_service
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

###############################################################################
# Managed policy attachments for the DRS service roles
###############################################################################

resource "aws_iam_role_policy_attachment" "drs_agent_policy_attachment" {
  role       = aws_iam_role.drs_agent_role.name
  policy_arn = data.aws_iam_policy.drs_agent_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_failback_policy_attachment" {
  role       = aws_iam_role.drs_failback_role.name
  policy_arn = data.aws_iam_policy.drs_failback_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_conversion_server_policy_attachment" {
  role       = aws_iam_role.drs_conversion_server_role.name
  policy_arn = data.aws_iam_policy.drs_conversion_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_policy_attachment" {
  role       = aws_iam_role.drs_recovery_instance_role.name
  policy_arn = data.aws_iam_policy.drs_recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_replication_server_policy_attachment" {
  role       = aws_iam_role.drs_replication_server_role.name
  policy_arn = data.aws_iam_policy.drs_replication_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_with_launch_actions_drs_policy_attachment" {
  role       = aws_iam_role.drs_recovery_instance_with_launch_actions_role.name
  policy_arn = data.aws_iam_policy.drs_recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_with_launch_actions_ssm_policy_attachment" {
  role       = aws_iam_role.drs_recovery_instance_with_launch_actions_role.name
  policy_arn = data.aws_iam_policy.amazon_ssm_managed_instance_core.arn
}

###############################################################################
# Root-path initializer role and its customer managed policy
###############################################################################

resource "aws_iam_role" "drs_initializer_role" {
  name        = "AWSElasticDisasterRecoveryInitializerRole"
  path        = local.root_path
  description = "Role used by the calling identity to initialize AWS Elastic Disaster Recovery."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCallingIdentityToAssumeInitializerRole"
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:userid" = data.aws_caller_identity.current.user_id
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  path        = local.root_path
  description = "Least-privilege policy that allows initialization of AWS Elastic Disaster Recovery and its supporting roles."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DrsServiceInitialization"
        Effect = "Allow"
        Action = [
          "drs:InitializeService",
          "drs:Describe*",
          "drs:Get*",
          "drs:List*",
        ]
        Resource = "*"
      },
      {
        Sid    = "InstanceProfileManagement"
        Effect = "Allow"
        Action = [
          "iam:CreateInstanceProfile",
          "iam:AddRoleToInstanceProfile",
          "iam:GetInstanceProfile",
        ]
        Resource = "*"
      },
      {
        Sid    = "CreateDrsServiceLinkedRole"
        Effect = "Allow"
        Action = [
          "iam:CreateServiceLinkedRole",
        ]
        Resource = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/${local.drs_service}/AWSServiceRoleForElasticDisasterRecovery"
        Condition = {
          StringEquals = {
            "iam:AWSServiceName" = local.drs_service
          }
        }
      },
      {
        Sid    = "Ec2AccessRequiredForDrsInitialization"
        Effect = "Allow"
        Action = [
          "ec2:*",
        ]
        Resource = "*"
      },
      {
        Sid    = "PassDrsRolesToAwsServices"
        Effect = "Allow"
        Action = [
          "iam:PassRole",
        ]
        Resource = local.drs_role_arns
        Condition = {
          StringEquals = {
            "iam:PassedToService" = [
              local.ec2_service,
              local.drs_service,
            ]
          }
        }
      },
      {
        Sid    = "DenyPassRoleOutsideDrsRoles"
        Effect = "Deny"
        Action = [
          "iam:PassRole",
        ]
        NotResource = local.drs_role_arns
      },
      {
        Sid    = "AttachDrsManagedPoliciesToDrsRoles"
        Effect = "Allow"
        Action = [
          "iam:AttachRolePolicy",
          "iam:DetachRolePolicy",
          "iam:ListAttachedRolePolicies",
        ]
        # The attached policy cannot be constrained by an IAM condition key, so
        # the permission is scoped to exactly the DRS roles managed in this file.
        Resource = local.drs_role_arns
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "initialize_policy_attachment" {
  role       = aws_iam_role.drs_initializer_role.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

###############################################################################
# Outputs
###############################################################################

output "drs_initializer_role_arn" {
  description = "ARN of the root-path AWS Elastic Disaster Recovery initializer role."
  value       = aws_iam_role.drs_initializer_role.arn
}

output "initialize_policy_arn" {
  description = "ARN of the customer managed InitializePolicy."
  value       = aws_iam_policy.initialize_policy.arn
}

output "drs_agent_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery agent role."
  value       = aws_iam_role.drs_agent_role.arn
}

output "drs_failback_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery failback role."
  value       = aws_iam_role.drs_failback_role.arn
}

output "drs_conversion_server_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery conversion server role."
  value       = aws_iam_role.drs_conversion_server_role.arn
}

output "drs_recovery_instance_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery recovery instance role."
  value       = aws_iam_role.drs_recovery_instance_role.arn
}

output "drs_replication_server_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery replication server role."
  value       = aws_iam_role.drs_replication_server_role.arn
}

output "drs_recovery_instance_with_launch_actions_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery recovery instance with launch actions role."
  value       = aws_iam_role.drs_recovery_instance_with_launch_actions_role.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  environment = "prod"
}

################################################################################
# External VPC - public facing / internet connected
################################################################################

resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = local.environment
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "Production External Default Security Group"
    environment = local.environment
  }
}

resource "aws_subnet" "external_subnet_0" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = "Subnet0-1a"
    environment = local.environment
  }
}

resource "aws_subnet" "external_subnet_1" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name        = "Subnet1-1b"
    environment = local.environment
  }
}

resource "aws_subnet" "external_subnet_2" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = {
    Name        = "Subnet2-1c"
    environment = local.environment
  }
}

resource "aws_subnet" "external_subnet_3" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.3.0/24"
  availability_zone = data.aws_availability_zones.available.names[3]

  tags = {
    Name        = "Subnet3-1d"
    environment = local.environment
  }
}

resource "aws_internet_gateway" "external_gw" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "External GW"
    environment = local.environment
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external_gw.id
  }

  tags = {
    Name        = "External Route Table"
    environment = local.environment
  }
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet_0" {
  subnet_id      = aws_subnet.external_subnet_0.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet_1" {
  subnet_id      = aws_subnet.external_subnet_1.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet_2" {
  subnet_id      = aws_subnet.external_subnet_2.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet_3" {
  subnet_id      = aws_subnet.external_subnet_3.id
  route_table_id = aws_route_table.external.id
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name        = "Production External Default NACL"
    environment = local.environment
  }
}

