    Name        = "Subnet2-1c"
    environment = local.environment
  }
}

resource "aws_subnet" "internal_subnet_3" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = "10.40.3.0/24"
  availability_zone = data.aws_availability_zones.available.names[3]

