################################################################################
# KMS key for encrypting VPC flow log groups
################################################################################

resource "aws_kms_key" "logs" {
  description             = "Customer managed key for VPC flow log CloudWatch log group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUse"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "Production VPC Flow Logs Key"
    environment = local.environment
  }
}

resource "aws_kms_alias" "logs" {
  name          = "alias/prod-vpc-flowlogs"
  target_key_id = aws_kms_key.logs.key_id
}

################################################################################
# VPC Flow Logs - external VPC
################################################################################

resource "aws_cloudwatch_log_group" "external_flow_logs" {
  name              = "/aws/vpc/flowlogs/external"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.logs.arn

  tags = {
    Name        = "Production External VPC Flow Logs"
    environment = local.environment
  }
}

resource "aws_flow_log" "external" {
  vpc_id               = aws_vpc.external.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.external_flow_logs.arn
  iam_role_arn         = aws_iam_role.flow_logs.arn

  tags = {
    Name        = "Production External VPC Flow Log"
    environment = local.environment
  }
}

################################################################################
# VPC Flow Logs - internal VPC
################################################################################

resource "aws_cloudwatch_log_group" "internal_flow_logs" {
  name              = "/aws/vpc/flowlogs/internal"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.logs.arn

  tags = {
    Name        = "Production Internal VPC Flow Logs"
    environment = local.environment
  }
}

resource "aws_flow_log" "internal" {
  vpc_id               = aws_vpc.internal.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.internal_flow_logs.arn
  iam_role_arn         = aws_iam_role.flow_logs.arn

  tags = {
    Name        = "Production Internal VPC Flow Log"
    environment = local.environment
  }
}

################################################################################
# IAM role for VPC Flow Logs delivery
################################################################################

resource "aws_iam_role" "flow_logs" {
  name = "vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowFlowLogsAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "VPC Flow Logs Role"
    environment = local.environment
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "vpc-flow-logs-policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowFlowLogsLogDelivery"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.external_flow_logs.arn}:*",
          "${aws_cloudwatch_log_group.internal_flow_logs.arn}:*"
        ]
      },
      {
        Sid    = "AllowFlowLogsKmsEncryption"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey*",
          "kms:Encrypt"
        ]
        Resource = [
          aws_kms_key.logs.arn
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  private_subnet_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  availability_zones = slice(data.aws_availability_zones.available.names, 0, 3)

  # Prefer a user supplied certificate, otherwise fall back to the imported self-signed cert.
  effective_certificate_arn = coalesce(var.certificate_arn, one(aws_acm_certificate.self_signed[*].arn))

  webhook_url = coalesce(var.url, "https://${aws_lb.n8n.dns_name}")

  logs_encryption_context_arns = [
    "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${var.resource_prefix}-logs",
    "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${var.resource_prefix}-vpc-flow-logs",
  ]

  common_tags = {
    Project   = var.resource_prefix
    ManagedBy = "terraform"
  }
}

variable "resource_prefix" {
  description = "Prefix applied to all resource names and tags."
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional ACM certificate ARN to use for the HTTPS listener. When null a self-signed certificate is generated."
  type        = string
  default     = null
}

variable "url" {
  description = "Optional externally reachable URL override, used for the WEBHOOK_URL environment variable."
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of ECS tasks to run."
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Container image used for the n8n task."
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider to use (FARGATE or FARGATE_SPOT)."
  type        = string
  default     = "FARGATE_SPOT"

  validation {
    condition     = contains(["FARGATE", "FARGATE_SPOT"], var.fargate_type)
    error_message = "fargate_type must be either FARGATE or FARGATE_SPOT."
  }
}

#############################################################
# Networking
#############################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-private-${count.index}"
    Tier = "private"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-public-${count.index}"
    Tier = "public"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

#############################################################
# KMS CMK for log encryption
#############################################################

data "aws_iam_policy_document" "logs_kms" {
  statement {
    sid    = "EnableRootAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryptionContext"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = local.logs_encryption_context_arns
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsDescribe"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions   = ["kms:Describe*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "logs" {
  description             = "CMK used to encrypt ${var.resource_prefix} CloudWatch log groups."
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.logs_kms.json

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-logs-key"
  })
}

resource "aws_kms_alias" "logs" {
  name          = "alias/${var.resource_prefix}-logs"
  target_key_id = aws_kms_key.logs.key_id
}

#############################################################
# CloudWatch logs
#############################################################

resource "aws_cloudwatch_log_group" "n8n" {
  name              = "${var.resource_prefix}-logs"
  retention_in_days = 1
  kms_key_id        = aws_kms_key.logs.arn

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-logs"
  })
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "${var.resource_prefix}-vpc-flow-logs"
  retention_in_days = 1
  kms_key_id        = aws_kms_key.logs.arn

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-vpc-flow-logs"
  })
}

#############################################################
# VPC Flow Logs
#############################################################

data "aws_iam_policy_document" "flow_logs_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "flow_logs" {
  name               = "${var.resource_prefix}-flow-logs"
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-flow-logs"
  })
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "${var.resource_prefix}-flow-logs"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_logs.arn,
          "${aws_cloudwatch_log_group.flow_logs.arn}:*",
        ]
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn         = aws_iam_role.flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-flow-log"
  })
}

#############################################################
# EFS security group
#############################################################

resource "aws_security_group" "efs" {
  name        = "${var.resource_prefix}-efs-sg"
  description = "Allow NFS traffic to the EFS mount targets from within the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "NFS within VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-efs-sg"
  })
}

#############################################################
# EFS
#############################################################

resource "aws_efs_file_system" "main" {
  creation_token   = "${var.resource_prefix}-efs"
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-efs-ap"
  })
}

resource "aws_efs_mount_target" "main" {
  count = 3

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

#############################################################
# Load balancer security group
#############################################################

resource "aws_security_group" "alb" {
  name        = "${var.resource_prefix}-alb-sg"
  description = "Allow inbound HTTP/HTTPS to the internal load balancer."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-alb-sg"
  })
}

#############################################################
# ECS task security group
#############################################################

resource "aws_security_group" "ecs_tasks" {
  name        = "${var.resource_prefix}-tasks-sg"
  description = "Allow traffic to the n8n tasks from the load balancer only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "n8n from load balancer"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-tasks-sg"
  })
}

#############################################################
# Application Load Balancer
#############################################################

resource "aws_lb" "n8n" {
  name                       = "${var.resource_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-alb"
  })
}

resource "aws_lb_target_group" "n8n" {
  name                 = "${var.resource_prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = "/healthz"
    protocol            = "HTTP"
    matcher             = "200"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-tg"
  })
}

#############################################################
# Self-signed certificate (only used when certificate_arn is null)
#############################################################

resource "tls_private_key" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  private_key_pem       = tls_private_key.self_signed[0].private_key_pem
  validity_period_hours = 8760
  early_renewal_hours   = 720

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]

  subject {
    common_name  = "${var.resource_prefix}.internal"
    organization = "n8n"
  }

  dns_names = [
    "${var.resource_prefix}.internal",
    aws_lb.n8n.dns_name,
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  private_key      = tls_private_key.self_signed[0].private_key_pem
  certificate_body = tls_self_signed_cert.self_signed[0].cert_pem

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-self-signed"
  })

  lifecycle {
    create_before_destroy = true
  }
}

#############################################################
# Listeners
#############################################################

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.n8n.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.effective_certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.n8n.arn
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-https-listener"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.n8n.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-http-listener"
  })
}

#############################################################
# IAM
#############################################################

data "aws_iam_policy_document" "ecs_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "task_execution" {
  name               = "${var.resource_prefix}-task-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-task-execution-role"
  })
}

resource "aws_iam_role" "task" {
  name               = "${var.resource_prefix}-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${var.resource_prefix}-task-role"
  })
}

resource "aws_iam_role_policy" "task_execution_logs" {
  name = "${var.resource_prefix}-task-execution-logs"
  role = aws_iam_role.task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*",
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_logs" {
  name = "${var.resource_prefix}-task-logs"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*",
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_efs" {
  name = "${var.resource_prefix}-task-efs"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess",
        ]
        Resource = [
          aws_efs_file_system.main.arn,
        ]
      }
    ]
  })
}

#############################################################
# ECS cluster
#############################################################

resource "aws_ecs_cluster" "n8n" {
  name = var.resource_prefix

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = merge(local.common_tags, {
    Name = var.resource_prefix
  })
}

resource "aws_ecs_cluster_capacity_providers" "n8n" {
  cluster_name = aws_ecs_cluster.n8n.name

  capacity_providers = ["FARGATE", "FARGATE_SPOT"]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

#############################################################
# ECS task definition
#############################################################

resource "aws_ecs_task_definition" "n8n" {
  family                   = var.resource_prefix
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.task_execution.arn
  task_role_arn            = aws_iam_role.task.arn

  container_definitions = jsonencode([
    {
      name      = var.resource_prefix
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        },
      ]

      mountPoints = [
        {
          sourceVolume  = "n8n-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.n8n.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = var.resource_prefix
        }
      }
    }
  ])

  volume {
    name = "n8n-data"

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.main.id
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
        iam             = "ENABLED"
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = var.resource_prefix
  })
}

#############################################################
# ECS service
#############################################################

resource "aws_ecs_service" "n8n" {
  name            = var.resource_prefix
  cluster         = aws_ecs_cluster.n8n.id
  task_definition = aws_ecs_task_definition.n8n.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs_tasks.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.n8n.arn
    container_name   = var.resource_prefix
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.http,
    aws_lb_listener.https,
  ]

  tags = merge(local.common_tags, {
    Name = var.resource_prefix
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.255.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "Quasar"
  })
}

data "aws_iam_policy_document" "vpc_flow_logs_kms" {
  statement {
    sid     = "KeyAdministration"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    resources = ["*"]
  }
}

data "aws_partition" "current" {}

resource "aws_kms_key" "vpc_flow_logs" {
  description             = "Customer-managed key for Quasar VPC flow log encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.vpc_flow_logs_kms.json

  tags = merge(local.tags, {
    Name = "Quasar-VPC-Flow-Logs-Key"
  })
}

resource "aws_kms_alias" "vpc_flow_logs" {
  name          = "alias/quasar-vpc-flow-logs"
  target_key_id = aws_kms_key.vpc_flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc/quasar-flow-logs"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.vpc_flow_logs.arn

  tags = merge(local.tags, {
    Name = "Quasar-VPC-Flow-Logs"
  })
}

data "aws_iam_policy_document" "vpc_flow_logs_assume_role" {
  statement {
    sid     = "VPCFlowLogsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name               = "Quasar-VPC-Flow-Logs-Role"
  assume_role_policy = data.aws_iam_policy_document.vpc_flow_logs_assume_role.json

  tags = merge(local.tags, {
    Name = "Quasar-VPC-Flow-Logs-Role"
  })
}

data "aws_iam_policy_document" "vpc_flow_logs" {
  statement {
    sid    = "VPCFlowLogsWriteToCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
    ]

    resources = [
      aws_cloudwatch_log_group.vpc_flow_logs.arn,
      "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*",
    ]
  }

  statement {
    sid    = "VPCFlowLogsUseKmsKey"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.vpc_flow_logs.arn,
    ]
  }
}

resource "aws_iam_policy" "vpc_flow_logs" {
  name        = "Quasar-VPC-Flow-Logs-Policy"
  description = "Least-privilege policy allowing VPC Flow Logs to publish to the Quasar flow log group"
  policy      = data.aws_iam_policy_document.vpc_flow_logs.json

  tags = merge(local.tags, {
    Name = "Quasar-VPC-Flow-Logs-Policy"
  })
}

resource "aws_iam_role_policy_attachment" "vpc_flow_logs" {
  role       = aws_iam_role.vpc_flow_logs.name
  policy_arn = aws_iam_policy.vpc_flow_logs.arn
}

resource "aws_flow_log" "main" {
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn             = aws_iam_role.vpc_flow_logs.arn
  max_aggregation_interval = 600

  tags = merge(local.tags, {
    Name = "Quasar-VPC-Flow-Log"
  })
}

resource "aws_subnet" "rds_1a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_1e" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.tags, {
    Name = "Quasar RDS - 1E"
  })
}

resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion (jump host) access for the Quasar data stack"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH access from the placeholder administrative CIDR 203.0.113.0/24 - replace with the real administrative range before production use"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]
  }

  egress {
    description = "Allow all outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, {
    Name = "Quasar-Bastion"
  })
}

resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "Public HTTP/HTTPS load balancing proxy for the Quasar data stack"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Public HTTP load balancing (explicitly exposed to 0.0.0.0/0)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Public HTTPS load balancing (explicitly exposed to 0.0.0.0/0)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH access from the Quasar-Bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "Allow all outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, {
    Name = "Quasar-HA-Proxy"
  })
}

resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "CI/CD automation host for the Quasar data stack"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH access from the Quasar-Bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "Jenkins web UI and agent traffic from the Quasar-HA-Proxy security group"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "Allow all outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, {
    Name = "Quasar-Jenkins"
  })
}

resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute nodes for the Quasar data stack"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH access from the Quasar-Bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "SSH access from the Quasar-Jenkins security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.jenkins.id]
  }

  egress {
    description = "Allow all outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, {
    Name = "Quasar-ETL"
  })
}

resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "Multi-AZ PostgreSQL database tier for the Quasar data stack"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access from 0.0.0.0/0 - broad exposure that mirrors the existing database access pattern; this rule MUST be narrowed to the finalized DB client/subnet CIDRs before production use"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "PostgreSQL access from the Quasar-ETL security group"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    description = "Allow all outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, {
    Name = "Quasar-PostgreSQL"
  })
}

###############################################################################
# Terraform & Provider Requirements
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

###############################################################################
# Data Sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "Global creation control for the entire module."
  type        = bool
  default     = true
}

variable "function_name" {
  description = "Name of the Lambda function targeted by the blue/green deployment."
  type        = string
  default     = "lambda-bluegreen-function"
}

variable "alias_name" {
  description = "Name of the Lambda alias used for the blue/green deployment."
  type        = string
  default     = "live"
}

variable "current_version" {
  description = "Lambda version currently served by the alias (blue)."
  type        = string
  default     = "1"
}

variable "target_version" {
  description = "Lambda version the deployment will shift traffic to (green)."
  type        = string
  default     = "1"
}

variable "before_allow_traffic_hook_arn" {
  description = "Optional ARN of the Lambda function invoked before traffic is allowed."
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "Optional ARN of the Lambda function invoked after traffic is allowed."
  type        = string
  default     = ""
}

variable "app_name" {
  description = "Name of the CodeDeploy application (Lambda compute platform)."
  type        = string
  default     = "lambda-bluegreen-app"
}

variable "deployment_config_name" {
  description = "CodeDeploy deployment configuration used by the deployment group."
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "create_app" {
  description = "Whether to create the CodeDeploy application."
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to use an existing CodeDeploy application instead of creating one."
  type        = bool
  default     = false
}

variable "existing_app_name" {
  description = "Name of the existing CodeDeploy application (when use_existing_app is true)."
  type        = string
  default     = ""
}

variable "create_deployment_group" {
  description = "Whether to create the CodeDeploy deployment group."
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to use an existing CodeDeploy deployment group instead of creating one."
  type        = bool
  default     = false
}

variable "existing_deployment_group_name" {
  description = "Name of the existing deployment group (overrides the generated name)."
  type        = string
  default     = ""
}

variable "create_codedeploy_role" {
  description = "Whether to create the IAM role assumed by CodeDeploy."
  type        = bool
  default     = true
}

variable "existing_codedeploy_role_arn" {
  description = "ARN of an existing CodeDeploy service role (when create_codedeploy_role is false)."
  type        = string
  default     = ""
}

variable "codedeploy_service_principals" {
  description = "Service principals allowed to assume the CodeDeploy role."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Whether to attach the inline policy granting lambda:InvokeFunction on lifecycle hooks."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach the inline policy granting sns:Publish on trigger targets."
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Whether to generate and optionally execute the deployment script."
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "AWS CLI command used inside the generated deployment script."
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Seconds to sleep between deployment status polls."
  type        = number
  default     = 5
}

variable "save_deploy_script" {
  description = "Whether to persist the generated deployment script locally."
  type        = bool
  default     = false
}

variable "script_output_path" {
  description = "Local path where the generated deployment script is written."
  type        = string
  default     = "./deploy.sh"
}

variable "run_deployment" {
  description = "Whether to execute the generated deployment script with a null_resource provisioner."
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "When true, a uuid trigger forces the deployment provisioner to re-run."
  type        = bool
  default     = false
}

variable "alarm_arns" {
  description = "CloudWatch alarm ARNs monitored by the deployment group."
  type        = list(string)
  default     = []
}

variable "trigger_configurations" {
  description = "CodeDeploy notification triggers for the deployment group."
  type = list(object({
    trigger_name       = string
    trigger_target_arn = string
    trigger_events     = set(string)
  }))
  default = []
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  lambda_function_arn = "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:${var.function_name}"
  lambda_alias_arn    = "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:${var.function_name}:${var.alias_name}"

  codedeploy_app_name              = var.use_existing_app ? var.existing_app_name : var.app_name
  codedeploy_deployment_group_name = var.existing_deployment_group_name != "" ? var.existing_deployment_group_name : "${var.app_name}-dg"
  codedeploy_role_name             = "${var.app_name}-codedeploy-role"

  hook_resource_arns = compact([
    var.before_allow_traffic_hook_arn,
    var.after_allow_traffic_hook_arn,
    local.lambda_alias_arn,
  ])

  trigger_topic_arns = distinct([for t in var.trigger_configurations : t.trigger_target_arn])

  appspec_hooks = merge(
    var.before_allow_traffic_hook_arn != "" ? { BeforeAllowTraffic = var.before_allow_traffic_hook_arn } : {},
    var.after_allow_traffic_hook_arn != "" ? { AfterAllowTraffic = var.after_allow_traffic_hook_arn } : {},
  )

  appspec_content = jsonencode({
    version = "0.0"
    Resources = [
      merge(
        {
          Name           = var.function_name
          Alias          = var.alias_name
          CurrentVersion = var.current_version
          TargetVersion  = var.target_version
        },
        length(keys(local.appspec_hooks)) > 0 ? { Hooks = local.appspec_hooks } : {},
      )
    ]
  })

  revision_json = jsonencode({
    revisionType = "AppSpecContent"
    appSpecContent = {
      content = local.appspec_content
    }
  })

  revision_base64 = base64encode(local.revision_json)

  deploy_script = <<-EOT
    #!/usr/bin/env bash
    set -euo pipefail

    REVISION_FILE="$(mktemp)"
    trap 'rm -f "$REVISION_FILE"' EXIT

    echo "${local.revision_base64}" | base64 --decode > "$REVISION_FILE"

    DEPLOYMENT_ID=$(${var.aws_cli_command} deploy create-deployment \
      --application-name "${local.codedeploy_app_name}" \
      --deployment-group-name "${local.codedeploy_deployment_group_name}" \
      --description "CodeDeploy blue/green deployment for ${var.function_name} alias ${var.alias_name}" \
      --revision "file://$REVISION_FILE" \
      --query 'deploymentId' \
      --output text)

    echo "Created deployment: $DEPLOYMENT_ID"

    STATUS="InProgress"
    while [ "$STATUS" != "Succeeded" ] && [ "$STATUS" != "Failed" ]; do
      sleep ${var.get_deployment_sleep_timer}
      STATUS=$(${var.aws_cli_command} deploy get-deployment \
        --deployment-id "$DEPLOYMENT_ID" \
        --query 'deploymentInfo.status' \
        --output text)
      echo "Deployment $DEPLOYMENT_ID status: $STATUS"
    done

    if [ "$STATUS" != "Succeeded" ]; then
      echo "Deployment $DEPLOYMENT_ID finished with status $STATUS" >&2
      exit 1
    fi

    echo "Deployment $DEPLOYMENT_ID succeeded"
  EOT
}

###############################################################################
# Lambda execution role (function + alias created for the blue/green target)
###############################################################################

data "aws_iam_policy_document" "lambda_assume" {
  count = var.create ? 1 : 0

  statement {
    sid     = "LambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda" {
  count = var.create ? 1 : 0

  name               = "${var.function_name}-lambda-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume[0].json

  tags = {
    Name        = "${var.function_name}-lambda-role"
    Environment = "blue-green"
  }
}

resource "aws_iam_role_policy_attachment" "lambda_basic" {
  count = var.create ? 1 : 0

  role       = aws_iam_role.lambda[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy_attachment" "lambda_xray" {
  count = var.create ? 1 : 0

  role       = aws_iam_role.lambda[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AWSXRayDaemonWriteAccess"
}

data "archive_file" "lambda" {
  count = var.create ? 1 : 0

  type        = "zip"
  output_path = "${path.module}/${var.function_name}.zip"

  source {
    filename = "index.py"
    content  = <<-PY
      import json


      def handler(event, context):
          return {
              "statusCode": 200,
              "body": json.dumps({"message": "hello from ${var.function_name}"}),
          }
    PY
  }
}

resource "aws_lambda_function" "this" {
  count = var.create ? 1 : 0

  function_name = var.function_name
  role          = aws_iam_role.lambda[0].arn
  handler       = "index.handler"
  runtime       = "python3.12"
  timeout       = 30
  memory_size   = 128
  publish       = true

  filename         = data.archive_file.lambda[0].output_path
  source_code_hash = data.archive_file.lambda[0].output_base64sha256

  tracing_config {
    mode = "Active"
  }

  tags = {
    Name        = var.function_name
    Environment = "blue-green"
  }

  lifecycle {
    ignore_changes = [
      filename,
      source_code_hash,
    ]
  }
}

resource "aws_lambda_alias" "this" {
  count = var.create ? 1 : 0

  name             = var.alias_name
  description      = "Alias targeted by the CodeDeploy blue/green deployment"
  function_name    = aws_lambda_function.this[0].function_name
  function_version = aws_lambda_function.this[0].version
}

###############################################################################
# CodeDeploy Application
###############################################################################

resource "aws_codedeploy_app" "this" {
  count = var.create && var.create_app && !var.use_existing_app ? 1 : 0

  name             = var.app_name
  compute_platform = "Lambda"

  tags = {
    Name        = var.app_name
    Environment = "blue-green"
  }
}

###############################################################################
# CodeDeploy IAM Role
###############################################################################

data "aws_iam_policy_document" "codedeploy_assume" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  statement {
    sid     = "CodeDeployAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.codedeploy_service_principals
    }
  }
}

resource "aws_iam_role" "this" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  name               = local.codedeploy_role_name
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume[0].json

  tags = {
    Name        = local.codedeploy_role_name
    Environment = "blue-green"
  }
}

resource "aws_iam_role_policy_attachment" "codedeploy_managed" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  role       = aws_iam_role.this[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

data "aws_iam_policy_document" "hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy ? 1 : 0

  dynamic "statement" {
    for_each = toset(local.hook_resource_arns)

    content {
      sid       = "InvokeLifecycleHook"
      effect    = "Allow"
      actions   = ["lambda:InvokeFunction"]
      resources = [statement.value]
    }
  }
}

resource "aws_iam_role_policy" "hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy ? 1 : 0

  name   = "${var.app_name}-codedeploy-hooks"
  role   = aws_iam_role.this[0].id
  policy = data.aws_iam_policy_document.hooks[0].json
}

data "aws_iam_policy_document" "triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy ? 1 : 0

  dynamic "statement" {
    for_each = toset(local.trigger_topic_arns)

    content {
      sid       = "PublishNotification"
      effect    = "Allow"
      actions   = ["sns:Publish"]
      resources = [statement.value]
    }
  }
}

resource "aws_iam_role_policy" "triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy ? 1 : 0

  name   = "${var.app_name}-codedeploy-triggers"
  role   = aws_iam_role.this[0].id
  policy = data.aws_iam_policy_document.triggers[0].json
}

###############################################################################
# CodeDeploy Deployment Group
###############################################################################

resource "aws_codedeploy_deployment_group" "this" {
  count = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? 1 : 0

  app_name               = var.use_existing_app ? var.existing_app_name : aws_codedeploy_app.this[0].name
  deployment_group_name  = local.codedeploy_deployment_group_name
  service_role_arn       = var.create_codedeploy_role ? aws_iam_role.this[0].arn : var.existing_codedeploy_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = true
    events  = ["DEPLOYMENT_STOP_ON_ALARM"]
  }

  dynamic "alarm_configuration" {
    for_each = length(var.alarm_arns) > 0 ? [1] : []

    content {
      enabled = true
      alarms  = var.alarm_arns
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_configurations

    content {
      trigger_name       = trigger_configuration.value.trigger_name
      trigger_target_arn = trigger_configuration.value.trigger_target_arn
      trigger_events     = trigger_configuration.value.trigger_events
    }
  }

  tags = {
    Name        = local.codedeploy_deployment_group_name
    Environment = "blue-green"
  }
}

###############################################################################
# Generated Deployment Script
###############################################################################

resource "local_file" "deploy_script" {
  count = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0

  content         = local.deploy_script
  filename        = var.script_output_path
  file_permission = "0755"
}

resource "null_resource" "deploy" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    force_deploy = var.force_deploy ? uuid() : "static"
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = local.deploy_script
  }

  depends_on = [
    aws_codedeploy_app.this,
    aws_codedeploy_deployment_group.this,
    aws_iam_role.this,
    aws_iam_role_policy_attachment.codedeploy_managed,
    aws_lambda_function.this,
    aws_lambda_alias.this,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "codedeploy_app_name" {
  description = "Name of the CodeDeploy application used by the blue/green deployment."
  value       = local.codedeploy_app_name
}

output "codedeploy_deployment_group_name" {
  description = "Name of the CodeDeploy deployment group."
  value       = local.codedeploy_deployment_group_name
}

output "codedeploy_role_arn" {
  description = "ARN of the CodeDeploy service role (created or existing)."
  value       = var.create_codedeploy_role ? try(aws_iam_role.this[0].arn, null) : var.existing_codedeploy_role_arn
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function targeted by the deployment."
  value       = local.lambda_function_arn
}

output "lambda_alias_arn" {
  description = "ARN of the Lambda alias targeted by the deployment."
  value       = local.lambda_alias_arn
}

output "deploy_script_path" {
  description = "Local path of the generated deployment script, when persisted."
  value       = try(local_file.deploy_script[0].filename, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

########################################################################
# Variables
########################################################################

variable "internal_domain" {
  description = "Internal DNS domain applied to the VPC DHCP options and the private hosted zone."
  type        = string
  default     = "internal"
}

variable "admin_cidrs" {
  description = "CIDR blocks permitted to reach the Home SSH security group over SSH."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "public_dns_server" {
  description = "Public DNS resolver used in addition to the VPC provided resolver."
  type        = string
  default     = "8.8.8.8"
}

########################################################################
# Locals
########################################################################

locals {
  flow_log_group_name = "/aws/vpc/flow-logs/main"
}

########################################################################
# Data sources
########################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

########################################################################
# VPC, internet gateway, DHCP options, private DNS zone
########################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "ig"
  }
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain
  domain_name_servers = ["AmazonProvidedDNS", var.public_dns_server]

  tags = {
    Name = "main"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_route53_zone" "internal" {
  name    = var.internal_domain
  comment = "Private hosted zone for the ${var.internal_domain} internal domain"

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = var.internal_domain
  }
}

########################################################################
# KMS CMK for VPC Flow Log encryption
########################################################################

resource "aws_kms_key" "flow_logs" {
  description             = "Customer managed key used to encrypt VPC flow log data."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUse"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.flow_log_group_name}"
          }
        }
      }
    ]
  })

  tags = {
    Name = "main-flow-logs"
  }
}

resource "aws_kms_alias" "flow_logs" {
  name          = "alias/vpc-flow-logs"
  target_key_id = aws_kms_key.flow_logs.key_id
}

########################################################################
# VPC Flow Logs (CloudWatch delivery)
########################################################################

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = local.flow_log_group_name
  retention_in_days = 90
  kms_key_id        = aws_kms_key.flow_logs.arn

  tags = {
    Name = "main"
  }
}

resource "aws_iam_role" "flow_logs" {
  name = "vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "vpc-flow-logs-role"
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "vpc-flow-logs-policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_logs.arn,
          "${aws_cloudwatch_log_group.flow_logs.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn         = aws_iam_role.flow_logs.arn

  tags = {
    Name = "main"
  }

  depends_on = [aws_iam_role_policy.flow_logs]
}

