########################################################################
# Security groups
########################################################################

resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "SSH access from admin CIDRs and group members; egress limited to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the configured admin CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_cidrs
  }

  ingress {
    description = "SSH from members of this security group"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Allow all traffic to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "Home SSH"
  }
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "SSH access from the VPC CIDR and group members; egress limited to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from members of this security group"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Allow all traffic to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "Packer SSH"
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Non-infrastructure (static / local) data sources only
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Input variables (all defaulted so `terraform apply` runs unattended)
###############################################################################

variable "bucket_name" {
  description = "Base name of the S3 bucket."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Prefix the bucket name with the AWS IAM account alias."
  type        = bool
  default     = false
}

variable "account_alias" {
  description = "AWS IAM account alias to provision and (optionally) use as a prefix."
  type        = string
  default     = "benchmark-alias"
}

variable "use_random_suffix" {
  description = "Prefix the bucket name with a random suffix."
  type        = bool
  default     = false
}

variable "enable_s3_public_access_block" {
  description = "Enable the S3 public access block configuration."
  type        = bool
  default     = true
}

variable "ownership_controls" {
  description = "S3 object ownership control setting."
  type        = string
  default     = "BucketOwnerEnforced"
}

variable "kms_master_key_id" {
  description = "KMS key ID used for SSE-KMS. When null, SSE-S3 (AES256) is used."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket keys for SSE-KMS."
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Bucket versioning status."
  type        = string
  default     = "Enabled"
}

variable "force_destroy" {
  description = "Force destroy the bucket (deletes all objects) on terraform destroy."
  type        = bool
  default     = false
}

variable "enable_analytics" {
  description = "Enable S3 storage class analytics."
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable S3 bucket inventory reporting."
  type        = bool
  default     = false
}

variable "enable_bucket_logging" {
  description = "Enable S3 server access logging to the internal or external log bucket."
  type        = bool
  default     = true
}

variable "logging_bucket" {
  description = "External target bucket for access logging. When null, an internal log bucket is created and used."
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status (e.g. Enabled/Suspended). Null disables configuration."
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Canned ACL to apply. Null keeps ACL application disabled."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rule objects applied to the bucket."
  type        = list(any)
  default     = []
}

variable "custom_bucket_policy" {
  description = "Optional JSON bucket policy merged into the enforced policy."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags applied to the bucket."
  type        = map(string)
  default     = {}
}

###############################################################################
# Bucket name derivation
###############################################################################

resource "random_id" "bucket_suffix" {
  count       = var.use_random_suffix ? 1 : 0
  byte_length = 4
}

resource "aws_iam_account_alias" "this" {
  count         = var.use_account_alias_prefix ? 1 : 0
  account_alias = var.account_alias
}

locals {
  random_suffix = join("", random_id.bucket_suffix[*].hex)

  bucket_prefix = (
    var.use_account_alias_prefix ? "${var.account_alias}-" :
    var.use_random_suffix ? "${local.random_suffix}-" :
    ""
  )

  bucket_name = lower(replace("${local.bucket_prefix}${var.bucket_name}", "/[^a-zA-Z0-9.-]/", "-"))

  log_bucket_name = lower(substr("logs-${local.bucket_prefix}${var.bucket_name}", 0, 63))
}

###############################################################################
# S3 bucket (primary data bucket)
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = merge(var.tags, {
    ManagedBy = "terraform"
    AccountId = data.aws_caller_identity.current.account_id
    Region    = data.aws_region.current.name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.ownership_controls
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }

    bucket_key_enabled = var.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = "all_storage_classes_128K"

  rule {
    id     = "abort-incomplete-multipart-upload"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent-version-management"
    status = "Enabled"

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []

    content {
      id     = "analytics-data-expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketAnalytics/"
      }

      expiration {
        days = 30
      }
    }
  }

  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []

    content {
      id     = "inventory-data-expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketInventory/"
      }

      expiration {
        days = 14
      }
    }
  }
}

###############################################################################
# Bucket policy (custom policy + TLS enforcement + service principal writes)
###############################################################################

data "aws_iam_policy_document" "this" {
  source_policy_documents = var.custom_bucket_policy != "" ? [var.custom_bucket_policy] : []

  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowS3InventoryAndAnalyticsDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.this.arn}/_AWSBucketInventory/*",
      "${aws_s3_bucket.this.arn}/_AWSBucketAnalytics/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.this.json
}

###############################################################################
# Analytics, inventory blocks
###############################################################################

resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "EntireBucket"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          format     = "CSV"
          prefix     = "_AWSBucketAnalytics/"
        }
      }
    }
  }
}

resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "EntireBucketInventory"

  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.this.arn
      format     = "ORC"
      prefix     = "_AWSBucketInventory/"
    }
  }
}

###############################################################################
# Access logging target bucket (created internally for greenfield accounts)
###############################################################################

resource "aws_s3_bucket" "logs" {
  bucket        = local.log_bucket_name
  force_destroy = var.force_destroy

  tags = merge(var.tags, {
    ManagedBy = "terraform"
    AccountId = data.aws_caller_identity.current.account_id
    Region    = data.aws_region.current.name
    Purpose   = "s3-access-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logs" {
  bucket = aws_s3_bucket.logs.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.logs]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = var.enable_bucket_logging ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_bucket != null ? var.logging_bucket : aws_s3_bucket.logs.id
  target_prefix = "s3/${aws_s3_bucket.this.id}/"

  depends_on = [aws_s3_bucket_acl.logs]
}

###############################################################################
# Transfer acceleration, ACL, CORS
###############################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "The name of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_name" {
  description = "The bucket name."
  value       = aws_s3_bucket.this.bucket
}

output "bucket_regional_domain_name" {
  description = "The region-specific domain name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_partition" {
  description = "AWS partition the bucket resides in."
  value       = data.aws_partition.current.partition
}

output "logging_bucket_id" {
  description = "The name of the S3 access logging target bucket."
  value       = aws_s3_bucket.logs.id
}

output "logging_bucket_arn" {
  description = "The ARN of the S3 access logging target bucket."
  value       = aws_s3_bucket.logs.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Data sources (static / local lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Optional globally unique name for the primary S3 bucket (max 63 characters)."
  type        = string
  default     = null

  validation {
    condition     = var.name == null || length(var.name) <= 63
    error_message = "The bucket name must be 63 characters or fewer."
  }
}

variable "name_prefix" {
  description = "Optional prefix used to generate the primary S3 bucket name (max 37 characters)."
  type        = string
  default     = null

  validation {
    condition     = var.name_prefix == null || length(var.name_prefix) <= 37
    error_message = "The bucket name prefix must be 37 characters or fewer."
  }
}

variable "force_destroy" {
  description = "Whether all objects should be deleted from the bucket so it can be destroyed without error."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting for the primary bucket."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition = contains(
      ["BucketOwnerEnforced", "ObjectWriter", "BucketOwnerPreferred"],
      var.object_ownership
    )
    error_message = "object_ownership must be one of BucketOwnerEnforced, ObjectWriter, or BucketOwnerPreferred."
  }
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for the primary bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for the primary bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for the primary bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for the primary bucket."
  type        = bool
  default     = true
}

variable "enable_versioning" {
  description = "Whether versioning is enabled on the primary bucket. When false, versioning is Suspended."
  type        = bool
  default     = true
}

variable "bucket_policy_json" {
  description = "Optional custom bucket policy JSON. Its statements are merged with the enforced statements."
  type        = string
  default     = ""
}

variable "logging_source_bucket_arns" {
  description = "Bucket ARNs permitted to deliver server access logs via logging.s3.amazonaws.com."
  type        = list(string)
  default     = []
}

variable "eventbridge_enabled" {
  description = "Whether EventBridge notifications are enabled for the primary bucket."
  type        = bool
  default     = false
}

variable "enable_access_logging" {
  description = "Whether server access logging is enabled for the primary bucket."
  type        = bool
  default     = true
}

variable "logging_target_bucket" {
  description = "Optional target bucket name for access logs. Defaults to the logging bucket created by this configuration."
  type        = string
  default     = ""
}

variable "logging_target_prefix" {
  description = "Prefix used for primary bucket server access log objects."
  type        = string
  default     = "access-logs/"
}

variable "replication_logging_target_prefix" {
  description = "Prefix used for replication destination bucket server access log objects."
  type        = string
  default     = "replication-logs/"
}

variable "object_lock_enabled" {
  description = "Whether S3 object lock is enabled on the primary bucket."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default retention mode for object lock."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be either GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_days" {
  description = "Default retention period in days for object lock. Set to 0 to use years instead."
  type        = number
  default     = 30
}

variable "object_lock_years" {
  description = "Default retention period in years for object lock. Only applied when object_lock_days is 0."
  type        = number
  default     = 0
}

variable "replication_rules" {
  description = "Cross-region replication rules for the primary bucket."
  type = list(object({
    id                              = string
    priority                        = number
    status                          = optional(string, "Enabled")
    prefix                          = optional(string)
    destination_bucket_arn          = optional(string)
    storage_class                   = optional(string)
    replicate_kms_encrypted_objects = optional(bool, false)
  }))
  default = []
}

variable "inventory_configurations" {
  description = "S3 inventory configurations keyed by inventory name."
  type = map(object({
    frequency                = string
    included_object_versions = optional(string, "Current")
    prefix                   = optional(string, "")
    destination_bucket_arn   = optional(string)
    destination_prefix       = optional(string, "inventory")
    format                   = optional(string, "Parquet")
    encryption_sse           = optional(string, "sse_kms")
    kms_key_arn              = optional(string)
    optional_fields          = optional(list(string), [])
  }))
  default = {}
}

variable "cors_rules" {
  description = "List of CORS rules to apply to the primary bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string), [])
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string), [])
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "Lifecycle rules to apply to the primary bucket."
  type = list(object({
    id      = string
    enabled = optional(bool, true)
    prefix  = optional(string)

    expiration = optional(object({
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))

    transitions = optional(list(object({
      days          = number
      storage_class = string
    })), [])

    noncurrent_version_expiration = optional(object({
      days                      = number
      newer_noncurrent_versions = optional(number)
    }))

    noncurrent_version_transitions = optional(list(object({
      days                      = number
      storage_class             = string
      newer_noncurrent_versions = optional(number)
    })), [])

    abort_incomplete_multipart_upload_days = optional(number)
  }))
  default = []
}

###############################################################################
# Locals
###############################################################################

locals {
  bucket_name_base = coalesce(var.name, var.name_prefix, "s3-enterprise")
  account_id       = data.aws_caller_identity.current.account_id

  tags = {
    ManagedBy = "Terraform"
  }

  replication_destination_bucket_arns = distinct([
    for r in var.replication_rules :
    coalesce(r.destination_bucket_arn, aws_s3_bucket.replication.arn)
  ])

  replication_destination_object_arns = [
    for arn in local.replication_destination_bucket_arns : "${arn}/*"
  ]

  ssl_only_statement = {
    Sid       = "DenyNonSecureTransport"
    Effect    = "Deny"
    Principal = "*"
    Action    = "s3:*"
    Resource = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*"
    ]
    Condition = {
      Bool = {
        "aws:SecureTransport" = "false"
      }
    }
  }

  logging_statement = length(var.logging_source_bucket_arns) > 0 ? [{
    Sid       = "AllowS3ServerAccessLogging"
    Effect    = "Allow"
    Principal = { Service = "logging.s3.amazonaws.com" }
    Action    = "s3:PutObject"
    Resource  = var.logging_source_bucket_arns
    Condition = {
      StringEquals = {
        "aws:SourceAccount" = local.account_id
      }
    }
  }] : []

  custom_statements = var.bucket_policy_json != "" ? try(jsondecode(var.bucket_policy_json).Statement, []) : []

  bucket_policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      local.custom_statements,
      [local.ssl_only_statement],
      local.logging_statement
    )
  })
}

###############################################################################
# KMS key and alias (customer managed key, always created)
###############################################################################

resource "aws_kms_key" "main" {
  description             = "KMS key for ${local.bucket_name_base} S3 encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "main" {
  name          = "alias/${local.bucket_name_base}-s3"
  target_key_id = aws_kms_key.main.key_id
}

###############################################################################
# Primary S3 bucket
###############################################################################

resource "aws_s3_bucket" "main" {
  bucket              = var.name
  bucket_prefix       = var.name_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket                  = aws_s3_bucket.main.id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "main" {
  count  = var.object_ownership == "ObjectWriter" ? 1 : 0
  bucket = aws_s3_bucket.main.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_notification" "main" {
  bucket      = aws_s3_bucket.main.id
  eventbridge = var.eventbridge_enabled
}

resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = local.bucket_policy

  depends_on = [aws_s3_bucket_public_access_block.main]
}

resource "aws_s3_bucket_logging" "main" {
  count = var.enable_access_logging ? 1 : 0

  bucket        = aws_s3_bucket.main.id
  target_bucket = var.logging_target_bucket != "" ? var.logging_target_bucket : aws_s3_bucket.logging.id
  target_prefix = var.logging_target_prefix

  lifecycle {
    precondition {
      condition     = (var.logging_target_bucket != "" ? var.logging_target_bucket : aws_s3_bucket.logging.id) != aws_s3_bucket.main.id
      error_message = "Access logging cannot target the same bucket that is being logged."
    }

    precondition {
      condition     = var.object_lock_enabled == false
      error_message = "Server access logging cannot be enabled on a bucket that has object lock enabled."
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "main" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_days > 0 ? var.object_lock_days : null
      years = var.object_lock_days > 0 ? null : var.object_lock_years
    }
  }

  lifecycle {
    precondition {
      condition     = var.enable_access_logging == false
      error_message = "Object lock cannot be enabled while source-bucket access logging is active."
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "main" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      filter {
        prefix = coalesce(rule.value.prefix, "")
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days           = noncurrent_version_expiration.value.days
          newer_noncurrent_versions = noncurrent_version_expiration.value.newer_noncurrent_versions
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions
        content {
          noncurrent_days           = noncurrent_version_transition.value.days
          storage_class             = noncurrent_version_transition.value.storage_class
          newer_noncurrent_versions = noncurrent_version_transition.value.newer_noncurrent_versions
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.main]
}

###############################################################################
# Logging destination bucket
###############################################################################

resource "aws_s3_bucket" "logging" {
  bucket_prefix = "${local.bucket_name_base}-logs-"
  force_destroy = false

  tags = merge(local.tags, { Purpose = "access-logging" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  bucket                  = aws_s3_bucket.logging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  bucket = aws_s3_bucket.logging.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  bucket = aws_s3_bucket.logging.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "logging" {
  bucket = aws_s3_bucket.logging.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "logging_bucket" {
  statement {
    sid    = "AllowS3ServerAccessLogging"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logging.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values = [
        aws_s3_bucket.main.arn,
        aws_s3_bucket.replication.arn,
      ]
    }
  }

  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions   = ["s3:*"]
    resources = [aws_s3_bucket.logging.arn, "${aws_s3_bucket.logging.arn}/*"]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "logging" {
  bucket = aws_s3_bucket.logging.id
  policy = data.aws_iam_policy_document.logging_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.logging]
}

###############################################################################
# Replication destination bucket
###############################################################################

resource "aws_s3_bucket" "replication" {
  bucket_prefix = "${local.bucket_name_base}-replica-"
  force_destroy = false

  tags = merge(local.tags, { Purpose = "replication-destination" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replication" {
  bucket                  = aws_s3_bucket.replication.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replication" {
  bucket = aws_s3_bucket.replication.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replication" {
  bucket = aws_s3_bucket.replication.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "replication" {
  bucket = aws_s3_bucket.replication.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "replication" {
  count = var.enable_access_logging ? 1 : 0

  bucket        = aws_s3_bucket.replication.id
  target_bucket = aws_s3_bucket.logging.id
  target_prefix = var.replication_logging_target_prefix

  lifecycle {
    precondition {
      condition     = aws_s3_bucket.logging.id != aws_s3_bucket.replication.id
      error_message = "Access logging cannot target the same bucket that is being logged."
    }
  }
}

###############################################################################
# Inventory configurations
###############################################################################

resource "aws_s3_bucket_inventory" "main" {
  for_each = var.inventory_configurations

  bucket                   = aws_s3_bucket.main.id
  name                     = each.key
  included_object_versions = each.value.included_object_versions
  optional_fields          = length(each.value.optional_fields) > 0 ? each.value.optional_fields : null

  schedule {
    frequency = each.value.frequency
  }

  filter {
    prefix = each.value.prefix
  }

  destination {
    bucket {
      format     = each.value.format
      bucket_arn = coalesce(each.value.destination_bucket_arn, aws_s3_bucket.logging.arn)
      prefix     = each.value.destination_prefix

      dynamic "encryption" {
        for_each = each.value.encryption_sse == "sse_kms" ? [1] : []
        content {
          sse_kms {
            key_id = coalesce(each.value.kms_key_arn, aws_kms_key.main.arn)
          }
        }
      }

      dynamic "encryption" {
        for_each = each.value.encryption_sse == "sse_s3" ? [1] : []
        content {
          sse_s3 {}
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_policy.main,
    aws_s3_bucket_versioning.main,
  ]
}

###############################################################################
# Replication IAM role and policy
###############################################################################

resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  name = "${local.bucket_name_base}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

data "aws_iam_policy_document" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.main.arn]
  }

  statement {
    sid    = "SourceObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.main.arn}/*"]
  }

  statement {
    sid    = "DestinationObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = local.replication_destination_object_arns
  }

  statement {
    sid    = "KmsReplicationPermissions"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.main.arn]
  }
}

resource "aws_iam_policy" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  name   = "${local.bucket_name_base}-replication-policy"
  policy = data.aws_iam_policy_document.replication[0].json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "main" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      filter {
        prefix = coalesce(rule.value.prefix, "")
      }

      destination {
        bucket        = coalesce(rule.value.destination_bucket_arn, aws_s3_bucket.replication.arn)
        storage_class = rule.value.storage_class
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.replicate_kms_encrypted_objects ? [1] : []
        content {
          sse_kms_encrypted_objects {
            status = "Enabled"
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.main,
    aws_s3_bucket_versioning.replication,
    aws_iam_role_policy_attachment.replication,
  ]

  lifecycle {
    precondition {
      condition     = var.enable_versioning
      error_message = "Cross-region replication requires versioning to be enabled on the source bucket."
    }
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  remote_state_bucket_name = "terraform-remote-state-${local.account_id}-${local.region}"
  log_bucket_name          = "terraform-log-delivery-${local.account_id}-${local.region}"

  ec2_service_linked_role_base       = "arn:aws:iam::${local.account_id}:role/aws-service-role"
  ec2_spot_service_linked_role       = "${local.ec2_service_linked_role_base}/spot.amazonaws.com/AWSServiceRoleForEC2Spot"
  ec2_spot_fleet_service_linked_role = "${local.ec2_service_linked_role_base}/spotfleet.amazonaws.com/AWSServiceRoleForEC2SpotFleet"
  auto_scaling_service_linked_role   = "${local.ec2_service_linked_role_base}/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"

  group_name_developer = "${var.group_name_prefix}_developer"
  group_name_admin     = "${var.group_name_prefix}_admin"

  common_tags = {
    ManagedBy = "Terraform"
    Purpose   = "Account-wide security baseline"
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "group_name_prefix" {
  description = "Prefix applied to the developer and admin IAM group names."
  type        = string
  default     = "app"
}

# ---------------------------------------------------------------------------
# Account-wide IAM password policy
# ---------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "baseline" {
  minimum_password_length        = 14
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  hard_expiry                    = false
  max_password_age               = 90
  password_reuse_prevention      = 5
}

# ---------------------------------------------------------------------------
# Account-wide S3 public access block
# ---------------------------------------------------------------------------
resource "aws_s3_account_public_access_block" "account" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Customer managed KMS key for remote state encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "remote_state" {
  description             = "Customer managed key for Terraform remote state bucket encryption."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "terraform-remote-state"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Terraform remote state bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "remote_state" {
  bucket = local.remote_state_bucket_name

  tags = merge(local.common_tags, {
    Name = local.remote_state_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.remote_state.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "remote_state" {
  bucket                  = aws_s3_bucket.remote_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Dedicated log-delivery bucket (server access logging destination)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "log_delivery" {
  bucket = local.log_bucket_name

  tags = merge(local.common_tags, {
    Name = local.log_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "log_delivery" {
  bucket = aws_s3_bucket.log_delivery.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_delivery" {
  bucket = aws_s3_bucket.log_delivery.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "log_delivery" {
  bucket                  = aws_s3_bucket.log_delivery.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "log_delivery" {
  statement {
    sid    = "AllowS3ServerAccessLogging"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.log_delivery.arn}/log/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.remote_state.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "log_delivery" {
  bucket = aws_s3_bucket.log_delivery.id
  policy = data.aws_iam_policy_document.log_delivery.json
}

# ---------------------------------------------------------------------------
# Server access logging on the remote-state bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  target_bucket = aws_s3_bucket.log_delivery.id
  target_prefix = "log/"
}

# ---------------------------------------------------------------------------
# IAM groups
# ---------------------------------------------------------------------------
resource "aws_iam_group" "developer" {
  name = local.group_name_developer
}

resource "aws_iam_group" "admin" {
  name = local.group_name_admin
}

# ---------------------------------------------------------------------------
# Developer group - AWS managed policy attachments
# ---------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "developer_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

# ---------------------------------------------------------------------------
# Developer group - inline MFA enforcement
# ---------------------------------------------------------------------------
resource "aws_iam_group_policy" "developer_mfa_enforcement" {
  name  = "${var.group_name_prefix}_developer_mfa_enforcement"
  group = aws_iam_group.developer.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnforceMFA"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:GetAccountPasswordPolicy",
          "iam:GetUser",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListAccessKeys",
          "sts:GetSessionToken",
          "sts:GetCallerIdentity"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Developer group - custom policy: manage own access keys
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "developer_access_keys" {
  name        = "${var.group_name_prefix}_developer_access_keys"
  description = "Allows developers to manage their own IAM access keys."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:ListAccessKeys",
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:UpdateAccessKey",
          "iam:GetAccessKeyLastUsed"
        ]
        Resource = "arn:aws:iam::${local.account_id}:user/$${aws:username}"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_access_keys.arn
}

# ---------------------------------------------------------------------------
# Developer group - custom policy: virtual MFA device management
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "developer_mfa" {
  name        = "${var.group_name_prefix}_developer_mfa"
  description = "Allows developers to manage their own virtual MFA devices; deactivation requires MFA."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnVirtualMFADevices"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices",
          "iam:DeactivateMFADevice"
        ]
        Resource = "*"
      },
      {
        Sid       = "DenyDeactivateMFADeviceWithoutMFA"
        Effect    = "Deny"
        Action    = ["iam:DeactivateMFADevice"]
        Resource  = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_mfa.arn
}

# ---------------------------------------------------------------------------
# Developer group - custom policy: MFA-gated S3 access
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "developer_s3" {
  name        = "${var.group_name_prefix}_developer_s3"
  description = "MFA-gated S3 access, region-restricted bucket creation, and remote state protection."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3AccessWithMFA"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::*",
          "arn:aws:s3:::*/*"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid       = "DenyCreateBucketOutsideRegion"
        Effect    = "Deny"
        Action    = ["s3:CreateBucket"]
        Resource  = "*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = data.aws_region.current.name
          }
        }
      },
      {
        Sid    = "DenyRemoteStateBucketAccess"
        Effect = "Deny"
        Action = ["s3:*"]
        Resource = [
          aws_s3_bucket.remote_state.arn,
          "arn:aws:s3:::${aws_s3_bucket.remote_state.id}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_s3" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3.arn
}

# ---------------------------------------------------------------------------
# Developer group - custom policy: MFA-gated EC2 / ELB / CloudWatch / AutoScaling
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "developer_compute" {
  name        = "${var.group_name_prefix}_developer_compute"
  description = "MFA-gated EC2, ELB, CloudWatch and AutoScaling access plus PassRole for service-linked roles."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowComputeServicesWithMFA"
        Effect = "Allow"
        Action = [
          # EC2
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeImages",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:DescribeTags",
          "ec2:DescribeLaunchTemplates",
          "ec2:DescribeLaunchTemplateVersions",
          "ec2:DescribeSpotInstanceRequests",
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:RebootInstances",
          "ec2:TerminateInstances",
          "ec2:RequestSpotInstances",
          "ec2:CancelSpotInstanceRequests",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:CreateKeyPair",
          "ec2:DeleteKeyPair",
          "ec2:ImportKeyPair",
          "ec2:CreateVolume",
          "ec2:DeleteVolume",
          "ec2:AttachVolume",
          "ec2:DetachVolume",
          "ec2:CreateSnapshot",
          "ec2:DeleteSnapshot",
          # Elastic Load Balancing
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:CreateLoadBalancer",
          "elasticloadbalancing:DeleteLoadBalancer",
          "elasticloadbalancing:CreateTargetGroup",
          "elasticloadbalancing:DeleteTargetGroup",
          "elasticloadbalancing:RegisterTargets",
          "elasticloadbalancing:DeregisterTargets",
          "elasticloadbalancing:CreateListener",
          "elasticloadbalancing:DeleteListener",
          "elasticloadbalancing:ModifyListener",
          "elasticloadbalancing:CreateRule",
          "elasticloadbalancing:DeleteRule",
          # CloudWatch
          "cloudwatch:DescribeAlarms",
          "cloudwatch:DescribeAlarmsForMetric",
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DeleteAlarms",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics",
          "cloudwatch:PutMetricData",
          "cloudwatch:SetAlarmState",
          "cloudwatch:EnableAlarmActions",
          "cloudwatch:DisableAlarmActions",
          # AutoScaling
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeAutoScalingInstances",
          "autoscaling:DescribeAutoScalingNotificationTypes",
          "autoscaling:DescribeLaunchConfigurations",
          "autoscaling:DescribeScalingActivities",
          "autoscaling:DescribeScalingProcessTypes",
          "autoscaling:DescribeTags",
          "autoscaling:CreateAutoScalingGroup",
          "autoscaling:UpdateAutoScalingGroup",
          "autoscaling:DeleteAutoScalingGroup",
          "autoscaling:SetDesiredCapacity",
          "autoscaling:TerminateInstanceInAutoScalingGroup",
          "autoscaling:AttachInstances",
          "autoscaling:DetachInstances",
          "autoscaling:CreateOrUpdateTags",
          "autoscaling:DeleteTags",
          "autoscaling:PutScalingPolicy",
          "autoscaling:DeletePolicy",
          "autoscaling:PutNotificationConfiguration"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "AllowPassServiceLinkedRolesWithMFA"
        Effect = "Allow"
        Action = ["iam:PassRole"]
        Resource = [
          local.ec2_spot_service_linked_role,
          local.ec2_spot_fleet_service_linked_role,
          local.auto_scaling_service_linked_role
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_compute" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_compute.arn
}

# ---------------------------------------------------------------------------
# Administrative access
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid     = "AllowAccountRootToAssumeAdminRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = "admin"
  description        = "Administrative role assumable by the account root principal."
  assume_role_policy = data.aws_iam_policy_document.admin_assume_role.json

  tags = merge(local.common_tags, {
    Name = "admin"
  })
}

resource "aws_iam_policy" "admin_full_access" {
  name        = "${var.group_name_prefix}_admin_full_access"
  description = "Full administrative access, gated on the presence of MFA."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowFullAdministrativeAccessWithMFA"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_full_access" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access.arn
}

resource "aws_iam_group_policy" "admin_assume_role" {
  name  = "${var.group_name_prefix}_admin_assume_role"
  group = aws_iam_group.admin.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAssumeAdminRoleWithMFA"
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "developer_group_name" {
  description = "Name of the developer IAM group."
  value       = aws_iam_group.developer.name
}

output "admin_group_name" {
  description = "Name of the administrative IAM group."
  value       = aws_iam_group.admin.name
}

output "admin_role_arn" {
  description = "ARN of the administrative IAM role."
  value       = aws_iam_role.admin.arn
}

output "remote_state_bucket_name" {
  description = "Name of the Terraform remote state S3 bucket."
  value       = aws_s3_bucket.remote_state.id
}

output "log_delivery_bucket_name" {
  description = "Name of the S3 server access log delivery bucket."
  value       = aws_s3_bucket.log_delivery.id
}

output "remote_state_kms_key_arn" {
  description = "ARN of the customer managed KMS key for remote state encryption."
  value       = aws_kms_key.remote_state.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "config" {
  description = "Path to the YAML file that drives the whole CI/CD orchestration framework."
  type        = string
  default     = "config.yml"
}

variable "name_prefix" {
  description = "Prefix used for naming every resource created by this framework."
  type        = string
  default     = "terraforest"
}

variable "create_default_pipeline_role" {
  description = "Create the shared default CodePipeline execution role under /terraforest/."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags applied to every taggable resource created by this configuration."
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  config = try(yamldecode(file(var.config)), {})

  pipelines              = try(local.config.pipelines, [])
  codestar_connections   = try(local.config.codestar_connections, [])
  codebuild_project_defs = try(local.config.codebuild_projects, [])
  lambda_function_defs   = try(local.config.lambda_functions, [])
  config_secret_defs     = try(local.config.secrets, [])

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  common_tags = merge(var.tags, {
    "terraforest:framework"  = "ci-cd-orchestration"
    "terraforest:managed-by" = "terraform"
  })

  pipeline_map = { for p in local.pipelines : p.name => p }

  s3_source_pipeline_names = toset([
    for p in local.pipelines : p.name if try(p.source.provider, "") == "S3"
  ])

  all_actions = flatten([
    for p in local.pipelines : [
      for s in try(p.stages, []) : [
        for a in try(s.actions, []) : a
      ]
    ]
  ])

  codecommit_repo_names = toset(compact(concat(
    [
      for a in local.all_actions : try(a.repository, a.repository_name, null)
      if try(a.provider, "") == "CodeCommit"
    ],
    [
      for p in local.pipelines : try(p.source.repository, null)
      if try(p.source.provider, "") == "CodeCommit"
    ]
  )))

  ecr_repo_names = toset(compact(concat(
    [
      for a in local.all_actions : try(a.repository, a.repository_name, null)
      if try(a.provider, "") == "ECR"
    ],
    [
      for p in local.pipelines : try(p.source.repository, null)
      if try(p.source.provider, "") == "ECR"
    ]
  )))

  codebuild_project_map = length(local.codebuild_project_defs) > 0 ? {
    for p in local.codebuild_project_defs : p.name => {
      name                  = p.name
      description           = try(p.description, "CodeBuild project managed by ${var.name_prefix}")
      buildspec             = try(p.buildspec, null)
      source_type           = try(p.source_type, "CODEPIPELINE")
      environment_type      = try(p.environment_type, "LINUX_CONTAINER")
      compute_type          = try(p.compute_type, "BUILD_GENERAL1_SMALL")
      image                 = try(p.image, "aws/codebuild/amazonlinux2-x86_64-standard:5.0")
      privileged_mode       = try(p.privileged_mode, false)
      build_timeout         = try(p.build_timeout, 60)
      environment_variables = try(p.environment_variables, {})
    }
    } : {
    for a in local.all_actions : try(a.project, a.project_name, a.name) => {
      name                  = try(a.project, a.project_name, a.name)
      description           = try(a.description, "CodeBuild project managed by ${var.name_prefix}")
      buildspec             = try(a.buildspec, null)
      source_type           = try(a.source_type, "CODEPIPELINE")
      environment_type      = try(a.environment_type, "LINUX_CONTAINER")
      compute_type          = try(a.compute_type, "BUILD_GENERAL1_SMALL")
      image                 = try(a.image, "aws/codebuild/amazonlinux2-x86_64-standard:5.0")
      privileged_mode       = try(a.privileged_mode, false)
      build_timeout         = try(a.build_timeout, 60)
      environment_variables = try(a.environment_variables, {})
    } if try(a.provider, "") == "CodeBuild"
  }

  lambda_function_map = { for f in local.lambda_function_defs : f.name => f }

  secret_defs = concat(
    [
      for s in local.config_secret_defs : {
        key      = "global-${try(s.name, "secret")}"
        name     = "${var.name_prefix}/${try(s.name, "secret")}"
        lambda   = null
        env_name = coalesce(try(s.env, null), upper(replace(try(s.name, "value"), "/[^0-9A-Za-z]/", "_")))
      }
    ],
    flatten([
      for f in local.lambda_function_defs : [
        for s in try(f.secrets, []) : {
          key      = "${f.name}-${try(s.name, "secret")}"
          name     = "${var.name_prefix}/${f.name}/${try(s.name, "secret")}"
          lambda   = f.name
          env_name = coalesce(try(s.env, null), upper(replace(try(s.name, "value"), "/[^0-9A-Za-z]/", "_")))
        }
      ]
    ])
  )

  secret_map = { for s in local.secret_defs : s.key => s }

  lambda_secret_envs = {
    for f in local.lambda_function_defs : f.name => {
      for s in local.secret_defs : s.env_name => aws_secretsmanager_secret.this[s.key].arn
      if try(s.lambda, null) == f.name
    }
  }

  connection_arns = { for k, c in aws_codestarconnections_connection.this : k => c.arn }

  codecommit_arns = { for k, r in aws_codecommit_repository.this : k => r.arn }

  events_role_names = {
    for p in local.pipelines :
    p.name => substr("terrabits-${replace(p.name, "/[^0-9A-Za-z+=,.@_-]/", "-")}", 0, 64)
  }

  explicit_triggers = flatten([
    for p in local.pipelines : [
      for t in try(p.triggers, []) : {
        key           = "${p.name}-${try(t.name, try(t.type, "custom"))}"
        pipeline      = p.name
        rule_name     = "terrabits-${p.name}-${try(t.name, try(t.type, "custom"))}"
        type          = try(t.type, "custom")
        schedule      = try(t.schedule_expression, null)
        event_pattern = try(t.event_pattern, null)
        repository    = try(t.repository, try(p.source.repository, null))
        branches      = try(t.branches, [])
        tag_names     = try(t.tag_names, [])
      }
    ]
  ])

  default_triggers = flatten([
    for p in local.pipelines : (
      length(try(p.triggers, [])) > 0 ? [] : concat(
        try(p.source.provider, "") == "CodeCommit" ? [{
          key           = "${p.name}-source-branch"
          pipeline      = p.name
          rule_name     = "terrabits-${p.name}-source"
          type          = "codecommit_branch"
          schedule      = null
          event_pattern = null
          repository    = try(p.source.repository, null)
          branches      = try(p.source.branches, [try(p.source.branch, "main")])
          tag_names     = []
        }] : [],
        try(p.source.provider, "") == "S3" ? [{
          key           = "${p.name}-source-object"
          pipeline      = p.name
          rule_name     = "terrabits-${p.name}-source"
          type          = "s3_object_created"
          schedule      = null
          event_pattern = null
          repository    = null
          branches      = []
          tag_names     = []
        }] : []
      )
    )
  ])

  pipeline_triggers = concat(local.explicit_triggers, local.default_triggers)

  trigger_map = { for t in local.pipeline_triggers : t.key => t }

  trigger_names = {
    for k, t in local.trigger_map :
    k => substr(replace(t.rule_name, "/[^0-9A-Za-z_.-]/", "-"), 0, 64)
  }

  trigger_event_patterns = {
    for k, t in local.trigger_map : k => (
      t.type == "codecommit_branch" ? jsonencode({
        source      = ["aws.codecommit"]
        detail-type = ["CodeCommit Repository State Change"]
        resources   = compact([try(aws_codecommit_repository.this[t.repository].arn, "")])
        detail = {
          event         = ["referenceCreated", "referenceUpdated"]
          referenceType = ["branch"]
          referenceName = t.branches
        }
      }) :
      t.type == "codecommit_tag" ? jsonencode({
        source      = ["aws.codecommit"]
        detail-type = ["CodeCommit Repository State Change"]
        resources   = compact([try(aws_codecommit_repository.this[t.repository].arn, "")])
        detail = {
          event         = ["referenceCreated", "referenceUpdated"]
          referenceType = ["tag"]
          referenceName = t.tag_names
        }
      }) :
      t.type == "s3_object_created" ? jsonencode({
        source      = ["aws.s3"]
        detail-type = ["Object Created"]
        detail = {
          bucket = {
            name = [aws_s3_bucket.artifacts.bucket]
          }
        }
      }) :
      t.event_pattern != null ? (
        can(tostring(t.event_pattern)) ? tostring(t.event_pattern) : jsonencode(t.event_pattern)
      ) :
      jsonencode({ source = ["aws.codepipeline"] })
    )
  }
}

resource "random_id" "bucket_suffix" {
  byte_length = 4

  keepers = {
    name_prefix = var.name_prefix
  }
}

data "aws_iam_policy_document" "artifacts_kms" {
  statement {
    sid       = "EnableAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCicdRolesUseOfKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = ["*"]

    principals {
      type = "AWS"
      identifiers = compact(concat(
        [one(aws_iam_role.pipeline_default[*].arn)],
        [aws_iam_role.codebuild.arn],
        [for r in values(aws_iam_role.events) : r.arn]
      ))
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowS3LoggingServiceUseOfKey"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey",
      "kms:Encrypt",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "artifacts" {
  description             = "KMS key encrypting ${var.name_prefix} pipeline artifacts, build cache and access logs"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.artifacts_kms.json

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "artifacts" {
  name          = "alias/${var.name_prefix}-artifacts"
  target_key_id = aws_kms_key.artifacts.key_id
}

resource "aws_s3_bucket" "logs" {
  bucket = "${var.name_prefix}-logs-${random_id.bucket_suffix.hex}"

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-logs"
    Role = "access-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.artifacts.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "logs_bucket" {
  statement {
    sid       = "DenyNonTLSRequests"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.logs.arn, "${aws_s3_bucket.logs.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "AllowS3ServerAccessLogging"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "logs" {
  bucket = aws_s3_bucket.logs.id
  policy = data.aws_iam_policy_document.logs_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.logs]
}

resource "aws_s3_bucket" "artifacts" {
  bucket = "${var.name_prefix}-artifacts-${random_id.bucket_suffix.hex}"

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-artifacts"
    Role = "codepipeline-artifacts"
  })

  lifecycle {
    prevent_destroy = true
  }
}

