resource "aws_s3_bucket_notification" "artifacts_eventbridge" {
  for_each = length(local.s3_source_pipeline_names) > 0 ? { artifacts = aws_s3_bucket.artifacts.id } : {}

  bucket      = each.value
  eventbridge = true
}

data "aws_iam_policy_document" "codepipeline_assume" {
  statement {
    sid     = "CodePipelineAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codebuild_assume" {
  statement {
    sid     = "CodeBuildAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "lambda_assume" {
  statement {
    sid     = "LambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "events_assume" {
  for_each = local.pipeline_map

  statement {
    sid     = "EventBridgeAssumeRoleWithSourceConditions"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:events:${local.region}:${local.account_id}:rule/terrabits-*"]
    }
  }
}

data "aws_iam_policy_document" "pipeline_default_permissions" {
  statement {
    sid    = "ArtifactAndCacheBucketAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
    ]

    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
      aws_s3_bucket.cache.arn,
      "${aws_s3_bucket.cache.arn}/*",
    ]
  }

  statement {
    sid       = "ArtifactEncryptionKeyAccess"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
    resources = [aws_kms_key.artifacts.arn]
  }

  dynamic "statement" {
    for_each = length(local.codecommit_repo_names) > 0 ? [1] : []

    content {
      sid    = "CodeCommitSourceAccess"
      effect = "Allow"

      actions = [
        "codecommit:GetRepository",
        "codecommit:GetBranch",
        "codecommit:GetCommit",
        "codecommit:GitPull",
        "codecommit:ListRepositories",
        "codecommit:UploadArchive",
        "codecommit:GetUploadArchiveStatus",
      ]

      resources = [for r in aws_codecommit_repository.this : r.arn]
    }
  }

  dynamic "statement" {
    for_each = length(local.codebuild_project_map) > 0 ? [1] : []

    content {
      sid    = "CodeBuildActionAccess"
      effect = "Allow"

      actions = [
        "codebuild:BatchGetBuilds",
        "codebuild:StartBuild",
        "codebuild:BatchGetBuildBatches",
        "codebuild:StartBuildBatch",
      ]

      resources = [
        for name in keys(local.codebuild_project_map) :
        "arn:${local.partition}:codebuild:${local.region}:${local.account_id}:project/${name}"
      ]
    }
  }

  dynamic "statement" {
    for_each = length(local.ecr_repo_names) > 0 ? [1] : []

    content {
      sid    = "EcrSourceAccess"
      effect = "Allow"

      actions = [
        "ecr:DescribeImages",
        "ecr:ListImages",
        "ecr:BatchGetImage",
        "ecr:BatchCheckLayerAvailability",
        "ecr:GetDownloadUrlForLayer",
      ]

      resources = [for r in aws_ecr_repository.this : r.arn]
    }
  }

  dynamic "statement" {
    for_each = length(local.codestar_connections) > 0 ? [1] : []

    content {
      sid       = "CodeStarConnectionAccess"
      effect    = "Allow"
      actions   = ["codestar-connections:UseConnection"]
      resources = [for c in aws_codestarconnections_connection.this : c.arn]
    }
  }
}

data "aws_iam_policy_document" "codebuild_permissions" {
  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/codebuild/*"]
  }

  statement {
    sid    = "ArtifactAndCacheBucketAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
    ]

    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
      aws_s3_bucket.cache.arn,
      "${aws_s3_bucket.cache.arn}/*",
    ]
  }

  statement {
    sid       = "ArtifactEncryptionKeyAccess"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
    resources = [aws_kms_key.artifacts.arn]
  }

  statement {
    sid       = "EcrAuthorizationToken"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  dynamic "statement" {
    for_each = length(local.ecr_repo_names) > 0 ? [1] : []

    content {
      sid    = "EcrRepositoryAccess"
      effect = "Allow"

      actions = [
        "ecr:BatchCheckLayerAvailability",
        "ecr:GetDownloadUrlForLayer",
        "ecr:BatchGetImage",
        "ecr:PutImage",
        "ecr:InitiateLayerUpload",
        "ecr:UploadLayerPart",
        "ecr:CompleteLayerUpload",
        "ecr:DescribeRepositories",
        "ecr:DescribeImages",
      ]

      resources = [for r in aws_ecr_repository.this : r.arn]
    }
  }

  dynamic "statement" {
    for_each = length(local.secret_map) > 0 ? [1] : []

    content {
      sid       = "SecretReadAccess"
      effect    = "Allow"
      actions   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
      resources = [for s in aws_secretsmanager_secret.this : s.arn]
    }
  }
}

data "aws_iam_policy_document" "lambda_permissions" {
  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*"]
  }

  dynamic "statement" {
    for_each = length(local.secret_map) > 0 ? [1] : []

    content {
      sid       = "SecretReadAccess"
      effect    = "Allow"
      actions   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
      resources = [for s in aws_secretsmanager_secret.this : s.arn]
    }
  }
}

resource "aws_iam_role" "pipeline_default" {
  count = var.create_default_pipeline_role ? 1 : 0

  name               = "${var.name_prefix}-codepipeline-default"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume.json

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-codepipeline-default" })
}

resource "aws_iam_role_policy" "pipeline_default" {
  count = var.create_default_pipeline_role ? 1 : 0

  name   = "${var.name_prefix}-codepipeline-default"
  role   = aws_iam_role.pipeline_default[0].id
  policy = data.aws_iam_policy_document.pipeline_default_permissions.json
}

resource "aws_iam_role" "codebuild" {
  name               = "${var.name_prefix}-codebuild"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume.json

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-codebuild" })
}

resource "aws_iam_role_policy" "codebuild" {
  name   = substr("${var.name_prefix}-codebuild", 0, 128)
  role   = aws_iam_role.codebuild.id
  policy = data.aws_iam_policy_document.codebuild_permissions.json
}

resource "aws_iam_role" "lambda" {
  for_each = local.lambda_function_map

  name               = substr("${var.name_prefix}-lambda-${each.key}", 0, 64)
  assume_role_policy = data.aws_iam_policy_document.lambda_assume.json

  tags = merge(local.common_tags, {
    Name   = substr("${var.name_prefix}-lambda-${each.key}", 0, 64)
    Lambda = each.key
  })
}

resource "aws_iam_role_policy" "lambda" {
  for_each = local.lambda_function_map

  name   = substr("${var.name_prefix}-lambda-${each.key}", 0, 128)
  role   = aws_iam_role.lambda[each.key].id
  policy = data.aws_iam_policy_document.lambda_permissions.json
}

resource "aws_iam_role" "events" {
  for_each = local.pipeline_map

  name               = local.events_role_names[each.key]
  assume_role_policy = data.aws_iam_policy_document.events_assume[each.key].json

  tags = merge(local.common_tags, {
    Name     = local.events_role_names[each.key]
    Pipeline = each.key
  })
}

resource "aws_iam_role_policy" "events" {
  for_each = local.pipeline_map

  name = substr("terrabits-start-pipeline-execution", 0, 128)
  role = aws_iam_role.events[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "StartPipelineExecution"
        Effect   = "Allow"
        Action   = ["codepipeline:StartPipelineExecution"]
        Resource = ["arn:${local.partition}:codepipeline:${local.region}:${local.account_id}:${each.value.name}"]
      }
    ]
  })
}

resource "aws_codestarconnections_host" "this" {
  for_each = {
    for c in local.codestar_connections : c.name => c
    if try(c.provider_type, "") == "GitHubEnterpriseServer"
  }

  name              = "${var.name_prefix}-${each.value.name}"
  provider_endpoint = each.value.provider_endpoint
  provider_type     = "GitHubEnterpriseServer"
}

resource "aws_codestarconnections_connection" "this" {
  for_each = { for c in local.codestar_connections : c.name => c }

  name          = "${var.name_prefix}-${each.value.name}"
  provider_type = each.value.provider_type
  host_arn      = try(aws_codestarconnections_host.this[each.key].arn, null)

  tags = merge(local.common_tags, {
    Name     = "${var.name_prefix}-${each.value.name}"
    Provider = each.value.provider_type
  })
}

resource "aws_codecommit_repository" "this" {
  for_each = local.codecommit_repo_names

  repository_name = each.value
  description     = "CodeCommit repository managed by ${var.name_prefix}"

  tags = merge(local.common_tags, { Name = each.value })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_repository" "this" {
  for_each = local.ecr_repo_names

  name                 = each.value
  image_tag_mutability = "MUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = merge(local.common_tags, { Name = each.value })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "this" {
  for_each = local.secret_map

  name                    = each.value.name
  description             = "Secret managed by ${var.name_prefix} CI/CD orchestration framework"
  recovery_window_in_days = 7

  tags = merge(local.common_tags, { Name = each.value.name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "random_password" "secret" {
  for_each = local.secret_map

  length  = 32
  special = true
}

resource "aws_secretsmanager_secret_version" "this" {
  for_each = local.secret_map

  secret_id     = aws_secretsmanager_secret.this[each.key].id
  secret_string = random_password.secret[each.key].result
}

resource "aws_codebuild_project" "this" {
  for_each = local.codebuild_project_map

  name          = each.value.name
  description   = each.value.description
  service_role  = aws_iam_role.codebuild.arn
  build_timeout = each.value.build_timeout

  source {
    type      = each.value.source_type
    buildspec = each.value.buildspec
  }

  environment {
    type            = each.value.environment_type
    compute_type    = each.value.compute_type
    image           = each.value.image
    privileged_mode = each.value.privileged_mode

    dynamic "environment_variable" {
      for_each = each.value.environment_variables

      content {
        name  = environment_variable.key
        value = tostring(environment_variable.value)
        type  = "PLAINTEXT"
      }
    }
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.cache.bucket
  }

  artifacts {
    type = "CODEPIPELINE"
  }

  tags = merge(local.common_tags, { Name = each.value.name })
}

resource "aws_codepipeline" "this" {
  for_each = local.pipeline_map

  name = each.value.name

  role_arn = coalesce(
    try(each.value.role_arn, null),
    one(aws_iam_role.pipeline_default[*].arn),
    "arn:${local.partition}:iam::${local.account_id}:role/terraforest/${var.name_prefix}-codepipeline-default"
  )

  tags = merge(local.common_tags, { Name = each.value.name })

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.artifacts.arn
      type = "KMS"
    }
  }

  dynamic "stage" {
    for_each = try(each.value.stages, [])

    content {
      name = stage.value.name

      dynamic "action" {
        for_each = try(stage.value.actions, [])

        content {
          name             = action.value.name
          category         = try(action.value.category, "Build")
          owner            = try(action.value.owner, "AWS")
          provider         = action.value.provider
          version          = try(action.value.version, "1")
          run_order        = try(action.value.run_order, null)
          input_artifacts  = try(action.value.input_artifacts, [])
          output_artifacts = try(action.value.output_artifacts, [])

          configuration = {
            for k, v in merge(
              try(action.value.configuration, {}),
              {
                RepositoryName       = try(action.value.repository, action.value.repository_name, null)
                BranchName           = try(action.value.branch, null)
                PollForSourceChanges = try(action.value.poll_for_source_changes, try(action.value.provider, "") == "S3" ? "false" : null)
                FullRepositoryId     = try(action.value.full_repository_id, null)
                ConnectionArn        = try(local.connection_arns[try(action.value.connection, "")], null)
                ProjectName          = try(action.value.project, action.value.project_name, null)
                BuildSpec            = try(action.value.buildspec, null)
                S3Bucket             = try(action.value.s3_bucket, null)
                S3ObjectKey          = try(action.value.s3_object_key, null)
                S3ObjectVersion      = try(action.value.s3_object_version, null)
                ImageTag             = try(action.value.image_tag, null)
                FunctionName         = try(action.value.function_name, null)
                UserParameters       = try(action.value.user_parameters, null)
                CustomData           = try(action.value.custom_data, null)
                ExternalEntityLink   = try(action.value.external_entity_link, null)
              }
            ) : k => tostring(v)
            if v != null && tostring(v) != ""
          }
        }
      }
    }
  }
}

module "lambda" {
  for_each = local.lambda_function_map
  source   = "terraform-aws-modules/lambda/aws"
  version  = "~> 7.2"

  function_name = each.value.name
  description   = try(each.value.description, "Lambda function managed by ${var.name_prefix}")
  handler       = try(each.value.handler, "index.handler")
  runtime       = try(each.value.runtime, "python3.12")
  timeout       = try(each.value.timeout, 60)
  memory_size   = try(each.value.memory_size, 256)
  architectures = try(each.value.architectures, ["x86_64"])
  source_path   = try(each.value.source_path, "${path.module}/lambda/${each.value.name}")

  create_role = false
  lambda_role = aws_iam_role.lambda[each.key].arn

  environment_variables = merge(
    try(each.value.environment_variables, {}),
    try(local.lambda_secret_envs[each.key], {})
  )

  tags = merge(local.common_tags, { Name = each.value.name })
}

resource "aws_cloudwatch_event_rule" "pipelines" {
  for_each = local.trigger_map

  name        = local.trigger_names[each.key]
  description = "terrabits trigger rule for CodePipeline ${each.value.pipeline}"

  schedule_expression = each.value.type == "schedule" ? each.value.schedule : null
  event_pattern       = each.value.type == "schedule" ? null : local.trigger_event_patterns[each.key]

  tags = merge(local.common_tags, {
    Name     = local.trigger_names[each.key]
    Pipeline = each.value.pipeline
  })
}

resource "aws_cloudwatch_event_target" "pipelines" {
  for_each = local.trigger_map

  rule     = aws_cloudwatch_event_rule.pipelines[each.key].name
  arn      = aws_codepipeline.this[each.value.pipeline].arn
  role_arn = aws_iam_role.events[each.value.pipeline].arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Provider metadata lookups (static, account-level metadata only)
################################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

################################################################################
# Module toggles and inputs
################################################################################

variable "create" {
  description = "Controls whether resources are created by this module."
  type        = bool
  default     = true
}

variable "create_new_security_group" {
  description = "When true a new security group is created. When false the module attaches rules to an existing security group supplied via existing_security_group_id."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the security group to create. Also used to derive the VPC flow log, log group and KMS alias names."
  type        = string
  default     = "app"

  validation {
    condition     = length(var.name) > 0
    error_message = "The security group name must not be empty."
  }
}

variable "description" {
  description = "Description of the security group to create."
  type        = string
  default     = "Security group managed by Terraform"
}

variable "existing_security_group_id" {
  description = "ID of a caller-supplied existing security group to add rules to when create_new_security_group is false."
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "ID of the VPC in which to create the new security group. When empty a VPC is created so the module remains self-contained."
  type        = string
  default     = ""
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC created by this module when vpc_id is empty. Also used as the default private target for the default egress rule."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr_block, 0))
    error_message = "vpc_cidr_block must be a valid CIDR block."
  }
}

variable "revoke_rules_on_delete" {
  description = "Whether all rules are revoked when the new security group is deleted. Applied as a top-level resource argument on aws_security_group."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags applied to all resources created by this module."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

################################################################################
# VPC flow log inputs
################################################################################

variable "enable_flow_logs" {
  description = "Whether to create VPC flow logs (plus their log group, KMS key and delivery IAM role) for the VPC created by this module."
  type        = bool
  default     = true
}

variable "flow_log_traffic_type" {
  description = "The type of traffic to capture in the VPC flow log. Valid values are ALL, ACCEPT or REJECT."
  type        = string
  default     = "ALL"

  validation {
    condition     = contains(["ALL", "ACCEPT", "REJECT"], var.flow_log_traffic_type)
    error_message = "flow_log_traffic_type must be one of ALL, ACCEPT or REJECT."
  }
}

variable "flow_log_retention_days" {
  description = "Number of days to retain VPC flow log events in CloudWatch Logs."
  type        = number
  default     = 365

  validation {
    condition     = contains([0, 1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653], var.flow_log_retention_days)
    error_message = "flow_log_retention_days must be a value supported by CloudWatch Logs retention."
  }
}

variable "flow_log_kms_key_arn" {
  description = "Optional caller-supplied KMS key ARN used to encrypt the flow log CloudWatch log group. When empty a customer-managed KMS key is created by this module."
  type        = string
  default     = ""
}

variable "flow_log_kms_deletion_window_in_days" {
  description = "Waiting period in days before the created KMS key is deleted. Must be between 7 and 30."
  type        = number
  default     = 30

  validation {
    condition     = var.flow_log_kms_deletion_window_in_days >= 7 && var.flow_log_kms_deletion_window_in_days <= 30
    error_message = "flow_log_kms_deletion_window_in_days must be between 7 and 30."
  }
}

################################################################################
# Security group rule definitions
################################################################################

variable "new_sg_ingress_rules" {
  description = "List of ingress rules applied to the newly created security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = number
    to_port                      = number
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.new_sg_ingress_rules : length([
        for target in [rule.cidr_ipv4, rule.cidr_ipv6, rule.referenced_security_group_id, rule.prefix_list_id] : target if target != null
      ]) == 1
    ])
    error_message = "Each rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

variable "new_sg_egress_rules" {
  description = "List of egress rules applied to the newly created security group. When left empty a private, non-public default egress rule to the module VPC CIDR is applied. Public (0.0.0.0/0 or ::/0) egress must be supplied explicitly by the caller. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = number
    to_port                      = number
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.new_sg_egress_rules : length([
        for target in [rule.cidr_ipv4, rule.cidr_ipv6, rule.referenced_security_group_id, rule.prefix_list_id] : target if target != null
      ]) == 1
    ])
    error_message = "Each rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

variable "existing_sg_ingress_rules" {
  description = "List of ingress rules applied to a caller-supplied existing security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = number
    to_port                      = number
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_sg_ingress_rules : length([
        for target in [rule.cidr_ipv4, rule.cidr_ipv6, rule.referenced_security_group_id, rule.prefix_list_id] : target if target != null
      ]) == 1
    ])
    error_message = "Each rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

variable "existing_sg_egress_rules" {
  description = "List of egress rules applied to a caller-supplied existing security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = string
    from_port                    = number
    to_port                      = number
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_sg_egress_rules : length([
        for target in [rule.cidr_ipv4, rule.cidr_ipv6, rule.referenced_security_group_id, rule.prefix_list_id] : target if target != null
      ]) == 1
    ])
    error_message = "Each rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

################################################################################
# Managed prefix list inputs
################################################################################

variable "create_prefix_list" {
  description = "Whether to create a customer-managed EC2 prefix list when no existing prefix list IDs are supplied."
  type        = bool
  default     = false
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list (IPv4 or IPv6)."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either IPv4 or IPv6."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries the managed prefix list can hold."
  type        = number
  default     = 0

  validation {
    condition     = !var.create_prefix_list || (var.prefix_list_max_entries > 0 && var.prefix_list_max_entries >= length(var.prefix_list_entries))
    error_message = "When create_prefix_list is true, prefix_list_max_entries must be greater than zero and at least the number of prefix_list_entries."
  }
}

variable "prefix_list_entries" {
  description = "List of CIDR blocks used to populate the managed prefix list."
  type        = list(string)
  default     = []
}

variable "existing_prefix_list_ids" {
  description = "Caller-supplied managed prefix list IDs. When non-empty no prefix list is created and the first entry is used as the module prefix list."
  type        = list(string)
  default     = []
}

################################################################################
# Locals
################################################################################

locals {
  tags = merge(
    var.tags,
    {
      Name = var.name
    },
  )

  # Fall back to a VPC created within this configuration when no VPC ID is supplied.
  vpc_id = var.vpc_id != "" ? var.vpc_id : try(aws_vpc.main[0].id, null)

  prefix_list_ids = length(var.existing_prefix_list_ids) > 0 ? var.existing_prefix_list_ids : aws_ec2_managed_prefix_list.main[*].id
  prefix_list_id  = length(local.prefix_list_ids) > 0 ? local.prefix_list_ids[0] : null

  # Private, non-public default egress rule (VPC CIDR only) used when the caller
  # does not supply explicit egress rules. Public egress must be opted into
  # explicitly, which prevents unrestricted 0.0.0.0/0 egress by default.
  default_new_sg_egress_rules = [
    {
      cidr_ipv4                    = var.vpc_cidr_block
      cidr_ipv6                    = null
      referenced_security_group_id = null
      prefix_list_id               = null
      ip_protocol                  = "-1"
      from_port                    = 0
      to_port                      = 0
      description                  = "Allow outbound traffic within the VPC CIDR"
    }
  ]

  effective_new_sg_egress_rules = length(var.new_sg_egress_rules) > 0 ? var.new_sg_egress_rules : local.default_new_sg_egress_rules

  new_sg_ingress_rules      = { for idx, rule in var.new_sg_ingress_rules : tostring(idx) => rule }
  new_sg_egress_rules       = { for idx, rule in local.effective_new_sg_egress_rules : tostring(idx) => rule }
  existing_sg_ingress_rules = { for idx, rule in var.existing_sg_ingress_rules : tostring(idx) => rule }
  existing_sg_egress_rules  = { for idx, rule in var.existing_sg_egress_rules : tostring(idx) => rule }

  create_new_security_group = var.create && var.create_new_security_group
  manage_existing_sg        = var.create && !var.create_new_security_group && var.existing_security_group_id != ""

  # Flow logs only make sense when this module owns the VPC it creates.
  create_flow_logs = var.create && var.create_new_security_group && var.vpc_id == "" && var.enable_flow_logs

  # Create a local CMK only when flow logs are enabled and the caller did not
  # supply their own key ARN.
  create_flow_log_kms_key = local.create_flow_logs && var.flow_log_kms_key_arn == ""
}

################################################################################
# Supporting VPC (only when no VPC ID is supplied)
################################################################################

resource "aws_vpc" "main" {
  count = var.create && var.create_new_security_group && var.vpc_id == "" ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "${var.name}-vpc" })
}

################################################################################
# VPC flow logs (KMS key + log group + delivery role + flow log)
################################################################################

data "aws_iam_policy_document" "flow_log_kms_key" {
  count = local.create_flow_log_kms_key ? 1 : 0

  # Account administration access.
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"

    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  # Scope CloudWatch Logs service usage to the flow log group via the logs service.
  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${var.name}-vpc-flow-logs"]
    }
  }
}

resource "aws_kms_key" "flow_logs" {
  count = local.create_flow_log_kms_key ? 1 : 0

  description             = "CMK for ${var.name} VPC flow log group"
  deletion_window_in_days = var.flow_log_kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.flow_log_kms_key[0].json

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "flow_logs" {
  count = local.create_flow_log_kms_key ? 1 : 0

  name          = "alias/${var.name}-flow-logs"
  target_key_id = aws_kms_key.flow_logs[0].key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  count = local.create_flow_logs ? 1 : 0

  name              = "${var.name}-vpc-flow-logs"
  retention_in_days = var.flow_log_retention_days
  kms_key_id        = var.flow_log_kms_key_arn != "" ? var.flow_log_kms_key_arn : try(aws_kms_key.flow_logs[0].arn, null)

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "flow_logs_assume_role" {
  count = local.create_flow_logs ? 1 : 0

  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "flow_logs" {
  count = local.create_flow_logs ? 1 : 0

  name               = "${var.name}-vpc-flow-logs"
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role[0].json

  tags = local.tags
}

data "aws_iam_policy_document" "flow_logs_delivery" {
  count = local.create_flow_logs ? 1 : 0

  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
    ]

    resources = [
      aws_cloudwatch_log_group.flow_logs[0].arn,
      "${aws_cloudwatch_log_group.flow_logs[0].arn}:*",
    ]
  }

  statement {
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = [
      var.flow_log_kms_key_arn != "" ? var.flow_log_kms_key_arn : try(aws_kms_key.flow_logs[0].arn, "*"),
    ]
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  count = local.create_flow_logs ? 1 : 0

  name   = "${var.name}-vpc-flow-logs"
  role   = aws_iam_role.flow_logs[0].id
  policy = data.aws_iam_policy_document.flow_logs_delivery[0].json
}

resource "aws_flow_log" "main" {
  count = local.create_flow_logs ? 1 : 0

  vpc_id               = aws_vpc.main[0].id
  traffic_type         = var.flow_log_traffic_type
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_logs[0].arn
  iam_role_arn         = aws_iam_role.flow_logs[0].arn

  tags = local.tags
}

################################################################################
# New security group
################################################################################

resource "aws_security_group" "new" {
  count = local.create_new_security_group ? 1 : 0

  name                   = var.name
  description            = var.description
  vpc_id                 = local.vpc_id
  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = local.tags

  lifecycle {
    create_before_destroy = true
  }
}

################################################################################
# Rules for the new security group
################################################################################

resource "aws_vpc_security_group_ingress_rule" "new" {
  for_each = local.create_new_security_group ? local.new_sg_ingress_rules : {}

  security_group_id            = aws_security_group.new[0].id
  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id == "managed" ? local.prefix_list_id : each.value.prefix_list_id
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  description                  = each.value.description

  tags = local.tags
}

resource "aws_vpc_security_group_egress_rule" "new" {
  for_each = local.create_new_security_group ? local.new_sg_egress_rules : {}

  security_group_id            = aws_security_group.new[0].id
  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id == "managed" ? local.prefix_list_id : each.value.prefix_list_id
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  description                  = each.value.description

  tags = local.tags
}

################################################################################
# Rules for a caller-supplied existing security group
################################################################################

resource "aws_vpc_security_group_ingress_rule" "existing" {
  for_each = local.manage_existing_sg ? local.existing_sg_ingress_rules : {}

  security_group_id            = var.existing_security_group_id
  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id == "managed" ? local.prefix_list_id : each.value.prefix_list_id
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  description                  = each.value.description

  tags = local.tags
}

resource "aws_vpc_security_group_egress_rule" "existing" {
  for_each = local.manage_existing_sg ? local.existing_sg_egress_rules : {}

  security_group_id            = var.existing_security_group_id
  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id == "managed" ? local.prefix_list_id : each.value.prefix_list_id
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  description                  = each.value.description

  tags = local.tags
}

################################################################################
# Optional customer-managed prefix list
################################################################################

resource "aws_ec2_managed_prefix_list" "main" {
  count = var.create && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? 1 : 0

  name           = "${var.name}-prefix-list"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = { for idx, cidr in var.prefix_list_entries : tostring(idx) => cidr }

    content {
      cidr        = entry.value
      description = "Managed prefix list entry ${entry.key}"
    }
  }

  tags = merge(var.tags, { Name = "${var.name}-prefix-list" })
}

################################################################################
# Outputs
################################################################################

output "security_group_id" {
  description = "ID of the security group managed by this module, either newly created or the caller-supplied existing group."
  value       = var.create_new_security_group ? try(aws_security_group.new[0].id, null) : var.existing_security_group_id
}

output "security_group_arn" {
  description = "ARN of the newly created security group, when one is created."
  value       = var.create_new_security_group ? try(aws_security_group.new[0].arn, null) : null
}

output "vpc_id" {
  description = "ID of the VPC used by the security group managed by this module."
  value       = local.vpc_id
}

output "flow_log_id" {
  description = "ID of the VPC flow log created by this module, when one is created."
  value       = try(aws_flow_log.main[0].id, null)
}

output "flow_log_group_arn" {
  description = "ARN of the CloudWatch log group receiving VPC flow logs, when one is created."
  value       = try(aws_cloudwatch_log_group.flow_logs[0].arn, null)
}

output "flow_log_kms_key_arn" {
  description = "ARN of the KMS key encrypting the flow log group, either created by this module or the caller-supplied key."
  value       = var.flow_log_kms_key_arn != "" ? var.flow_log_kms_key_arn : try(aws_kms_key.flow_logs[0].arn, null)
}

output "prefix_list_id" {
  description = "ID of the prefix list used by this module, either newly created or the first caller-supplied existing prefix list."
  value       = local.prefix_list_id
}

output "prefix_list_ids" {
  description = "All prefix list IDs available to this module."
  value       = local.prefix_list_ids
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name applied to all resource tags."
  type        = string
  default     = "dev"
}

locals {
  environment = var.environment
}

# -----------------------------------------------------------------------------
# Customer-managed KMS key for DynamoDB encryption at rest
# -----------------------------------------------------------------------------

resource "aws_kms_key" "dynamodb" {
  description             = "Customer-managed KMS key for DynamoDB tables (wallet/file management backend)"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "dynamodb"
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
