terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0.0"
    }
  }
}

variable "name" {
  description = "Name of the AWS Transfer Family server. If not provided, a random pet name is generated."
  type        = string
  default     = null
}

variable "logging_role_arn" {
  description = "ARN of the IAM role for Transfer Family logging. If not provided, a role is created."
  type        = string
  default     = null
}

variable "enable_api_gateway" {
  description = "Whether to use API Gateway as the identity provider."
  type        = bool
  default     = false
}

variable "endpoint_type" {
  description = "Endpoint type for the Transfer server."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of PUBLIC, VPC, or VPC_ENDPOINT."
  }
}

variable "protocols" {
  description = "Protocols enabled for the Transfer server."
  type        = list(string)
  default     = ["SFTP"]
}

variable "storage_type" {
  description = "Storage type for user home directories."
  type        = string
  default     = "S3"
}

variable "certificate_arn" {
  description = "ACM certificate ARN for FTPS."
  type        = string
  default     = null
}

variable "pre_authentication_login_banner" {
  description = "Optional message to display before authentication succeeds (SFTP/FTPS)."
  type        = string
  default     = null
}

variable "post_authentication_login_banner" {
  description = "Optional message to display after authentication succeeds (SFTP/FTPS)."
  type        = string
  default     = null
}

variable "security_policy_name" {
  description = "Security policy name for the Transfer server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "host_key" {
  description = "SSH host key for the Transfer server."
  type        = string
  default     = null
}

variable "structured_log_destinations" {
  description = "CloudWatch log group ARNs for structured logging."
  type        = list(string)
  default     = []
}

variable "protocol_details" {
  description = "Protocol details for the Transfer server."
  type = object({
    as2_transports              = optional(list(string))
    passive_ip                  = optional(string)
    set_stat_option             = optional(string)
    tls_session_resumption_mode = optional(string)
  })
  default = {}
}

variable "route53_zone_name" {
  description = "Route 53 hosted zone name. If provided, a CNAME record is created."
  type        = string
  default     = null
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID. If not provided, a zone is created when route53_zone_name is set."
  type        = string
  default     = null
}

variable "subdomain" {
  description = "Subdomain for the Route 53 CNAME record."
  type        = string
  default     = "sftp"
}

variable "users" {
  description = "Map of SFTP users to create."
  type = map(object({
    user_name           = string
    home_directory      = optional(string)
    home_directory_type = optional(string, "LOGICAL")
    s3_bucket           = optional(string)
    s3_prefix           = optional(string)
  }))
  default = {}
}

variable "user_ssh_keys" {
  description = "Map of user names to lists of SSH public keys."
  type        = map(list(string))
  default     = {}
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Project   = "AWS-Transfer-Family"
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC when endpoint_type is VPC or VPC_ENDPOINT."
  type        = string
  default     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

resource "random_pet" "server_name" {
  length    = 2
  separator = "-"
}

locals {
  server_name      = var.name != null && var.name != "" ? var.name : random_pet.server_name.id
  name_prefix      = local.server_name
  safe_name_prefix = replace(local.name_prefix, "/[^a-zA-Z0-9+=,.@_-]/", "-")

  create_vpc          = contains(["VPC", "VPC_ENDPOINT"], var.endpoint_type)
  create_vpc_endpoint = var.endpoint_type == "VPC_ENDPOINT"

  azs = slice(
    data.aws_availability_zones.available.names,
    0,
    min(2, length(data.aws_availability_zones.available.names))
  )

  logging_role_arn = coalesce(var.logging_role_arn, one(aws_iam_role.transfer_logging[*].arn))

  route53_zone_id = var.route53_zone_id != null ? var.route53_zone_id : one(aws_route53_zone.transfer[*].zone_id)

  users = {
    for k, v in var.users : k => {
      user_name           = v.user_name
      home_directory      = coalesce(v.home_directory, "/${aws_s3_bucket.home.id}/${v.user_name}")
      home_directory_type = v.home_directory_type
      s3_bucket           = coalesce(v.s3_bucket, aws_s3_bucket.home.id)
      s3_prefix           = coalesce(v.s3_prefix, v.user_name)
    }
  }

  user_ssh_keys = merge([
    for user_key, keys in var.user_ssh_keys : {
      for idx, key in keys : "${user_key}-${idx}" => {
        user_key   = user_key
        public_key = key
      }
    }
    if contains(keys(var.users), user_key)
  ]...)
}

data "aws_iam_policy_document" "transfer_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "api_gateway_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com", "apigateway.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "kms_transfer" {
  statement {
    sid     = "EnableRootAccountFullAccess"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "log_bucket" {
  statement {
    sid     = "S3ServerAccessLogsPolicy"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    resources = ["${aws_s3_bucket.logs.arn}/logs/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.home.id}"]
    }
  }

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    resources = [
      aws_s3_bucket.logs.arn,
      "${aws_s3_bucket.logs.arn}/*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0

  name               = "${local.safe_name_prefix}-transfer-logging"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0

  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

resource "aws_iam_role" "api_gateway" {
  count = var.enable_api_gateway ? 1 : 0

  name               = "${local.safe_name_prefix}-transfer-api-gateway"
  assume_role_policy = data.aws_iam_policy_document.api_gateway_assume.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "api_gateway" {
  count = var.enable_api_gateway ? 1 : 0

  role       = aws_iam_role.api_gateway[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_kms_key" "transfer" {
  description             = "Customer managed key for AWS Transfer Family home directory S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_transfer.json
  tags                    = merge(var.tags, { Name = "${local.name_prefix}-transfer-kms" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "transfer" {
  name          = "alias/${local.safe_name_prefix}-transfer-home"
  target_key_id = aws_kms_key.transfer.key_id
}

resource "aws_s3_bucket" "home" {
  bucket_prefix = "transfer-home-"
  tags          = merge(var.tags, { Name = "${local.name_prefix}-transfer-home" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "home" {
  bucket = aws_s3_bucket.home.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "home" {
  bucket = aws_s3_bucket.home.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.transfer.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "home" {
  bucket = aws_s3_bucket.home.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "logs" {
  bucket_prefix = "transfer-home-logs-"
  tags          = merge(var.tags, { Name = "${local.name_prefix}-transfer-home-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "logs" {
  bucket = aws_s3_bucket.logs.id
  policy = data.aws_iam_policy_document.log_bucket.json

  depends_on = [
    aws_s3_bucket_public_access_block.logs
  ]
}

resource "aws_s3_bucket_logging" "home" {
  bucket = aws_s3_bucket.home.id

  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "logs/"

  depends_on = [
    aws_s3_bucket_policy.logs
  ]
}

data "aws_iam_policy_document" "user" {
  for_each = local.users

  statement {
    sid     = "ListBucket"
    actions = ["s3:ListBucket"]

    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${local.users[each.key].s3_bucket}"
    ]
  }

  statement {
    sid = "ObjectAccess"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]

    resources = [
      local.users[each.key].s3_prefix == "" ? "arn:${data.aws_partition.current.partition}:s3:::${local.users[each.key].s3_bucket}/*" : "arn:${data.aws_partition.current.partition}:s3:::${local.users[each.key].s3_bucket}/${local.users[each.key].s3_prefix}/*"
    ]
  }

  statement {
    sid = "KmsAccess"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]

    resources = [aws_kms_key.transfer.arn]
  }
}

resource "aws_iam_role" "user" {
  for_each = local.users

  name               = "${local.safe_name_prefix}-transfer-${replace(each.key, "/[^a-zA-Z0-9+=,.@_-]/", "-")}"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume.json
  tags               = var.tags
}

resource "aws_iam_policy" "user" {
  for_each = local.users

  name   = "${local.safe_name_prefix}-transfer-${replace(each.key, "/[^a-zA-Z0-9+=,.@_-]/", "-")}-policy"
  policy = data.aws_iam_policy_document.user[each.key].json
  tags   = var.tags
}

resource "aws_iam_role_policy_attachment" "user" {
  for_each = local.users

  role       = aws_iam_role.user[each.key].name
  policy_arn = aws_iam_policy.user[each.key].arn
}

resource "aws_vpc" "transfer" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(var.tags, { Name = "${local.name_prefix}-transfer-vpc" })
}

resource "aws_subnet" "transfer" {
  count = local.create_vpc ? length(local.azs) : 0

  vpc_id                  = aws_vpc.transfer[0].id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true
  tags                    = merge(var.tags, { Name = "${local.name_prefix}-transfer-subnet-${count.index}" })
}

resource "aws_internet_gateway" "transfer" {
  count = local.create_vpc ? 1 : 0

  vpc_id = aws_vpc.transfer[0].id
  tags   = merge(var.tags, { Name = "${local.name_prefix}-transfer-igw" })
}

resource "aws_route_table" "transfer" {
  count = local.create_vpc ? 1 : 0

  vpc_id = aws_vpc.transfer[0].id
  tags   = merge(var.tags, { Name = "${local.name_prefix}-transfer-rt" })
}

resource "aws_route" "transfer" {
  count = local.create_vpc ? 1 : 0

  route_table_id         = aws_route_table.transfer[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.transfer[0].id
}

resource "aws_route_table_association" "transfer" {
  count = local.create_vpc ? length(local.azs) : 0

  subnet_id      = aws_subnet.transfer[count.index].id
  route_table_id = aws_route_table.transfer[0].id
}

resource "aws_security_group" "transfer" {
  count = local.create_vpc ? 1 : 0

  name        = "${local.name_prefix}-transfer-sg"
  description = "Security group for AWS Transfer Family server"
  vpc_id      = aws_vpc.transfer[0].id

  ingress {
    description = "SFTP"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, { Name = "${local.name_prefix}-transfer-sg" })
}

resource "aws_vpc_endpoint" "transfer" {
  count = local.create_vpc && local.create_vpc_endpoint ? 1 : 0

  vpc_id              = aws_vpc.transfer[0].id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.transfer.server"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.transfer[*].id
  security_group_ids  = [aws_security_group.transfer[0].id]
  private_dns_enabled = false
  tags                = merge(var.tags, { Name = "${local.name_prefix}-transfer-vpce" })
}

resource "aws_eip" "vpc_endpoint" {
  count = local.create_vpc && local.create_vpc_endpoint ? length(local.azs) : 0

  domain = "vpc"
  tags   = merge(var.tags, { Name = "${local.name_prefix}-transfer-vpce-eip-${count.index}" })
}

resource "aws_eip_association" "vpc_endpoint" {
  count = local.create_vpc && local.create_vpc_endpoint ? length(local.azs) : 0

  allocation_id        = aws_eip.vpc_endpoint[count.index].id
  network_interface_id = aws_vpc_endpoint.transfer[0].network_interface_ids[count.index]
}

resource "aws_eip" "vpc" {
  count = local.create_vpc && var.endpoint_type == "VPC" ? length(local.azs) : 0

  domain = "vpc"
  tags   = merge(var.tags, { Name = "${local.name_prefix}-transfer-vpc-eip-${count.index}" })
}

resource "aws_transfer_server" "server" {
  endpoint_type                    = var.endpoint_type
  protocols                        = var.protocols
  certificate                      = var.certificate_arn
  logging_role                     = local.logging_role_arn
  security_policy_name             = var.security_policy_name
  host_key                         = var.host_key
  pre_authentication_login_banner  = var.pre_authentication_login_banner
  post_authentication_login_banner = var.post_authentication_login_banner
  structured_log_destinations      = length(var.structured_log_destinations) > 0 ? var.structured_log_destinations : null
  identity_provider_type           = var.enable_api_gateway ? "API_GATEWAY" : "SERVICE_MANAGED"
  invocation_role                  = var.enable_api_gateway ? one(aws_iam_role.api_gateway[*].arn) : null
  tags                             = merge(var.tags, { Name = local.server_name, StorageType = var.storage_type })

  dynamic "protocol_details" {
    for_each = length(keys(var.protocol_details)) > 0 ? [var.protocol_details] : []

    content {
      as2_transports              = try(protocol_details.value.as2_transports, null)
      passive_ip                  = try(protocol_details.value.passive_ip, null)
      set_stat_option             = try(protocol_details.value.set_stat_option, null)
      tls_session_resumption_mode = try(protocol_details.value.tls_session_resumption_mode, null)
    }
  }

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "PUBLIC" ? [] : [1]

    content {
      vpc_endpoint_id        = var.endpoint_type == "VPC_ENDPOINT" ? one(aws_vpc_endpoint.transfer[*].id) : null
      subnet_ids             = var.endpoint_type == "VPC" ? aws_subnet.transfer[*].id : null
      security_group_ids     = var.endpoint_type == "VPC" ? aws_security_group.transfer[*].id : null
      vpc_id                 = var.endpoint_type == "VPC" ? one(aws_vpc.transfer[*].id) : null
      address_allocation_ids = var.endpoint_type == "VPC" ? aws_eip.vpc[*].id : null
    }
  }

  depends_on = [
    aws_iam_role.transfer_logging,
    aws_iam_role.api_gateway,
    aws_iam_role_policy_attachment.transfer_logging,
    aws_iam_role_policy_attachment.api_gateway
  ]
}

resource "aws_transfer_user" "user" {
  for_each = local.users

  server_id           = aws_transfer_server.server.id
  user_name           = each.value.user_name
  role                = aws_iam_role.user[each.key].arn
  home_directory      = each.value.home_directory
  home_directory_type = each.value.home_directory_type
  tags                = var.tags
}

resource "aws_transfer_ssh_key" "user" {
  for_each = local.user_ssh_keys

  server_id = aws_transfer_server.server.id
  user_name = local.users[each.value.user_key].user_name
  body      = each.value.public_key

  depends_on = [
    aws_transfer_user.user
  ]
}

resource "aws_route53_zone" "transfer" {
  count = var.route53_zone_name != null && var.route53_zone_id == null ? 1 : 0

  name = var.route53_zone_name
  tags = var.tags
}

resource "aws_route53_record" "transfer" {
  count = var.route53_zone_name != null ? 1 : 0

  zone_id = local.route53_zone_id
  name    = "${var.subdomain}.${var.route53_zone_name}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.server.endpoint]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Data sources (static / provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "vpc_flow_logs_assume_role" {
  statement {
    sid     = "VPCFlowLogsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "vpc_flow_logs_permissions" {
  statement {
    sid    = "VPCFlowLogsWriteToLogGroup"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = ["${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*"]
  }
}

data "aws_iam_policy_document" "vpc_flow_logs_kms" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsServiceUsage"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${var.aws_region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:*"]
    }
  }
}

###############################################################################
# Input variables
###############################################################################

variable "aws_region" {
  description = "AWS region the networking stack is deployed into."
  type        = string
  default     = "us-east-1"
}

variable "availability_zone_count" {
  description = "Number of availability zones to spread subnets across. When null, every available AZ in the region is used."
  type        = number
  default     = null

  validation {
    condition     = coalesce(var.availability_zone_count, 1) > 0
    error_message = "The availability_zone_count value must be greater than 0 when it is provided."
  }
}

variable "create_public_subnets" {
  description = "Whether to create public subnets (and the internet gateway / public route table)."
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets (and the private route table)."
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create a NAT gateway for private subnet egress. Requires create_public_subnets = true."
  type        = bool
  default     = true
}

variable "vpc_name" {
  description = "Name used for the VPC and for tagging all resources in the stack."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC. Subnet CIDRs are derived from this block."
  type        = string
  default     = "10.0.0.0/18"
}

variable "environment" {
  description = "Environment label applied through the common tag set."
  type        = string
  default     = "dev"
}

variable "flow_logs_retention_in_days" {
  description = "Retention period, in days, for the VPC flow log CloudWatch log group."
  type        = number
  default     = 30
}

###############################################################################
# Locals
###############################################################################

locals {
  az_count = var.availability_zone_count != null ? var.availability_zone_count : length(data.aws_availability_zones.available.names)

  common_tags = {
    Name        = var.vpc_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }

  vpc_flow_logs_log_group_name = "/aws/vpc/${var.vpc_name}"
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = var.vpc_name })

  lifecycle {
    precondition {
      condition     = var.availability_zone_count == null || var.availability_zone_count <= length(data.aws_availability_zones.available.names)
      error_message = "availability_zone_count cannot exceed the number of available AZs in the region."
    }

    precondition {
      condition     = !var.create_nat_gateway || var.create_public_subnets
      error_message = "create_nat_gateway = true requires create_public_subnets = true."
    }
  }
}

###############################################################################
# Internet gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-igw" })
}

###############################################################################
# Public subnets
###############################################################################

resource "aws_subnet" "public" {
  count = var.create_public_subnets ? local.az_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-public-${count.index}" })
}

###############################################################################
# Private subnets
###############################################################################

resource "aws_subnet" "private" {
  count = var.create_private_subnets ? local.az_count : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + local.az_count)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-private-${count.index}" })
}

###############################################################################
# NAT gateway (single, placed in the first public subnet)
###############################################################################

resource "aws_eip" "nat" {
  count = var.create_nat_gateway ? 1 : 0

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-nat-eip" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = var.create_nat_gateway ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-nat" })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Route tables
###############################################################################

resource "aws_route_table" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-public-rt" })
}

resource "aws_route_table" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  dynamic "route" {
    for_each = var.create_nat_gateway ? [1] : []

    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.main[0].id
    }
  }

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-private-rt" })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

###############################################################################
# Network ACLs
###############################################################################

resource "aws_network_acl" "public" {
  vpc_id = aws_vpc.main.id

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-public-nacl" })
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-private-nacl" })
}

resource "aws_network_acl_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  network_acl_id = aws_network_acl.public.id
}

resource "aws_network_acl_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  network_acl_id = aws_network_acl.private.id
}

###############################################################################
# VPC Flow Logs delivery chain
###############################################################################

resource "aws_kms_key" "vpc_flow_logs" {
  description             = "Customer-managed key used to encrypt VPC flow logs for ${var.vpc_name}."
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.vpc_flow_logs_kms.json

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-vpc-flow-logs-key" })
}

resource "aws_kms_alias" "vpc_flow_logs" {
  name          = "alias/${var.vpc_name}-vpc-flow-logs"
  target_key_id = aws_kms_key.vpc_flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = local.vpc_flow_logs_log_group_name
  retention_in_days = var.flow_logs_retention_in_days
  kms_key_id        = aws_kms_key.vpc_flow_logs.arn

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-vpc-flow-logs" })

  depends_on = [aws_kms_key.vpc_flow_logs]
}

resource "aws_iam_role" "vpc_flow_logs" {
  name               = "${var.vpc_name}-vpc-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.vpc_flow_logs_assume_role.json

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-vpc-flow-logs-role" })
}

resource "aws_iam_policy" "vpc_flow_logs" {
  name        = "${var.vpc_name}-vpc-flow-logs-policy"
  description = "Least-privilege permissions allowing VPC Flow Logs to publish events to the ${local.vpc_flow_logs_log_group_name} log group."
  policy      = data.aws_iam_policy_document.vpc_flow_logs_permissions.json

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-vpc-flow-logs-policy" })
}

resource "aws_iam_role_policy_attachment" "vpc_flow_logs" {
  role       = aws_iam_role.vpc_flow_logs.name
  policy_arn = aws_iam_policy.vpc_flow_logs.arn
}

resource "aws_flow_log" "main" {
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn             = aws_iam_role.vpc_flow_logs.arn
  max_aggregation_interval = 60

  tags = merge(local.common_tags, { Name = "${var.vpc_name}-flow-log" })

  depends_on = [
    aws_iam_role_policy_attachment.vpc_flow_logs,
    aws_cloudwatch_log_group.vpc_flow_logs,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the created public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the created private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "The ID of the NAT gateway, or null when it is not created."
  value       = length(aws_nat_gateway.main) > 0 ? aws_nat_gateway.main[0].id : null
}

output "internet_gateway_id" {
  description = "The ID of the internet gateway, or null when it is not created."
  value       = length(aws_internet_gateway.main) > 0 ? aws_internet_gateway.main[0].id : null
}

output "public_network_acl_id" {
  description = "The ID of the public network ACL."
  value       = aws_network_acl.public.id
}

output "private_network_acl_id" {
  description = "The ID of the private network ACL."
  value       = aws_network_acl.private.id
}

output "public_route_table_id" {
  description = "The ID of the public route table, or null when it is not created."
  value       = length(aws_route_table.public) > 0 ? aws_route_table.public[0].id : null
}

output "private_route_table_id" {
  description = "The ID of the private route table, or null when it is not created."
  value       = length(aws_route_table.private) > 0 ? aws_route_table.private[0].id : null
}

output "vpc_flow_log_id" {
  description = "The ID of the VPC flow log bound to the VPC."
  value       = aws_flow_log.main.id
}

output "vpc_flow_logs_log_group_name" {
  description = "Name of the CloudWatch log group receiving VPC flow logs."
  value       = aws_cloudwatch_log_group.vpc_flow_logs.name
}

output "vpc_flow_logs_log_group_arn" {
  description = "ARN of the CloudWatch log group receiving VPC flow logs."
  value       = aws_cloudwatch_log_group.vpc_flow_logs.arn
}

output "vpc_flow_logs_role_arn" {
  description = "ARN of the IAM role assumed by the VPC Flow Logs service."
  value       = aws_iam_role.vpc_flow_logs.arn
}

output "vpc_flow_logs_kms_key_arn" {
  description = "ARN of the customer-managed KMS key used to encrypt VPC flow logs."
  value       = aws_kms_key.vpc_flow_logs.arn
}

output "vpc_flow_logs_kms_alias_name" {
  description = "Name of the KMS alias pointing at the VPC flow log encryption key."
  value       = aws_kms_alias.vpc_flow_logs.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Input variables
###############################################################################

variable "is_ipv6_enabled" {
  description = "Enable dual-stack (IPv4 + Amazon-provided IPv6) networking for the VPC and its subnets."
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block assigned to the main VPC."
  type        = string
  default     = "10.16.0.0/16"
}

variable "sn_details" {
  description = "Subnet definitions (name, target availability zone index, and public/private indicator)."
  type = list(object({
    name   = string
    az     = number
    public = bool
  }))

  default = [
    { name = "web-1", az = 0, public = true },
    { name = "web-2", az = 1, public = true },
    { name = "web-3", az = 2, public = true },
    { name = "app-1", az = 0, public = false },
    { name = "app-2", az = 1, public = false },
    { name = "app-3", az = 2, public = false },
    { name = "db-1", az = 0, public = false },
    { name = "db-2", az = 1, public = false },
    { name = "db-3", az = 2, public = false },
    { name = "reserved-1", az = 0, public = false },
    { name = "reserved-2", az = 1, public = false },
    { name = "reserved-3", az = 2, public = false },
  ]

  validation {
    condition     = length(var.sn_details) > 0 && alltrue([for s in var.sn_details : s.az >= 0 && s.az <= 2])
    error_message = "sn_details must contain at least one subnet and every 'az' index must be between 0 and 2."
  }

  validation {
    condition     = length(distinct([for s in var.sn_details : s.name])) == length(var.sn_details)
    error_message = "Every subnet name in sn_details must be unique."
  }
}

variable "environment" {
  description = "Environment name applied to all taggable resources."
  type        = string
  default     = "dev"
}

variable "owner" {
  description = "Team or individual accountable for the environment."
  type        = string
  default     = "platform-team"
}

variable "flow_log_retention_in_days" {
  description = "Retention period (days) for the VPC flow log CloudWatch log group."
  type        = number
  default     = 90
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period (days) before the flow-log KMS key is deleted on destroy."
  type        = number
  default     = 30
}

###############################################################################
# Static provider metadata
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

###############################################################################
# IAM / KMS policy documents (pure local evaluation)
###############################################################################

data "aws_iam_policy_document" "flow_logs_assume_role" {
  statement {
    sid     = "VpcFlowLogsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "flow_logs_delivery" {
  statement {
    sid    = "VpcFlowLogsWriteToCloudWatch"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
    ]

    resources = [
      aws_cloudwatch_log_group.vpc_flow_logs.arn,
      "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*",
    ]
  }

  statement {
    sid    = "VpcFlowLogsUseCloudWatchKmsKey"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:Encrypt",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.vpc_flow_logs.arn,
    ]
  }
}

data "aws_iam_policy_document" "vpc_flow_logs_kms" {
  statement {
    sid    = "AllowAccountAdministrationOfKey"
    effect = "Allow"

    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsToUseKey"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*"]
    }
  }
}

data "aws_partition" "current" {}

###############################################################################
# Local values
###############################################################################

locals {
  sn_map = { for s in var.sn_details : s.name => s }

  public_sn_map = { for s in var.sn_details : s.name => s if s.public }

  ipv4_cidr_by_name = module.ipv4_subnets.network_cidr_blocks

  ipv6_cidr_by_name = var.is_ipv6_enabled ? module.ipv6_subnets[0].network_cidr_blocks : {}

  common_tags = {
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "terraform"
  }
}

###############################################################################
# VPC (dual-stack)
###############################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Dynamic subnet CIDR calculation (IPv4 /20 and IPv6 /64)
###############################################################################

module "ipv4_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block

  networks = [
    for s in var.sn_details : {
      name     = s.name
      new_bits = 4
    }
  ]
}

module "ipv6_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  count = var.is_ipv6_enabled ? 1 : 0

  base_cidr_block = aws_vpc.main.ipv6_cidr_block

  networks = [
    for s in var.sn_details : {
      name     = s.name
      new_bits = 8
    }
  ]
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "this" {
  for_each = local.sn_map

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.ipv4_cidr_by_name[each.key]
  availability_zone = data.aws_availability_zones.available.names[each.value.az]

  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = var.is_ipv6_enabled
  ipv6_cidr_block                 = lookup(local.ipv6_cidr_by_name, each.key, null)

  tags = merge(local.common_tags, {
    Name = each.key
    Tier = each.value.public ? "public" : "private"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Internet gateway and public routing
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "public-rt-web"
  })
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  count = var.is_ipv6_enabled ? 1 : 0

  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_sn_map

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security groups (resource shells only — cross-SG rules are standalone)
###############################################################################

resource "aws_security_group" "web_sg" {
  name        = "web_sg"
  description = "Web tier: inbound TLS from the internet and SSH from within the VPC; outbound TLS to the app tier."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from the internet (IPv4)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description      = "HTTPS from the internet (IPv6)"
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    ipv6_cidr_blocks = ["::/0"]
  }

  ingress {
    description = "SSH from within the VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "web_sg"
    Tier = "web"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "app_sg" {
  name        = "app_sg"
  description = "Application tier: inbound TLS from the web tier only; outbound TLS to the database tier."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "app_sg"
    Tier = "app"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Database tier: inbound TLS from the application tier only; restricted outbound HTTPS inside the VPC."
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Restricted HTTPS outbound within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "db_sg"
    Tier = "database"
  })

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Standalone cross-SG rules (break the SG -> SG dependency cycle)
###############################################################################

resource "aws_vpc_security_group_egress_rule" "web_to_app_https" {
  security_group_id            = aws_security_group.web_sg.id
  description                  = "HTTPS to the application tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.app_sg.id
}

resource "aws_vpc_security_group_ingress_rule" "app_from_web_https" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "HTTPS from the web tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.web_sg.id
}

resource "aws_vpc_security_group_egress_rule" "app_to_db_https" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "HTTPS to the database tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.db_sg.id
}

resource "aws_vpc_security_group_ingress_rule" "db_from_app_https" {
  security_group_id            = aws_security_group.db_sg.id
  description                  = "HTTPS from the application tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.app_sg.id
}

###############################################################################
# VPC Flow Logs (CloudWatch delivery chain, CMK-encrypted)
###############################################################################

resource "aws_kms_key" "vpc_flow_logs" {
  description             = "Customer-managed key encrypting the main-vpc CloudWatch flow logs."
  enable_key_rotation     = true
  deletion_window_in_days = var.kms_deletion_window_in_days
  policy                  = data.aws_iam_policy_document.vpc_flow_logs_kms.json

  tags = merge(local.common_tags, {
    Name = "main-vpc-flow-logs-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "vpc_flow_logs" {
  name          = "alias/main-vpc-flow-logs"
  target_key_id = aws_kms_key.vpc_flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc/flow-logs/main-vpc"
  retention_in_days = var.flow_log_retention_in_days
  kms_key_id        = aws_kms_key.vpc_flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "main-vpc-flow-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name               = "main-vpc-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role.json

  tags = merge(local.common_tags, {
    Name = "main-vpc-flow-logs-role"
  })
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name   = "main-vpc-flow-logs-policy"
  role   = aws_iam_role.vpc_flow_logs.id
  policy = data.aws_iam_policy_document.flow_logs_delivery.json
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn         = aws_iam_role.vpc_flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "main-vpc-flow-log"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "create_vpc" {
  description = "Controls whether the VPC and all dependent resources are created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name prefix applied to the VPC and used to build resource Name tags."
  type        = string
  default     = "vpc"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_support" {
  description = "Whether DNS resolution is supported within the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Whether instances launched in the VPC receive DNS hostnames."
  type        = bool
  default     = true
}

variable "azs" {
  description = "Explicit list of availability zone names or IDs. When empty, availability zones are resolved dynamically via the aws_availability_zones data source."
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "List of CIDR blocks for public subnets (routed to an Internet Gateway)."
  type        = list(string)
  default     = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnets" {
  description = "List of CIDR blocks for private subnets (routed to NAT gateways when enabled)."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24", "10.0.12.0/24"]
}

variable "intra_subnets" {
  description = "List of CIDR blocks for isolated (intra) subnets with no external internet route."
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24", "10.0.22.0/24"]
}

variable "public_subnet_names" {
  description = "Optional explicit Name tags for public subnets that override the generated names."
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Optional explicit Name tags for private subnets that override the generated names."
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Optional explicit Name tags for intra subnets that override the generated names."
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix used when generating public subnet Name tags."
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix used when generating private subnet Name tags."
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix used when generating intra subnet Name tags."
  type        = string
  default     = "intra"
}

variable "map_public_ip_on_launch" {
  description = "Whether public subnets auto-assign public IP addresses to launched instances."
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Whether an Internet Gateway is created and attached to the VPC when public subnets exist."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Whether Elastic IPs and NAT gateways are created for private subnet egress."
  type        = bool
  default     = false
}

variable "enable_flow_logs" {
  description = "Whether VPC Flow Logs are delivered to an encrypted CloudWatch log group for the VPC."
  type        = bool
  default     = true
}

variable "flow_logs_retention_in_days" {
  description = "Retention period in days for the VPC flow log CloudWatch log group."
  type        = number
  default     = 90
}

variable "flow_logs_kms_deletion_window_in_days" {
  description = "Waiting period, in days, before the flow log KMS customer-managed key is deleted."
  type        = number
  default     = 7
}

variable "tags" {
  description = "Map of additional tags merged into every resource managed by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  name = var.name

  azs_available = data.aws_availability_zones.available.names

  required_az_count = max(
    length(var.public_subnets),
    length(var.private_subnets),
    length(var.intra_subnets),
    1,
  )

  azs = length(var.azs) > 0 ? var.azs : slice(
    local.azs_available,
    0,
    min(length(local.azs_available), local.required_az_count),
  )

  az_count = max(length(local.azs), 1)

  public_subnet_map = var.create_vpc ? {
    for idx, cidr in var.public_subnets : tostring(idx) => {
      cidr = cidr
      az   = local.azs[idx % local.az_count]
      name = try(
        var.public_subnet_names[idx],
        "${local.name}-${var.public_subnet_suffix}-${local.azs[idx % local.az_count]}",
      )
    }
  } : {}

  private_subnet_map = var.create_vpc ? {
    for idx, cidr in var.private_subnets : tostring(idx) => {
      cidr = cidr
      az   = local.azs[idx % local.az_count]
      name = try(
        var.private_subnet_names[idx],
        "${local.name}-${var.private_subnet_suffix}-${local.azs[idx % local.az_count]}",
      )
    }
  } : {}

  intra_subnet_map = var.create_vpc ? {
    for idx, cidr in var.intra_subnets : tostring(idx) => {
      cidr = cidr
      az   = local.azs[idx % local.az_count]
      name = try(
        var.intra_subnet_names[idx],
        "${local.name}-${var.intra_subnet_suffix}-${local.azs[idx % local.az_count]}",
      )
    }
  } : {}

  nat_count = (
    var.create_vpc
    && var.enable_nat_gateway
    && length(var.public_subnets) > 0
    && length(var.private_subnets) > 0
  ) ? min(length(var.public_subnets), length(var.private_subnets)) : 0

  private_nat_route_map = local.nat_count > 0 ? {
    for key, subnet in local.private_subnet_map : key => tonumber(key) % local.nat_count
  } : {}

  create_flow_logs = var.create_vpc && var.enable_flow_logs

  flow_log_group_name = "/aws/vpc/${local.name}-flow-logs"

  flow_log_group_arn = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.flow_log_group_name}"
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = merge(var.tags, { Name = local.name })
}

###############################################################################
# VPC Flow Logs: KMS CMK + CloudWatch Logs destination + delivery role
###############################################################################

data "aws_iam_policy_document" "flow_log_kms" {
  count = local.create_flow_logs ? 1 : 0

  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsUse"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = [local.flow_log_group_arn]
    }
  }
}

resource "aws_kms_key" "flow_log" {
  count = local.create_flow_logs ? 1 : 0

  description             = "Customer-managed key for VPC flow log encryption"
  deletion_window_in_days = var.flow_logs_kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.flow_log_kms[0].json

  tags = merge(var.tags, { Name = "${local.name}-flow-logs" })
}

resource "aws_kms_alias" "flow_log" {
  count = local.create_flow_logs ? 1 : 0

  name          = "alias/${local.name}-flow-logs"
  target_key_id = aws_kms_key.flow_log[0].key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  count = local.create_flow_logs ? 1 : 0

  name              = local.flow_log_group_name
  retention_in_days = var.flow_logs_retention_in_days
  kms_key_id        = aws_kms_key.flow_log[0].arn

  tags = merge(var.tags, { Name = "${local.name}-flow-logs" })

  depends_on = [aws_kms_alias.flow_log]
}

data "aws_iam_policy_document" "flow_log_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "flow_log" {
  count = local.create_flow_logs ? 1 : 0

  name               = "${local.name}-flow-logs"
  assume_role_policy = data.aws_iam_policy_document.flow_log_assume_role.json

  tags = merge(var.tags, { Name = "${local.name}-flow-logs" })
}

data "aws_iam_policy_document" "flow_log_delivery" {
  count = local.create_flow_logs ? 1 : 0

  statement {
    sid    = "CloudWatchLogsDelivery"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
    ]

    resources = ["${aws_cloudwatch_log_group.flow_log[0].arn}:*"]
  }

  statement {
    sid    = "FlowLogGroupKMSAccess"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]

    resources = [aws_kms_key.flow_log[0].arn]
  }
}

resource "aws_iam_role_policy" "flow_log" {
  count = local.create_flow_logs ? 1 : 0

  name   = "${local.name}-flow-logs"
  role   = aws_iam_role.flow_log[0].id
  policy = data.aws_iam_policy_document.flow_log_delivery[0].json
}

resource "aws_flow_log" "main" {
  count = local.create_flow_logs ? 1 : 0

  vpc_id               = aws_vpc.main[0].id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_log[0].arn
  iam_role_arn         = aws_iam_role.flow_log[0].arn

  tags = merge(var.tags, { Name = "${local.name}-flow-logs" })

  depends_on = [
    aws_kms_key.flow_log,
    aws_cloudwatch_log_group.flow_log,
    aws_iam_role_policy.flow_log,
  ]
}

###############################################################################
# Public tier: Internet Gateway, route table, route, subnets and associations
###############################################################################

resource "aws_internet_gateway" "main" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, { Name = "${local.name}-igw" })
}

resource "aws_subnet" "public" {
  for_each = local.public_subnet_map

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(var.tags, { Name = each.value.name })
}

resource "aws_route_table" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, { Name = "${local.name}-public-rt" })
}

resource "aws_route" "public_internet" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnet_map

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# Private tier: subnets, per-subnet route tables, optional NAT gateways
###############################################################################

resource "aws_subnet" "private" {
  for_each = local.private_subnet_map

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = each.value.name })
}

resource "aws_eip" "nat" {
  count = local.nat_count

  domain = "vpc"

  tags = merge(var.tags, { Name = "${local.name}-nat-${count.index + 1}" })
}

resource "aws_nat_gateway" "main" {
  count = local.nat_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[tostring(count.index)].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(var.tags, { Name = "${local.name}-nat-${count.index + 1}" })
}

resource "aws_route_table" "private" {
  for_each = local.private_subnet_map

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, {
    Name = "${local.name}-${var.private_subnet_suffix}-rt-${each.value.az}"
  })
}

resource "aws_route" "private_nat" {
  for_each = local.private_nat_route_map

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[each.value].id
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnet_map

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

###############################################################################
# Intra (isolated) tier: subnets and route tables with no external route
###############################################################################

resource "aws_subnet" "intra" {
  for_each = local.intra_subnet_map

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = each.value.name })
}

resource "aws_route_table" "intra" {
  for_each = local.intra_subnet_map

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, {
    Name = "${local.name}-${var.intra_subnet_suffix}-rt-${each.value.az}"
  })
}

resource "aws_route_table_association" "intra" {
  for_each = local.intra_subnet_map

  subnet_id      = aws_subnet.intra[each.key].id
  route_table_id = aws_route_table.intra[each.key].id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "The ID of the VPC."
  value       = try(aws_vpc.main[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC."
  value       = try(aws_vpc.main[0].cidr_block, null)
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = [for subnet in aws_subnet.public : subnet.id]
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = [for subnet in aws_subnet.private : subnet.id]
}

output "intra_subnet_ids" {
  description = "IDs of the intra (isolated) subnets."
  value       = [for subnet in aws_subnet.intra : subnet.id]
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway, if created."
  value       = try(aws_internet_gateway.main[0].id, null)
}

output "nat_gateway_ids" {
  description = "IDs of the NAT gateways, if created."
  value       = [for nat in aws_nat_gateway.main : nat.id]
}

output "public_route_table_id" {
  description = "The ID of the public route table, if created."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "IDs of the per-private-subnet route tables."
  value       = [for route_table in aws_route_table.private : route_table.id]
}

output "intra_route_table_ids" {
  description = "IDs of the per-intra-subnet route tables."
  value       = [for route_table in aws_route_table.intra : route_table.id]
}

output "flow_log_id" {
  description = "The ID of the VPC flow log, if created."
  value       = try(aws_flow_log.main[0].id, null)
}

output "flow_log_cloudwatch_log_group_arn" {
  description = "The ARN of the CloudWatch log group receiving VPC flow logs, if created."
  value       = try(aws_cloudwatch_log_group.flow_log[0].arn, null)
}

output "flow_log_kms_key_arn" {
  description = "The ARN of the customer-managed KMS key used to encrypt VPC flow logs, if created."
  value       = try(aws_kms_key.flow_log[0].arn, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "api_type" {
  description = "Type of API Gateway to provision: 'http' (v2) or 'rest' (v1)."
  type        = string
  default     = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either 'http' or 'rest'."
  }
}

variable "api_name" {
  description = "Name of the API Gateway."
  type        = string
  default     = "benchmark-api"
}

variable "environment" {
  description = "Environment name used to derive the deployment stage name."
  type        = string
  default     = "dev"
}

variable "enable_vpc_link" {
  description = "Whether to provision VPC link integration resources."
  type        = bool
  default     = false
}

variable "vpc_link_port" {
  description = "TCP port used by the VPC link load balancer listener and target group."
  type        = number
  default     = 443
}

variable "create_custom_domain" {
  description = "Whether to create ACM certificate, Route53 zone and API Gateway custom domain resources."
  type        = bool
  default     = false
}

variable "create_dns_record" {
  description = "Whether to create the Route53 alias A record for the custom domain."
  type        = bool
  default     = false
}

variable "domain_name" {
  description = "Custom domain name used for the API Gateway endpoint."
  type        = string
  default     = "example.com"
}

variable "allowed_ip_cidrs" {
  description = "CIDR ranges allowed to invoke the REST API when IP restriction is enabled."
  type        = list(string)
  default     = ["10.0.0.0/8"]
}

variable "enable_ip_restriction" {
  description = "Whether to apply an IP based resource policy to the REST API."
  type        = bool
  default     = false
}

variable "enable_authorizer" {
  description = "Whether to provision the custom Lambda authorizer."
  type        = bool
  default     = false
}

variable "authorizer_result_ttl_in_seconds" {
  description = "TTL for cached REST authorizer results."
  type        = number
  default     = 300
}

variable "xray_tracing_enabled" {
  description = "Whether to enable X-Ray tracing on the REST API stage."
  type        = bool
  default     = false
}

variable "vpc_cidr" {
  description = "CIDR block for the greenfield VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks used to create private subnets across the selected availability zones."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "log_retention_days" {
  description = "Retention period in days for CloudWatch log groups."
  type        = number
  default     = 30
}

variable "http_routes" {
  description = "Map describing HTTP API v2 routes and their backing integrations."
  type = map(object({
    route_key          = string
    integration_type   = optional(string, "AWS_PROXY")
    use_lambda_backend = optional(bool, true)
    integration_uri    = optional(string, null)
    authorization_type = optional(string, "NONE")
    use_authorizer     = optional(bool, false)
  }))
  default = {
    get_root = {
      route_key = "GET /"
    }
  }
}

variable "rest_resources" {
  description = "Map describing REST API v1 resource paths. 'parent' references another key in this map, null means the API root."
  type = map(object({
    path_part = string
    parent    = optional(string, null)
  }))
  default = {
    items = {
      path_part = "items"
      parent    = null
    }
  }
}

variable "rest_methods" {
  description = "Map describing REST API v1 methods for the declared resources."
  type = map(object({
    resource_key       = string
    http_method        = string
    authorization      = optional(string, "NONE")
    use_authorizer     = optional(bool, false)
    request_parameters = optional(map(bool), {})
  }))
  default = {
    get_items = {
      resource_key = "items"
      http_method  = "GET"
    }
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  stage_name = "${var.environment}-stage"

  common_tags = {
    Project     = var.api_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  private_subnets = {
    for idx, cidr in var.private_subnet_cidrs :
    "private-${idx}" => {
      cidr = cidr
      az   = data.aws_availability_zones.available.names[idx]
    }
  }

  http_integrations_enabled = var.api_type == "http"
  rest_enabled              = var.api_type == "rest"
  http_vpc_link_enabled     = local.http_integrations_enabled && var.enable_vpc_link
  rest_vpc_link_enabled     = local.rest_enabled && var.enable_vpc_link
}

###############################################################################
# Static provider metadata / greenfield network
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "api" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${var.api_name}-vpc" })
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id                  = aws_vpc.api.id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${var.api_name}-${each.key}" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.api.id

  tags = merge(local.common_tags, { Name = "${var.api_name}-private-rt" })
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnets

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "vpc_link" {
  name        = "${var.api_name}-vpclink-sg"
  description = "Security group for internal VPC link load balancers."
  vpc_id      = aws_vpc.api.id

  ingress {
    description = "Allow VPC link traffic from within the VPC."
    from_port   = var.vpc_link_port
    to_port     = var.vpc_link_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.api.cidr_block]
  }

  egress {
    description = "Allow outbound traffic within the VPC."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.api.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "${var.api_name}-vpclink-sg" })
}

###############################################################################
# Customer managed KMS key for log encryption
###############################################################################

data "aws_iam_policy_document" "logs_kms" {
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"]
    }
  }

  statement {
    sid    = "AllowFlowLogsRoleUse"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.flow_log.arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]
  }
}

data "aws_partition" "current" {}

resource "aws_kms_key" "logs" {
  description             = "KMS key used to encrypt ${var.api_name} CloudWatch log groups."
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.logs_kms.json

  tags = local.common_tags
}

resource "aws_kms_alias" "logs" {
  name          = "alias/${var.api_name}-logs"
  target_key_id = aws_kms_key.logs.key_id
}

###############################################################################
# Shared CloudWatch logging
###############################################################################

resource "aws_cloudwatch_log_group" "api" {
  name              = "/aws/apigateway/${var.api_name}/${var.environment}"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.logs.arn

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# VPC Flow Logs destination and IAM role
###############################################################################

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/${var.api_name}-flow-logs"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.logs.arn

  tags = local.common_tags
}

data "aws_iam_policy_document" "flow_log_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "flow_log" {
  name               = "${var.api_name}-flow-log-role"
  assume_role_policy = data.aws_iam_policy_document.flow_log_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "flow_log" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
    ]
    resources = [
      aws_cloudwatch_log_group.flow_log.arn,
      "${aws_cloudwatch_log_group.flow_log.arn}:*",
    ]
  }
}

resource "aws_iam_role_policy" "flow_log" {
  name   = "${var.api_name}-flow-log-policy"
  role   = aws_iam_role.flow_log.id
  policy = data.aws_iam_policy_document.flow_log.json
}

resource "aws_flow_log" "api" {
  vpc_id               = aws_vpc.api.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_group_name       = aws_cloudwatch_log_group.flow_log.name
  iam_role_arn         = aws_iam_role.flow_log.arn

  tags = local.common_tags

  depends_on = [aws_iam_role_policy.flow_log]
}

###############################################################################
# Backend Lambda (integration target for both API modes)
###############################################################################

data "archive_file" "backend" {
  type        = "zip"
  output_path = "${path.module}/build/backend.zip"

  source {
    filename = "index.js"
    content  = <<-JS
      'use strict';

      exports.handler = async (event) => {
        return {
          statusCode: 200,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            message: 'Hello from the backend Lambda',
            path: event.rawPath || event.path || '/'
          }),
          isBase64Encoded: false
        };
      };
    JS
  }
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backend" {
  name               = "${var.api_name}-backend-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "backend" {
  name              = "/aws/lambda/${var.api_name}-backend"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.logs.arn

  tags = local.common_tags
}

data "aws_iam_policy_document" "backend_logs" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      aws_cloudwatch_log_group.backend.arn,
      "${aws_cloudwatch_log_group.backend.arn}:*",
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "xray:PutTraceSegments",
      "xray:PutTelemetryRecords",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "backend" {
  name   = "${var.api_name}-backend-logs"
  role   = aws_iam_role.backend.id
  policy = data.aws_iam_policy_document.backend_logs.json
}

resource "aws_lambda_function" "backend" {
  function_name    = "${var.api_name}-backend"
  role             = aws_iam_role.backend.arn
  handler          = "index.handler"
  runtime          = "nodejs20.x"
  filename         = data.archive_file.backend.output_path
  source_code_hash = data.archive_file.backend.output_base64sha256
  timeout          = 15

  tracing_config {
    mode = "Active"
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy.backend,
    aws_cloudwatch_log_group.backend,
  ]
}

resource "aws_lambda_permission" "backend_http" {
  count = local.http_integrations_enabled ? 1 : 0

  statement_id  = "AllowHTTPAPIInvokeBackend"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.backend.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.this[0].execution_arn}/*/*"
}

resource "aws_lambda_permission" "backend_rest" {
  count = local.rest_enabled ? 1 : 0

  statement_id  = "AllowRESTAPIInvokeBackend"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.backend.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.this[0].execution_arn}/*/*"
}

###############################################################################
# Custom Lambda authorizer (shared)
###############################################################################

data "archive_file" "authorizer" {
  count       = var.enable_authorizer ? 1 : 0
  type        = "zip"
  output_path = "${path.module}/build/authorizer.zip"

  source {
    filename = "index.js"
    content  = <<-JS
      'use strict';

      exports.handler = async (event) => {
        const headers = event.headers || {};
        const authorization = headers.Authorization || headers.authorization || '';
        const allowed = authorization.length > 0;
        const principalId = allowed ? authorization : 'anonymous';

        // HTTP API (payload format 2.0) simple response
        if (event.version === '2.0' || event.routeArn) {
          return {
            isAuthorized: allowed,
            context: { principalId: principalId }
          };
        }

        // REST API (v1) IAM policy response
        return {
          principalId: principalId,
          policyDocument: {
            Version: '2012-10-17',
            Statement: [
              {
                Action: 'execute-api:Invoke',
                Effect: allowed ? 'Allow' : 'Deny',
                Resource: event.methodArn
              }
            ]
          }
        };
      };
    JS
  }
}

resource "aws_iam_role" "authorizer" {
  count = var.enable_authorizer ? 1 : 0

  name               = "${var.api_name}-authorizer-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "authorizer" {
  count = var.enable_authorizer ? 1 : 0

  name              = "/aws/lambda/${var.api_name}-authorizer"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.logs.arn

  tags = local.common_tags
}

data "aws_iam_policy_document" "authorizer_logs" {
  count = var.enable_authorizer ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      aws_cloudwatch_log_group.authorizer[0].arn,
      "${aws_cloudwatch_log_group.authorizer[0].arn}:*",
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "xray:PutTraceSegments",
      "xray:PutTelemetryRecords",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "authorizer" {
  count = var.enable_authorizer ? 1 : 0

  name   = "${var.api_name}-authorizer-logs"
  role   = aws_iam_role.authorizer[0].id
  policy = data.aws_iam_policy_document.authorizer_logs[0].json
}

resource "aws_lambda_function" "authorizer" {
  count = var.enable_authorizer ? 1 : 0

  function_name    = "${var.api_name}-authorizer"
  role             = aws_iam_role.authorizer[0].arn
  handler          = "index.handler"
  runtime          = "nodejs20.x"
  filename         = data.archive_file.authorizer[0].output_path
  source_code_hash = data.archive_file.authorizer[0].output_base64sha256
  timeout          = 10

  tracing_config {
    mode = "Active"
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy.authorizer,
    aws_cloudwatch_log_group.authorizer,
  ]
}

resource "aws_lambda_permission" "authorizer" {
  count = var.enable_authorizer ? 1 : 0

  statement_id  = "AllowAPIGatewayInvokeAuthorizer"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer[0].function_name
  principal     = "apigateway.amazonaws.com"

  source_arn = var.api_type == "http" ? "${try(aws_apigatewayv2_api.this[0].execution_arn, "")}/*/*" : "${try(aws_api_gateway_rest_api.this[0].execution_arn, "")}/*/*"
}

###############################################################################
# HTTP API (v2) mode
###############################################################################

resource "aws_apigatewayv2_api" "this" {
  count = local.http_integrations_enabled ? 1 : 0

  name          = var.api_name
  protocol_type = "HTTP"

  tags = local.common_tags
}

resource "aws_apigatewayv2_integration" "this" {
  for_each = { for k, v in var.http_routes : k => v if local.http_integrations_enabled }

  api_id                 = aws_apigatewayv2_api.this[0].id
  integration_type       = each.value.integration_type
  integration_uri        = each.value.use_lambda_backend ? aws_lambda_function.backend.invoke_arn : each.value.integration_uri
  integration_method     = each.value.integration_type == "AWS_PROXY" ? "POST" : null
  payload_format_version = "2.0"
}

resource "aws_apigatewayv2_route" "this" {
  for_each = { for k, v in var.http_routes : k => v if local.http_integrations_enabled }

  api_id             = aws_apigatewayv2_api.this[0].id
  route_key          = each.value.route_key
  target             = "integrations/${aws_apigatewayv2_integration.this[each.key].id}"
  authorization_type = each.value.use_authorizer && var.enable_authorizer ? "CUSTOM" : each.value.authorization_type
  authorizer_id      = each.value.use_authorizer && var.enable_authorizer ? try(aws_apigatewayv2_authorizer.this[0].id, null) : null
}

resource "aws_apigatewayv2_authorizer" "this" {
  count = local.http_integrations_enabled && var.enable_authorizer ? 1 : 0

  api_id                            = aws_apigatewayv2_api.this[0].id
  name                              = "${var.api_name}-authorizer"
  authorizer_type                   = "REQUEST"
  authorizer_uri                    = aws_lambda_function.authorizer[0].invoke_arn
  authorizer_payload_format_version = "2.0"
  enable_simple_responses           = true
  identity_sources                  = ["$request.header.Authorization"]
}

resource "aws_apigatewayv2_stage" "this" {
  count = local.http_integrations_enabled ? 1 : 0

  api_id      = aws_apigatewayv2_api.this[0].id
  name        = local.stage_name
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api.arn

    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestMethod  = "$context.httpMethod"
      routeKey       = "$context.routeKey"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
    })
  }

  tags = local.common_tags
}

resource "aws_apigatewayv2_domain_name" "this" {
  count = local.http_integrations_enabled && var.create_custom_domain ? 1 : 0

  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = aws_acm_certificate.this[0].arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }

  tags = local.common_tags

  depends_on = [aws_acm_certificate_validation.this]
}

resource "aws_apigatewayv2_api_mapping" "this" {
  count = local.http_integrations_enabled && var.create_custom_domain ? 1 : 0

  api_id      = aws_apigatewayv2_api.this[0].id
  domain_name = aws_apigatewayv2_domain_name.this[0].id
  stage       = aws_apigatewayv2_stage.this[0].id
}

###############################################################################
# HTTP API (v2) VPC link stack
###############################################################################

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_instance" "backend" {
  count = local.http_vpc_link_enabled ? 1 : 0

  ami                         = data.aws_ami.amazon_linux.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.private["private-0"].id
  vpc_security_group_ids      = [aws_security_group.vpc_link.id]
  associate_public_ip_address = false

  tags = merge(local.common_tags, { Name = "${var.api_name}-backend" })
}

resource "aws_lb" "http_nlb" {
  count = local.http_vpc_link_enabled ? 1 : 0

  name               = substr("${var.api_name}-http-nlb", 0, 32)
  internal           = true
  load_balancer_type = "network"
  subnets            = [for s in aws_subnet.private : s.id]
  security_groups    = [aws_security_group.vpc_link.id]

  tags = merge(local.common_tags, { Name = "${var.api_name}-http-nlb" })
}

resource "aws_lb_target_group" "http" {
  count = local.http_vpc_link_enabled ? 1 : 0

  name        = substr("${var.api_name}-http-tg", 0, 32)
  port        = var.vpc_link_port
  protocol    = "TCP"
  target_type = "instance"
  vpc_id      = aws_vpc.api.id

  health_check {
    protocol            = "TCP"
    port                = "traffic-port"
    healthy_threshold   = 3
    unhealthy_threshold = 3
    interval            = 30
  }

  tags = local.common_tags
}

resource "aws_lb_target_group_attachment" "http" {
  count = local.http_vpc_link_enabled ? 1 : 0

  target_group_arn = aws_lb_target_group.http[0].arn
  target_id        = aws_instance.backend[0].id
  port             = var.vpc_link_port
}

resource "aws_lb_listener" "http" {
  count = local.http_vpc_link_enabled ? 1 : 0

  load_balancer_arn = aws_lb.http_nlb[0].arn
  port              = var.vpc_link_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.http[0].arn
  }

  tags = local.common_tags
}

resource "aws_apigatewayv2_vpc_link" "this" {
  count = local.http_vpc_link_enabled ? 1 : 0

  name               = substr("${var.api_name}-vpclink", 0, 32)
  subnet_ids         = [for s in aws_subnet.private : s.id]
  security_group_ids = [aws_security_group.vpc_link.id]

  tags = local.common_tags

  depends_on = [aws_lb.http_nlb]
}

###############################################################################
# REST API (v1) mode
###############################################################################

resource "aws_api_gateway_rest_api" "this" {
  count = local.rest_enabled ? 1 : 0

  name        = var.api_name
  description = "Managed by Terraform"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "this" {
  for_each = { for k, v in var.rest_resources : k => v if local.rest_enabled }

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  parent_id   = each.value.parent == null ? aws_api_gateway_rest_api.this[0].root_resource_id : aws_api_gateway_resource.this[each.value.parent].id
  path_part   = each.value.path_part
}

resource "aws_api_gateway_method" "this" {
  for_each = { for k, v in var.rest_methods : k => v if local.rest_enabled }

  rest_api_id        = aws_api_gateway_rest_api.this[0].id
  resource_id        = aws_api_gateway_resource.this[each.value.resource_key].id
  http_method        = each.value.http_method
  authorization      = each.value.use_authorizer && var.enable_authorizer ? "CUSTOM" : each.value.authorization
  authorizer_id      = each.value.use_authorizer && var.enable_authorizer ? try(aws_api_gateway_authorizer.this[0].id, null) : null
  request_parameters = each.value.request_parameters
}

resource "aws_api_gateway_integration" "this" {
  for_each = { for k, v in var.rest_methods : k => v if local.rest_enabled }

  rest_api_id             = aws_api_gateway_rest_api.this[0].id
  resource_id             = aws_api_gateway_resource.this[each.value.resource_key].id
  http_method             = aws_api_gateway_method.this[each.key].http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.backend.invoke_arn
}

data "aws_iam_policy_document" "ip_restriction" {
  count = local.rest_enabled && var.enable_ip_restriction ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["execute-api:Invoke"]
    resources = ["execute-api:/*"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "IpAddress"
      variable = "aws:SourceIp"
      values   = var.allowed_ip_cidrs
    }
  }
}

resource "aws_api_gateway_rest_api_policy" "this" {
  count = local.rest_enabled && var.enable_ip_restriction ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  policy      = data.aws_iam_policy_document.ip_restriction[0].json
}

resource "aws_api_gateway_deployment" "this" {
  count = local.rest_enabled ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.this[0].id

  triggers = {
    redeployment = sha1(jsonencode(concat(
      [for r in aws_api_gateway_resource.this : r.id],
      [for m in aws_api_gateway_method.this : m.id],
      [for i in aws_api_gateway_integration.this : i.id],
    )))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_method.this,
    aws_api_gateway_integration.this,
    aws_api_gateway_rest_api_policy.this,
  ]
}

resource "aws_api_gateway_stage" "this" {
  count = local.rest_enabled ? 1 : 0

  rest_api_id          = aws_api_gateway_rest_api.this[0].id
  deployment_id        = aws_api_gateway_deployment.this[0].id
  stage_name           = local.stage_name
  xray_tracing_enabled = var.xray_tracing_enabled

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api.arn

    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestMethod  = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
      latency        = "$context.responseLatency"
    })
  }

  tags = local.common_tags
}

resource "aws_api_gateway_authorizer" "this" {
  count = local.rest_enabled && var.enable_authorizer ? 1 : 0

  name                             = "${var.api_name}-authorizer"
  rest_api_id                      = aws_api_gateway_rest_api.this[0].id
  authorizer_uri                   = aws_lambda_function.authorizer[0].invoke_arn
  type                             = "REQUEST"
  identity_source                  = "method.request.header.Authorization"
  authorizer_result_ttl_in_seconds = var.authorizer_result_ttl_in_seconds
}

###############################################################################
# REST API (v1) usage plan / API key / secret storage
###############################################################################

resource "aws_api_gateway_usage_plan" "this" {
  count = local.rest_enabled ? 1 : 0

  name = "${var.api_name}-${var.environment}-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.this[0].id
    stage  = aws_api_gateway_stage.this[0].stage_name
  }

  throttle_settings {
    burst_limit = 100
    rate_limit  = 50
  }

  quota_settings {
    limit  = 10000
    period = "MONTH"
  }

  tags = local.common_tags
}

resource "aws_api_gateway_api_key" "this" {
  count = local.rest_enabled ? 1 : 0

  name = "${var.api_name}-${var.environment}-key"

  tags = local.common_tags
}

resource "aws_api_gateway_usage_plan_key" "this" {
  count = local.rest_enabled ? 1 : 0

  key_id        = aws_api_gateway_api_key.this[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.this[0].id
}

resource "aws_ssm_parameter" "api_key" {
  count = local.rest_enabled ? 1 : 0

  name        = "/${var.api_name}/${var.environment}/api-key"
  description = "API key for ${var.api_name} (${var.environment})"
  type        = "SecureString"
  value       = aws_api_gateway_api_key.this[0].value

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# REST API (v1) custom domain
###############################################################################

resource "aws_api_gateway_domain_name" "this" {
  count = local.rest_enabled && var.create_custom_domain ? 1 : 0

  domain_name              = var.domain_name
  regional_certificate_arn = aws_acm_certificate.this[0].arn
  security_policy          = "TLS_1_2"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.common_tags

  depends_on = [aws_acm_certificate_validation.this]
}

resource "aws_api_gateway_base_path_mapping" "this" {
  count = local.rest_enabled && var.create_custom_domain ? 1 : 0

  api_id      = aws_api_gateway_rest_api.this[0].id
  stage_name  = aws_api_gateway_stage.this[0].stage_name
  domain_name = aws_api_gateway_domain_name.this[0].domain_name
}

###############################################################################
# REST API (v1) VPC link stack
###############################################################################

resource "aws_lb" "internal" {
  count = local.rest_vpc_link_enabled ? 1 : 0

  name               = substr("${var.api_name}-internal-alb", 0, 32)
  internal           = true
  load_balancer_type = "application"
  subnets            = [for s in aws_subnet.private : s.id]
  security_groups    = [aws_security_group.vpc_link.id]

  tags = merge(local.common_tags, { Name = "${var.api_name}-internal-alb" })
}

resource "aws_lb" "rest_nlb" {
  count = local.rest_vpc_link_enabled ? 1 : 0

  name               = substr("${var.api_name}-rest-nlb", 0, 32)
  internal           = true
  load_balancer_type = "network"
  subnets            = [for s in aws_subnet.private : s.id]
  security_groups    = [aws_security_group.vpc_link.id]

  tags = merge(local.common_tags, { Name = "${var.api_name}-rest-nlb" })
}

resource "aws_lb_target_group" "rest" {
  count = local.rest_vpc_link_enabled ? 1 : 0

  name                 = substr("${var.api_name}-rest-tg", 0, 32)
  port                 = var.vpc_link_port
  protocol             = "TCP"
  target_type          = "alb"
  vpc_id               = aws_vpc.api.id
  deregistration_delay = 30

  health_check {
    protocol            = "HTTPS"
    port                = "traffic-port"
    path                = "/"
    interval            = 30
    timeout             = 6
    healthy_threshold   = 3
    unhealthy_threshold = 3
    matcher             = "200-399"
  }

  tags = local.common_tags
}

resource "aws_lb_target_group_attachment" "rest" {
  count = local.rest_vpc_link_enabled ? 1 : 0

  target_group_arn = aws_lb_target_group.rest[0].arn
  target_id        = aws_lb.internal[0].arn
  port             = var.vpc_link_port
}

resource "aws_lb_listener" "rest" {
  count = local.rest_vpc_link_enabled ? 1 : 0

  load_balancer_arn = aws_lb.rest_nlb[0].arn
  port              = var.vpc_link_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.rest[0].arn
  }

  tags = local.common_tags
}

resource "aws_api_gateway_vpc_link" "rest" {
  count = local.rest_vpc_link_enabled ? 1 : 0

  name        = substr("${var.api_name}-rest-vpclink", 0, 32)
  target_arns = [aws_lb.rest_nlb[0].arn]

  tags = local.common_tags
}

###############################################################################
# ACM certificate, Route53 zone and DNS validation
###############################################################################

resource "aws_route53_zone" "this" {
  count = var.create_custom_domain ? 1 : 0

  name = var.domain_name

  tags = local.common_tags
}

resource "aws_acm_certificate" "this" {
  count = var.create_custom_domain ? 1 : 0

  domain_name               = var.domain_name
  validation_method         = "DNS"
  subject_alternative_names = ["*.${var.domain_name}"]

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = {
    for dvo in try(aws_acm_certificate.this[0].domain_validation_options, []) :
    dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  }

  zone_id         = aws_route53_zone.this[0].zone_id
  name            = each.value.name
  type            = each.value.type
  records         = [each.value.record]
  ttl             = 60
  allow_overwrite = true
}

resource "aws_acm_certificate_validation" "this" {
  count = var.create_custom_domain ? 1 : 0

  certificate_arn         = aws_acm_certificate.this[0].arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

###############################################################################
# Alias A records for the custom domain
###############################################################################

resource "aws_route53_record" "http_api" {
  count = local.http_integrations_enabled && var.create_custom_domain && var.create_dns_record ? 1 : 0

  zone_id = aws_route53_zone.this[0].zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.this[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.this[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "rest_api" {
  count = local.rest_enabled && var.create_custom_domain && var.create_dns_record ? 1 : 0

  zone_id = aws_route53_zone.this[0].zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_api_gateway_domain_name.this[0].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.this[0].regional_zone_id
    evaluate_target_health = false
  }
}

###############################################################################
# API Gateway account level CloudWatch logging role (REST only)
###############################################################################

data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "apigw_cloudwatch" {
  statement {
    sid       = "DescribeLogGroups"
    effect    = "Allow"
    actions   = ["logs:DescribeLogGroups", "logs:DescribeLogStreams"]
    resources = ["*"]
  }

  statement {
    sid    = "WriteApiGatewayLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:GetLogEvents",
      "logs:FilterLogEvents",
    ]
    resources = [
      aws_cloudwatch_log_group.api.arn,
      "${aws_cloudwatch_log_group.api.arn}:*",
    ]
  }
}

resource "aws_iam_role" "apigw_cloudwatch" {
  count = local.rest_enabled ? 1 : 0

  name               = "${var.api_name}-apigw-cloudwatch-role"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy" "apigw_cloudwatch" {
  count = local.rest_enabled ? 1 : 0

  name   = "${var.api_name}-apigw-cloudwatch-policy"
  role   = aws_iam_role.apigw_cloudwatch[0].id
  policy = data.aws_iam_policy_document.apigw_cloudwatch.json
}

resource "aws_api_gateway_account" "this" {
  count = local.rest_enabled ? 1 : 0

  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch[0].arn

  depends_on = [aws_iam_role_policy.apigw_cloudwatch]
}

###############################################################################
# Outputs
###############################################################################

output "api_id" {
  description = "Identifier of the deployed API Gateway."
  value       = var.api_type == "http" ? try(aws_apigatewayv2_api.this[0].id, null) : try(aws_api_gateway_rest_api.this[0].id, null)
}

output "api_endpoint" {
  description = "Default execution endpoint of the deployed API."
  value = var.api_type == "http" ? try(aws_apigatewayv2_api.this[0].api_endpoint, null) : try(
    "https://${aws_api_gateway_rest_api.this[0].id}.execute-api.${data.aws_region.current.name}.amazonaws.com",
    null
  )
}

output "stage_invoke_url" {
  description = "Invoke URL of the deployed stage."
  value       = var.api_type == "http" ? try(aws_apigatewayv2_stage.this[0].invoke_url, null) : try(aws_api_gateway_stage.this[0].invoke_url, null)
}

output "custom_domain_target" {
  description = "Regional target domain name of the custom domain, if created."
  value = var.create_custom_domain ? (
    var.api_type == "http"
    ? try(aws_apigatewayv2_domain_name.this[0].domain_name_configuration[0].target_domain_name, null)
    : try(aws_api_gateway_domain_name.this[0].regional_domain_name, null)
  ) : null
}

output "vpc_link_id" {
  description = "Identifier of the provisioned VPC link, if any."
  value = var.enable_vpc_link ? (
    var.api_type == "http"
    ? try(aws_apigatewayv2_vpc_link.this[0].id, null)
    : try(aws_api_gateway_vpc_link.rest[0].id, null)
  ) : null
}

output "authorizer_function_arn" {
  description = "ARN of the custom Lambda authorizer function, if created."
  value       = var.enable_authorizer ? try(aws_lambda_function.authorizer[0].arn, null) : null
}

output "api_key_ssm_parameter_name" {
  description = "Name of the SSM SecureString parameter holding the API key."
  value       = local.rest_enabled ? try(aws_ssm_parameter.api_key[0].name, null) : null
}

output "api_key_id" {
  description = "Identifier of the generated API key."
  value       = local.rest_enabled ? try(aws_api_gateway_api_key.this[0].id, null) : null
}

output "api_key_name" {
  description = "Name of the generated API key."
  value       = local.rest_enabled ? try(aws_api_gateway_api_key.this[0].name, null) : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Data sources (static, non-infrastructure lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Random suffix for the default bucket names
###############################################################################

resource "random_string" "bucket_suffix" {
  length  = 8
  lower   = true
  upper   = false
  special = false
  numeric = true
}

###############################################################################
# Variables
###############################################################################

variable "s3_bucket_name" {
  description = "Name of the S3 bucket used to store CloudTrail logs. When empty a name is generated."
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Whether to delete all objects from the CloudTrail log buckets on destroy (destroy guard)."
  type        = bool
  default     = true
}

variable "enable_bucket_versioning" {
  description = "Whether to enable versioning on the CloudTrail log bucket."
  type        = bool
  default     = true
}

variable "cloudwatch_log_retention_days" {
  description = "Number of days CloudTrail CloudWatch Logs are retained."
  type        = number
  default     = 90
}

variable "create_sns_topic" {
  description = "Whether to create an SNS topic for CloudTrail notifications."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "Existing SNS topic ARN to use for CloudTrail notifications when create_sns_topic is false."
  type        = string
  default     = ""
}

variable "kms_alias_prefix" {
  description = "Prefix used for the KMS key alias (alias/<prefix>)."
  type        = string
  default     = "cloudtrail"
}

variable "kms_key_decrypt_role_arn" {
  description = "Optional IAM role ARN granted kms:Decrypt on the CloudTrail KMS key."
  type        = string
  default     = ""
}

variable "trail_name" {
  description = "Name of the CloudTrail trail."
  type        = string
  default     = "cloudtrail"
}

variable "s3_key_prefix" {
  description = "Optional S3 key prefix for CloudTrail log delivery."
  type        = string
  default     = ""
}

variable "include_global_service_events" {
  description = "Whether to include global service events in the trail."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Whether the trail is a multi-region trail."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Whether logging is enabled for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an organization trail."
  type        = bool
  default     = false
}

variable "read_write_type" {
  description = "Type of events the event selector applies to (All, ReadOnly, WriteOnly)."
  type        = string
  default     = "All"

  validation {
    condition     = contains(["All", "ReadOnly", "WriteOnly"], var.read_write_type)
    error_message = "read_write_type must be one of: All, ReadOnly, WriteOnly."
  }
}

variable "include_management_events" {
  description = "Whether the event selector includes management events."
  type        = bool
  default     = true
}

variable "data_resources" {
  description = "List of data resource selectors for the event selector."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_types" {
  description = "List of CloudTrail Insights types (e.g. ApiCallErrorRate, ApiCallVolume)."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags applied to all resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  cloudtrail_bucket_name    = var.s3_bucket_name != "" ? var.s3_bucket_name : "aws-cloudtrail-logs-${local.account_id}-${local.region}-${random_string.bucket_suffix.result}"
  access_log_bucket_name    = "aws-cloudtrail-access-logs-${local.account_id}-${local.region}-${random_string.bucket_suffix.result}"
  cloudwatch_log_group_name = "/aws/cloudtrail/${var.trail_name}"

  # Locally-computed trail ARN: identical to aws_cloudtrail.main.arn but derived
  # only from static provider metadata and var.trail_name, avoiding a dependency
  # edge from policy documents back into the trail resource.
  cloudtrail_trail_arn = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"

  sns_topic_arn = var.sns_topic_arn != "" ? var.sns_topic_arn : (var.create_sns_topic ? aws_sns_topic.cloudtrail_alerts[0].arn : null)

  common_tags = merge(
    var.tags,
    {
      "ManagedBy" = "terraform"
    }
  )
}

###############################################################################
# S3 bucket for CloudTrail log storage
###############################################################################

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.cloudtrail_bucket_name
  force_destroy = var.force_destroy

  tags = merge(local.common_tags, {
    Name = local.cloudtrail_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = var.enable_bucket_versioning ? "Enabled" : "Disabled"
  }
}

###############################################################################
# Dedicated S3 bucket for server access logs of the CloudTrail log bucket
###############################################################################

resource "aws_s3_bucket" "cloudtrail_access_logs" {
  bucket        = local.access_log_bucket_name
  force_destroy = var.force_destroy

  tags = merge(local.common_tags, {
    Name = local.access_log_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_access_logs" {
  bucket = aws_s3_bucket.cloudtrail_access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_access_logs" {
  bucket = aws_s3_bucket.cloudtrail_access_logs.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_access_logs" {
  bucket = aws_s3_bucket.cloudtrail_access_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "cloudtrail_access_logs_bucket" {
  statement {
    sid    = "S3ServerAccessLogsAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_access_logs.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "S3ServerAccessLogsWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_access_logs.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.cloudtrail_access_logs.arn,
      "${aws_s3_bucket.cloudtrail_access_logs.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_access_logs" {
  bucket = aws_s3_bucket.cloudtrail_access_logs.id
  policy = data.aws_iam_policy_document.cloudtrail_access_logs_bucket.json
}

###############################################################################
# Server access logging on the CloudTrail log bucket
###############################################################################

resource "aws_s3_bucket_logging" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  target_bucket = aws_s3_bucket.cloudtrail_access_logs.id
  target_prefix = "cloudtrail-access-logs/"
}

###############################################################################
# Bucket policy for the CloudTrail log bucket
###############################################################################

data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_logs.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.cloudtrail_trail_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_logs.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.cloudtrail_trail_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.cloudtrail_logs.arn,
      "${aws_s3_bucket.cloudtrail_logs.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json
}

###############################################################################
# KMS key, alias and key policy dedicated to CloudTrail
###############################################################################

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key used to encrypt CloudTrail logs and CloudWatch Logs for the ${var.trail_name} trail"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = 365

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${var.kms_alias_prefix}"
  target_key_id = aws_kms_key.cloudtrail.id
}

data "aws_iam_policy_document" "kms_cloudtrail" {
  statement {
    sid    = "EnableRootAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["kms:GenerateDataKey*"]
    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = [local.cloudtrail_trail_arn]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.cloudwatch_log_group_name}*"]
    }
  }

  statement {
    sid    = "AllowS3BucketEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = ["*"]

    condition {
      test = "StringEquals"
      variable = "aws:SourceArn"
      values = [
        aws_s3_bucket.cloudtrail_logs.arn,
        aws_s3_bucket.cloudtrail_access_logs.arn,
      ]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  dynamic "statement" {
    for_each = var.kms_key_decrypt_role_arn != "" ? [var.kms_key_decrypt_role_arn] : []

    content {
      sid    = "AllowLogDecryptionForProvidedRole"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = [statement.value]
      }

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
      ]
      resources = ["*"]
    }
  }
}

resource "aws_kms_key_policy" "cloudtrail" {
  key_id = aws_kms_key.cloudtrail.id
  policy = data.aws_iam_policy_document.kms_cloudtrail.json
}

###############################################################################
# CloudWatch Log Group for the trail
###############################################################################

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.cloudwatch_log_group_name
  retention_in_days = var.cloudwatch_log_retention_days
  kms_key_id        = aws_kms_key.cloudtrail.arn

  tags = local.common_tags
}

###############################################################################
# IAM role + policy allowing CloudTrail to ingest into CloudWatch Logs
###############################################################################

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    sid    = "AllowCloudTrailAssumeRole"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "${var.trail_name}-cloudwatch-logs-role"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch" {
  statement {
    sid    = "AllowCloudTrailToWriteToCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.cloudtrail.arn,
      "${aws_cloudwatch_log_group.cloudtrail.arn}:*",
    ]
  }
}

resource "aws_iam_policy" "cloudtrail_cloudwatch" {
  name        = "${var.trail_name}-cloudwatch-logs-policy"
  description = "Least-privilege policy allowing CloudTrail to write to the ${var.trail_name} CloudWatch Logs group"
  policy      = data.aws_iam_policy_document.cloudtrail_cloudwatch.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "cloudtrail_cloudwatch" {
  role       = aws_iam_role.cloudtrail_cloudwatch.name
  policy_arn = aws_iam_policy.cloudtrail_cloudwatch.arn
}

###############################################################################
# Optional SNS topic for CloudTrail notifications
###############################################################################

resource "aws_sns_topic" "cloudtrail_alerts" {
  count = var.create_sns_topic ? 1 : 0

  name = "${var.trail_name}-cloudtrail-alerts"

  tags = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_sns" {
  count = var.create_sns_topic ? 1 : 0

  statement {
    sid    = "AllowCloudTrailToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.cloudtrail_alerts[0].arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.cloudtrail_trail_arn]
    }
  }
}

resource "aws_sns_topic_policy" "cloudtrail_alerts" {
  count = var.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.cloudtrail_alerts[0].arn
  policy = data.aws_iam_policy_document.cloudtrail_sns[0].json
}

###############################################################################
# CloudTrail trail
###############################################################################

resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  s3_key_prefix                 = var.s3_key_prefix != "" ? var.s3_key_prefix : null
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  enable_log_file_validation    = true
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  sns_topic_name                = local.sns_topic_arn

  tags = local.common_tags

  dynamic "event_selector" {
    for_each = [true]

    content {
      read_write_type           = var.read_write_type
      include_management_events = var.include_management_events

      dynamic "data_resource" {
        for_each = var.data_resources

        content {
          type   = data_resource.value.type
          values = data_resource.value.values
        }
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_types

    content {
      insight_type = insight_selector.value
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.cloudtrail_cloudwatch,
    aws_s3_bucket_policy.cloudtrail_logs,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "cloudtrail_arn" {
  description = "ARN of the CloudTrail trail."
  value       = aws_cloudtrail.main.arn
}

output "cloudtrail_bucket_name" {
  description = "Name of the S3 bucket storing CloudTrail logs."
  value       = aws_s3_bucket.cloudtrail_logs.id
}

output "cloudtrail_bucket_arn" {
  description = "ARN of the S3 bucket storing CloudTrail logs."
  value       = aws_s3_bucket.cloudtrail_logs.arn
}

output "cloudtrail_access_logs_bucket_name" {
  description = "Name of the S3 bucket storing server access logs for the CloudTrail log bucket."
  value       = aws_s3_bucket.cloudtrail_access_logs.id
}

output "cloudtrail_access_logs_bucket_arn" {
  description = "ARN of the S3 bucket storing server access logs for the CloudTrail log bucket."
  value       = aws_s3_bucket.cloudtrail_access_logs.arn
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Log Group receiving CloudTrail logs."
  value       = aws_cloudwatch_log_group.cloudtrail.name
}

output "kms_key_arn" {
  description = "ARN of the KMS key used to encrypt CloudTrail logs."
  value       = aws_kms_key.cloudtrail.arn
}

output "kms_key_alias" {
  description = "Alias of the KMS key used to encrypt CloudTrail logs."
  value       = aws_kms_alias.cloudtrail.name
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic used for CloudTrail notifications (empty when not created)."
  value       = var.create_sns_topic ? aws_sns_topic.cloudtrail_alerts[0].arn : ""
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
  }
}

variable "cluster_name" {
  description = "Name of the EKS cluster. Drives every IAM role, policy, and instance profile name in this configuration."
  type        = string
  default     = "legion"
}

locals {
  master_role_name           = "tf-${var.cluster_name}"
  node_role_name             = "tf-${var.cluster_name}-node"
  node_instance_profile_name = "tf-${var.cluster_name}-node"
  autoscaling_policy_name    = "eks-worker-autoscaling-${var.cluster_name}"

  tags = {
    Cluster   = var.cluster_name
    ManagedBy = "terraform"
  }
}

# ---------------------------------------------------------------------------
# AWS managed policy lookups (resolved by name so no ARNs are hardcoded)
# ---------------------------------------------------------------------------

data "aws_iam_policy" "eks_cluster_policy" {
  name = "AmazonEKSClusterPolicy"
}

data "aws_iam_policy" "eks_service_policy" {
  name = "AmazonEKSServicePolicy"
}

data "aws_iam_policy" "eks_worker_node_policy" {
  name = "AmazonEKSWorkerNodePolicy"
}

data "aws_iam_policy" "eks_cni_policy" {
  name = "AmazonEKS_CNI_Policy"
}

data "aws_iam_policy" "ec2_container_registry_read_only" {
  name = "AmazonEC2ContainerRegistryReadOnly"
}

# ---------------------------------------------------------------------------
# Assume role policy documents
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "master_assume_role" {
  statement {
    sid     = "EKSClusterAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "node_assume_role" {
  statement {
    sid     = "EC2NodeAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# IAM roles
# ---------------------------------------------------------------------------

resource "aws_iam_role" "master" {
  name               = local.master_role_name
  assume_role_policy = data.aws_iam_policy_document.master_assume_role.json
  description        = "EKS control plane role for the ${var.cluster_name} cluster"

  tags = local.tags
}

resource "aws_iam_role" "node" {
  name               = local.node_role_name
  assume_role_policy = data.aws_iam_policy_document.node_assume_role.json
  description        = "EKS worker node role for the ${var.cluster_name} cluster"

  tags = local.tags
}

# ---------------------------------------------------------------------------
# Master (control plane) managed policy attachments
# ---------------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "master_eks_cluster_policy" {
  role       = aws_iam_role.master.name
  policy_arn = data.aws_iam_policy.eks_cluster_policy.arn
}

resource "aws_iam_role_policy_attachment" "master_eks_service_policy" {
  role       = aws_iam_role.master.name
  policy_arn = data.aws_iam_policy.eks_service_policy.arn
}

# ---------------------------------------------------------------------------
# Worker node managed policy attachments
# ---------------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "node_eks_worker_node_policy" {
  role       = aws_iam_role.node.name
  policy_arn = data.aws_iam_policy.eks_worker_node_policy.arn
}

resource "aws_iam_role_policy_attachment" "node_eks_cni_policy" {
  role       = aws_iam_role.node.name
  policy_arn = data.aws_iam_policy.eks_cni_policy.arn
}

resource "aws_iam_role_policy_attachment" "node_ec2_container_registry_read_only" {
  role       = aws_iam_role.node.name
  policy_arn = data.aws_iam_policy.ec2_container_registry_read_only.arn
}

# ---------------------------------------------------------------------------
# Cluster Autoscaler custom policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_worker_autoscaling" {
  statement {
    sid    = "AllowAutoscalingRead"
    effect = "Allow"

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:DescribeLaunchTemplateVersions",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowAutoscalingCapacityModification"
    effect = "Allow"

    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "eks_worker_autoscaling" {
  name        = local.autoscaling_policy_name
  description = "Allows the Cluster Autoscaler on the ${var.cluster_name} worker nodes to read Auto Scaling state and modify capacity for cluster-tagged Auto Scaling groups."
  policy      = data.aws_iam_policy_document.eks_worker_autoscaling.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "node_eks_worker_autoscaling" {
  role       = aws_iam_role.node.name
  policy_arn = aws_iam_policy.eks_worker_autoscaling.arn
}

# ---------------------------------------------------------------------------
# Worker node instance profile
# ---------------------------------------------------------------------------

resource "aws_iam_instance_profile" "node" {
  name = local.node_instance_profile_name
  role = aws_iam_role.node.name

  tags = local.tags
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "admin_mfa" {
  statement {
    sid    = "RequireMFA"
    effect = "Allow"

    actions   = ["*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "admin_terraform_cloud_mfa" {
  statement {
    sid    = "RequireMFA"
    effect = "Allow"

    actions   = ["*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "github_mfa" {
  statement {
    sid    = "RequireMFA"
    effect = "Allow"

    actions = [
      "acm:*",
      "cloudfront:*",
      "iam:*",
      "lambda:*",
      "route53:*",
      "s3:AbortMultipartUpload",
      "s3:DeleteObject",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
      "s3:PutObject",
      "sqs:*"
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "serverless_mfa" {
  statement {
    sid    = "RequireMFA"
    effect = "Allow"

    actions = [
      "acm:*",
      "cloudfront:*",
      "iam:*",
      "lambda:*",
      "logs:*",
      "route53:*",
      "s3:AbortMultipartUpload",
      "s3:DeleteObject",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
      "s3:PutObject",
      "sqs:*"
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "serverless" {
  statement {
    sid    = "AcmCertificates"
    effect = "Allow"

    actions = [
      "acm:AddTagsToCertificate",
      "acm:DeleteCertificate",
      "acm:DescribeCertificate",
      "acm:GetCertificate",
      "acm:ListCertificates",
      "acm:ListTagsForCertificate",
      "acm:RequestCertificate"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudFrontDistributions"
    effect = "Allow"

    actions = [
      "cloudfront:CreateDistribution",
      "cloudfront:CreateInvalidation",
      "cloudfront:DeleteDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:GetDistributionConfig",
      "cloudfront:GetInvalidation",
      "cloudfront:ListDistributions",
      "cloudfront:ListInvalidations",
      "cloudfront:UpdateDistribution"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "IamPassServerlessRole"
    effect = "Allow"

    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.serverless.arn]
  }

  statement {
    sid    = "DenyPassRoleToNonLambdaServices"
    effect = "Deny"

    actions   = ["iam:PassRole"]
    resources = ["*"]

    condition {
      test     = "StringNotEquals"
      variable = "iam:PassedToService"
      values   = ["lambda.amazonaws.com"]
    }
  }

  statement {
    sid    = "IamReadMetadata"
    effect = "Allow"

    actions = [
      "iam:GetPolicy",
      "iam:GetPolicyVersion",
      "iam:GetRole",
      "iam:GetRolePolicy",
      "iam:ListPolicies",
      "iam:ListRolePolicies",
      "iam:ListRoles"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "LambdaCompute"
    effect = "Allow"

    actions = ["lambda:*"]
    resources = [
      "arn:${local.partition}:lambda:*:${local.account_id}:function:*",
      "arn:${local.partition}:lambda:*:${local.account_id}:function:*:*",
      "arn:${local.partition}:lambda:*:${local.account_id}:layer:*",
      "arn:${local.partition}:lambda:*:${local.account_id}:layer:*:*",
      "arn:${local.partition}:lambda:*:${local.account_id}:event-source-mapping:*"
    ]
  }

  statement {
    sid    = "LambdaListRead"
    effect = "Allow"

    actions = [
      "lambda:GetAccountSettings",
      "lambda:ListEventSourceMappings",
      "lambda:ListFunctions",
      "lambda:ListLayers"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*",
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*:*",
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*:*:*"
    ]
  }

  statement {
    sid    = "Route53Records"
    effect = "Allow"

    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:ChangeTagsForResource",
      "route53:GetChange",
      "route53:GetHostedZone",
      "route53:ListResourceRecordSets",
      "route53:ListTagsForResource"
    ]
    resources = [
      "arn:${local.partition}:route53:::hostedzone/*",
      "arn:${local.partition}:route53:::change/*"
    ]
  }

  statement {
    sid    = "Route53List"
    effect = "Allow"

    actions = [
      "route53:ListHostedZones",
      "route53:ListHostedZonesByName"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3BucketsAndObjects"
    effect = "Allow"

    actions = [
      "s3:AbortMultipartUpload",
      "s3:DeleteObject",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
      "s3:PutObject"
    ]
    resources = [
      "arn:${local.partition}:s3:::*",
      "arn:${local.partition}:s3:::*/*"
    ]
  }

  statement {
    sid    = "SqsQueues"
    effect = "Allow"

    actions = [
      "sqs:CreateQueue",
      "sqs:DeleteMessage",
      "sqs:DeleteQueue",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
      "sqs:PurgeQueue",
      "sqs:ReceiveMessage",
      "sqs:SendMessage",
      "sqs:SetQueueAttributes"
    ]
    resources = [
      "arn:${local.partition}:sqs:${local.region}:${local.account_id}:*"
    ]
  }

  statement {
    sid    = "SqsList"
    effect = "Allow"

    actions   = ["sqs:ListQueues"]
    resources = ["*"]
  }
}

locals {
  common_tags = {
    Project   = "iam-access-management"
    ManagedBy = "Terraform"
  }

  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name
  account_id = data.aws_caller_identity.current.account_id
}

resource "aws_kms_key" "secrets" {
  description             = "CMK for IAM access-key secrets"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSecretsManagerUse"
        Effect = "Allow"
        Principal = {
          Service = "secretsmanager.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "secrets" {
  name          = "alias/iam-access-management-secrets"
  target_key_id = aws_kms_key.secrets.key_id
}

resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_group_policy" "admin" {
  name  = "admin"
  group = "admin"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "FullAdministrativeAccess"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
      }
    ]
  })

  depends_on = [aws_iam_group.admin]
}

resource "aws_iam_policy" "admin_mfa" {
  name        = "admin-mfa"
  path        = "/admin/"
  description = "MFA enforcement policy for the admin group"
  policy      = data.aws_iam_policy_document.admin_mfa.json
  tags        = local.common_tags
}

resource "aws_iam_group_policy" "admin_mfa" {
  name   = "admin-mfa"
  group  = "admin"
  policy = data.aws_iam_policy_document.admin_mfa.json

  depends_on = [aws_iam_group.admin]
}

resource "aws_iam_group_policy_attachment" "admin_mfa" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_mfa.arn
}

resource "aws_iam_group" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_group_policy" "admin_terraform_cloud" {
  name  = "admin-terraform-cloud"
  group = "admin-terraform-cloud"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "FullAdministrativeAccess"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
      }
    ]
  })

  depends_on = [aws_iam_group.admin_terraform_cloud]
}

resource "aws_iam_policy" "admin_terraform_cloud_mfa" {
  name        = "admin-terraform-cloud-mfa"
  path        = "/admin_terraform_cloud/"
  description = "MFA enforcement policy for the admin-terraform-cloud group"
  policy      = data.aws_iam_policy_document.admin_terraform_cloud_mfa.json
  tags        = local.common_tags
}

resource "aws_iam_group_policy" "admin_terraform_cloud_mfa" {
  name   = "admin-terraform-cloud-mfa"
  group  = "admin-terraform-cloud"
  policy = data.aws_iam_policy_document.admin_terraform_cloud_mfa.json

  depends_on = [aws_iam_group.admin_terraform_cloud]
}

resource "aws_iam_group_policy_attachment" "admin_terraform_cloud_mfa" {
  group      = aws_iam_group.admin_terraform_cloud.name
  policy_arn = aws_iam_policy.admin_terraform_cloud_mfa.arn
}

resource "aws_iam_group" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_group_policy" "github" {
  name  = "github"
  group = "github"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AcmCertificates"
        Effect = "Allow"
        Action = [
          "acm:AddTagsToCertificate",
          "acm:DeleteCertificate",
          "acm:DescribeCertificate",
          "acm:GetCertificate",
          "acm:ListCertificates",
          "acm:ListTagsForCertificate",
          "acm:RequestCertificate"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudFrontDistributions"
        Effect = "Allow"
        Action = [
          "cloudfront:CreateDistribution",
          "cloudfront:CreateInvalidation",
          "cloudfront:DeleteDistribution",
          "cloudfront:GetDistribution",
          "cloudfront:GetDistributionConfig",
          "cloudfront:GetInvalidation",
          "cloudfront:ListDistributions",
          "cloudfront:UpdateDistribution"
        ]
        Resource = "*"
      },
      {
        Sid    = "IamPassServerlessRole"
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = [
          aws_iam_role.serverless.arn
        ]
      },
      {
        Sid    = "LambdaDeployments"
        Effect = "Allow"
        Action = [
          "lambda:*"
        ]
        Resource = [
          "arn:${local.partition}:lambda:*:${local.account_id}:function:*",
          "arn:${local.partition}:lambda:*:${local.account_id}:function:*:*",
          "arn:${local.partition}:lambda:*:${local.account_id}:layer:*",
          "arn:${local.partition}:lambda:*:${local.account_id}:layer:*:*",
          "arn:${local.partition}:lambda:*:${local.account_id}:event-source-mapping:*"
        ]
      },
      {
        Sid    = "LambdaListRead"
        Effect = "Allow"
        Action = [
          "lambda:GetAccountSettings",
          "lambda:ListFunctions",
          "lambda:ListLayers"
        ]
        Resource = "*"
      },
      {
        Sid    = "Route53Records"
        Effect = "Allow"
        Action = [
          "route53:ChangeResourceRecordSets",
          "route53:ChangeTagsForResource",
          "route53:GetChange",
          "route53:GetHostedZone",
          "route53:ListResourceRecordSets",
          "route53:ListTagsForResource"
        ]
        Resource = [
          "arn:${local.partition}:route53:::hostedzone/*",
          "arn:${local.partition}:route53:::change/*"
        ]
      },
      {
        Sid    = "Route53List"
        Effect = "Allow"
        Action = [
          "route53:ListHostedZones",
          "route53:ListHostedZonesByName"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3BucketsAndObjects"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:DeleteObject",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [
          "arn:${local.partition}:s3:::*",
          "arn:${local.partition}:s3:::*/*"
        ]
      },
      {
        Sid    = "SqsQueues"
        Effect = "Allow"
        Action = [
          "sqs:CreateQueue",
          "sqs:DeleteMessage",
          "sqs:DeleteQueue",
          "sqs:GetQueueAttributes",
          "sqs:GetQueueUrl",
          "sqs:PurgeQueue",
          "sqs:ReceiveMessage",
          "sqs:SendMessage",
          "sqs:SetQueueAttributes"
        ]
        Resource = [
          "arn:${local.partition}:sqs:${local.region}:${local.account_id}:*"
        ]
      },
      {
        Sid    = "SqsList"
        Effect = "Allow"
        Action = [
          "sqs:ListQueues"
        ]
        Resource = "*"
      }
    ]
  })

  depends_on = [aws_iam_group.github]
}

resource "aws_iam_policy" "github_mfa" {
  name        = "github-mfa"
  path        = "/github/"
  description = "MFA enforcement policy for the github group"
  policy      = data.aws_iam_policy_document.github_mfa.json
  tags        = local.common_tags
}

resource "aws_iam_group_policy" "github_mfa" {
  name   = "github-mfa"
  group  = "github"
  policy = data.aws_iam_policy_document.github_mfa.json

  depends_on = [aws_iam_group.github]
}

resource "aws_iam_group_policy_attachment" "github_mfa" {
  group      = aws_iam_group.github.name
  policy_arn = aws_iam_policy.github_mfa.arn
}

resource "aws_iam_group" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

resource "aws_iam_group_policy" "serverless" {
  name   = "serverless"
  group  = "serverless"
  policy = data.aws_iam_policy_document.serverless.json

  depends_on = [aws_iam_group.serverless]
}

resource "aws_iam_policy" "serverless_mfa" {
