  group  = "serverless"
  policy = data.aws_iam_policy_document.serverless_mfa.json

  depends_on = [aws_iam_group.serverless]
}

resource "aws_iam_group_policy_attachment" "serverless_mfa" {
  group      = aws_iam_group.serverless.name
  policy_arn = aws_iam_policy.serverless_mfa.arn
}

