}

output "admin_macbook_pro_user_name" {
  value       = aws_iam_user.admin_macbook_pro.name
  description = "Name of the admin-macbook-pro IAM user"
}

output "admin_terraform_cloud_user_name" {
  value       = aws_iam_user.admin_terraform_cloud.name
