terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

################################################################
# Variables
################################################################

variable "namespace" {
  type        = string
  description = "Namespace (organization / project) used for consistent naming."
  default     = "acme"
}

variable "environment" {
  type        = string
  description = "Environment identifier used for consistent naming."
  default     = "ue1"
}

variable "name" {
  type        = string
  description = "Base name used for consistent naming."
  default     = "iam"
}

variable "tags" {
  type        = map(string)
  description = "Additional tags applied to every taggable resource."
  default     = {}
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes appended to generated names."
  default     = []
}

variable "admin_user_names" {
  type        = list(string)
  description = "List of IAM user names that should be created as members of the admin group."
  default     = []
}

variable "non_admin_user_names" {
  type        = list(string)
  description = "List of IAM user names that should be created as members of the non-admin group."
  default     = []
}

################################################################
# CloudPosse label modules (single source of truth for naming)
################################################################

module "this" {
  source  = "cloudposse/label/null"
  version = "~> 0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  tags        = var.tags
  attributes  = var.attributes
}

module "admin_label" {
  source  = "cloudposse/label/null"
  version = "~> 0.25.0"

  attributes = ["admin"]
  context    = module.this.context
}

module "non_admin_label" {
  source  = "cloudposse/label/null"
  version = "~> 0.25.0"

  attributes = ["non-admin"]
  context    = module.this.context
}

module "self_management_label" {
  source  = "cloudposse/label/null"
  version = "~> 0.25.0"

  attributes = ["self-management"]
  context    = module.this.context
}

module "admin_assume_role_label" {
  source  = "cloudposse/label/null"
  version = "~> 0.25.0"

  attributes = ["admin-assume-role"]
  context    = module.this.context
}

module "admin_role_label" {
  source  = "cloudposse/label/null"
  version = "~> 0.25.0"

  attributes = ["admin-role"]
  context    = module.this.context
}

################################################################
# IAM groups
################################################################

resource "aws_iam_group" "admin" {
  name = module.admin_label.id
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin_label.id
  path = "/"
}

################################################################
# Shared self-management policy
################################################################

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowManageOwnPasswordAndProfile"
    effect = "Allow"

    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:CreateLoginProfile",
      "iam:UpdateLoginProfile",
    ]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"

    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:UpdateAccessKey",
      "iam:ListAccessKeys",
    ]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
    ]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid    = "AllowListAccountMFAAndPasswordPolicy"
    effect = "Allow"

    actions = [
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:GetAccountPasswordPolicy",
      "iam:ListAccountAliases",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowDeactivateOwnMFADeviceOnlyWithMFA"
    effect = "Allow"

    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = module.self_management_label.id
  description = "Self-management permissions allowing users to manage their own credentials and MFA devices."
  policy      = data.aws_iam_policy_document.self_management.json
  tags        = module.self_management_label.tags
}

resource "aws_iam_group_policy_attachment" "admin_self_management" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admin_self_management" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

################################################################
# Admin role and its trust policy
################################################################

data "aws_iam_policy_document" "admin_trust" {
  statement {
    sid    = "AllowAccountRootToAssumeRoleWithMFA"
    effect = "Allow"

    actions = [
      "sts:AssumeRole",
    ]

    principals {
      type = "AWS"
      identifiers = [
        "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root",
      ]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = module.admin_role_label.id
  assume_role_policy = data.aws_iam_policy_document.admin_trust.json
  tags               = module.admin_role_label.tags
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

################################################################
# Admin-only policy to assume the admin role (MFA required)
################################################################

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid    = "AllowAssumeAdminRoleWithMFA"
    effect = "Allow"

    actions = [
      "sts:AssumeRole",
    ]

    resources = [
      aws_iam_role.admin.arn,
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }

    condition {
      test     = "NumericLessThan"
      variable = "aws:MultiFactorAuthAge"
      values   = ["3600"]
    }
  }
}

resource "aws_iam_policy" "admin_assume_role" {
  name        = module.admin_assume_role_label.id
  description = "Allows admin group members to assume the admin role, requiring a fresh MFA session."
  policy      = data.aws_iam_policy_document.admin_assume_role.json
  tags        = module.admin_assume_role_label.tags
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role.arn
}

################################################################
# IAM users
################################################################

resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_user_names)

  name = each.value
  path = "/"
  tags = module.admin_label.tags
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_user_names)

  name = each.value
  path = "/"
  tags = module.non_admin_label.tags
}

################################################################
# Conditional group memberships
################################################################

resource "aws_iam_user_group_membership" "admin" {
  for_each = aws_iam_user.admin

  user   = each.value.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "non_admin" {
  for_each = aws_iam_user.non_admin

  user   = each.value.name
  groups = [aws_iam_group.non_admin.name]
}

################################################################
# Account password policy
################################################################

resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 24
  hard_expiry                    = false
}

################################################################
# Outputs
################################################################

output "admin_group_name" {
  description = "Name of the admin IAM group."
  value       = aws_iam_group.admin.name
}

output "non_admin_group_name" {
  description = "Name of the non-admin IAM group."
  value       = aws_iam_group.non_admin.name
}

output "admin_role_arn" {
  description = "ARN of the admin IAM role."
  value       = aws_iam_role.admin.arn
}

output "self_management_policy_arn" {
  description = "ARN of the shared self-management IAM policy."
  value       = aws_iam_policy.self_management.arn
}

output "admin_assume_role_policy_arn" {
  description = "ARN of the admin-only assume-role IAM policy."
  value       = aws_iam_policy.admin_assume_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Static provider metadata lookups (no pre-existing infrastructure involved)
################################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

################################################################################
# Git based labels module - single source of truth for naming and tagging
################################################################################

module "labels" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"

  name        = var.name
  environment = var.environment
  delimiter   = var.delimiter
  attributes  = var.attributes
  enabled     = var.enable
}

################################################################################
# Core toggles
################################################################################

variable "enable" {
  description = "Master toggle for the whole module. When false nothing is provisioned."
  type        = bool
  default     = true
}

variable "create_sg" {
  description = "When true a new security group is created. When false, rules are attached to an existing security group supplied via existing_sg_id."
  type        = bool
  default     = true
}

variable "existing_sg_id" {
  description = "ID of an existing security group that rules are attached to when create_sg = false."
  type        = string
  default     = ""

  validation {
    condition     = var.existing_sg_id == "" || can(regex("^sg-[0-9a-f]{8,}$", var.existing_sg_id))
    error_message = "existing_sg_id must be empty or a valid security group id (sg-...)."
  }
}

variable "vpc_id" {
  description = "VPC the new security group is created in. When empty a fallback VPC (10.0.0.0/16) is created."
  type        = string
  default     = ""

  validation {
    condition     = var.vpc_id == "" || can(regex("^vpc-[0-9a-f]{8,}$", var.vpc_id))
    error_message = "vpc_id must be empty or a valid VPC id (vpc-...)."
  }
}

################################################################################
# Managed prefix list inputs
################################################################################

variable "create_prefix_list" {
  description = "Create a managed prefix list (only when no existing prefix list ids are supplied)."
  type        = bool
  default     = false
}

variable "existing_prefix_list_ids" {
  description = "Existing managed prefix list ids to reuse instead of creating a new one."
  type        = list(string)
  default     = []
}

variable "prefix_list_cidrs" {
  description = "CIDR entries for the managed prefix list. A maximum of 5 entries is enforced (max_entries = 5)."
  type        = list(string)
  default     = []

  validation {
    condition     = length(var.prefix_list_cidrs) <= 5
    error_message = "A managed prefix list supports a maximum of 5 entries (max_entries = 5)."
  }

  validation {
    condition     = alltrue([for cidr in var.prefix_list_cidrs : can(cidrhost(cidr, 0))])
    error_message = "prefix_list_cidrs must contain valid CIDR blocks."
  }
}

################################################################################
# Naming / tagging inputs fed into the labels module
################################################################################

variable "name" {
  description = "Name (project/application) used by the labels module."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment used by the labels module (e.g. prod, staging)."
  type        = string
  default     = ""
}

variable "delimiter" {
  description = "Delimiter used by the labels module when building the resource id."
  type        = string
  default     = "-"
}

variable "attributes" {
  description = "Additional attributes appended by the labels module. Use this to carry extra naming context (namespace, stage, etc.)."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags applied to every resource directly at the resource layer (the labels module has no tags input)."
  type        = map(string)
  default     = {}
}

################################################################################
# Flow log / logging inputs
################################################################################

variable "flow_log_retention_in_days" {
  description = "Retention (in days) for the VPC flow log CloudWatch log group."
  type        = number
  default     = 30

  validation {
    condition = contains(
      [1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653],
      var.flow_log_retention_in_days
    )
    error_message = "flow_log_retention_in_days must be a value supported by CloudWatch Logs."
  }
}

variable "flow_log_traffic_type" {
  description = "Type of traffic to capture in the VPC flow log (ACCEPT, REJECT or ALL)."
  type        = string
  default     = "ALL"

  validation {
    condition     = contains(["ACCEPT", "REJECT", "ALL"], var.flow_log_traffic_type)
    error_message = "flow_log_traffic_type must be one of: ACCEPT, REJECT or ALL."
  }
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period (in days) before the KMS key used for flow log encryption is deleted."
  type        = number
  default     = 30

  validation {
    condition     = var.kms_deletion_window_in_days >= 7 && var.kms_deletion_window_in_days <= 30
    error_message = "kms_deletion_window_in_days must be between 7 and 30."
  }
}

################################################################################
# Security group rule inputs
################################################################################

variable "ingress_rules" {
  description = "Map of ingress rules keyed by a unique rule name."
  type = map(object({
    description              = optional(string, "Managed ingress rule")
    from_port                = number
    to_port                  = number
    protocol                 = optional(string, "tcp")
    cidr_blocks              = optional(list(string), [])
    ipv6_cidr_blocks         = optional(list(string), [])
    self                     = optional(bool, false)
    source_security_group_id = optional(string, "")
    prefix_list_ids          = optional(list(string), [])
    allow_all_cidr           = optional(bool, false)
  }))
  default = {}

  validation {
    condition = alltrue([
      for rule in values(var.ingress_rules) :
      contains(["tcp", "udp", "icmp", "icmpv6", "-1"], lower(rule.protocol))
    ])
    error_message = "Ingress rule protocol must be one of: tcp, udp, icmp, icmpv6 or -1."
  }

  validation {
    condition = alltrue([
      for rule in values(var.ingress_rules) :
      !(rule.self && rule.source_security_group_id != "")
    ])
    error_message = "An ingress rule cannot set self = true and source_security_group_id at the same time."
  }

  validation {
    condition = alltrue([
      for rule in values(var.ingress_rules) :
      rule.self || rule.source_security_group_id != "" || length(rule.cidr_blocks) > 0 || length(rule.ipv6_cidr_blocks) > 0 || length(rule.prefix_list_ids) > 0
    ])
    error_message = "Each ingress rule must define at least one of: cidr_blocks, ipv6_cidr_blocks, self, source_security_group_id or prefix_list_ids."
  }

  validation {
    condition = alltrue([
      for rule in values(var.ingress_rules) :
      !contains(rule.cidr_blocks, "0.0.0.0/0") ||
      rule.allow_all_cidr ||
      contains([80, 443], rule.from_port) ||
      contains([80, 443], rule.to_port)
    ])
    error_message = "Ingress from 0.0.0.0/0 is only allowed on ports 80 or 443. Set allow_all_cidr = true on the rule to explicitly justify public ingress on any other port."
  }
}

variable "egress_rules" {
  description = "Map of egress rules keyed by a unique rule name."
  type = map(object({
    description              = optional(string, "Managed egress rule")
    from_port                = number
    to_port                  = number
    protocol                 = optional(string, "tcp")
    cidr_blocks              = optional(list(string), [])
    ipv6_cidr_blocks         = optional(list(string), [])
    self                     = optional(bool, false)
    source_security_group_id = optional(string, "")
    prefix_list_ids          = optional(list(string), [])
    allow_all_cidr           = optional(bool, false)
  }))
  default = {}

  validation {
    condition = alltrue([
      for rule in values(var.egress_rules) :
      contains(["tcp", "udp", "icmp", "icmpv6", "-1"], lower(rule.protocol))
    ])
    error_message = "Egress rule protocol must be one of: tcp, udp, icmp, icmpv6 or -1."
  }

  validation {
    condition = alltrue([
      for rule in values(var.egress_rules) :
      !(rule.self && rule.source_security_group_id != "")
    ])
    error_message = "An egress rule cannot set self = true and source_security_group_id at the same time."
  }

  validation {
    condition = alltrue([
      for rule in values(var.egress_rules) :
      rule.self || rule.source_security_group_id != "" || length(rule.cidr_blocks) > 0 || length(rule.ipv6_cidr_blocks) > 0 || length(rule.prefix_list_ids) > 0
    ])
    error_message = "Each egress rule must define at least one of: cidr_blocks, ipv6_cidr_blocks, self, source_security_group_id or prefix_list_ids."
  }
}

################################################################################
# Locals
################################################################################

locals {
  sg_name          = "${module.labels.id}-sg"
  prefix_list_name = "${module.labels.id}-prefix-list"

  # Caller-supplied tags, applied directly at the resource layer.
  caller_tags = var.tags

  # Fallback VPC: only when we must create a security group and no VPC is given.
  create_fallback_vpc = var.enable && var.create_sg && var.vpc_id == ""

  # Safe splat reference - resolves to null when no fallback VPC exists.
  fallback_vpc_id = one(aws_vpc.fallback[*].id)

  # Resolves to the newly created SG id, otherwise to the supplied existing SG id.
  security_group_id = var.create_sg ? one(aws_security_group.this[*].id) : var.existing_sg_id

  # Managed prefix list creation gate (never when pre-existing prefix lists are supplied).
  create_managed_prefix_list = var.enable && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0
  managed_prefix_list_ids    = local.create_managed_prefix_list ? aws_ec2_managed_prefix_list.this[*].id : []
  effective_prefix_list_ids  = length(var.existing_prefix_list_ids) > 0 ? var.existing_prefix_list_ids : local.managed_prefix_list_ids

  # Rule gating - a single toggle disables everything without breaking apply.
  rules_enabled = var.enable && (var.create_sg || var.existing_sg_id != "")
  ingress_rules = local.rules_enabled ? var.ingress_rules : {}
  egress_rules  = local.rules_enabled ? var.egress_rules : {}

  # Hard cap of 5 entries to satisfy max_entries = 5.
  prefix_list_entries = distinct(slice(var.prefix_list_cidrs, 0, min(length(var.prefix_list_cidrs), 5)))

  # Flow log / KMS naming and principals.
  flow_log_name      = "${module.labels.id}-flow-logs"
  flow_log_role_name = "${module.labels.id}-flow-logs-role"
  kms_key_alias_name = "alias/${module.labels.id}-flow-logs"

  # Region-scoped CloudWatch Logs service principal used for KMS usage grants.
  logs_service_principal = "logs.${data.aws_region.current.name}.amazonaws.com"
}

################################################################################
# Fallback VPC (only created when no VPC id is supplied and an SG is requested)
################################################################################

resource "aws_vpc" "fallback" {
  count = local.create_fallback_vpc ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    module.labels.tags,
    local.caller_tags,
    {
      Name = "${module.labels.id}-fallback-vpc"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

################################################################################
# Customer managed KMS key for encrypting the flow log CloudWatch log group
################################################################################

resource "aws_kms_key" "flow_logs" {
  count = local.create_fallback_vpc ? 1 : 0

  description             = "CMK encrypting the ${module.labels.id} VPC flow log CloudWatch log group"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true

  tags = merge(
    module.labels.tags,
    local.caller_tags,
    {
      Name = "${module.labels.id}-flow-logs-key"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "flow_logs_kms" {
  count = local.create_fallback_vpc ? 1 : 0

  # Root account administration - keeps the key fully manageable.
  statement {
    sid    = "AllowKeyAdministration"
    effect = "Allow"

    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  # CloudWatch Logs usage - allows the log service to encrypt on the log group's behalf.
  statement {
    sid    = "AllowCloudWatchLogsUsage"
    effect = "Allow"

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*"
    ]

    principals {
      type        = "Service"
      identifiers = [local.logs_service_principal]
    }

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*"]
    }
  }
}

resource "aws_kms_key_policy" "flow_logs" {
  count = local.create_fallback_vpc ? 1 : 0

  key_id = aws_kms_key.flow_logs[0].id
  policy = data.aws_iam_policy_document.flow_logs_kms[0].json
}

resource "aws_kms_alias" "flow_logs" {
  count = local.create_fallback_vpc ? 1 : 0

  name          = local.kms_key_alias_name
  target_key_id = aws_kms_key.flow_logs[0].key_id
}

################################################################################
# VPC Flow Logs (only for the fallback VPC, clearing AVD-AWS-0178)
################################################################################

resource "aws_cloudwatch_log_group" "flow_logs" {
  count = local.create_fallback_vpc ? 1 : 0

  name              = local.flow_log_name
  retention_in_days = var.flow_log_retention_in_days
  kms_key_id        = aws_kms_key.flow_logs[0].arn

  tags = merge(
    module.labels.tags,
    local.caller_tags,
    {
      Name = local.flow_log_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "flow_logs_assume_role" {
  count = local.create_fallback_vpc ? 1 : 0

  statement {
    sid     = "AllowFlowLogsToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.logs_service_principal]
    }
  }
}

resource "aws_iam_role" "flow_logs" {
  count = local.create_fallback_vpc ? 1 : 0

  name               = local.flow_log_role_name
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role[0].json

  tags = merge(
    module.labels.tags,
    local.caller_tags,
    {
      Name = local.flow_log_role_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  count = local.create_fallback_vpc ? 1 : 0

  name = local.flow_log_role_name
  role = aws_iam_role.flow_logs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowFlowLogsToWriteToCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_logs[0].arn,
          "${aws_cloudwatch_log_group.flow_logs[0].arn}:*"
        ]
      },
      {
        Sid    = "AllowFlowLogsToUseKmsKey"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.flow_logs[0].arn
        ]
      }
    ]
  })
}

resource "aws_flow_log" "this" {
  count = local.create_fallback_vpc ? 1 : 0

  vpc_id               = local.fallback_vpc_id
  traffic_type         = var.flow_log_traffic_type
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_logs[0].arn
  iam_role_arn         = aws_iam_role.flow_logs[0].arn

  tags = merge(
    module.labels.tags,
    local.caller_tags,
    {
      Name = local.flow_log_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

################################################################################
# Security group
################################################################################

resource "aws_security_group" "this" {
  count = var.enable && var.create_sg ? 1 : 0

  name        = local.sg_name
  description = "Managed security group for application workloads"
  vpc_id      = var.vpc_id != "" ? var.vpc_id : local.fallback_vpc_id

  tags = merge(
    module.labels.tags,
    local.caller_tags,
    {
      Name = local.sg_name
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

################################################################################
# Managed prefix list (IPv4, max 5 entries)
################################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_managed_prefix_list ? 1 : 0

  name           = local.prefix_list_name
  address_family = "IPv4"
  max_entries    = 5

  dynamic "entry" {
    for_each = local.prefix_list_entries
    content {
      cidr        = entry.value
      description = "Managed entry ${entry.key}"
    }
  }

  tags = merge(
    module.labels.tags,
    local.caller_tags,
    {
      Name = local.prefix_list_name
    }
  )
}

################################################################################
# Ingress rules
################################################################################

resource "aws_security_group_rule" "ingress" {
  for_each = local.ingress_rules

  type              = "ingress"
  security_group_id = local.security_group_id

  description = each.value.description
  from_port   = each.value.from_port
  to_port     = each.value.to_port
  protocol    = each.value.protocol

  cidr_blocks      = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null

  # Self referencing rules resolve to the managed (or supplied existing) security group id.
  source_security_group_id = each.value.self ? local.security_group_id : (each.value.source_security_group_id != "" ? each.value.source_security_group_id : null)

  # Defaults to the managed prefix list when the rule does not specify one explicitly.
  prefix_list_ids = length(each.value.prefix_list_ids) > 0 ? each.value.prefix_list_ids : local.effective_prefix_list_ids
}

################################################################################
# Egress rules
################################################################################

resource "aws_security_group_rule" "egress" {
  for_each = local.egress_rules

  type              = "egress"
  security_group_id = local.security_group_id

  description = each.value.description
  from_port   = each.value.from_port
  to_port     = each.value.to_port
  protocol    = each.value.protocol

  cidr_blocks      = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null

  # Self referencing rules resolve to the managed (or supplied existing) security group id.
  source_security_group_id = each.value.self ? local.security_group_id : (each.value.source_security_group_id != "" ? each.value.source_security_group_id : null)

  # Defaults to the managed prefix list when the rule does not specify one explicitly.
  prefix_list_ids = length(each.value.prefix_list_ids) > 0 ? each.value.prefix_list_ids : local.effective_prefix_list_ids
}

################################################################################
# Outputs
################################################################################

output "labels_id" {
  description = "Base identifier produced by the labels module."
  value       = module.labels.id
}

output "labels_tags" {
  description = "Tags produced by the labels module."
  value       = module.labels.tags
}

output "security_group_id" {
  description = "ID of the created security group or the supplied existing security group."
  value       = local.security_group_id
}

output "security_group_arn" {
  description = "ARN of the created security group (null when an existing security group is used)."
  value       = one(aws_security_group.this[*].arn)
}

output "security_group_name" {
  description = "Name of the created security group (null when an existing security group is used)."
  value       = one(aws_security_group.this[*].name)
}

output "fallback_vpc_id" {
  description = "ID of the fallback VPC created when no VPC id was supplied."
  value       = one(aws_vpc.fallback[*].id)
}

output "managed_prefix_list_id" {
  description = "ID of the managed prefix list created by this module."
  value       = one(aws_ec2_managed_prefix_list.this[*].id)
}

output "flow_log_id" {
  description = "ID of the VPC flow log created for the fallback VPC."
  value       = one(aws_flow_log.this[*].id)
}

output "flow_logs_log_group_name" {
  description = "Name of the CloudWatch log group receiving flow logs."
  value       = one(aws_cloudwatch_log_group.flow_logs[*].name)
}

output "flow_logs_log_group_arn" {
  description = "ARN of the CloudWatch log group receiving flow logs."
  value       = one(aws_cloudwatch_log_group.flow_logs[*].arn)
}

output "flow_logs_role_arn" {
  description = "ARN of the IAM role used by the flow-logs delivery service."
  value       = one(aws_iam_role.flow_logs[*].arn)
}

output "flow_logs_kms_key_arn" {
  description = "ARN of the customer managed KMS key encrypting the flow log CloudWatch log group."
  value       = one(aws_kms_key.flow_logs[*].arn)
}

output "flow_logs_kms_alias_name" {
  description = "Alias name of the customer managed KMS key encrypting the flow log CloudWatch log group."
  value       = one(aws_kms_alias.flow_logs[*].name)
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "= 4.0.6"
    }
    local = {
      source  = "hashicorp/local"
      version = "= 2.4.1"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/${local.eks_version}/amazon-linux-2/recommended/image_id"
}

locals {
  cluster_name      = "demo-eks"
  eks_version       = "1.30"
  cfn_stack_name    = "eks-cluster-stack"
  cluster_role_name = "eksClusterRole"
  node_role_name    = "eks-demo-node"
  node_kp_name      = "eks_kp"
  nat_gateway_name  = "demo-eks-nat"
  flow_log_name     = "demo-eks-vpc-flow-logs"

  vpc_cidr             = "10.0.0.0/16"
  public_subnet_cidr   = "10.0.0.0/24"
  private_subnet_cidrs = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  cluster_role_arn = "arn:${local.partition}:iam::${local.account_id}:role/${local.cluster_role_name}"

  common_tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }

  node_group_template = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Description              = "Unmanaged EKS worker node Auto Scaling Group for the ${local.cluster_name} cluster"

    Parameters = {
      ClusterName = {
        Type        = "String"
        Description = "Name of the EKS cluster that the worker nodes join."
      }
      LaunchTemplateId = {
        Type        = "String"
        Description = "ID of the launch template used by the worker nodes."
      }
      LaunchTemplateVersion = {
        Type        = "String"
        Description = "Version of the launch template used by the worker nodes."
      }
      NodeSecurityGroupId = {
        Type        = "AWS::EC2::SecurityGroup::Id"
        Description = "Security group attached to the worker nodes."
      }
      NodeInstanceProfileName = {
        Type        = "String"
        Description = "IAM instance profile attached to the worker nodes."
      }
      SubnetIds = {
        Type        = "List<AWS::EC2::Subnet::Id>"
        Description = "Private subnets the Auto Scaling Group spans."
      }
    }

    Resources = {
      NodeGroup = {
        Type = "AWS::AutoScaling::AutoScalingGroup"

        CreationPolicy = {
          ResourceSignal = {
            Count   = 3
            Timeout = "PT15M"
          }
        }

        UpdatePolicy = {
          AutoScalingRollingUpdate = {
            MaxBatchSize          = 1
            MinInstancesInService = 3
            PauseTime             = "PT5M"
          }
        }

        Properties = {
          AutoScalingGroupName = "${local.cluster_name}-node-asg"
          MinSize              = "1"
          DesiredCapacity      = "3"
          MaxSize              = "4"
          VPCZoneIdentifier    = { Ref = "SubnetIds" }

          LaunchTemplate = {
            LaunchTemplateId = { Ref = "LaunchTemplateId" }
            Version          = { Ref = "LaunchTemplateVersion" }
          }

          Tags = [
            {
              Key               = "Name"
              Value             = "${local.cluster_name}-node"
              PropagateAtLaunch = true
            },
            {
              Key               = "ClusterName"
              Value             = { Ref = "ClusterName" }
              PropagateAtLaunch = true
            },
            {
              Key               = "NodeSecurityGroupId"
              Value             = { Ref = "NodeSecurityGroupId" }
              PropagateAtLaunch = true
            },
            {
              Key               = "NodeInstanceProfileName"
              Value             = { Ref = "NodeInstanceProfileName" }
              PropagateAtLaunch = true
            }
          ]
        }
      }
    }

    Outputs = {
      AutoScalingGroupId = {
        Description = "ID of the Auto Scaling Group created for the EKS worker nodes."
        Value       = { Ref = "NodeGroup" }
      }
    }
  })
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                     = "${local.cluster_name}-public-${data.aws_availability_zones.available.names[0]}"
    "kubernetes.io/role/elb" = "1"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name                              = "${local.cluster_name}-private-${data.aws_availability_zones.available.names[count.index]}"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.common_tags, {
    Name = local.nat_gateway_name
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_kms_key" "cloudwatch" {
  description             = "Customer managed key for ${local.flow_log_name} CloudWatch log encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAdmin"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowCloudWatchLogsUseOfKey"
        Effect    = "Allow"
        Principal = { Service = "logs.${local.region}.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.flow_log_name}-cmk"
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${local.flow_log_name}"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc/flow-logs/${local.flow_log_name}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.cloudwatch.arn

  tags = merge(local.common_tags, {
    Name = local.flow_log_name
  })
}

resource "aws_iam_role" "vpc_flow_logs" {
  name = local.flow_log_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "vpc-flow-logs.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = local.flow_log_name
  })
}

resource "aws_iam_role_policy_attachment" "vpc_flow_logs" {
  role       = aws_iam_role.vpc_flow_logs.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/CloudWatchLogsFullAccess"
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "${local.flow_log_name}-publish"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "PublishFlowLogsToCloudWatch"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.vpc_flow_logs.arn,
          "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id          = aws_vpc.main.id
  traffic_type    = "ALL"
  log_destination = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn    = aws_iam_role.vpc_flow_logs.arn

  tags = merge(local.common_tags, {
    Name = local.flow_log_name
  })

  depends_on = [
    aws_iam_role_policy.vpc_flow_logs,
    aws_iam_role_policy_attachment.vpc_flow_logs
  ]
}

resource "aws_kms_key" "eks" {
  description             = "Customer managed key for ${local.cluster_name} EKS secrets envelope encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAdmin"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowEKSClusterRoleUseOfKey"
        Effect    = "Allow"
        Principal = { AWS = local.cluster_role_arn }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey*",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-eks-secrets"
  })
}

resource "aws_kms_alias" "eks" {
  name          = "alias/${local.cluster_name}-eks-secrets"
  target_key_id = aws_kms_key.eks.key_id
}

resource "aws_iam_role" "eks_cluster" {
  name = local.cluster_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "eks.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = local.cluster_role_name
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policies" {
  count = 2

  role = aws_iam_role.eks_cluster.name
  policy_arn = element([
    "arn:${local.partition}:iam::aws:policy/AmazonEKSClusterPolicy",
    "arn:${local.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
  ], count.index)
}

resource "aws_iam_role_policy" "eks_cluster_kms" {
  name = "${local.cluster_name}-cluster-kms"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "UseCustomerManagedKeyForSecretsEncryption"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey*",
          "kms:CreateGrant"
        ]
        Resource = aws_kms_key.eks.arn
      }
    ]
  })
}

resource "aws_eks_cluster" "demo" {
  name     = local.cluster_name
  version  = local.eks_version
  role_arn = aws_iam_role.eks_cluster.arn

  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  tags = merge(local.common_tags, {
    Name = local.cluster_name
  })

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policies,
    aws_iam_role_policy.eks_cluster_kms,
    aws_kms_key.eks,
    aws_kms_alias.eks
  ]
}

resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_private_key" {
  content         = tls_private_key.eks.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0400"
}

resource "aws_key_pair" "eks_kp" {
  key_name   = local.node_kp_name
  public_key = tls_private_key.eks.public_key_openssh

  tags = merge(local.common_tags, {
    Name = local.node_kp_name
  })
}

resource "aws_security_group" "node" {
  name        = "${local.cluster_name}-node-sg"
  description = "Security group for the ${local.cluster_name} unmanaged worker nodes"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Unrestricted communication between nodes in the group"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  ingress {
    description     = "HTTPS from the EKS control plane"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id]
  }

  ingress {
    description     = "Kubelet and service traffic from the EKS control plane"
    from_port       = 1025
    to_port         = 65535
    protocol        = "tcp"
    security_groups = [aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id]
  }

  egress {
    description = "Unrestricted outbound communication between nodes in the group"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description     = "HTTPS to the EKS control plane"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id]
  }

  egress {
    description     = "Kubelet and service traffic to the EKS control plane"
    from_port       = 1025
    to_port         = 65535
    protocol        = "tcp"
    security_groups = [aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-node-sg"
  })
}

resource "aws_iam_role" "node" {
  name = local.node_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = local.node_role_name
  })
}

resource "aws_iam_role_policy_attachment" "node_policies" {
  count = 4

  role = aws_iam_role.node.name
  policy_arn = element([
    "arn:${local.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy",
    "arn:${local.partition}:iam::aws:policy/AmazonEKS_CNI_Policy",
    "arn:${local.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly",
    "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
  ], count.index)
}

resource "aws_iam_instance_profile" "node" {
  name = local.node_role_name
  role = aws_iam_role.node.name
}

resource "aws_launch_template" "node" {
  name_prefix   = "${local.cluster_name}-node-"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks_kp.key_name

  user_data = base64encode(<<-EOT
    #!/bin/bash
    set -o xtrace
    /etc/eks/bootstrap.sh '${local.cluster_name}' \
      --apiserver-endpoint '${aws_eks_cluster.demo.endpoint}' \
      --b64-cluster-ca '${aws_eks_cluster.demo.certificate_authority[0].data}'
    /opt/aws/bin/cfn-signal --exit-code $? \
      --stack '${local.cfn_stack_name}' \
      --resource NodeGroup \
      --region '${local.region}'
  EOT
  )

  iam_instance_profile {
    name = aws_iam_instance_profile.node.name
  }

  vpc_security_group_ids = [aws_security_group.node.id]

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp2"
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, {
      Name = "${local.cluster_name}-node"
    })
  }

  tag_specifications {
    resource_type = "volume"

    tags = merge(local.common_tags, {
      Name = "${local.cluster_name}-node-volume"
    })
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-node-lt"
  })
}

resource "terraform_data" "lt_settle" {
  triggers_replace = {
    launch_template_latest_version = aws_launch_template.node.latest_version
  }

  provisioner "local-exec" {
    command = "sleep 30"
  }

  depends_on = [aws_launch_template.node]
}

resource "aws_cloudformation_stack" "eks_cluster" {
  name          = local.cfn_stack_name
  template_body = local.node_group_template
  on_failure    = "ROLLBACK"

  timeout_in_minutes = 30

  parameters = {
    ClusterName             = local.cluster_name
    LaunchTemplateId        = aws_launch_template.node.id
    LaunchTemplateVersion   = aws_launch_template.node.latest_version
    NodeSecurityGroupId     = aws_security_group.node.id
    NodeInstanceProfileName = aws_iam_instance_profile.node.name
    SubnetIds               = join(",", aws_subnet.private[*].id)
  }

  tags = merge(local.common_tags, {
    Name = local.cfn_stack_name
  })

  depends_on = [terraform_data.lt_settle]
}

output "node_instance_role_arn" {
  description = "ARN of the IAM role attached to the EKS worker nodes."
  value       = aws_iam_role.node.arn
}

output "node_security_group_id" {
  description = "ID of the security group attached to the EKS worker nodes."
  value       = aws_security_group.node.id
}

output "asg_id" {
  description = "ID of the Auto Scaling Group created by the eks-cluster-stack CloudFormation stack."
  value       = aws_cloudformation_stack.eks_cluster.outputs["AutoScalingGroupId"]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "= 2.5.2"
    }
  }
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

###############################################################################
# Variables
###############################################################################

variable "primary_region" {
  description = "AWS region hosting the primary Terraform remote state bucket."
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "AWS region hosting the disaster-recovery replica state bucket."
  type        = string
  default     = "us-west-2"
}

variable "eks_stacks" {
  description = "Map of EKS stack name => region used to drive per-stack state locking and backend generation."
  type        = map(string)
  default = {
    "eks-dev"  = "us-east-1"
    "eks-prod" = "us-east-1"
  }
}

###############################################################################
# Static provider metadata lookups (no pre-existing infrastructure required)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  state_bucket_name   = "eks-terraform-state-${local.account_id}-${var.primary_region}"
  replica_bucket_name = "eks-terraform-state-${local.account_id}-${var.replica_region}"

  logs_primary_bucket_name = "eks-terraform-logs-${local.account_id}-${var.primary_region}"
  logs_replica_bucket_name = "eks-terraform-logs-${local.account_id}-${var.replica_region}"

  # Constructed ARNs used to avoid a graph edge back to the state/replica bucket resources.
  state_bucket_arn   = "arn:${local.partition}:s3:::${local.state_bucket_name}"
  replica_bucket_arn = "arn:${local.partition}:s3:::${local.replica_bucket_name}"

  common_tags = {
    Project         = "eks-remote-state"
    Environment     = "shared"
    Purpose         = "terraform-remote-state"
    ManagedBy       = "terraform"
    StackManagement = "true"
  }
}

###############################################################################
# Primary KMS key (us-east-1) for state encryption
###############################################################################

resource "aws_kms_key" "state" {
  description             = "CMK used to encrypt EKS Terraform remote state objects and lock tables."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "eks-terraform-state-key-policy"
    Statement = [
      {
        Sid    = "EnableAccountRootFullAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowStateReplicationRoleUsage"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:GenerateDataKey*",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowS3LogDeliveryEncryption"
        Effect = "Allow"
        Principal = {
          Service = ["logging.s3.amazonaws.com"]
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.${var.primary_region}.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "state" {
  name          = "alias/eks-terraform-state"
  target_key_id = aws_kms_key.state.key_id

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Primary log-delivery bucket (us-east-1)
###############################################################################

resource "aws_s3_bucket" "logs_primary" {
  bucket        = local.logs_primary_bucket_name
  force_destroy = false

  tags = merge(local.common_tags, {
    Name = local.logs_primary_bucket_name
    Role = "logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_ownership_controls" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.logs_primary]
}

resource "aws_s3_bucket_policy" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "eks-terraform-logs-primary-bucket-policy"
    Statement = [
      {
        Sid    = "AllowS3LogDelivery"
        Effect = "Allow"
        Principal = {
          Service = ["logging.s3.amazonaws.com"]
        }
        Action   = ["s3:PutObject"]
        Resource = "${aws_s3_bucket.logs_primary.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.state_bucket_arn
          }
        }
      },
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.logs_primary.arn,
          "${aws_s3_bucket.logs_primary.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.logs_primary]
}

###############################################################################
# Primary state bucket (us-east-1)
###############################################################################

resource "aws_s3_bucket" "state" {
  bucket        = local.state_bucket_name
  force_destroy = false

  logging {
    target_bucket = aws_s3_bucket.logs_primary.id
    target_prefix = "state-access-logs/"
  }

  tags = merge(local.common_tags, {
    Name = local.state_bucket_name
    Role = "primary"
  })

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_s3_bucket.logs_primary,
  ]
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "eks-terraform-state-bucket-policy"
    Statement = [
      {
        Sid    = "AllowS3LogDelivery"
        Effect = "Allow"
        Principal = {
          Service = ["logging.s3.amazonaws.com"]
        }
        Action   = ["s3:PutObject"]
        Resource = "${aws_s3_bucket.state.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.state_bucket_arn
          }
        }
      },
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyUnencryptedObjectUploads"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.state.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.state]
}

###############################################################################
# Replica KMS key (disaster-recovery region)
###############################################################################

resource "aws_kms_key" "replica" {
  provider = aws.replica

  description             = "Dedicated CMK used to encrypt replicated EKS Terraform remote state in ${var.replica_region}."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "eks-terraform-state-replica-key-policy"
    Statement = [
      {
        Sid    = "EnableAccountRootFullAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowStateReplicationRoleUsage"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:GenerateDataKey*",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowS3LogDeliveryEncryption"
        Effect = "Allow"
        Principal = {
          Service = ["logging.s3.amazonaws.com"]
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.${var.replica_region}.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica" {
  provider = aws.replica

  name          = "alias/eks-terraform-state-replica"
  target_key_id = aws_kms_key.replica.key_id

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Replica log-delivery bucket (disaster-recovery region)
###############################################################################

resource "aws_s3_bucket" "logs_replica" {
  provider = aws.replica

  bucket        = local.logs_replica_bucket_name
  force_destroy = false

  tags = merge(local.common_tags, {
    Name = local.logs_replica_bucket_name
    Role = "logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logs_replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.logs_replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "logs_replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.logs_replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs_replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.logs_replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_ownership_controls" "logs_replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.logs_replica.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logs_replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.logs_replica.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.logs_replica]
}

resource "aws_s3_bucket_policy" "logs_replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.logs_replica.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "eks-terraform-logs-replica-bucket-policy"
    Statement = [
      {
        Sid    = "AllowS3LogDelivery"
        Effect = "Allow"
        Principal = {
          Service = ["logging.s3.amazonaws.com"]
        }
        Action   = ["s3:PutObject"]
        Resource = "${aws_s3_bucket.logs_replica.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.replica_bucket_arn
          }
        }
      },
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.logs_replica.arn,
          "${aws_s3_bucket.logs_replica.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.logs_replica]
}

###############################################################################
# Replica state bucket (disaster-recovery region)
###############################################################################

resource "aws_s3_bucket" "replica" {
  provider = aws.replica

  bucket        = local.replica_bucket_name
  force_destroy = false

  logging {
    target_bucket = aws_s3_bucket.logs_replica.id
    target_prefix = "replica-access-logs/"
  }

  tags = merge(local.common_tags, {
    Name = local.replica_bucket_name
    Role = "replica"
  })

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_s3_bucket.logs_replica,
  ]
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "eks-terraform-state-replica-bucket-policy"
    Statement = [
      {
        Sid    = "AllowS3LogDelivery"
        Effect = "Allow"
        Principal = {
          Service = ["logging.s3.amazonaws.com"]
        }
        Action   = ["s3:PutObject"]
        Resource = "${aws_s3_bucket.replica.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.replica_bucket_arn
          }
        }
      },
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

###############################################################################
# Cross-region replication IAM role + least-privilege policy
###############################################################################

resource "aws_iam_role" "replication" {
  name        = "eks-terraform-state-replication-role"
  description = "Role assumed by S3 to replicate KMS-encrypted Terraform state to the DR region."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ReplicationServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.state_bucket_arn
          }
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "replication" {
  name        = "eks-terraform-state-replication-policy"
  description = "Least-privilege permissions for S3 CRR of KMS-encrypted Terraform state objects."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadSourceBucketConfiguration"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.state.arn]
      },
      {
        Sid    = "ReadSourceObjectVersions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = ["${aws_s3_bucket.state.arn}/*"]
      },
      {
        Sid    = "DecryptSourceWithPrimaryKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.state.arn]
      },
      {
        Sid    = "EncryptReplicaWithReplicaKey"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*"
        ]
        Resource = [aws_kms_key.replica.arn]
      },
      {
        Sid    = "WriteToReplicaBucket"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = ["${aws_s3_bucket.replica.arn}/*"]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

###############################################################################
# S3 cross-region replication configuration
###############################################################################

resource "aws_s3_bucket_replication_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "eks-terraform-state-crr"
    status = "Enabled"

    filter {
      prefix = ""
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }

      replica_modifications {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.state,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy_attachment.replication,
  ]
}

###############################################################################
# Per-stack state locking tables (pay-per-request)
###############################################################################

resource "aws_dynamodb_table" "lock" {
  for_each = var.eks_stacks

  name         = "${each.key}-terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.state.arn
  }

  tags = merge(local.common_tags, {
    Name  = "${each.key}-terraform-locks"
    Stack = each.key
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Per-stack least-privilege state access policies
###############################################################################

resource "aws_iam_policy" "stack" {
  for_each = var.eks_stacks

  name        = "${each.key}-terraform-state-access"
  description = "Least-privilege access to the ${each.key} Terraform remote state backend resources."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StackStateLocking"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "dynamodb:UpdateItem",
          "dynamodb:DescribeTable",
          "dynamodb:Query"
        ]
        Resource = [aws_dynamodb_table.lock[each.key].arn]
      },
      {
        Sid      = "ListStackStatePrefix"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.state.arn]
        Condition = {
          StringLike = {
            "s3:prefix" = [
              "${each.key}/",
              "${each.key}/*"
            ]
          }
        }
      },
      {
        Sid    = "ReadWriteStackStateObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = ["${aws_s3_bucket.state.arn}/${each.key}/*"]
      },
      {
        Sid    = "UseStateEncryptionKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.state.arn]
      }
    ]
  })

  tags = merge(local.common_tags, {
    Stack = each.key
  })
}

###############################################################################
# Per-stack backend.tf generation
###############################################################################

resource "local_file" "backend" {
  for_each = var.eks_stacks

  filename = "${path.module}/eks-stacks/${each.key}/backend.tf"

  content = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.state.id}"
        key            = "${each.key}/terraform.tfstate"
        region         = "${var.primary_region}"
        dynamodb_table = "${aws_dynamodb_table.lock[each.key].name}"
        encrypt        = true
        kms_key_id     = "${aws_kms_key.state.arn}"
      }
    }
  EOT

  depends_on = [
    aws_s3_bucket.state,
    aws_s3_bucket_policy.state,
    aws_s3_bucket_replication_configuration.state,
    aws_dynamodb_table.lock,
    aws_kms_key.state,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "primary_state_bucket_name" {
  description = "Name of the primary Terraform remote state bucket."
  value       = aws_s3_bucket.state.id
}

output "primary_state_bucket_arn" {
  description = "ARN of the primary Terraform remote state bucket."
  value       = aws_s3_bucket.state.arn
}

output "replica_state_bucket_name" {
  description = "Name of the disaster-recovery replica state bucket."
  value       = aws_s3_bucket.replica.id
}

output "replica_state_bucket_arn" {
  description = "ARN of the disaster-recovery replica state bucket."
  value       = aws_s3_bucket.replica.arn
}

output "logs_primary_bucket_name" {
  description = "Name of the primary region S3 access-log delivery bucket."
  value       = aws_s3_bucket.logs_primary.id
}

output "logs_primary_bucket_arn" {
  description = "ARN of the primary region S3 access-log delivery bucket."
  value       = aws_s3_bucket.logs_primary.arn
}

output "logs_replica_bucket_name" {
  description = "Name of the replica region S3 access-log delivery bucket."
  value       = aws_s3_bucket.logs_replica.id
}

output "logs_replica_bucket_arn" {
  description = "ARN of the replica region S3 access-log delivery bucket."
  value       = aws_s3_bucket.logs_replica.arn
}

output "primary_kms_key_arn" {
  description = "ARN of the primary state encryption KMS key."
  value       = aws_kms_key.state.arn
}

output "replica_kms_key_arn" {
  description = "ARN of the replica state encryption KMS key."
  value       = aws_kms_key.replica.arn
}

output "replication_role_arn" {
  description = "ARN of the S3 cross-region replication IAM role."
  value       = aws_iam_role.replication.arn
}

output "backend_config_paths" {
  description = "Map of stack name to the generated backend.tf path."
  value       = { for stack, file in local_file.backend : stack => file.filename }
}

output "dynamodb_lock_table_names" {
  description = "Map of stack name to its DynamoDB state locking table name."
  value       = { for stack, table in aws_dynamodb_table.lock : stack => table.name }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "3.6.3"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Shared two-word pet name reused by the API, queue, KMS alias and log group
# ---------------------------------------------------------------------------
resource "random_pet" "this" {
  length = 2
}

# ---------------------------------------------------------------------------
# Customer-managed KMS key dedicated to the SQS queue (with rotation)
# Also protects the CloudWatch Logs access-log group
# ---------------------------------------------------------------------------
resource "aws_kms_key" "sqs" {
  description             = "Customer managed key for SQS queue ${random_pet.this.id} used by the WebSocket API"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CancelKeyDeletion",
          "kms:CreateAlias",
          "kms:CreateGrant",
          "kms:DeleteAlias",
          "kms:DescribeKey",
          "kms:DisableKey",
          "kms:DisableKeyRotation",
          "kms:EnableKey",
          "kms:EnableKeyRotation",
          "kms:GetKeyPolicy",
          "kms:GetKeyRotationStatus",
          "kms:ListAliases",
          "kms:ListGrants",
          "kms:ListKeyPolicies",
          "kms:ListResourceTags",
          "kms:PutKeyPolicy",
          "kms:RevokeGrant",
          "kms:ScheduleKeyDeletion",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:UpdateAlias",
          "kms:UpdateKeyDescription",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowApiGatewayRoleToUseKey"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.apigw_sqs.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/${random_pet.this.id}-sqs"
  target_key_id = aws_kms_key.sqs.id
}

# ---------------------------------------------------------------------------
# SQS queue that receives the raw client messages
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "messages" {
  name                              = random_pet.this.id
  kms_master_key_id                 = aws_kms_key.sqs.arn
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# CloudWatch log group for WebSocket access logs (1 day retention, CMK-encrypted)
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "ws_access" {
  name              = "/aws/apigateway/${random_pet.this.id}-ws-access-logs"
  retention_in_days = 1
  kms_key_id        = aws_kms_key.sqs.arn
}

# ---------------------------------------------------------------------------
# Execution role assumed by API Gateway for the AWS service integrations
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    sid     = "AllowApiGatewayAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigw_sqs" {
  name               = "${random_pet.this.id}-apigw-sqs-role"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json
}

data "aws_iam_policy_document" "apigw_sqs_access" {
  statement {
    sid     = "AllowSendMessageToQueue"
    effect  = "Allow"
    actions = ["sqs:SendMessage", "sqs:GetQueueAttributes"]
    resources = [
      aws_sqs_queue.messages.arn,
    ]
  }

  statement {
    sid     = "AllowKmsAccessForSseSqs"
    effect  = "Allow"
    actions = ["kms:GenerateDataKey", "kms:Decrypt"]
    resources = [
      aws_kms_key.sqs.arn,
    ]
  }

  statement {
    sid    = "AllowApiGatewayAccessLogging"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
      "logs:DescribeLogGroups",
    ]
    resources = [
      aws_cloudwatch_log_group.ws_access.arn,
      "${aws_cloudwatch_log_group.ws_access.arn}:*",
    ]
  }
}

resource "aws_iam_role_policy" "apigw_sqs" {
  name   = "${random_pet.this.id}-apigw-sqs-policy"
  role   = aws_iam_role.apigw_sqs.id
  policy = data.aws_iam_policy_document.apigw_sqs_access.json
}

# ---------------------------------------------------------------------------
# Account-level CloudWatch role required so API Gateway can emit access logs
# ---------------------------------------------------------------------------
resource "aws_api_gateway_account" "this" {
  cloudwatch_role_arn = aws_iam_role.apigw_sqs.arn
}

# ---------------------------------------------------------------------------
# WebSocket API
# ---------------------------------------------------------------------------
resource "aws_apigatewayv2_api" "ws" {
  name                       = random_pet.this.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# ---------------------------------------------------------------------------
# $connect route -> MOCK integration returning HTTP 200
# ---------------------------------------------------------------------------
resource "aws_apigatewayv2_integration" "connect" {
  api_id             = aws_apigatewayv2_api.ws.id
  integration_type   = "MOCK"
  integration_method = "POST"
}

resource "aws_apigatewayv2_route" "connect" {
  api_id             = aws_apigatewayv2_api.ws.id
  route_key          = "$connect"
  authorization_type = "NONE"
  target             = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_integration_response" "connect" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.connect.id
  integration_response_key = "/200/"
}

# ---------------------------------------------------------------------------
# $default route -> WebSocket AWS service integration SQS-SendMessage
# ---------------------------------------------------------------------------
resource "aws_apigatewayv2_integration" "default_send" {
  api_id             = aws_apigatewayv2_api.ws.id
  integration_type   = "AWS"
  integration_method = "POST"
  integration_uri    = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.name}:sqs:action/SendMessage"
  credentials_arn    = aws_iam_role.apigw_sqs.arn

  request_templates = {
    "application/x-www-form-urlencoded" = "QueueUrl=${aws_sqs_queue.messages.url}&MessageBody=$input.body"
  }
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default_send.id}"
}

resource "aws_apigatewayv2_route_response" "default" {
  api_id             = aws_apigatewayv2_api.ws.id
  route_id           = aws_apigatewayv2_route.default.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration_response" "default_send" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.default_send.id
  integration_response_key = "/200/"

  response_templates = {
    "$default" = "$input.body"
  }
}

# ---------------------------------------------------------------------------
# $disconnect route -> WebSocket AWS service integration SQS-SendMessage
# ---------------------------------------------------------------------------
resource "aws_apigatewayv2_integration" "disconnect_send" {
  api_id             = aws_apigatewayv2_api.ws.id
  integration_type   = "AWS"
  integration_method = "POST"
  integration_uri    = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.name}:sqs:action/SendMessage"
  credentials_arn    = aws_iam_role.apigw_sqs.arn

  request_templates = {
    "application/x-www-form-urlencoded" = "QueueUrl=${aws_sqs_queue.messages.url}&MessageBody=Client+disconnected"
  }
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect_send.id}"
}

# ---------------------------------------------------------------------------
# Deployment (redeploys on any route/integration change)
# ---------------------------------------------------------------------------
resource "aws_apigatewayv2_deployment" "ws" {
  api_id      = aws_apigatewayv2_api.ws.id
  description = "Deployment for ${random_pet.this.id} WebSocket API"

  triggers = {
    redeployment = sha1(jsonencode([
      aws_apigatewayv2_route.connect.id,
      aws_apigatewayv2_route.default.id,
      aws_apigatewayv2_route.disconnect.id,
      aws_apigatewayv2_integration.connect.id,
      aws_apigatewayv2_integration.default_send.id,
      aws_apigatewayv2_integration.disconnect_send.id,
      aws_apigatewayv2_integration_response.connect.id,
      aws_apigatewayv2_integration_response.default_send.id,
      aws_apigatewayv2_route_response.default.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Stage "dev" with auto-deploy and access logging to CloudWatch
# ---------------------------------------------------------------------------
resource "aws_apigatewayv2_stage" "dev" {
  api_id        = aws_apigatewayv2_api.ws.id
  name          = "dev"
  deployment_id = aws_apigatewayv2_deployment.ws.id
  auto_deploy   = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.ws_access.arn

    format = jsonencode({
      requestId         = "$context.requestId"
      routeKey          = "$context.routeKey"
      status            = "$context.status"
      connectionId      = "$context.connectionId"
      errorMessage      = "$context.error.message"
      extendedRequestId = "$context.extendedRequestId"
    })
  }

  default_route_settings {
    logging_level          = "INFO"
    throttling_burst_limit = 100
    throttling_rate_limit  = 50
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "websocket_endpoint" {
  description = "Full WebSocket endpoint URL including the dev stage name"
  value       = aws_apigatewayv2_stage.dev.invoke_url
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary_region"
  region = var.secondary_region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "primary_bucket_name" {
  description = "Base name of the primary S3 bucket. The AWS account ID is appended to guarantee global uniqueness."
  type        = string
  default     = "example1"
}

variable "secondary_bucket_name" {
  description = "Base name of the secondary (replica) S3 bucket. The AWS account ID is appended to guarantee global uniqueness."
  type        = string
  default     = "example2"
}

variable "log_bucket_name" {
  description = "Base name of the primary-region S3 server access logging bucket. The AWS account ID is appended to guarantee global uniqueness."
  type        = string
  default     = "example-logs"
}

variable "secondary_log_bucket_name" {
  description = "Base name of the secondary-region S3 server access logging bucket. The AWS account ID is appended to guarantee global uniqueness."
  type        = string
  default     = "example-logs-secondary"
}

variable "mrap_name" {
  description = "Name of the S3 Multi-Region Access Point."
  type        = string
  default     = "example-mrap"
}

variable "secondary_region" {
  description = "Secondary AWS region that hosts the replica bucket and the Multi-Region Access Point control plane."
  type        = string
  default     = "us-west-2"
}

variable "tags" {
  description = "Tags applied to every taggable resource in this configuration."
  type        = map(string)
  default = {
    Project     = "s3-multi-region-access-point"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  primary_bucket_name   = "${var.primary_bucket_name}-${data.aws_caller_identity.current.account_id}"
  secondary_bucket_name = "${var.secondary_bucket_name}-${data.aws_caller_identity.current.account_id}"

  log_primary_bucket_name   = "${var.log_bucket_name}-${data.aws_caller_identity.current.account_id}"
  log_secondary_bucket_name = "${var.secondary_log_bucket_name}-${data.aws_caller_identity.current.account_id}"

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  mrap_object_arn = "arn:${local.partition}:s3::${local.account_id}:accesspoint/${var.mrap_name}/object/*"

  common_tags = merge(var.tags, {
    PrimaryBucket          = local.primary_bucket_name
    SecondaryBucket        = local.secondary_bucket_name
    LoggingBucketPrimary   = local.log_primary_bucket_name
    LoggingBucketSecondary = local.log_secondary_bucket_name
    MultiRegionAccessPoint = var.mrap_name
  })
}

###############################################################################
# KMS customer-managed keys (one per region / per bucket)
###############################################################################

data "aws_iam_policy_document" "primary_kms_policy" {
  statement {
    sid    = "AllowOwningAccountFullAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowReplicationRoleToDecryptPrimaryObjects"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.s3_replication.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "secondary_kms_policy" {
  statement {
    sid    = "AllowOwningAccountFullAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowReplicationRoleToEncryptReplicaObjects"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.s3_replication.arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:Decrypt",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "primary" {
  description             = "Customer-managed key used to encrypt objects in the primary S3 bucket ${local.primary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.primary_kms_policy.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "secondary" {
  provider = aws.secondary_region

  description             = "Customer-managed key used to encrypt objects in the secondary S3 bucket ${local.secondary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.secondary_kms_policy.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# S3 buckets
###############################################################################

resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "secondary" {
  provider = aws.secondary_region

  bucket = local.secondary_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "logs_primary" {
  bucket = local.log_primary_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "logs_secondary" {
  provider = aws.secondary_region

  bucket = local.log_secondary_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.secondary_region

  bucket = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_ownership_controls" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_ownership_controls" "logs_secondary" {
  provider = aws.secondary_region

  bucket = aws_s3_bucket.logs_secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.secondary_region

  bucket = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "logs_secondary" {
  provider = aws.secondary_region

  bucket = aws_s3_bucket.logs_secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary_region

  bucket = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "logs_secondary" {
  provider = aws.secondary_region

  bucket = aws_s3_bucket.logs_secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary_region

  bucket = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs_secondary" {
  provider = aws.secondary_region

  bucket = aws_s3_bucket.logs_secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Server access logging: region-local log targets + per-bucket logging wiring
###############################################################################

data "aws_iam_policy_document" "logs_primary_bucket_policy" {
  statement {
    sid    = "AllowS3LogDeliveryServiceToWritePrimaryLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs_primary.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values = [
        aws_s3_bucket.primary.arn,
      ]
    }
  }
}

resource "aws_s3_bucket_policy" "logs_primary" {
  bucket = aws_s3_bucket.logs_primary.id
  policy = data.aws_iam_policy_document.logs_primary_bucket_policy.json

  depends_on = [
    aws_s3_bucket_public_access_block.logs_primary,
    aws_s3_bucket_ownership_controls.logs_primary,
  ]
}

data "aws_iam_policy_document" "logs_secondary_bucket_policy" {
  provider = aws.secondary_region

  statement {
    sid    = "AllowS3LogDeliveryServiceToWriteSecondaryLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs_secondary.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values = [
        aws_s3_bucket.secondary.arn,
      ]
    }
  }
}

resource "aws_s3_bucket_policy" "logs_secondary" {
  provider = aws.secondary_region

  bucket = aws_s3_bucket.logs_secondary.id
  policy = data.aws_iam_policy_document.logs_secondary_bucket_policy.json

  depends_on = [
    aws_s3_bucket_public_access_block.logs_secondary,
    aws_s3_bucket_ownership_controls.logs_secondary,
  ]
}

resource "aws_s3_bucket_logging" "primary" {
  bucket = aws_s3_bucket.primary.id

  target_bucket = aws_s3_bucket.logs_primary.id
  target_prefix = "logs/primary/"

  depends_on = [
    aws_s3_bucket_ownership_controls.logs_primary,
    aws_s3_bucket_public_access_block.logs_primary,
    aws_s3_bucket_policy.logs_primary,
  ]
}

resource "aws_s3_bucket_logging" "secondary" {
  provider = aws.secondary_region

  bucket = aws_s3_bucket.secondary.id

  target_bucket = aws_s3_bucket.logs_secondary.id
  target_prefix = "logs/secondary/"

  depends_on = [
    aws_s3_bucket_ownership_controls.logs_secondary,
    aws_s3_bucket_public_access_block.logs_secondary,
    aws_s3_bucket_policy.logs_secondary,
  ]
}

###############################################################################
# IAM role, policy and attachment used by S3 replication
###############################################################################

data "aws_iam_policy_document" "s3_replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceToAssumeReplicationRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  name               = "${var.mrap_name}-s3-replication-role"
  description        = "Role assumed by Amazon S3 to replicate objects from the primary bucket to the secondary bucket"
  assume_role_policy = data.aws_iam_policy_document.s3_replication_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "s3_replication_permissions" {
  statement {
    sid    = "ReadSourceBucketReplicationConfiguration"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    sid    = "ReadSourceBucketObjects"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    sid    = "ReplicateObjectsToDestinationBucket"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }

  statement {
    sid    = "DecryptSourceObjects"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.primary.arn]
  }

  statement {
    sid    = "EncryptReplicaObjects"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:Decrypt",
    ]

    resources = [aws_kms_key.secondary.arn]
  }
}

resource "aws_iam_policy" "s3_replication" {
  name        = "${var.mrap_name}-s3-replication-policy"
  description = "Least-privilege permissions used by the S3 replication role"
  policy      = data.aws_iam_policy_document.s3_replication_permissions.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

###############################################################################
# Cross-region replication: primary -> secondary
###############################################################################

resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id     = "replicate-all-kms-objects"
    status = "Enabled"

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }

    delete_marker_replication {
      status = "Disabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_s3_bucket_ownership_controls.primary,
    aws_s3_bucket_ownership_controls.secondary,
    aws_s3_bucket_public_access_block.primary,
    aws_s3_bucket_public_access_block.secondary,
    aws_iam_role_policy_attachment.s3_replication,
  ]
}

###############################################################################
# Multi-Region Access Point (control plane must be us-west-2)
###############################################################################

resource "aws_s3control_multi_region_access_point" "main" {
  provider = aws.secondary_region

  account_id = local.account_id

  details {
    name = var.mrap_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_s3_bucket_replication_configuration.primary,
  ]
}

data "aws_iam_policy_document" "mrap_policy" {
  statement {
    sid    = "AllowOwningAccountGetAndPutObjects"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = [local.mrap_object_arn]
  }
}

resource "aws_s3control_multi_region_access_point_policy" "main" {
  provider = aws.secondary_region

  account_id = local.account_id

  details {
    name   = aws_s3control_multi_region_access_point.main.details[0].name
    policy = data.aws_iam_policy_document.mrap_policy.json
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  dynamodb_table_arn   = "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/*"
  dynamodb_backup_arn  = "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/*/backup/*"
  lambda_log_group_arn = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*"

  lambda_assume_role_policy_name = "lambda_assume_role_policy"
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = {
    Name        = "create_ddb_backup_role"
    ManagedBy   = "terraform"
    Description = "Lambda execution role for creating DynamoDB backups"
  }
}

resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = {
    Name        = "remove_ddb_backup_role"
    ManagedBy   = "terraform"
    Description = "Lambda execution role for removing DynamoDB backups"
  }
}

data "aws_iam_policy_document" "create_ddb_backup" {
  statement {
    sid     = "CreateDynamoDBBackup"
    effect  = "Allow"
    actions = ["dynamodb:CreateBackup"]
    resources = [
      local.dynamodb_table_arn,
    ]
  }

  statement {
    sid     = "DescribeAndListDynamoDBBackups"
    effect  = "Allow"
    actions = [
      "dynamodb:DescribeBackup",
      "dynamodb:ListBackups",
    ]
    resources = [
      local.dynamodb_table_arn,
      local.dynamodb_backup_arn,
    ]
  }
}

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Least-privilege permissions to create and inspect DynamoDB backups"
  policy      = data.aws_iam_policy_document.create_ddb_backup.json

  tags = {
    Name      = "create_ddb_backup_policy"
    ManagedBy = "terraform"
  }
}

data "aws_iam_policy_document" "remove_ddb_backup" {
  statement {
    sid     = "DeleteDynamoDBBackup"
    effect  = "Allow"
    actions = ["dynamodb:DeleteBackup"]
    resources = [
      local.dynamodb_backup_arn,
    ]
  }

  statement {
    sid     = "DescribeAndListDynamoDBBackups"
    effect  = "Allow"
    actions = [
      "dynamodb:DescribeBackup",
      "dynamodb:ListBackups",
    ]
    resources = [
      local.dynamodb_table_arn,
      local.dynamodb_backup_arn,
    ]
  }
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Least-privilege permissions to list and delete DynamoDB backups"
  policy      = data.aws_iam_policy_document.remove_ddb_backup.json

  tags = {
    Name      = "remove_ddb_backup_policy"
    ManagedBy = "terraform"
  }
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    sid     = "CreateLambdaLogGroupsAndStreams"
    effect  = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
    ]
    resources = [
      local.lambda_log_group_arn,
      "${local.lambda_log_group_arn}:*",
    ]
  }

  statement {
    sid     = "WriteLambdaLogEvents"
    effect  = "Allow"
    actions = [
      "logs:PutLogEvents",
    ]
    resources = [
      "${local.lambda_log_group_arn}:*",
    ]
  }
}

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Shared CloudWatch Logs write permissions for Lambda execution roles"
  policy      = data.aws_iam_policy_document.lambda_logging.json

  tags = {
    Name      = "lambda_logging"
    ManagedBy = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_policy_attachment" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_lambda_logging_attachment" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_policy_attachment" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_lambda_logging_attachment" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

output "create_ddb_backup_role_arn" {
  description = "ARN of the IAM role used by Lambda to create DynamoDB backups"
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "create_ddb_backup_role_name" {
  description = "Name of the IAM role used by Lambda to create DynamoDB backups"
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the IAM role used by Lambda to remove DynamoDB backups"
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the IAM role used by Lambda to remove DynamoDB backups"
  value       = aws_iam_role.remove_ddb_backup_role.name
}

output "create_ddb_backup_policy_arn" {
  description = "ARN of the customer-managed policy allowing creation of DynamoDB backups"
  value       = aws_iam_policy.create_ddb_backup_policy.arn
}

output "remove_ddb_backup_policy_arn" {
  description = "ARN of the customer-managed policy allowing removal of DynamoDB backups"
  value       = aws_iam_policy.remove_ddb_backup_policy.arn
}

output "lambda_logging_policy_arn" {
  description = "ARN of the shared customer-managed policy granting CloudWatch Logs write permissions"
  value       = aws_iam_policy.lambda_logging.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  vpc_name     = "projectvpc"
  public_name  = "projectvpc-public"
  private_name = "projectvpc-private"
  common_tags = {
    Project   = "projectvpc"
    ManagedBy = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = local.public_name
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = local.private_name
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id     = aws_eip.nat.id
  subnet_id         = aws_subnet.public.id
  connectivity_type = "public"

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

data "aws_iam_policy_document" "cloudwatch_kms" {
  statement {
    sid    = "EnableRootAccountControl"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "cloudwatch" {
  description             = "CMK for ${local.vpc_name} flow-log encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.cloudwatch_kms.json

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-flow-logs-cmk"
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${local.vpc_name}-flow-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc/${local.vpc_name}-flow-logs"
  retention_in_days = 365
  kms_key_id        = aws_kms_key.cloudwatch.arn

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-flow-logs"
  })
}

data "aws_iam_policy_document" "flow_logs_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "flow_logs" {
  name               = "${local.vpc_name}-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-flow-logs-role"
  })
}

data "aws_iam_policy_document" "flow_logs_permissions" {
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
      "logs:DescribeLogGroups",
    ]

    resources = [
      aws_cloudwatch_log_group.flow_logs.arn,
      "${aws_cloudwatch_log_group.flow_logs.arn}:*",
    ]
  }
}

resource "aws_iam_policy" "flow_logs" {
  name        = "${local.vpc_name}-flow-logs-policy"
  description = "Permissions for VPC flow logs to write to CloudWatch Logs"
  policy      = data.aws_iam_policy_document.flow_logs_permissions.json

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-flow-logs-policy"
  })
}

resource "aws_iam_role_policy_attachment" "flow_logs" {
  role       = aws_iam_role.flow_logs.name
  policy_arn = aws_iam_policy.flow_logs.arn
}

resource "aws_flow_log" "main" {
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn             = aws_iam_role.flow_logs.arn
  max_aggregation_interval = 60

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-flow-log"
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

variable "tags" {
  description = "A map of tags to apply to the resources"
  type        = map(string)
  default = {
    Project = "endpoint-backup"
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  tags = merge(var.tags, {
    Region = data.aws_region.current.name
  })
}

# Customer-managed KMS key used for bucket default encryption.
# The default key policy delegates all actions to IAM, so the IAM policy below
# grants the required kms:* access without a custom key policy.
resource "aws_kms_key" "endpoint_backup" {
  description             = "KMS key for endpoint-backup S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.tags
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket              = "endpoint-backup-${data.aws_caller_identity.current.account_id}"
  object_lock_enabled = false

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyTLSVersionBelow12"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
        Condition = {
          NumericLessThan = {
            "s3:TlsVersion" = "1.2"
          }
        }
      },
      {
        Sid       = "DenyComplianceRetentionOver90Days"
        Effect    = "Deny"
        Principal = "*"
        Action = [
          "s3:PutObject",
          "s3:PutObjectRetention"
        ]
        Resource = "${aws_s3_bucket.endpoint_backup.arn}/*"
        Condition = {
          StringEquals = {
            "s3:object-lock-mode" = "COMPLIANCE"
          }
          NumericGreaterThan = {
            "s3:object-lock-remaining-retention-days" = "90"
          }
        }
      }
    ]
  })
}

# Dedicated access-log destination bucket.
resource "aws_s3_bucket" "logs" {
  bucket = "endpoint-backup-logs-${data.aws_caller_identity.current.account_id}"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# BucketOwnerEnforced (the greenfield default) disables ACLs, so switch the log
# bucket to BucketOwnerPreferred to allow the log-delivery-write canned ACL.
resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# log-delivery-write is not a public ACL, so the public access block stays valid.
resource "aws_s3_bucket_acl" "logs" {
  depends_on = [aws_s3_bucket_ownership_controls.logs]

  bucket = aws_s3_bucket.logs.id
  acl    = "log-delivery-write"
}

# SSE-KMS is unsupported for logging-destination buckets, so use AES256 here.
resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "logs" {
  bucket = aws_s3_bucket.logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3ServerAccessLogging"
        Effect    = "Allow"
        Principal = { Service = ["logging.s3.amazonaws.com"] }
        Action    = ["s3:PutObject"]
        Resource  = "${aws_s3_bucket.logs.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "log/"
}

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"
  tags = local.tags
}

resource "aws_iam_group" "endpoint_backup" {
  name = "endpoint-backup"
}

resource "aws_iam_group_membership" "endpoint_backup" {
  name  = "endpoint-backup"
  users = [aws_iam_user.endpoint_backup.name]
  group = aws_iam_group.endpoint_backup.name
}

# MFA enforcement for the group: deny sensitive/destructive actions when MFA
# is not present. Kept narrow so routine backup S3/KMS operations are unaffected.
resource "aws_iam_group_policy" "endpoint_backup_mfa" {
  name  = "endpoint-backup-mfa-enforcement"
  group = aws_iam_group.endpoint_backup.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DenySensitiveActionsWithoutMFA"
        Effect = "Deny"
        Action = [
          "iam:*",
          "s3:DeleteBucket",
          "s3:PutBucketPolicy",
          "s3:PutBucketAcl"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "endpoint_backup_bucket_read_write_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Read/write access to the endpoint-backup S3 bucket"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BucketLevelAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListBucketVersions",
          "s3:GetBucketLocation"
        ]
        Resource = aws_s3_bucket.endpoint_backup.arn
      },
      {
        Sid    = "ObjectLevelAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion",
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts",
          "s3:RestoreObject",
          "s3:GetObjectRetention",
          "s3:PutObjectRetention",
          "s3:GetObjectLegalHold",
          "s3:PutObjectLegalHold",
          "s3:GetObjectTagging",
          "s3:PutObjectTagging",
          "s3:DeleteObjectTagging"
        ]
        Resource = "${aws_s3_bucket.endpoint_backup.arn}/*"
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.endpoint_backup.arn
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "endpoint_backup" {
  group      = aws_iam_group.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_read_write_access.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "source2"
  region = var.source2_region
}

provider "aws" {
  alias  = "replica1"
  region = var.replica1_region
}

provider "aws" {
  alias  = "replica2"
  region = var.replica2_region
}

variable "source2_region" {
  description = "AWS region used for the second set of source log buckets."
  type        = string
  default     = "us-west-2"
}

variable "replica1_region" {
  description = "AWS region used for the first set of replica log buckets."
  type        = string
  default     = "eu-west-1"
}

variable "replica2_region" {
  description = "AWS region used for the second set of replica log buckets."
  type        = string
  default     = "ap-southeast-1"
}

variable "tags" {
  description = "Common tags applied to every resource created by this configuration."
  type        = map(string)
  default = {
    Env = "dev"
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  common_tags = var.tags

  log1a_bucket = "log1a.veerum-${local.account_id}"
  log1b_bucket = "log1b.veerum-${local.account_id}"
  log2a_bucket = "log2a.veerum-${local.account_id}"
  log2b_bucket = "log2b.veerum-${local.account_id}"

  log1a_replica1_bucket = "log1a.veerum-replica1-${local.account_id}"
  log1b_replica1_bucket = "log1b.veerum-replica1-${local.account_id}"
  log2a_replica1_bucket = "log2a.veerum-replica1-${local.account_id}"
  log2b_replica1_bucket = "log2b.veerum-replica1-${local.account_id}"

  log1a_replica2_bucket = "log1a.veerum-replica2-${local.account_id}"
  log1b_replica2_bucket = "log1b.veerum-replica2-${local.account_id}"
  log2a_replica2_bucket = "log2a.veerum-replica2-${local.account_id}"
  log2b_replica2_bucket = "log2b.veerum-replica2-${local.account_id}"

  log_dest_1_bucket = "logs-veerum-us-east-1-${local.account_id}"
  log_dest_2_bucket = "logs-veerum-${var.source2_region}-${local.account_id}"
  log_dest_3_bucket = "logs-veerum-${var.replica1_region}-${local.account_id}"
  log_dest_4_bucket = "logs-veerum-${var.replica2_region}-${local.account_id}"
}

################################################################################
# IAM role assumed by Amazon S3 for cross-region replication
################################################################################

data "aws_iam_policy_document" "s3_replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  name               = "s3-cross-region-replication-role"
  description        = "IAM role assumed by Amazon S3 to replicate log buckets across regions."
  assume_role_policy = data.aws_iam_policy_document.s3_replication_assume_role.json
  tags               = local.common_tags
}

################################################################################
# KMS key policies
################################################################################

data "aws_iam_policy_document" "kms_source1" {
  statement {
    sid    = "AllowRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ReplicationDecrypt"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.s3_replication.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]
  }
}

