################################################################################
# KMS customer managed keys (one per region)
################################################################################

resource "aws_kms_key" "source1" {
  description             = "SSE-KMS key for source log buckets in us-east-1."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_source1.json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "source1" {
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.key_id
}

resource "aws_kms_key" "source2" {
  provider                = aws.source2
  description             = "SSE-KMS key for source log buckets in the second source region."
  deletion_window_in_days = 30
