################################################################################
# Log-destination bucket policies (authorize S3 server access logging)
################################################################################

data "aws_iam_policy_document" "log_dest_1" {
  statement {
    sid    = "AllowS3ServerAccessLogDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.log_dest_1.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "log_dest_1" {
  bucket = aws_s3_bucket.log_dest_1.id
  policy = data.aws_iam_policy_document.log_dest_1.json
}

