################################################################################
# Least-privilege IAM policy for the replication role
################################################################################

data "aws_iam_policy_document" "s3_replication" {
  statement {
    sid    = "ReadSourceBucketsAndObjects"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = [
      aws_s3_bucket.log1a.arn,
      aws_s3_bucket.log1b.arn,
      aws_s3_bucket.log2a.arn,
      aws_s3_bucket.log2b.arn,
      "${aws_s3_bucket.log1a.arn}/*",
      "${aws_s3_bucket.log1b.arn}/*",
      "${aws_s3_bucket.log2a.arn}/*",
      "${aws_s3_bucket.log2b.arn}/*",
    ]
  }

  statement {
    sid    = "ReplicateIntoReplicaBuckets"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = [
      aws_s3_bucket.log1a_replica1.arn,
      aws_s3_bucket.log1b_replica1.arn,
      aws_s3_bucket.log2a_replica1.arn,
      aws_s3_bucket.log2b_replica1.arn,
      aws_s3_bucket.log1a_replica2.arn,
      aws_s3_bucket.log1b_replica2.arn,
      aws_s3_bucket.log2a_replica2.arn,
      aws_s3_bucket.log2b_replica2.arn,
      "${aws_s3_bucket.log1a_replica1.arn}/*",
      "${aws_s3_bucket.log1b_replica1.arn}/*",
      "${aws_s3_bucket.log2a_replica1.arn}/*",
      "${aws_s3_bucket.log2b_replica1.arn}/*",
      "${aws_s3_bucket.log1a_replica2.arn}/*",
      "${aws_s3_bucket.log1b_replica2.arn}/*",
      "${aws_s3_bucket.log2a_replica2.arn}/*",
      "${aws_s3_bucket.log2b_replica2.arn}/*",
    ]
  }

  statement {
    sid    = "DecryptSourceObjects"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.source1.arn,
      aws_kms_key.source2.arn,
    ]
  }

  statement {
    sid    = "EncryptReplicaObjects"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.replica1.arn,
      aws_kms_key.replica2.arn,
    ]
  }
}

resource "aws_iam_policy" "s3_replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Least-privilege policy permitting cross-region replication of SSE-KMS encrypted log buckets."
  policy      = data.aws_iam_policy_document.s3_replication.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

################################################################################
# Replication configuration - us-east-1 source buckets (default provider)
################################################################################

resource "aws_s3_bucket_replication_configuration" "log1a" {
  bucket = aws_s3_bucket.log1a.id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id     = "replicate-to-replica-region-1"
    status = "Enabled"

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.log1a_replica1.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }
  }

  rule {
    id     = "replicate-to-replica-region-2"
    status = "Enabled"

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.log1a_replica2.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.log1a]
}

